pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Perfect 2-step match: post_residual exactly equals next item size.
    if next_item_size > 0 && post_residual == next_item_size {
        score -= 1000.0;
    }
    // Near-perfect lookahead match: next item fits with tiny leftover.
    else if next_item_size > 0 && post_residual >= next_item_size {
        let slack = (post_residual - next_item_size) as f64;
        score -= 300.0 - slack * 2.5;
    }
    // Next item cannot use the leftover: penalize dead space proportional to how
    // far below the next item the residual falls.
    else if next_item_size > 0 && post_residual < next_item_size {
        let gap = (next_item_size - post_residual) as f64;
        score += gap * 1.5;
    }

    // Penalize residuals that are too small to ever be useful (below min item size).
    if post_residual < 10 && post_residual > 0 {
        score += 80.0;
    }

    // Last-chance bin: strongly favor using it to avoid opening a new bin.
    if fitting_bins_count == 1 && bin_residual != bin_capacity {
        score -= 250.0;
    }

    // Prefer bins tighter than the mean residual (compact packing).
    score += (post_residual as f64 - mean_residual) * 0.8;

    // Early in the stream, prefer tighter fits to build dense bins.
    let progress = step_index as f64 / (total_items.max(1) as f64);
    score *= 1.0 + 0.3 * (1.0 - progress);

    // Mild penalty for the brand-new empty bin candidate, so it's only chosen
    // when open bins score very badly (poor fits).
    if bin_residual == bin_capacity {
        score += 60.0;
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Perfect fit reward: strong bonus when the item exactly fills the bin.
    if post_residual == 0 {
        score -= 1000.0;
    }

    // 2-step lookahead: if the next item exactly fits the post-residual,
    // this placement creates a chain, reward heavily.
    if next_item_size > 0 {
        if post_residual == next_item_size {
            score -= 400.0;
        } else if post_residual > next_item_size {
            // Next item fits inside remaining space; mild reward scaled by tightness.
            let slack = (post_residual - next_item_size) as f64;
            score -= 80.0 * (1.0 - slack / bin_capacity as f64);
        } else {
            // Next item cannot use the residual; penalize dead space proportionally.
            let dead = post_residual as f64;
            score += 0.5 * dead * (1.0 + dead / bin_capacity as f64);
        }
    }

    // Prefer bins whose residual is already small (tight packing).
    let tightness = 1.0 - (bin_residual as f64 / bin_capacity as f64);
    score -= 30.0 * tightness;

    // Relative to mean residual: placing into a below-average-residual bin
    // consolidates space; reward that.
    score -= 10.0 * (mean_residual - bin_residual as f64) / bin_capacity as f64;

    // Last-chance bin: if this is the only bin that fits, strongly prefer it
    // to avoid opening a new bin.
    if fitting_bins_count == 1 && bin_residual != bin_capacity {
        score -= 250.0;
    }

    // Penalize the brand-new empty bin candidate mildly, unless the item is
    // huge relative to capacity or many bins are open (bin-opening pressure).
    if bin_residual == bin_capacity {
        let item_frac = item_size as f64 / bin_capacity as f64;
        let pressure = open_bins_count as f64 / (1.0 + step_index as f64 / (total_items.max(1) as f64)).max(1.0);
        score += 120.0 - 100.0 * item_frac - 5.0 * pressure;
        // If next item is small, a fresh bin wastes capacity; extra penalty.
        if next_item_size > 0 && next_item_size < post_residual {
            score += 40.0;
        }
    }

    score
}

