pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Harmonic class of the leftover space: classify post_residual into
    // capacity-fraction buckets. Small classes (perfect fits) rewarded hard.
    let frac = post_residual as f64 / bin_capacity as f64;

    // Perfect fit: zero dead space -> strong reward.
    if post_residual == 0 {
        score -= 1000.0;
    } else {
        // Dead-space penalty grows non-linearly for unusable slivers.
        // Slivers below the smallest possible item can never be filled.
        if post_residual < 10 {
            score += 500.0;
        } else {
            // Harmonic weighting: score contribution ~ 1/(class index).
            // Classes: (0,10], (10,25], (25,50], (50,100]
            let class = if post_residual <= 10 { 1 }
                        else if post_residual <= 25 { 2 }
                        else if post_residual <= 50 { 3 }
                        else { 4 };
            score += (40.0 / class as f64) * (1.0 - frac);
        }
    }

    // Lookahead coupling: does next_item_size fit in post_residual?
    // If yes, this bin supports a chain -> reward proportionally to how snugly.
    if next_item_size > 0 && next_item_size <= post_residual {
        let snug = (post_residual - next_item_size) as f64;
        score -= 30.0 - snug.min(30.0) * 0.5;
    } else if next_item_size > post_residual {
        // Next item won't fit here; mildly penalize leaving awkward gaps.
        score += 5.0;
    }

    // Last-chance bin: if this is the only bin that can fit the item,
    // strongly prefer it over opening a new bin.
    if fitting_bins_count == 1 && bin_residual >= item_size {
        score -= 200.0;
    }

    // New-bin candidate handling: an empty bin has post_residual == capacity.
    // Only open a new bin if the item is large relative to typical residuals
    // or late in the stream; otherwise bias toward existing bins.
    if bin_residual == bin_capacity {
        let progress = step_index as f64 / total_items.max(1) as f64;
        let big_item = (item_size as f64 / bin_capacity as f64) > 0.6;
        // Reward opening a new bin for large items or when existing bins are crowded.
        if big_item || mean_residual < item_size as f64 * 0.5 {
            score -= 20.0 + 40.0 * progress;
        } else {
            score += 25.0; // prefer placing into an existing open bin
        }
    }

    // Mild pressure toward consolidating: fewer open bins -> prefer tight fits.
    score += (open_bins_count as f64).ln().max(0.0) * 2.0;

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Dead-space penalty: residual that cannot fit any plausible item (<=10) is wasted.
    if post_residual < 10 {
        score += 60.0;
    }

    // Harmonic class of post_residual: how many "size classes" of items (10..80 step 10)
    // can still fit. Fewer classes = tighter fit = better packing.
    let classes_fit = (post_residual / 10).min(8) as f64;
    score -= 14.0 * classes_fit;

    // Modulo-10 class penalty: prefer post_residual near multiples of 10 (clean splits),
    // penalize awkward odd residues that fragment space.
    let mod10 = (post_residual % 10) as f64;
    score += 0.8 * (mod10 * mod10) / 25.0;

    // Lookahead: if next item fits in post_residual, reward; if not, penalize slightly
    // unless this bin was the last chance anyway.
    if next_item_size > 0 {
        if next_item_size <= post_residual {
            score -= 8.0;
        } else {
            score += 5.0;
        }
        // Harmonic coupling: next item's own post-fit residual class
        if next_item_size <= post_residual {
            let next_post = post_residual - next_item_size;
            if next_post < 10 {
                score += 4.0; // would create new dead space for the following step
            } else {
                score -= (next_post / 10) as f64 * 2.0;
            }
        }
    }

    // Last-chance bonus: if this is the only fitting bin, strongly favor using it
    // over opening a new bin.
    if fitting_bins_count == 1 {
        score -= 35.0;
    }

    // New-bin candidate handling: empty bin has high raw score; make it attractive
    // only when current bin's post_residual would be unusable dead space.
    if bin_residual == bin_capacity {
        // Base cost of opening a new bin, softened by stream progress.
        score = 45.0 + 20.0 * (step_index as f64 / total_items.max(1) as f64);
        // More attractive if open bins are already quite full on average.
        score -= (mean_residual / bin_capacity as f64) * 15.0;
        // Discourage hoarding bins early in the stream.
        score += 3.0 * (open_bins_count as f64).sqrt();
        // If next item is huge and won't fit alongside typical residuals, new bin is safer.
        if next_item_size > 60 {
            score -= 10.0;
        }
    }

    // Global tightness: prefer bins whose residual is far below the mean (tighter bins
    // get filled first), keeping loose bins available for future awkward items.
    score += 0.3 * (mean_residual - bin_residual as f64).max(-100.0) * 0.1;

    // Small penalty for very large item relative to residual (near-exact fit is good,
    // but extreme tightness leaves nothing) — mild shaping.
    let fill = item_size as f64 / bin_residual.max(1) as f64;
    if fill > 0.9 {
        score -= 6.0;
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;
    let progress = if total_items > 0 { step_index as f64 / total_items as f64 } else { 0.0 };

    // Aggressive 2-step lookahead: reward exact match between post_residual and next item
    if next_item_size > 0 {
        let diff = (post_residual as i64 - next_item_size as i64).abs() as f64;
        score += 0.5 * diff;
        // Perfect chain: post_residual == next_item_size -> strong bonus
        if post_residual == next_item_size {
            score -= 60.0;
        } else if post_residual < next_item_size {
            // next item won't fit here; penalize dead space proportional to gap
            score += 0.3 * (next_item_size - post_residual) as f64;
        } else {
            // next item fits with leftover; bonus scaled by tightness
            score -= 10.0 * (1.0 - diff / bin_capacity as f64);
        }
    } else {
        // last item: prefer minimal post_residual strongly
        score += 0.2 * post_residual as f64;
    }

    // Relative to mean residual: prefer bins tighter than average
    score += 0.4 * (mean_residual - post_residual as f64);

    // Penalize tiny unusable residuals (dead space)
    if post_residual > 0 && post_residual < 10 {
        score += 15.0;
    }

    // Last-chance bin: strong reward to avoid opening a new bin
    if fitting_bins_count == 1 && bin_residual != bin_capacity {
        score -= 25.0 * (1.0 - progress);
    }

    // New-bin candidate: penalize unless current residuals are large relative to item
    if bin_residual == bin_capacity {
        let avg_fit = mean_residual;
        if avg_fit > item_size as f64 * 1.5 {
            score += 40.0; // keep using open bins
        } else {
            score -= 5.0; // opening fresh bin is reasonable
        }
    }

    // Mild preference to fill older/fuller bins as stream progresses
    score += 0.05 * progress * post_residual as f64;

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Perfect fit is always ideal.
    if post_residual == 0 {
        score -= 1000.0;
    }

    // Harmonic classes: partition post_residual into usability bands.
    // Dead space (very small residual) is worthless — penalize it heavily.
    if post_residual > 0 && post_residual <= 10 {
        score += 60.0;
    } else if post_residual <= 25 {
        score += 10.0;
    } else if post_residual <= 50 {
        score -= 15.0;
    } else {
        // Large residual left: flexible bin, reward proportionally.
        score -= 25.0;
    }

    // Modulo-arithmetic coupling: residuals that are multiples of common
    // small sizes (1,2,4,5,10) are more likely reusable by future items.
    let r = post_residual;
    if r > 0 && (r % 10 == 0 || r % 5 == 0) {
        score -= 8.0;
    }
    if r > 0 && r % 2 == 0 {
        score -= 2.0;
    }

    // Lookahead: if the next item fits exactly in the post residual,
    // this is a chained perfect fit — strongly reward.
    if next_item_size > 0 {
        if next_item_size == post_residual {
            score -= 120.0;
        } else if next_item_size < post_residual {
            let next_post = post_residual - next_item_size;
            if next_post <= 10 {
                score += 20.0; // creates new dead space after chain
            } else {
                score -= 12.0;
            }
        } else {
            // next item won't fit here anyway; residual value is its own.
            score += 3.0;
        }
    }

    // Last-chance bin: if this is the only bin that fits, avoid opening
    // a new bin unless the fit is terrible (huge dead space).
    if fitting_bins_count == 1 {
        score -= 30.0;
        if post_residual > 0 && post_residual <= 5 {
            score += 25.0; // but not if it wastes nearly everything
        }
    }

    // New-bin candidate handling: an empty bin has maximal residual.
    // Prefer it only when no open bin offers a decent fit.
    if bin_residual == bin_capacity {
        // Neutral base; slight penalty so decent existing fits win.
        score += 5.0;
        if fitting_bins_count == 0 {
            score -= 200.0;
        }
        if next_item_size > 0 && next_item_size >= item_size {
            score -= 10.0; // good for pairing large items together
        }
    }

    // Progress-based tightening: late in the stream, minimize bin count
    // aggressively; early, keep flexibility.
    let progress = step_index as f64 / (total_items.max(1) as f64);
    score -= 10.0 * progress;

    // Mean residual coupling: if this bin's residual is far below the mean,
    // it's already fragmented; penalize using it for loose fits.
    let dev = mean_residual - bin_residual as f64;
    score += 0.15 * dev;

    // Many open bins: encourage consolidation into tight fits.
    if open_bins_count > 8 {
        score -= 0.5 * (post_residual as f64);
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Dead-space penalty: residuals that are too small to hold even the
    // smallest plausible future item are nearly useless.
    let min_future = if next_item_size > 0 { next_item_size.min(20) } else { 20 };
    if post_residual < min_future {
        score += 40.0 * (min_future - post_residual) as f64;
    }

    // Perfect fit reward: leaving exactly zero residual is ideal.
    if post_residual == 0 {
        score -= 60.0;
    }

    // Reward tight fits: fraction of bin consumed by this placement.
    let fill = item_size as f64 / bin_capacity as f64;
    score -= 30.0 * fill;

    // Penalize creating a residual that is small but nonzero and awkward
    // (below half the next item, i.e., likely wasted).
    if next_item_size > 0 && post_residual > 0 && post_residual < next_item_size {
        score += 25.0;
    }

    // Last-chance bonus: if this is the only bin that fits, strongly prefer
    // using it over opening a new bin (unless the fit is terrible).
    if fitting_bins_count == 1 && bin_residual != bin_capacity {
        score -= 50.0;
    }

    // New-bin candidate handling: opening a new bin wastes the residual of
    // every existing bin; make it costly unless current bins are nearly full.
    if bin_residual == bin_capacity {
        // Base cost of opening a new bin.
        score += 55.0;
        // Cheaper to open when existing bins are crowded.
        let crowding = 1.0 - (mean_residual / bin_capacity as f64).clamp(0.0, 1.0);
        score -= 45.0 * crowding;
        // If next item cannot fit into this fresh bin either, opening is
        // more attractive (fresh bin gives full flexibility).
        if next_item_size > 0 && next_item_size > item_size {
            score -= 15.0;
        }
        // Late in the stream, avoid proliferating bins with tiny leftover loads.
        let progress = step_index as f64 / total_items.max(1) as f64;
        score += 10.0 * (1.0 - progress);
    }

    // Mild pressure against accumulating many open bins: prefer packing
    // into existing bins when several choices exist.
    score += 0.5 * open_bins_count as f64;

    // Prefer bins whose residual is close to the item (snug fit) over
    // bins with huge residual (save large space for large items).
    let snug = (bin_residual as f64 - item_size as f64).abs();
    score += 0.15 * snug;

    // Lookahead: if the next item fits exactly in the post-residual,
    // this placement sets up a perfect follow-up.
    if next_item_size > 0 && post_residual == next_item_size {
        score -= 45.0;
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Perfect-fit reward: zero post-residual is ideal.
    if post_residual == 0 {
        score -= 1000.0;
    }

    // 2-step lookahead: reward when the next item fits exactly into post_residual.
    if next_item_size > 0 && post_residual >= next_item_size {
        let slack = post_residual - next_item_size;
        if slack == 0 {
            score -= 500.0; // chain of two perfect fits
        } else {
            score -= 200.0 - slack as f64; // next item fits, penalize leftover slack
        }
    } else if next_item_size > 0 {
        // Next item won't fit here: penalize proportionally to the wasted opportunity.
        score += 50.0 + (next_item_size - post_residual) as f64 * 0.5;
    }

    // Penalize small unusable residuals (dead space below the minimum item size).
    if post_residual > 0 && post_residual < 10 {
        score += 300.0;
    }

    // Compare against mean residual: bins tighter than average are better targets.
    score -= (mean_residual - post_residual as f64) * 0.5;

    // Last-chance bin: strongly favor using the only bin that can fit the item.
    if fitting_bins_count == 1 && bin_residual != bin_capacity {
        score -= 400.0;
    }

    // New-bin candidate: neutral-ish baseline, penalize slightly so we prefer
    // reusing open bins unless the fit is truly poor.
    if bin_residual == bin_capacity {
        score += 20.0;
    }

    // Late in the stream, be slightly more conservative about opening new bins.
    let progress = step_index as f64 / total_items.max(1) as f64;
    if bin_residual == bin_capacity {
        score += progress * 30.0;
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Strict dead-space avoidance: tiny leftover gaps are nearly unusable.
