        if post_residual == next_item_size {
            score -= 20.0;
        }
    } else if next_item_size > 0 && post_residual > 0 {
        // Residual too small for next item: penalize proportionally to how close it is.
        let gap = next_item_size as f64 - dead;
        if gap < 15.0 {
            score += gap * 1.5;
        }
    }

    // --- Fit tightness reward: prefer bins where item dominates residual ---
    let fill_ratio = item_size as f64 / bin_residual as f64;
    score -= fill_ratio * 15.0;

    // --- Last-chance pressure ---
    if fitting_bins_count == 1 && bin_residual != bin_capacity {
        score -= 25.0; // strongly prefer using the only bin that fits
    }

    // --- New-bin candidate handling ---
    if bin_residual == bin_capacity {
        // Opening a new bin is only attractive when current open bins are crowded
        // or the fit would create dead space in an existing bin.
        let pressure = open_bins_count as f64 * 2.0;
        score = bin_capacity as f64 - pressure
            + (12.0 - dead.min(12.0)); // empty bin has max residual; make it competitive only under pressure
        if fitting_bins_count == 1 {
            score += 30.0; // never open a new bin when a last-chance fit exists
        }
    }

    // --- Open-bin count pressure: discourage bin sprawl ---
    score += open_bins_count as f64 * 0.8;

    // --- Mean residual coupling: if mean residual is high, avoid bins far from mean ---
    let dev = (bin_residual as f64 - mean_residual).abs();
    score += dev * 0.3;

    // --- Mild stream progression: late in stream, prefer exact fills even more ---
    let progress = step_index as f64 / total_items.max(1) as f64;
    score -= (1.0 - fill_ratio) * progress * 5.0;

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
