    // dumping into existing bins; few open bins -> new bin more acceptable.
    let ob = open_bins_count as f64;
    if bin_residual == bin_capacity {
        // new-bin candidate: base cost, adjusted by global pressure
        let mut new_score = 55.0;
        new_score -= 4.0 * ob;
        new_score += 0.25 * mean_residual;
        if next_item_size > 0 && next_item_size >= 60 {
            new_score -= 15.0; // large next item benefits from fresh bin
        }
        if progress > 0.7 {
            new_score += 20.0; // late stream: avoid opening bins
        }
        score = new_score;
    } else {
