        // Early in the stream, allow more bin openings (exploration).
        let progress = if total_items > 0 { step_index as f64 / total_items as f64 } else { 0.0 };
        let openness = 1.5 - progress; // more tolerant early
        score += 40.0 * avg_fill * avg_fill * openness;
        // But if item is huge and nothing decent fits, new bin is fine.
        if item_size >= 70 {
            score -= 20.0;
        }
        // Mild bias against hoarding too many open bins late.
        score += 0.4 * open_bins_count as f64 * (1.0 - avg_fill);
    }

    // Consolidation pressure: prefer bins below mean residual (emptier bins fill first),
    // keeping some slack in the system for future large items.
    let diff = mean_residual - bin_residual as f64;
    score += 0.15 * diff;

    // Time horizon: as the stream nears its end, prioritize zero-waste packing harder.
    if total_items > 0 {
        let progress = step_index as f64 / total_items as f64;
        score -= 15.0 * progress * tightness;
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let progress = step_index as f64 / total_items.max(1) as f64;
    let pr = post_residual as f64;
    let cap = bin_capacity as f64;
    let norm_pr = pr / cap;

    // Base: prefer tight fits, but with non-linear (quadratic) penalty on waste.
    let mut score = pr + 4.0 * norm_pr * norm_pr * cap;

    // Smooth coupling: waste is less tolerable later in the stream.
    score += 20.0 * progress * norm_pr * norm_pr * cap;

    // Perfect-fit bonus (smooth exponential rather than piecewise).
    score -= 30.0 * (-pr as f64 / 5.0_f64.max(1.0)).exp();

    // Lookahead coupling: reward residuals that still fit the next item,
    // penalize residuals that leave the next item stranded.
    if next_item_size > 0 {
        let nxt = next_item_size as f64;
        if pr >= nxt {
            let slack = (pr - nxt) / cap;
            score -= 10.0 * (1.0 - slack) * (1.0 - progress);
        } else {
            let gap = (nxt - pr) / cap;
            score += 15.0 * gap * gap * cap * (0.5 + 0.5 * progress);
        }
    }

    // Last-chance bin: strongly favor using the only bin that fits.
    if fitting_bins_count == 1 && bin_residual != bin_capacity {
        score -= 25.0 * (1.0 + progress);
    }

    // New-bin candidate: keep it available early, allow it when open bins are wasteful.
    if bin_residual == bin_capacity {
        let waste = (mean_residual / cap).max(0.0);
        score += 12.0 - 10.0 * waste - 8.0 * progress;
    }

    // Mild load-balancing: prefer bins near mean residual (smooth coupling).
    score += 2.0 * ((pr - mean_residual) / cap).abs();

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let cap = bin_capacity as f64;
    let post = post_residual as f64;
    let mut score = post;

    // Harmonic class of post_residual: residuals divisible by large powers / common
    // item sizes are more reusable. Class = post_residual mod 10.
    let post_u = post_residual;
    let class_mod = (post_u % 10) as f64;
    // Residuals that are multiples of 10 align with the item grid -> reward.
    if post_u % 10 == 0 {
        score -= 12.0;
    } else {
        score += class_mod * 0.8; // misaligned residue penalized
    }
    // Multiples of 5 are semi-aligned.
    if post_u % 5 == 0 && post_u % 10 != 0 {
        score -= 4.0;
    }

    // Integer-division thresholds: can next item fit exactly in the post residual?
    if next_item_size > 0 {
        if next_item_size == post_u {
            score -= 25.0; // perfect two-item closure
        } else if next_item_size <= post_u {
            // closeness of next item to filling the bin
            let gap = (post_u - next_item_size) as f64;
            score -= 10.0 * (1.0 - gap / cap);
            // harmonic compatibility: next item divides post residual
            if post_u % next_item_size == 0 {
                score -= 8.0;
            }
        } else {
            // next item cannot use this residual; dead-space risk scaled by progress
            let progress = step_index as f64 / total_items.max(1) as f64;
            score += 6.0 + 6.0 * progress;
        }
    } else {
        // last item: strongly prefer tightest fit
        score += 0.0;
    }

    // Fraction-of-capacity thresholds on post_residual.
    let frac = post / cap;
    if frac <= 0.05 {
        score -= 20.0; // nearly closed bin, excellent
    } else if frac <= 0.15 {
        score -= 10.0;
    } else if frac >= 0.7 {
        score += 8.0; // wasteful low fill
    }

    // Last-chance bonus: if this is the only bin that fits, avoid opening a new one
    // unless the fit is terrible.
    if fitting_bins_count == 1 && bin_residual != bin_capacity {
        score -= 15.0;
    }

    // New-bin candidate: score it against mean residual of open bins.
    if bin_residual == bin_capacity {
        // Opening a new bin is attractive only when existing bins fit poorly
        // (large post residual) or many bins are already open and mean residual low.
        score = cap * 0.55
            + 0.25 * mean_residual
            - 8.0 * (open_bins_count as f64).ln().max(0.0);
        if next_item_size > 0 && next_item_size >= bin_capacity - item_size && next_item_size <= bin_capacity {
            score -= 10.0; // next item pairs well with a fresh bin
        }
        if fitting_bins_count == 1 {
            score += 40.0; // never displace the sole fitting bin
        }
    }

    // Slight tie-break toward filling fuller bins when many are open.
    score -= 0.05 * (bin_residual as f64) / cap * (open_bins_count as f64).min(10.0);

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Strict dead-space avoidance: residuals that no plausible item (>=1) can
    // use well are heavily penalized. Gaps of 1..=9 are near-unusable.
    let pr = post_residual;
    if pr == 0 {
        // Perfect fit: strongly reward closing a bin exactly.
        score -= 60.0;
    } else if pr <= 9 {
        // Dead space penalty grows as gap shrinks toward 1.
        score += (10 - pr) as f64 * 8.0;
    } else if pr <= 20 {
        // Moderately usable gap: mild penalty proportional to waste.
        score += (pr as f64 - 9.0) * 0.5;
    }

    // Reward tight fits: fraction of bin used by this placement.
    let fill_ratio = item_size as f64 / bin_capacity as f64;
    score -= fill_ratio * 25.0;

    // Last-chance pressure: if this is the only bin that fits, prefer using it
    // over opening a new bin (penalize the new-bin candidate instead).
    if fitting_bins_count == 1 && bin_residual != bin_capacity {
        score -= 15.0;
    }

    // New-bin candidate: discourage opening a new bin unless the item is large
    // and no open bin fits well (post_residual here equals capacity).
    if bin_residual == bin_capacity {
        score += 40.0;
        // Large items legitimately warrant fresh bins; soften penalty.
        score -= fill_ratio * 20.0;
        // Late in the stream, prefer consolidating into open bins.
        let progress = step_index as f64 / total_items.max(1) as f64;
        score += progress * 10.0;
    }

    // Open-bin pressure: many open bins -> favor placements that reduce
    // fragmentation (low post_residual already does); add mild global pressure
    // to keep bin count down by rewarding use of existing bins.
    score -= (open_bins_count as f64).ln().max(0.0) * 2.0;

    // Lookahead: if the next item fits exactly in the post residual,
    // strongly favor this bin (chained packing).
    if next_item_size > 0 && next_item_size == pr {
        score -= 30.0;
    } else if next_item_size > 0 && next_item_size <= pr {
        // Next item fits but not perfectly: mild bonus.
        score -= 5.0;
    }

    // Prefer bins below mean residual (balances load, avoids stranding
    // large residuals elsewhere).
    score += (post_residual as f64 - mean_residual) * 0.3;

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Strong reward for perfect fit (no dead space at all)
    if post_residual == 0 {
        score -= 1000.0;
        return score;
    }

    // Aggressive 2-step lookahead: does the next item fit into the residual we leave behind?
    if next_item_size > 0 {
        if post_residual >= next_item_size {
            // Reward proportional to how snugly the next item fits this leftover
            let snug = (post_residual - next_item_size) as f64;
            score -= 60.0 * (1.0 - snug / bin_capacity as f64);
        } else {
            // The leftover is dead space for the next item: penalize
            score += 30.0 + (next_item_size - post_residual) as f64;
        }
    }

    // Penalize residuals that are too small to hold any plausible future item
    let min_item = 1.0;
    if (post_residual as f64) < min_item {
        score += 500.0;
    }

    // Prefer bins tighter than the mean residual (best-fit flavor)
    score += (post_residual as f64 - mean_residual).max(0.0) * 2.0;

    // Last-chance bin: strongly favor using it before opening a new bin
    if fitting_bins_count == 1 && bin_residual >= item_size {
        score -= 80.0;
    }

    // Late in the stream, consolidate into fewer bins
    let progress = step_index as f64 / total_items.max(1) as f64;
    score -= progress * 10.0;

    // Slight bias against opening a new bin when many bins are already open
    if bin_residual == bin_capacity {
        score += 5.0 + open_bins_count as f64;
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Reward tight fits: perfect fit gets a big discount.
    if post_residual == 0 {
        score -= 1000.0;
    } else {
        // Non-linear penalty on wasted space, sharper for small leftovers.
        let pr = post_residual as f64;
        score += (bin_capacity as f64 / pr).min(50.0);
    }

    // Lookahead: if the next item fits exactly in the post-residual, favor this bin.
    if next_item_size > 0 {
        if post_residual == next_item_size {
            score -= 400.0;
        } else if post_residual >= next_item_size {
            // Next item fits but leaves further slack: mild penalty proportional to slack.
            let slack = (post_residual - next_item_size) as f64;
            score += slack * 0.3;
        } else {
            // Next item cannot use this bin's residual: penalize leaving dead space
            // that is too small to be useful later.
            score += 50.0;
        }
    }

    // Last-chance bonus: if this is the only bin that can fit the item, strongly prefer it
    // over opening a new bin.
    if fitting_bins_count == 1 && bin_residual >= item_size && bin_residual != bin_capacity {
        score -= 300.0;
    }

    // Penalize bins whose residual is far below the mean (they are nearly full anyway);
    // slightly favor bins with above-average residual unless the fit is tight.
    let fit_tightness = item_size as f64 / bin_residual.max(1) as f64;
    if fit_tightness < 0.9 {
        score += (mean_residual - bin_residual as f64).max(0.0) * 0.2;
    }

    // Time horizon: early in the stream, be more willing to open new bins / spread items;
    // late in the stream, consolidate aggressively into existing bins.
    let progress = if total_items > 0 { step_index as f64 / total_items as f64 } else { 0.0 };
    score -= progress * 40.0 * (1.0 - fit_tightness.min(1.0));

    // New-bin candidate: default mild preference against opening new bins unless
    // the item is large and no good fit exists (handled by last-chance bonus above).
    if bin_residual == bin_capacity {
        score += 120.0 + open_bins_count as f64 * 5.0;
        // Large items are cheap to start a new bin with early on.
        if item_size >= bin_capacity / 2 {
            score -= 60.0 * (1.0 - progress);
        }
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let progress = step_index as f64 / total_items.max(1) as f64;
    let pr = post_residual as f64;
    let cap = bin_capacity as f64;
    let norm_pr = pr / cap;

    // Base: post residual, with non-linear penalty on large dead space
    let mut score = pr * (1.0 + norm_pr * norm_pr);

    // Polynomial coupling of post_residual with stream progress:
    // late in the stream, small residuals become more valuable (tight packing)
    let tight = 1.0 - norm_pr;
    score -= tight * tight * progress * 20.0;

    // Reward near-perfect fits with smooth bell shape around small residuals
    let fit_bell = (-norm_pr * norm_pr * 12.0) * (1.0 - progress);
    score -= fit_bell * 15.0;

    // Penalize bins whose residual deviates strongly from mean residual (balance)
    let dev = pr - mean_residual;
    score += (dev * dev) / (cap * cap) * 8.0;

    // Last-chance bonus: if this is the only fitting bin, strongly prefer it
    if fitting_bins_count == 1 {
        score -= 25.0 + 15.0 * progress;
    }

    // Lookahead: reward leaving residual compatible with the next item
    if next_item_size > 0 {
        let nxt = next_item_size as f64;
        if pr >= nxt {
            let gap = (pr - nxt) / cap;
            score -= 10.0 * (-gap * gap * 20.0);
        } else {
            score += (nxt - pr) * 0.15;
        }
    }

    // Mild penalty for many open bins to discourage bin proliferation
    score += open_bins_count as f64 * 0.05;

    // New-bin candidate: keep it neutral-to-slightly-high unless residual is large
    if bin_residual == bin_capacity {
        score += 5.0 - 10.0 * progress;
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Harmonic class of the post-residual: residues near "useful" sizes
    // (small multiples of a base quantum) are more likely to be filled later.
    let quantum: u32 = 10;
    let r = post_residual % quantum;
    let class_penalty = match r {
        0 => -6.0,                    // perfectly aligned residual -> very reusable
        1 | 9 => 4.0,                 // off-by-one slivers -> dead space
        2 | 8 => 2.0,
        3 | 7 => 0.0,
        4 | 6 => -2.0,
        _ => -1.0,
    };
    score += class_penalty;

    // Integer-division threshold: post_residual in [1..=quantum] is nearly dead.
    if post_residual > 0 && post_residual <= quantum {
        score += 12.0 * (1.0 - post_residual as f64 / quantum as f64);
    }

    // Coupling with lookahead item: reward if next item fits the post-residual.
    if next_item_size > 0 {
        if next_item_size == post_residual {
            score -= 15.0; // perfect chain
        } else if next_item_size <= post_residual {
            score -= 8.0 * (next_item_size as f64 / post_residual as f64);
        } else {
            // next item won't fit: penalize wasted residual scaled by its size class
            let nxt_class = (next_item_size / quantum) as f64;
            score += 1.5 * nxt_class;
        }
    }

    // Capacity fraction coupling: bins whose residual is a small fraction of
    // capacity are "mature"; prefer filling them.
    let frac = post_residual as f64 / bin_capacity as f64;
    score += 20.0 * frac * frac;

    // Last-chance bin: strongly favor using the only fitting bin.
    if fitting_bins_count == 1 && bin_residual >= item_size {
        score -= 10.0;
    }

    // Many open bins with high mean residual: encourage consolidation.
    if open_bins_count > 2 && (mean_residual as u32 as f64) > 0.5 * bin_capacity as f64 {
        score += 2.0;
    }

    // New-bin candidate: only attractive when nothing fits well
    // (post_residual == capacity here). Penalize opening early in the stream
    // or when decent fitting bins exist.
    if bin_residual == bin_capacity {
        let progress = step_index as f64 / total_items.max(1) as f64;
        score = 60.0 + 40.0 * (1.0 - progress) + 5.0 * fitting_bins_count as f64;
        if next_item_size > 0 && next_item_size >= item_size {
            score -= 10.0; // pairing potential in a fresh bin
        }
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Strict dead-space avoidance: tiny gaps (1..=10) are effectively unusable
    // for typical items (sizes >= 1, practically >= 10 in classic streams).
    if post_residual >= 1 && post_residual <= 10 {
        score += 60.0; // heavy penalty for creating dead space
    } else if post_residual <= 20 {
        score += 25.0; // risky small gap
    } else if post_residual == 0 {
        score -= 40.0; // perfect fit: strongly reward exact packing
    }

    // Reward tight fits (small waste relative to capacity) non-linearly.
    let tightness = item_size as f64 / bin_residual as f64;
    score -= 30.0 * tightness * tightness;

    // Open-bin pressure: discourage opening new bins when many bins are open.
    let is_new_bin = bin_residual == bin_capacity;
    if is_new_bin {
        score += 15.0 + 4.0 * open_bins_count as f64;
        // Opening a bin is acceptable if mean residual is large (fragmented state).
        if mean_residual > 35.0 {
            score -= 20.0;
        }
    }

    // Last-chance bin: strongly prefer using the only bin that fits,
    // avoiding a brand-new bin otherwise.
    if fitting_bins_count == 1 && !is_new_bin {
        score -= 45.0;
    }

    // Lookahead coupling: if the next item fits exactly into post_residual,
    // reward this placement (chained packing).
    if next_item_size > 0 && next_item_size == post_residual {
        score -= 35.0;
    } else if next_item_size > 0 && next_item_size > post_residual {
        // Next item cannot use this bin's remainder anyway; slight bonus for
        // leaving a large reusable gap.
        if post_residual >= next_item_size {
            score -= 10.0;
        }
    }

    // Mild preference for filling bins as the stream progresses.
    let progress = step_index as f64 / total_items.max(1) as f64;
    score -= progress * 5.0 * (bin_capacity - post_residual) as f64 / bin_capacity as f64;

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Perfect fit reward: nearly zero waste is excellent.
    if post_residual == 0 {
        score -= 500.0;
    } else if post_residual <= 2 {
        score -= 200.0;
    }

    // 2-step lookahead: reward post_residual that exactly (or nearly) matches next item.
    if next_item_size > 0 {
        let nxt = next_item_size as f64;
        let post = post_residual as f64;
        let gap = (post - nxt).abs();
        if post >= nxt {
            // next item fits: reward tightness of the match
            score -= 120.0 - gap.min(120.0);
            if gap == 0.0 {
                score -= 150.0; // perfect chain fit
            }
        } else {
            // next item will NOT fit here: penalize dead space below next item size,
            // worse when the dead space is small (unusable fragment).
            let dead = nxt - post;
            score += dead * 0.8 + 20.0;
            // extra penalty if this fragment is too small for even the smallest item
            if post < 10 {
                score += 60.0;
            }
        }
    }

    // Compare post_residual against mean residual: leaving more than average
    // remaining space is relatively good (bin stays flexible).
    let post_f = post_residual as f64;
    if post_f >= mean_residual {
        score -= (post_f - mean_residual) * 0.5;
    } else {
        score += (mean_residual - post_f) * 0.3;
    }

    // Last-chance bonus: if this is the only fitting bin, strongly prefer using it
    // over opening a new bin.
    if fitting_bins_count == 1 {
        score -= 90.0;
    }

    // Mild pressure to consolidate into fewer bins as the stream grows.
    let progress = if total_items > 0 { step_index as f64 / total_items as f64 } else { 0.0 };
    score -= progress * 25.0;

    // Penalize new-bin candidate slightly so it is only chosen when open bins
    // would create truly bad fits.
    if bin_residual == bin_capacity {
        score += 70.0;
        // but allow new bin if existing fits would strand tiny fragments
        if next_item_size > 0 && post_residual == bin_capacity && item_size >= next_item_size {
            score -= 40.0;
        }
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Strongly prefer tight fits: reward small post_residual non-linearly.
    if post_residual == 0 {
        score -= 40.0;
    } else if post_residual <= 10 {
        score -= 20.0;
    } else {
        score += (post_residual as f64).powf(1.3) * 0.15;
    }

    // Lookahead: if the next item fits exactly in the post-residual, big reward.
    if next_item_size > 0 {
        if post_residual == next_item_size {
            score -= 35.0;
        } else if post_residual >= next_item_size && post_residual - next_item_size <= 10 {
            score -= 15.0;
        } else if next_item_size > post_residual && post_residual > 0 && post_residual < 10 {
            score += 5.0; // dead space too small for next item
        }
    }

    // Last-chance bin: strongly favor filling the only fitting bin.
    if fitting_bins_count == 1 && bin_residual >= item_size {
        score -= 25.0;
    }

    // Penalize opening new bins when many bins are already open and fit exists.
    let is_new_bin = bin_residual == bin_capacity;
    if is_new_bin {
        let progress = step_index as f64 / total_items.max(1) as f64;
        // New bins more acceptable early; heavily penalized later.
        score += 30.0 * (1.0 - progress) + 20.0 * (open_bins_count as f64).ln().max(0.0);
        // If next item is large and this bin would be fresh, mild discount.
        if next_item_size >= 60 {
            score -= 10.0;
        }
        // If mean residual across open bins is low (all bins tight), opening is fine.
        if mean_residual < 15.0 {
            score -= 25.0;
        }
    }

    // Coupling with mean residual: placing into a bin far below mean residual
    // balances the workload — mild reward.
    let diff = mean_residual - bin_residual as f64;
    score += diff * 0.05;

    // Prefer using bins with larger residual among equal fits (fill fuller bins first).
    score -= bin_residual as f64 * 0.03;

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let progress = step_index as f64 / total_items.max(1) as f64;
    let pr = post_residual as f64;
    let cap = bin_capacity as f64;
    let norm_pr = pr / cap;

    // Base: prefer small post-residual, with non-linear sharpening
    let mut score = pr * (1.0 + 0.8 * norm_pr * norm_pr);

    // Smooth coupling: post_residual interacts with stream progress.
    // Early on, tolerate larger residuals; later, penalize them more.
    let progress_coupling = pr * (0.5 + 1.5 * progress * progress);
    score += 0.35 * progress_coupling;

    // Quadratic dead-space term: residuals that are too small to fit
    // typical future items (small relative to capacity) are penalized
    // super-linearly.
    let dead = 1.0 - norm_pr;
    score += 12.0 * dead * dead * (1.0 - progress);

    // Last-chance bonus: if this is the only bin that fits, reward strongly
    if fitting_bins_count == 1 {
        score -= 25.0 * (1.0 + progress);
    }

    // Prefer bins tighter than the mean residual (good compaction)
    score -= 0.15 * (mean_residual - pr);

    // Lookahead: if the next item fits exactly in the post-residual,
    // reward; if next item is large and post-residual is small, mild penalty.
    if next_item_size > 0 {
        let nx = next_item_size as f64;
        if nx <= pr {
            score -= 6.0 * (1.0 - (nx / pr).powf(2.0));
        } else {
            score += 0.1 * (nx - pr);
        }
    }

    // Mild preference for consolidating into fewer bins when many are open
    score += 0.05 * open_bins_count as f64 * norm_pr;

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Harmonic class of post_residual: exact fill is perfect, small dead space is penalized
    let pr = post_residual;
    if pr == 0 {
        score -= 50.0;
    } else {
        // Dead-space penalty grows when residual falls into "unusable" classes
        // Items are 1..100; residual that cannot host typical items is bad.
        let class = pr % 10;
        // residuals congruent to small classes (< 5) are hard to fill
        if class < 5 && pr < 10 {
            score += 30.0;
        }
        // Fractional fill of capacity: prefer post_residual near multiples of common item sizes
        let frac = pr as f64 / bin_capacity as f64;
        score += 20.0 * frac;
    }

    // Lookahead coupling: if next item fits exactly in post_residual, big reward
    if next_item_size > 0 {
        if next_item_size == pr {
            score -= 40.0;
        } else if next_item_size < pr {
            // next item fits: reward proportionally to tightness
            score -= 10.0 * (1.0 - (pr - next_item_size) as f64 / bin_capacity as f64);
        } else {
            // next item won't fit here: mild penalty if we leave awkward residual
            score += 5.0;
        }
    }

    // Last-chance bin: strongly prefer using it over opening a new bin
    if fitting_bins_count == 1 && bin_residual < bin_capacity {
        score -= 25.0;
    }

    // New-bin candidate: penalize opening a new bin unless current fit is terrible
    if bin_residual == bin_capacity {
        score += 15.0 + 0.1 * open_bins_count as f64;
        // but if item is large relative to capacity, new bin is fine
        if item_size as f64 > 0.7 * bin_capacity as f64 {
            score -= 20.0;
        }
    }

    // Prefer tight fits generally
    score -= 15.0 * (1.0 - (item_size as f64 / bin_residual as f64)).abs().min(1.0) * -1.0;

    // Progression: early on, be more willing to open bins (explore)
    let progress = if total_items > 0 { step_index as f64 / total_items as f64 } else { 0.0 };
    if bin_residual == bin_capacity {
        score -= 10.0 * (1.0 - progress);
    }

    // Mean residual alignment: prefer bins whose residual deviates from mean when mean is small
    if mean_residual < 20.0 && bin_residual < bin_capacity {
        score -= 5.0;
    }

    // Integer division threshold: post_residual in [1,9] is nearly dead
    if pr >= 1 && pr <= 9 {
        score += 12.0;
    }
    // post_residual exactly divisible by 10 leaves clean harmonic slots
    if pr > 0 && pr % 10 == 0 {
        score -= 8.0;
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Strict dead-space avoidance: residuals that are too small to ever
    // hold another item (min item size = 1, but tiny gaps are still poor
    // targets for the lookahead item) are heavily penalized.
    let dead_zone = 6.0;
    if post_residual > 0 && (post_residual as f64) < dead_zone {
        score += (dead_zone - post_residual as f64) * 12.0;
    }
    if post_residual == 0 {
        // Perfect fit: reward strongly.
        score -= 40.0;
    }

    // Reward fits that leave room for the lookahead item exactly.
    if next_item_size > 0 {
        if post_residual == next_item_size {
            score -= 25.0;
        } else if post_residual > next_item_size {
            score -= 5.0;
        } else {
            // Lookahead cannot use what remains: penalize proportionally.
            score += (next_item_size as f64 - post_residual as f64) * 0.8;
        }
    }

    // Open-bin pressure: discourage spreading across many bins; encourage
    // using existing bins when the fleet is already large.
    let progress = step_index as f64 / total_items.max(1) as f64;
    let pressure = open_bins_count as f64 * (0.15 + 0.35 * progress);
    score += pressure * 0.5;

    // Penalize bins whose residual deviates strongly below the mean
    // (fragmenting the fleet's usable space).
    let dev = mean_residual - bin_residual as f64;
    if dev > 0.0 {
        score += dev * 0.3;
    }

    // Last-chance bin: strongly favor it before opening a new bin.
    if fitting_bins_count == 1 && bin_residual != bin_capacity {
        score -= 30.0;
    }

    // New-bin candidate: make it moderately attractive only when the item
    // is large relative to remaining capacity elsewhere or fleet is small.
    if bin_residual == bin_capacity {
        let new_bin_base = item_size as f64 * 0.6 + 20.0;
        score = new_bin_base + open_bins_count as f64 * 2.0 - (post_residual as f64) * 0.5;
        if fitting_bins_count == 0 {
            score -= 100.0; // no alternative: must open
        }
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Base: prefer minimal post residual (best-fit core).
    score = post_residual as f64;

    // Aggressive 2-step lookahead: reward exact chain fits (item + next item).
    if next_item_size > 0 {
        if next_item_size == post_residual {
            score -= 60.0; // perfect two-step fill
        } else if next_item_size < post_residual {
            let two_step = post_residual as f64 - next_item_size as f64;
            score -= 25.0 * (1.0 - two_step / bin_capacity as f64);
            // Penalize leaving a residual the next item can't use at all
            if two_step > 0.0 && next_item_size as f64 > 0.0 && two_step < next_item_size as f64 {
                score += 10.0; // dead space smaller than next item
            }
        } else {
            // Next item cannot follow into this residual: penalize proportionally
            score += 15.0 * (next_item_size as f64 - post_residual as f64) / bin_capacity as f64;
        }
    }

    // Relative-to-mean coupling: bins with residual near mean are flexible targets.
    let dev = (post_residual as f64 - mean_residual).abs();
    score += 0.15 * dev;

    // Last-chance bin: strongly favor using it rather than opening a new bin.
    if fitting_bins_count == 1 && bin_residual != bin_capacity {
        score -= 40.0;
    }

    // New-bin candidate: only attractive when this item leaves a huge residual
    // that matches the lookahead item, or when no open bin fits well.
    if bin_residual == bin_capacity {
        let lookahead_bonus = if next_item_size > 0 && (item_size + next_item_size) as f64 <= bin_capacity as f64 {
            8.0
        } else {
            0.0
        };
        score += 20.0 - lookahead_bonus;
        // Crowding: with many open bins, discourage new bins.
        score += 2.0 * open_bins_count as f64;
    }

    // Stream progression: late in the stream, be more conservative (avoid new bins).
    let progress = step_index as f64 / total_items.max(1) as f64;
    if bin_residual == bin_capacity {
        score += 15.0 * progress;
    } else {
        score -= 10.0 * progress * (1.0 - post_residual as f64 / bin_capacity as f64);
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Reward tight fits (small post residual) non-linearly.
    let cap = bin_capacity as f64;
    let tightness = 1.0 - (post_residual as f64) / cap;
    score -= 12.0 * tightness * tightness;

    // Penalize dead space: residuals too small for any plausible future item (1..=100).
    if post_residual > 0 && post_residual < 10 {
        score += 25.0;
    }

    // Lookahead: reward bins whose post residual fits the next item exactly-ish.
    if next_item_size > 0 {
        if post_residual >= next_item_size {
            let slack = (post_residual - next_item_size) as f64;
            score -= 8.0 * (1.0 - slack / cap);
        } else {
            score += 6.0; // next item cannot follow here
        }
    }

    // Last-chance bonus: only fitting bin -> strongly prefer using it.
    if fitting_bins_count == 1 {
        score -= 30.0;
    }

    // Time horizon: early in stream, prefer spreading into new bins less;
    // late in stream, consolidate aggressively into existing bins.
    let progress = step_index as f64 / (total_items.max(1) as f64);
    score -= 10.0 * progress * tightness;

    // Global state coupling: many open bins with high mean residual -> prefer
    // filling existing bins; few open bins -> allow opening new ones.
    let new_bin = (bin_residual as f64 - cap).abs() < 0.5;
    if new_bin {
        score += 15.0 * (1.0 - progress);
        score += (open_bins_count as f64).sqrt() * 2.0;
        score -= 0.05 * mean_residual;
        if fitting_bins_count == 0 {
            score -= 40.0; // no existing bin fits: must open
        }
    } else {
        // Favor bins with residual below mean (consolidate fragmented space).
        score += 0.08 * ((bin_residual as f64) - mean_residual);
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;
    let progress = if total_items > 0 { step_index as f64 / total_items as f64 } else { 0.0 };
    let cap = bin_capacity as f64;
    let pr = post_residual as f64;
    let norm_pr = pr / cap;
    // Non-linear polynomial coupling of post_residual with stream progress
    let poly = norm_pr * norm_pr * (1.0 - progress) + norm_pr * progress * (1.0 - norm_pr);
    score += 8.0 * poly;
    // Reward tight fits, more strongly later in the stream
    let tight = 1.0 - norm_pr;
    score -= (2.0 + 6.0 * progress) * tight * tight;
    // Penalize dead space relative to mean residual
    score += 0.3 * (pr - mean_residual).abs() * (0.5 + progress);
    // Last-chance bin bonus
    if fitting_bins_count == 1 {
        score -= 4.0 + 4.0 * progress;
    }
    // Lookahead: favor bins whose post-residual fits the next item
    if next_item_size > 0 && (post_residual as u32) >= next_item_size {
        score -= 3.0 * (next_item_size as f64 / cap);
    } else if next_item_size > 0 && next_item_size > post_residual as u32 && post_residual > 0 {
        score += 2.0 * (1.0 - pr / (next_item_size as f64 + 1.0));
    }
    // Mild penalty for spreading across many bins
    score += 0.05 * open_bins_count as f64 * norm_pr;
    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Harmonic class of the post residual: which quarter of the capacity it lands in.
    let quarter = bin_capacity / 4;
    match post_residual / quarter {
        0 => score -= 25.0,                 // nearly full bin: excellent
        1 => score += 5.0,                  // awkward mid-low residual
        2 => score += 10.0,                 // half-empty: mediocre
        _ => score -= 3.0,                  // large residual: still flexible
    }

    // Dead-space penalty for tiny unusable leftovers (modular classes on post_residual).
    if post_residual < 10 {
        score += 40.0;
    } else if post_residual <= 15 && post_residual % 5 == 0 {
        score += 12.0; // divisible-by-5 slivers pair poorly with common sizes
    }

    // Lookahead coupling: reward if the next item exactly fills the post residual class.
    if next_item_size > 0 {
        if next_item_size == post_residual {
            score -= 60.0; // perfect two-item closure
        } else if next_item_size <= post_residual {
            score -= 10.0;
        } else {
            score += 8.0; // next item cannot use this bin's leftover
        }
        // Harmonic pairing: next item plus leftover hits a multiple of 25
        if (post_residual + next_item_size) % 25 == 0 && post_residual + next_item_size <= bin_capacity {
            score -= 15.0;
        }
    }

    // Last-chance bin before opening a new one: strong bonus to use it.
    if fitting_bins_count == 1 && bin_residual != bin_capacity {
        score -= 30.0;
    }

    // New-bin candidate: prefer it only when current bins fit poorly.
    if bin_residual == bin_capacity {
        let pressure = if fitting_bins_count == 0 { 1.0 } else { 0.0 };
        score += 20.0 - 45.0 * pressure;
        score += (open_bins_count as f64) * 0.5; // mild consolidation preference
    }

    // Progress term: late in the stream, tighten up (favor closing bins).
    let progress = step_index as f64 / (total_items.max(1) as f64);
    score -= progress * (mean_residual - post_residual as f64) * 0.3;

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Strict dead-space avoidance: penalize small unusable gaps.
    if post_residual > 0 {
        let min_item = 1u32;
        if post_residual < min_item {
            score += 1000.0;
        }
        // Penalize gaps too small for typical items (1..=100 range, small items rare).
        if post_residual < 10 {
            score += (10 - post_residual) as f64 * 12.0;
        }
    } else {
        // Perfect fit: strong reward.
        score -= 60.0;
    }

    // Lookahead: reward bins whose leftover can fit the next item.
    if next_item_size > 0 {
        if post_residual >= next_item_size {
            score -= 10.0;
        } else if post_residual > 0 {
            score += 8.0;
        }
    }

    // Last-chance bin: strongly favor using it before opening a new bin.
    if fitting_bins_count == 1 && bin_residual != bin_capacity {
        score -= 25.0;
    }

    // Open-bin pressure: prefer consolidating into fewer bins.
    score += open_bins_count as f64 * 0.5;

    // Prefer tighter bins (lower residual before placement).
    score += (bin_residual as f64 - mean_residual) * 0.15;

    // New-bin candidate: penalize slightly so it wins only when fits are terrible.
    if bin_residual == bin_capacity {
        score += 15.0;
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Aggressive 2-step lookahead: reward when the next item fits exactly into post_residual
    if next_item_size > 0 {
        if next_item_size == post_residual {
            // Perfect 2-chain: strongly favor
            score -= 30.0;
        } else if next_item_size <= post_residual {
            // Next item fits but leaves slack; penalize by leftover after next placement
            let after_next = post_residual - next_item_size;
            score += after_next as f64 * 0.5;
            score -= 5.0;
        } else {
            // Next item won't fit here: penalize proportionally to the mismatch
            let mismatch = (next_item_size - post_residual) as f64;
            score += mismatch * 0.3;
        }
    }

    // Relative tightness vs mean residual: prefer bins that end tighter than average
    score += (mean_residual - post_residual as f64) * 0.4;

    // Last-chance bonus: if this is the only fitting bin, avoid opening a new bin
    if fitting_bins_count == 1 {
        score -= 12.0;
    }

    // Penalize very small dead space that is hard to fill (below minimum item size)
    if post_residual > 0 && post_residual < 10 {
        score += 25.0;
    }

    // New-bin candidate handling: neutral-ish score, only chosen when open bins fit badly
    if bin_residual == bin_capacity {
        // New bin is attractive early in the stream, less so when many bins are open
        let progress = step_index as f64 / (total_items.max(1) as f64);
        score = bin_capacity as f64 * 0.9 + open_bins_count as f64 * 2.0 + progress * 20.0;
        if fitting_bins_count == 1 {
            // Never prefer a new bin when an existing bin is the last chance
            score += 100.0;
        }
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let cap = bin_capacity as f64;
    let post = post_residual as f64;

    // Base: prefer tight fit (low post-residual), scaled by fill fraction.
    let mut score = post * (1.0 + 0.5 * (post / cap));

    // Reward near-perfect fits strongly.
    if post_residual == 0 {
        score -= 50.0;
    } else if post_residual <= 5 {
        score -= 20.0;
    }

    // Penalize dead space that is too small to be useful later.
    if post_residual > 0 && post_residual < 10 {
        score += 15.0;
    }

    // Lookahead: if next item fits in the post-residual, reward this placement.
    if next_item_size > 0 {
        let nxt = next_item_size as f64;
        if next_item_size <= post_residual {
            score -= 8.0 + 4.0 * (nxt / cap);
        } else {
            // Next item would need a new bin from here; penalize wasted space.
            score += 4.0 * (post / cap);
        }
    }

    // Last-chance bin: strongly favor using it to avoid opening a new bin.
    if fitting_bins_count == 1 && bin_residual != bin_capacity {
        score -= 25.0;
    }

    // Many open bins: encourage consolidation (prefer bins with small residual).
    let progress = if total_items > 0 { step_index as f64 / total_items as f64 } else { 0.0 };
    let openness = (open_bins_count as f64).ln_1p();
    score += 0.3 * openness * (bin_residual as f64 / cap) * (0.5 + progress);

    // Mean-residual coupling: when average residual is high, avoid scattering space.
    let dev = bin_residual as f64 - mean_residual;
    score += 0.1 * (dev / cap);

    // New-bin candidate logic: only attractive when no good fit exists.
    if bin_residual == bin_capacity {
        let desperation = if fitting_bins_count == 0 {
            -100.0 // no alternative, must open
        } else {
            // penalize opening new bins proportionally to available alternatives
            10.0 + 12.0 * (fitting_bins_count as f64).ln_1p() + 15.0 * (1.0 - progress)
        };
        score += desperation;
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let progress = step_index as f64 / total_items.max(1) as f64;
    let cap = bin_capacity as f64;
    let pr = post_residual as f64;

    // Base: prefer tight fits (small post_residual), with a smooth
    // non-linear penalty that grows super-linearly for large dead space.
    let mut score = pr + 0.35 * (pr * pr) / cap;

    // Non-linear polynomial coupling of post_residual with stream progress:
    // early in the stream, leftover space is more reusable (discount it);
    // late in the stream, dead space is nearly worthless (amplify it).
    let coupling = 1.0 + 1.2 * progress * progress - 0.6 * (1.0 - progress) * (1.0 - progress);
    score *= coupling;

    // Smooth preference for post_residual that still accommodates the lookahead item.
    if next_item_size > 0 && (next_item_size as f64) <= pr {
        score -= 6.0 + 4.0 * progress;
    }

    // Last-chance bin: strongly favor using it to avoid opening a new bin.
    if fitting_bins_count == 1 {
        score -= 10.0 + 15.0 * progress;
    }

    // Mild penalty when this bin's residual deviates far below the mean
    // (fragmenting small residuals is bad), scaled by number of open bins.
    let dev = (mean_residual - pr) / cap;
    score += 2.0 * dev * dev * (open_bins_count as f64).ln().max(1.0);

    // New-bin candidate: make it attractive only when it beats wasteful fits,
    // via a smooth function of progress and current bin count.
    if bin_residual == bin_capacity {
        let new_bin_cost = 25.0 + 20.0 * progress + 1.5 * (open_bins_count as f64);
        score = new_bin_cost + 0.1 * pr;
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Harmonic class of post_residual: perfect-fit (0), tiny (1..=5),
    // small (6..=15), medium (16..=35), large (36..=60), huge (>60).
    let class_penalty: f64 = if post_residual == 0 {
        -50.0 // perfect fit: always reward heavily
    } else if post_residual <= 5 {
        -10.0 // near-perfect, tiny dead space
    } else if post_residual <= 15 {
        8.0   // small dead space, hard to reuse
    } else if post_residual <= 35 {
        20.0  // medium dead space
    } else if post_residual <= 60 {
        30.0  // large dead space
    } else {
        40.0  // huge waste: item left most of the bin empty
    };
    score += class_penalty;

    // Lookahead: does next_item_size fit into post_residual?
    if next_item_size > 0 && post_residual > 0 {
        if next_item_size <= post_residual {
            // Chainable residual: reward proportionally to how well it matches
            let tight = 1.0 - (post_residual - next_item_size) as f64 / post_residual as f64;
            score -= 15.0 + 10.0 * tight;
        } else {
            // Next item cannot use this residual: penalize dead space more
            score += 6.0;
        }
    }

    // Harmonic modulo classes on post_residual (residuals divisible by
    // common item sizes are more reusable).
    if post_residual % 10 == 0 {
        score -= 4.0;
    } else if post_residual % 5 == 0 {
        score -= 2.0;
    }

    // Last chance bin: if this is the only bin that fits, strongly prefer
    // using it over opening a new bin (unless the fit is terrible).
    if fitting_bins_count == 1 && bin_residual < bin_capacity {
        score -= 12.0;
        if post_residual <= 20 {
            score -= 10.0; // still a decent fit, definitely use it
        }
    }

    // Penalize spreading across many bins when mean residual is already low
    // (prefer consolidating into tight bins).
    if bin_residual < bin_capacity {
        let tightness = 1.0 - bin_residual as f64 / bin_capacity as f64;
        score -= 5.0 * tightness;
    }

    // New-bin candidate (empty bin): make it attractive only when no open
    // bin offers a good fit. Base cost of opening a bin:
    if bin_residual == bin_capacity {
        score += 25.0;
        // If mean residual across open bins is large, discourage new bin
        score += mean_residual * 0.3;
        // Late in the stream, prefer reusing bins (fewer total bins)
        let progress = step_index as f64 / total_items.max(1) as f64;
        score += 15.0 * progress;
    }

    // Mild penalty for opening bins when many are already open and loose.
    if open_bins_count > 0 && mean_residual > 40.0 && bin_residual == bin_capacity {
        score += 20.0;
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Strict dead-space avoidance: penalize small unusable gaps.
    // A post_residual that is too small to hold even the smallest item (1)
    // is pure waste; gaps below ~10 are nearly dead too.
    if post_residual == 0 {
        score -= 40.0; // perfect fit: highly desirable
    } else if post_residual < 10 {
        score += 25.0; // dead space: nearly unusable gap
    } else if post_residual < 20 {
        score += 12.0; // risky small gap
    }

    // Reward tight fits relative to item size.
    let fit_ratio = item_size as f64 / bin_residual.max(1) as f64;
    score -= 15.0 * fit_ratio;

    // Open-bin pressure: when many bins are open, prefer filling existing bins
    // rather than opening new ones. Penalize the new-bin candidate.
    if bin_residual == bin_capacity {
        score += 30.0 + 3.0 * open_bins_count as f64;
    } else {
        score -= 2.0 * open_bins_count.min(20) as f64;
    }

    // Last-chance bonus: if this is the only fitting bin, strongly favor it
    // to avoid opening a new bin.
    if fitting_bins_count == 1 && bin_residual != bin_capacity {
        score -= 20.0;
    }

    // Lookahead: if next item fits in the post residual, reward this placement.
    if next_item_size > 0 && (post_residual as f64) >= next_item_size as f64 {
        score -= 8.0;
    }
    // If next item would leave this bin with dead space, mild penalty.
    if next_item_size > 0 && post_residual > 0 && (post_residual as u32) < next_item_size && post_residual < 10 {
        score += 10.0;
    }

    // Mean residual coupling: prefer bins below mean residual (filling fuller bins)
    let dev = mean_residual - bin_residual as f64;
    score += 0.3 * dev;

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Perfect fit for the NEXT item is the jackpot: reserve this bin.
    if next_item_size > 0 && post_residual == next_item_size {
        score -= 40.0;
    }
    // Near-perfect chain fit (next item leaves a tiny remainder).
    if next_item_size > 0 && post_residual > next_item_size {
        let chain = post_residual - next_item_size;
        if chain <= 5 {
            score -= 12.0;
        } else if chain <= 15 {
            score -= 5.0;
        }
    }
    // Penalize dead space: residuals too small for any future item.
    let min_future = if next_item_size > 0 { next_item_size.min(10) } else { 10 };
    if post_residual > 0 && post_residual < min_future {
        score += 15.0;
    }
    // Reward tight fits relative to bin capacity.
    let tightness = 1.0 - (post_residual as f64 / bin_capacity as f64);
    score -= tightness * 8.0;
    // Compare against mean residual: filling a bin above average is good.
    score -= (mean_residual - post_residual as f64) * 0.15;
    // Last-chance bin bonus: avoid opening a new bin when this is the only fit.
    if fitting_bins_count == 1 && bin_residual != bin_capacity {
        score -= 10.0;
    }
    // Penalize wasting a fresh bin unless the item is large.
    if bin_residual == bin_capacity {
        let waste = bin_capacity - item_size;
        score += (waste as f64) * 0.3;
        if item_size >= 60 {
            score -= 20.0;
        }
    }
    // Late in the stream, prefer closing bins tightly.
    let progress = step_index as f64 / total_items.max(1) as f64;
    score -= progress * (bin_capacity - post_residual) as f64 * 0.05;

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Reward near-perfect fits strongly (non-linear).
    let fill_ratio = 1.0 - (post_residual as f64 / bin_capacity as f64);
    score -= 18.0 * fill_ratio * fill_ratio;

    // Penalize small unusable post residuals (dead space) but reward exact fit.
    if post_residual > 0 && post_residual < 10 {
        score += 6.0;
    }
    if post_residual == 0 {
        score -= 25.0;
    }

    // Last chance bin: strongly prefer using it before opening a new bin.
    if fitting_bins_count == 1 && bin_residual >= item_size {
        score -= 15.0;
    }

    // Lookahead: reward leaving residual that can host the next item exactly.
    if next_item_size > 0 {
        if post_residual >= next_item_size {
            let slack = post_residual - next_item_size;
            score -= 8.0 * (1.0 - slack as f64 / bin_capacity as f64);
        } else {
            score += 3.0;
        }
    }

    // Time horizon: late in the stream, consolidate aggressively into open bins.
    let progress = step_index as f64 / total_items.max(1) as f64;
    score += 10.0 * progress * (open_bins_count as f64 / (mean_residual / bin_capacity as f64).max(1.0));

    // New-bin candidate: prefer it only when few bins fit and mean residual is small.
    if bin_residual == bin_capacity {
        let scarcity = (fitting_bins_count == 0) as i32 as f64;
        let tight_state = (mean_residual / bin_capacity as f64) < 0.15;
        if scarcity > 0.5 || (tight_state && progress > 0.5) {
            score -= 20.0;
        } else {
            score += 30.0 + 20.0 * (1.0 - progress);
        }
    }

    // Mild preference for bins with residuals just above the item (tightness coupling).
    let tightness = (bin_residual as f64 - item_size as f64) / bin_capacity as f64;
    score += 5.0 * tightness;

    // Global load balancing: penalize placing into bins when mean residual is high and this bin is wasteful.
    if (bin_residual as f64) > mean_residual + item_size as f64 {
        score += 2.0;
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let pr = post_residual as f64;
    let cap = bin_capacity as f64;
    let x = pr / cap; // normalized post residual
    let progress = if total_items > 0 { step_index as f64 / total_items as f64 } else { 0.0 };

    // Base: penalize leftover space, superlinearly (dead space is bad).
    let mut score = pr * (1.0 + 1.5 * x * x);

    // Smooth stream-progress coupling: later in the stream, waste matters more.
    score += 8.0 * x * progress;

    // Coupling with mean residual: prefer bins whose residual deviates from mean
    // in a way that tightens the population (place into bins with small residual).
    let dev = (bin_residual as f64 - mean_residual) / cap;
    score += 4.0 * dev * (1.0 - progress);

    // Lookahead: reward if next item fits the post residual (smooth affinity).
    if next_item_size > 0 {
        let gap = (pr - next_item_size as f64) / cap;
        let fit_affinity = 1.0 / (1.0 + (gap * 6.0).exp());
        score -= 6.0 * fit_affinity;
    } else {
        // Last item: strongly prefer exact fill.
        score -= 5.0 * (1.0 - x) * (1.0 - x);
    }

    // Scarcity bonus: if this is the only fitting bin, strongly favor it.
    if fitting_bins_count == 1 {
        score -= 12.0;
    } else {
        // Mild competition scaling: more fitting bins -> less urgency each.
        score += (fitting_bins_count as f64).ln().max(0.0);
    }

    // New-bin candidate: make empty bins moderately attractive only when
    // existing residuals are poor; penalize opening bins early.
    if bin_residual == bin_capacity {
        let crowd = open_bins_count as f64;
        let avg_waste = mean_residual / cap;
        let quality = (avg_waste - x).abs();
        score = 10.0 + 3.0 * crowd * (1.0 - progress) + 15.0 * quality * progress;
        if fitting_bins_count <= 2 {
            score -= 8.0 * progress;
        }
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Harmonic class of the post-residual: quantize leftover space into
    // capacity-fraction classes (C/8 granularity). Small classes are good
    // (tight fit), large classes are bad (dead space).
    let cap = bin_capacity as f64;
    let eighth = cap / 8.0;
    let pr = post_residual as f64;
    let class = (pr / eighth).floor().min(8.0); // 0..8 harmonic class
    // Class-dependent reward: lower classes (tight fits) get subtracted.
    score -= (8.0 - class) * 3.0;

    // Perfect-fit bonus: post_residual in {0, 5, 10} -> nearly no waste.
    if post_residual <= 5 {
        score -= 40.0;
    } else if post_residual <= 10 {
        score -= 20.0;
    }

    // Modulo-16 arithmetic on post_residual: residues near 0 mod 16 tend to
    // align with common item sizes; reward them.
    let m = post_residual % 16;
    if m == 0 {
        score -= 8.0;
    } else if m >= 12 {
        score -= 4.0;
    } else if m <= 3 {
        score -= 2.0;
    }

    // Lookahead: if the next item fits exactly in the post-residual,
    // strongly favor this bin (chain packing).
    if next_item_size > 0 {
        if next_item_size == post_residual {
            score -= 60.0;
        } else if next_item_size <= post_residual {
            // Next item fits: penalize proportionally to leftover-after-next.
            let after_next = post_residual - next_item_size;
            score -= (after_next as f64).min(30.0);
            // Integer-division threshold: next item occupies >= half of post-residual
            if next_item_size * 2 >= post_residual {
                score -= 10.0;
            }
        } else {
            // Next item cannot use this residual: penalize large residuals.
            score += pr * 0.15;
        }
    }

    // Last-chance bin: if this is the only bin that fits, avoid opening a
    // new bin unless the fit is terrible.
    if fitting_bins_count == 1 && bin_residual != bin_capacity {
        score -= 25.0;
        // But if residual class is huge (>= half capacity wasted), soften.
        if class >= 4.0 {
            score += 15.0;
        }
    }

    // New-bin candidate handling: an empty bin has residual == capacity.
    if bin_residual == bin_capacity {
        // Opening a new bin is only attractive when no tight fit exists.
        // Base penalty keeps it behind decent fits.
        score += 30.0;
        // If the item is small relative to capacity, opening a new bin wastes
        // capacity; penalize more.
        if (item_size as f64) < cap * 0.4 {
            score += 20.0;
        }
        // Late in the stream, prefer consolidating into open bins.
        let progress = step_index as f64 / total_items.max(1) as f64;
        score += progress * 15.0;
        // Many open bins with low mean residual -> consolidation is fine.
        if mean_residual < cap * 0.2 && open_bins_count > 2 {
            score += 10.0;
        }
    } else {
        // Existing bin: reward using bins whose residual is above the mean
        // (drain the fat bins first, keep tight bins tight).
        if pr as f64 > mean_residual {
            score -= 5.0;
        }
    }

    // Mild global pressure: when many bins are open, prefer tightening fits.
    score -= (open_bins_count as f64).min(20.0) * 0.5;

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let score = 0.0;
    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Reward tight fits: post_residual near 0 is best.
    score -= 40.0 * (-post_residual as f64 / 20.0).exp();

    // 2-step lookahead: if next item exactly fills post_residual, strong reward.
    if next_item_size > 0 {
        let gap = (post_residual as i64 - next_item_size as i64).abs() as f64;
        if post_residual == next_item_size {
            score -= 60.0;
        } else if post_residual >= next_item_size {
            // next item fits here after this one: reward proportionally to closeness
            score -= 35.0 * (-gap / 25.0).exp();
        } else {
            // next item won't fit after placement: penalize wasted potential
            score += 8.0 * (gap / 50.0);
        }
    }

    // Compare post_residual to mean residual: leaving more than average is wasteful.
    score += 0.25 * (post_residual as f64 - mean_residual).max(0.0);

    // Last-chance bin: strongly prefer using it to avoid opening a new bin.
    if fitting_bins_count == 1 && bin_residual >= item_size && bin_residual != bin_capacity {
        score -= 30.0;
    }

    // New-bin candidate: penalize so it's only chosen when fits are very poor.
    if bin_residual == bin_capacity {
        score += 45.0;
        // Early in stream, slightly more willing to open bins.
        let progress = if total_items > 0 { step_index as f64 / total_items as f64 } else { 0.0 };
        score -= 15.0 * (1.0 - progress);
    }

    // Prefer denser bins (small residual before placement) to keep others flexible.
    score += 0.1 * (bin_residual as f64 - item_size as f64);

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Progress through the stream: later => prefer closing bins tightly.
    let progress = if total_items > 0 { step_index as f64 / total_items as f64 } else { 0.0 };

    // Fractional fill of this bin after placement.
    let fill = 1.0 - (post_residual as f64 / bin_capacity as f64);

    // Reward high fill more strongly as stream progresses (non-linear).
    score -= fill * fill * (30.0 + 40.0 * progress);

    // Penalize small dead space less than medium dead space:
    // residuals that still fit the next item are valuable.
    if next_item_size > 0 {
        if post_residual >= next_item_size {
            // Lookahead bonus: residual can host the next item.
            let slack = (post_residual - next_item_size) as f64;
            score -= 12.0 * (1.0 - slack / bin_capacity as f64) * (1.0 - 0.5 * progress);
        } else {
            // Residual too small for next item: penalize proportionally to uselessness.
            score += 8.0 * (1.0 - post_residual as f64 / next_item_size as f64);
        }
    }

    // Last-chance bin: strongly favor using it to avoid opening a new bin.
    if fitting_bins_count == 1 && bin_residual >= item_size {
        score -= 25.0 * (1.0 + progress);
    }

    // Many open bins => encourage consolidation into existing bins.
    let pressure = (open_bins_count as f64 / (open_bins_count as f64 + 5.0)).sqrt();
    score -= 10.0 * pressure * fill;

    // Global mean residual coupling: if this bin's post residual is below mean,
    // it is tighter than average; reward tightening.
    let diff = mean_residual - post_residual as f64;
    score -= 0.15 * diff * (1.0 - progress * 0.5);

    // Penalize leaving exactly awkward residuals (e.g., tiny unusable gaps 1..9).
    if post_residual > 0 && post_residual < 10 {
        score += 15.0;
    }

    // New-bin candidate handling: an empty bin should only win when no open bin
    // gives a good fit. Penalize opening a new bin unless current bins are crowded
    // or the fit is terrible.
    if bin_residual == bin_capacity {
        let crowded = open_bins_count == 0
            || mean_residual < item_size as f64 * 0.9
            || post_residual as f64 > mean_residual + 0.5 * bin_capacity as f64;
        if crowded {
            score -= 20.0;
        } else {
            score += 30.0 + 20.0 * (1.0 - progress);
        }
    }

    // Mild penalty for very large items into nearly full bins (fragmentation risk).
    if item_size > 60 && bin_residual < item_size + 10 && bin_residual >= item_size {
        score += 5.0;
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let cap = bin_capacity as f64;
    let pr = post_residual as f64;
    let progress = step_index as f64 / total_items.max(1) as f64;
    let tightness = 1.0 - (pr / cap);

    // Base: penalize wasted residual, with a smooth non-linear (quadratic) waste term.
    let mut score = pr + 0.35 * (pr * pr) / cap;

    // Non-linear coupling: waste matters more as the stream progresses (quartic ramp).
    let ramp = progress * progress * (3.0 - 2.0 * progress);
    score += 2.0 * ramp * (pr * pr) / cap;

    // Reward tight fits via smooth saturating tightness term.
    score -= 3.0 * tightness * tightness * tightness;

    // Dead-space penalty: residuals too small for the smallest plausible item,
    // penalized smoothly via a logistic-like term on post_residual.
    let dead = 1.0 / (1.0 + (pr / 8.0).exp());
    score += 6.0 * dead;

    // Lookahead: if next item fits the post-residual, reward this bin.
    if next_item_size > 0 {
        let fits_next = if (pr >= next_item_size as f64) { 1.0 } else { 0.0 };
        score -= 4.0 * fits_next * (1.0 - progress);
        // Smooth mismatch penalty when next item nearly fits.
        let gap = (pr - next_item_size as f64).abs();
        score += 0.5 * gap / cap;
    }

    // Last-chance bonus: strongly prefer using the only fitting bin.
    if fitting_bins_count == 1 && bin_residual != bin_capacity {
        score -= 8.0;
    }

    // Scarcity pressure: many open bins -> prefer consolidation (penalize spreading).
    let scarcity = (open_bins_count as f64).ln() / (1.0 + (open_bins_count as f64).ln());
    score += 1.5 * scarcity * (pr / cap);

    // New-bin candidate: neutral base plus mild preference early, penalty late.
    if bin_residual == bin_capacity {
        score = cap * 0.6 + 2.0 * (1.0 - progress) - 3.0 * progress;
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // --- Harmonic class of the residual space after placement ---
    // Partition the capacity into 5 harmonic bands (0..20, 20..40, 40..60, 60..80, 80..100).
    let band = post_residual / 20; // 0..=5
    let band_center = (band * 20 + 10) as f64;

    // Reward residuals near a "harmonic" band center (clean, reusable classes),
    // penalize residuals in awkward in-between zones (dead space).
    let off_center = (post_residual as f64 - band_center).abs();
    score += 0.6 * off_center;

    // --- Lookahead coupling: does the next item land in this residual class? ---
    if next_item_size > 0 {
        if next_item_size <= post_residual {
            // Perfect reuse: strongly reward, scaled by how snugly it fits.
            let snug = 1.0 - (post_residual - next_item_size) as f64 / 100.0;
            score -= 12.0 + 10.0 * snug;
            // Extra reward when the pair leaves a harmonic residual again.
            let post2 = post_residual - next_item_size;
            if post2 % 10 == 0 {
                score -= 4.0;
            }
        } else {
            // Next item cannot use this bin's leftover: penalize by wasted fraction.
            let waste = (post_residual as f64) / bin_capacity as f64;
            score += 6.0 * waste;
        }
    } else {
        // Last item: prefer tightest fit only.
        score += 0.0;
    }

    // --- Integer-division threshold on post_residual: micro-residuals are dead space ---
    if post_residual < 10 {
        score += 15.0; // unusable sliver
    } else if post_residual <= 20 {
        score += 4.0;  // low utility class
    }

    // --- Last-chance bin: if this is the only bin that fits, avoid opening a new one ---
    if fitting_bins_count == 1 && bin_residual < bin_capacity {
        score -= 18.0;
    }

    // --- New-bin candidate handling ---
    if bin_residual == bin_capacity {
        // Fresh bin: attractive when current open bins are crowded or the fit is loose.
        let crowding = open_bins_count as f64 / (open_bins_count as f64 + mean_residual / 20.0 + 1.0);
        score = 100.0 - 20.0 * crowding;
        // Opening a new bin is good if next item is large and would fragment an existing bin.
        if next_item_size > 60 {
            score -= 8.0;
        }
        // Discourage opening bins early in the stream when reuse is still cheap.
        let progress = step_index as f64 / (total_items.max(1) as f64);
        score += 10.0 * (1.0 - progress);
    }

    // --- Modulo arithmetic: residuals divisible by 10 align with typical item classes ---
    if post_residual % 10 == 0 && post_residual > 0 {
        score -= 3.0;
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Strict dead-space avoidance: residuals that are too small to be useful
    // for typical items are heavily penalized.
    let min_item = 1u32;
    if post_residual < min_item.max(1) {
        score += 1000.0; // perfect fit, reward strongly
        score -= 1000.0;
    }
    // Penalize small "dead" gaps: post_residual in [1, 10) is nearly unusable
    if post_residual > 0 && post_residual < 10 {
        score += (10 - post_residual) as f64 * 8.0;
    }
    // Medium dead space (10..20) moderately penalized
    if post_residual >= 10 && post_residual < 20 {
        score += (20 - post_residual) as f64 * 2.0;
    }

    // Reward tight fits (small post_residual relative to item)
    if item_size > 0 {
        score -= (item_size as f64) / (bin_residual as f64) * 6.0;
    }

    // Lookahead: if next item can use the post_residual, reward this bin
    if next_item_size > 0 && post_residual >= next_item_size {
        score -= 10.0;
    }
    // If next item cannot fit in the post gap, penalize slightly
    if next_item_size > 0 && post_residual > 0 && post_residual < next_item_size {
        score += 5.0;
    }

    // Open bins pressure: with many open bins, prefer consolidating into
    // existing bins rather than opening new ones.
    score += open_bins_count as f64 * 0.5;

    // New-bin candidate handling: an empty bin has high post_residual;
    // penalize it unless existing bins would create dead space.
    if bin_residual == bin_capacity {
        score += 15.0 + mean_residual * 0.3;
    }

    // Last-chance bin: strongly favor using the only bin that fits
    if fitting_bins_count == 1 && bin_residual != bin_capacity {
        score -= 12.0;
    }

    // Mean residual coupling: bins below mean residual are already tight,
    // prefer filling them fully.
    if (bin_residual as f64) < mean_residual {
        score -= 3.0;
    }

    // Stream progression: late in the stream, be more conservative about
    // opening bins and more aggressive about tight fits.
    let progress = step_index as f64 / (total_items.max(1) as f64);
    score += post_residual as f64 * progress * 0.3;

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Exact fit: huge reward.
    if post_residual == 0 {
        score -= 1000.0;
    }

    // 2-step lookahead: if the NEXT item exactly fills this bin's post-residual,
    // strongly favor this bin (chained perfect packing).
    if next_item_size > 0 && post_residual > 0 {
        if next_item_size == post_residual {
            score -= 900.0;
        } else if next_item_size < post_residual {
            // Next item fits after this one: mild reward proportional to leftover after both.
            let after_two = post_residual - next_item_size;
            score -= 0.8 * after_two as f64;
            if after_two == 0 {
                score -= 250.0; // two-item perfect chain
            }
        } else {
            // Next item cannot use the leftover: penalize dead space creation.
            score += 0.5 * (next_item_size - post_residual) as f64;
        }
    }

    // Reward tight fits relative to residual (small post_residual is good).
    let fill_ratio = item_size as f64 / bin_residual.max(1) as f64;
    score -= 60.0 * fill_ratio;

    // Penalize bins whose residual deviates far from mean (prefer typical bins,
    // keep outlier-large residuals available for big items).
    let dev = (bin_residual as f64 - mean_residual).abs();
    score += 0.3 * dev;

    // Last-chance bin: avoid opening a new bin if this is the only one that fits.
    if fitting_bins_count == 1 && bin_residual != bin_capacity {
        score -= 120.0;
    }

    // New-bin candidate: penalize moderately so open bins are preferred,
    // unless this is an exact fit situation already handled above.
    if bin_residual == bin_capacity {
        score += 150.0;
        // Opening a bin is more attractive late in the stream when open bins are fragmented.
        let progress = step_index as f64 / total_items.max(1) as f64;
        score -= 40.0 * progress;
        if open_bins_count == 0 {
            score -= 500.0;
        }
        // If next item is large and this item is small, a fresh bin is fine.
        if next_item_size > 60 && item_size < 30 {
            score -= 60.0;
        }
    }

    // Slight preference for denser bins (low residual) overall.
    score += 0.1 * bin_residual as f64;

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let progress = step_index as f64 / total_items.max(1) as f64;
    let mut score = post_residual as f64;

    // Reward tight fits: larger items consume more of the bin's value.
    score -= (item_size as f64 / bin_capacity as f64) * 20.0;

    // Penalize residuals that deviate badly from the global mean (fragmentation signal).
    let dev = post_residual as f64 - mean_residual;
    if dev > 0.0 {
        score += dev * 0.12;
    } else {
        score += dev.abs() * 0.04;
    }

    // Lookahead coupling: favor bins whose leftover can host the next item.
    if next_item_size > 0 {
        if post_residual >= next_item_size {
            score -= 8.0;
        } else {
            score += (next_item_size as f64 - post_residual as f64) * 0.15;
        }
    }

    // Last-chance bin before opening a new one: strong incentive to use it.
    if fitting_bins_count == 1 {
        score -= 12.0;
    }

    // New-bin candidate: penalize mildly; penalty shrinks for large items
    // (an empty bin wastes less when the item nearly fills it) and later in stream.
    if bin_residual == bin_capacity {
        let item_frac = item_size as f64 / bin_capacity as f64;
        score += 15.0 * (1.0 - 0.5 * item_frac) + 10.0 * (1.0 - progress);
    } else {
        score -= 3.0;
    }

    // Mild pressure to prefer already-open bins as bin count grows.
    score += open_bins_count as f64 * 0.2;

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let progress = step_index as f64 / total_items as f64;
    let pr = post_residual as f64;
    let cap = bin_capacity as f64;
    let norm_pr = pr / cap;

    // Base: penalize wasted residual, but weight shrinks as stream progresses
    // (late in the stream, tight packing matters more -> amplify waste penalty)
    let mut score = pr * (1.0 + 0.8 * progress * progress);

    // Non-linear coupling: quadratic term in normalized residual, modulated by progress
    score += 12.0 * norm_pr * norm_pr * (0.5 + progress);

    // Favor bins whose residual tightly matches the item (smooth sigmoid-like fit term)
    let fit_ratio = item_size as f64 / bin_residual as f64;
    score -= 6.0 * (fit_ratio * fit_ratio) * (1.0 - progress);

    // Reward using bins with below-mean residual (compact bins first), smooth coupling
    score += 0.05 * (mean_residual - bin_residual as f64);

    // Last-chance bin: strong discount, stronger early when opening bins is costly
    if fitting_bins_count == 1 {
        score -= 10.0 * (1.0 - 0.5 * progress);
    }

    // Lookahead: if the post-residual can fit the next item, reward this placement
    if next_item_size > 0 && post_residual >= next_item_size {
        score -= 4.0 * (next_item_size as f64 / cap) * (1.0 + progress);
    } else if next_item_size > post_residual {
        // Next item won't fit here; mild penalty for leaving a nearly-useless gap
        score += 3.0 * (1.0 - pr / (next_item_size as f64 + 1.0)).max(0.0);
    }

    // New-bin candidate: penalize mildly, more when many bins are open and progress is low
    if bin_residual == bin_capacity {
        score += 8.0 + 2.0 * (open_bins_count as f64) * (1.0 - progress);
    }

    // Smooth interaction: small-bin-residual bins get priority late in stream
    score -= 5.0 * progress * (1.0 - norm_pr) * (1.0 - norm_pr);

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let cap = bin_capacity as f64;
    let mut score = post_residual as f64;

    // Harmonic class of post_residual: which quarter of the capacity does it fall in?
    let quarter = bin_capacity / 4;
    let half = bin_capacity / 2;
    let post = post_residual;

    // Reward tight fits: post_residual in the smallest harmonic band gets strong discount.
    if post < quarter / 2 {
        score -= 40.0;
    } else if post < quarter {
        score -= 18.0;
    } else if post < half {
        score -= 5.0;
    } else {
        score += 8.0; // large dead space penalty
    }

    // Modulo-class bonus: residuals that are multiples of common item sizes (divisible by 5 or 10)
    // are more reusable by future items.
    if post % 10 == 0 && post > 0 {
        score -= 12.0;
    } else if post % 5 == 0 && post > 0 {
        score -= 6.0;
    }

    // Exact fill is perfect.
    if post == 0 {
        score -= 60.0;
    }

    // Lookahead coupling: if next item fits exactly into post_residual, big reward.
    if next_item_size > 0 {
        if next_item_size == post {
            score -= 55.0;
        } else if next_item_size < post {
            // next item fits: bonus proportional to how well it fills remainder
            let next_fit = (post - next_item_size) as f64;
            score -= 15.0 * (1.0 - next_fit / cap);
        } else {
            // next item cannot use this residual: penalize proportionally
            score += 6.0;
        }
    }

    // Last-chance bin: strongly favor using the only bin that fits.
    if fitting_bins_count == 1 && bin_residual < bin_capacity {
        score -= 35.0;
    }

    // New-bin candidate handling: empty bin should only win when open bins are fragmented.
    if bin_residual == bin_capacity {
        // neutral-ish base for fresh bin; penalize more when many bins are open and mean residual is usable
        score += 25.0;
        if open_bins_count > 0 {
            score += 10.0 * (mean_residual / cap).min(1.0);
        }
        if fitting_bins_count == 0 {
            score -= 100.0; // no alternative, must open
        }
    }

    // Stream progression: early on, be pickier (preserve flexibility); late, consolidate.
    let progress = step_index as f64 / total_items.max(1) as f64;
    score -= 10.0 * progress * (1.0 - post as f64 / cap);

    // Prefer bins below mean residual (consolidating fuller bins first).
    score += 0.15 * (post as f64 - mean_residual);

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Base: prefer tight fits (small post_residual) — non-linear reward.
    let pr = post_residual as f64;
    score = pr * (1.0 + 0.02 * pr / bin_capacity as f64);

    // Strict dead-space avoidance: residuals that are too small to ever
    // hold a plausible item (min size 1, but realistically < 12) are toxic.
    if post_residual > 0 && post_residual < 12 {
        score += 45.0 - 3.0 * post_residual as f64; // gap of 1 => +42, gap of 11 => +12
    }

    // Perfect fit bonus.
    if post_residual == 0 {
        score -= 30.0;
    }

    // Reward bins whose residual is "shaped" for the next item (lookahead k=2).
    if next_item_size > 0 {
        if post_residual == next_item_size {
            score -= 25.0;
        } else if post_residual > next_item_size {
            score -= 0.15 * next_item_size as f64;
        } else {
            // post_residual too small for next item: mild penalty scaled by
            // how much of the next item is wasted.
            score += 0.2 * (next_item_size - post_residual) as f64;
        }
    }

    // Last-chance bin: if this is the only bin that fits, strongly favor it
    // over opening a new bin.
    if fitting_bins_count == 1 && bin_residual != bin_capacity {
        score -= 20.0;
    }

    // Open-bin pressure: with many open bins, discourage opening new ones
    // (penalize the new-bin candidate) and encourage consolidation.
    if bin_residual == bin_capacity {
        // New-bin candidate: base cost plus pressure from open bins.
        score = bin_capacity as f64 * 1.1 + 8.0 * open_bins_count as f64;
        // Early in the stream, opening bins is cheaper (diversity helps).
        let progress = step_index as f64 / total_items.max(1) as f64;
        score -= 15.0 * (1.0 - progress);
        // If the item fits badly everywhere, new bin becomes attractive.
        if fitting_bins_count > 0 {
            let worst_gap = bin_capacity as f64 - item_size as f64;
            if worst_gap < 12.0 {
                score -= 40.0; // item is big; fresh bin wastes less
            }
        }
    } else {
        // Existing bin: slight reward when many bins are open (consolidate).
        score -= 0.3 * open_bins_count as f64;
        // Prefer bins below mean residual (filling emptier bins).
        score += 0.1 * (bin_residual as f64 - mean_residual);
    }

    // Stream-progress modulation: late in the stream, avoid leaving any gap.
    let progress = step_index as f64 / total_items.max(1) as f64;
    if bin_residual != bin_capacity {
        score -= 10.0 * progress * (1.0 - pr / bin_capacity as f64);
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Core: reward when the next item exactly fills the resulting residual (2-step lookahead).
    if next_item_size > 0 {
        let next = next_item_size as f64;
        let post = post_residual as f64;
        let gap = (post - next).abs();
        if post >= next {
            // Next item fits after this placement: strongly reward tight chaining.
            score -= 40.0 * (1.0 - gap / bin_capacity as f64);
            if gap == 0.0 {
                score -= 60.0; // perfect 2-step fill
            }
        } else {
            // Next item won't fit here: penalize leaving awkward residual.
            score += 10.0 * (1.0 - post / bin_capacity as f64);
        }
    } else {
        // Last item: reward closing the bin as tightly as possible.
        score -= 30.0 * (1.0 - post_residual as f64 / bin_capacity as f64);
    }

    // Reward tight fits relative to mean residual (waste minimization).
    let mean_gap = (post_residual as f64 - mean_residual).abs();
    score -= 5.0 / (1.0 + mean_gap);

    // Last-chance bin: strong bonus to use it rather than open a new bin.
    if fitting_bins_count == 1 && bin_residual >= item_size {
        score -= 25.0;
    }

    // New-bin candidate: neutral-ish baseline; penalize slightly unless item is huge
    // relative to capacity (then opening fresh can beat a poor fit).
    if bin_residual == bin_capacity {
        let tightness = item_size as f64 / bin_capacity as f64;
        if tightness > 0.7 {
            score -= 20.0 * (tightness - 0.7) / 0.3; // prefer fresh bin for big items
        } else {
            score += 15.0; // discourage opening new bins for small items
        }
    }

    // Mild progression pressure: as stream advances, prefer consolidating.
    let progress = step_index as f64 / (total_items.max(1) as f64);
    score -= 5.0 * progress * (1.0 - post_residual as f64 / bin_capacity as f64);

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Strongly reward near-perfect fits (non-linear tightening).
    let fit_ratio = item_size as f64 / bin_residual as f64;
    score -= (fit_ratio * fit_ratio) * 30.0;

    // Penalize dead space that is too small to ever be useful again
    // (residual < 10 can hold nothing from a 1..100 stream).
    if post_residual > 0 && post_residual < 10 {
        score += 25.0;
    }

    // Lookahead: reward bins whose leftover can host the next item,
    // scaled by how well the next item would fill that leftover.
    if next_item_size > 0 && post_residual >= next_item_size {
        let next_fill = next_item_size as f64 / post_residual as f64;
        score -= 8.0 + 20.0 * next_fill * next_fill;
    } else if next_item_size > 0 && next_item_size <= bin_residual && post_residual < next_item_size {
        // This bin could have served the next item but we'd waste that chance.
        score += 6.0;
    }

    // Last-chance bonus: if this is the only fitting bin, strongly prefer it
    // over opening a new bin (unless the fit is terrible).
    if fitting_bins_count == 1 && bin_residual < bin_capacity {
        score -= 15.0 + 0.1 * (item_size as f64);
    }

    // New-bin candidate logic: an empty bin is a fresh resource.
    if bin_residual == bin_capacity {
        // Base cost of opening a new bin, shrinking late in the stream
        // when there is less future to amortize.
        let progress = if total_items > 0 { step_index as f64 / total_items as f64 } else { 0.0 };
        let mut open_cost = 40.0 * (1.0 - 0.5 * progress);
        // Cheaper to open a new bin when many bins are already open and
        // fragmented (high mean residual spread means poor fits likely).
        open_cost -= 2.0 * (open_bins_count as f64).sqrt();
        if mean_residual > 0.0 && (mean_residual - item_size as f64).abs() < 5.0 {
            open_cost += 10.0; // an open bin is a near-perfect fit; don't open
        }
        // Prefer new bin if the item is huge relative to typical residuals.
        if item_size as f64 > mean_residual + 15.0 {
            open_cost -= 12.0;
        }
        score += open_cost;
        // New bin has zero dead-space penalty by construction.
        score -= 5.0;
    } else {
        // Mild reward for using already-open bins to keep bin count low.
        score -= 3.0;
        // Penalize placing into bins whose residual deviates wildly from mean
        // (keeps residual distribution balanced for future items).
        let dev = (bin_residual as f64 - mean_residual).abs();
        score += 0.05 * dev;
    }

    // Slight time pressure: early on, keep flexibility (avoid ultra-tight fits
    // that strand bins); later, consolidation matters more.
    let progress = if total_items > 0 { step_index as f64 / total_items as f64 } else { 0.0 };
    score -= 10.0 * progress * (1.0 - post_residual as f64 / bin_capacity as f64);

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let progress = step_index as f64 / total_items.max(1) as f64;
    let pr = post_residual as f64;
    let cap = bin_capacity as f64;
    let norm_pr = pr / cap;

    // Base: prefer tight fits (low post residual), non-linearly penalized
    let mut score = pr * (1.0 + 0.8 * norm_pr * norm_pr);

    // Polynomial coupling of post_residual with stream progress:
    // early on tolerate larger residuals; late in stream demand tightness
    let progress_coupling = 1.0 - 0.9 * progress * (3.0 - 2.0 * progress) * progress;
    score *= progress_coupling;

    // Reward near-exact fills
    let tightness = 1.0 - norm_pr;
    score -= 25.0 * tightness * tightness * tightness;

    // Last-chance bin: strong reward to use it
    if fitting_bins_count == 1 && bin_residual != bin_capacity {
        score -= 40.0;
    }

    // Lookahead: if next item fits exactly in post_residual, big reward
    if next_item_size > 0 && post_residual >= next_item_size {
        let gap = (post_residual - next_item_size) as f64;
        score -= 15.0 * (1.0 - gap / cap);
    } else if next_item_size > post_residual as u32 && next_item_size > 0 {
        score += 5.0;
    }

    // Penalize opening new bins when many bins already open and mean residual high
    if bin_residual == bin_capacity {
        score += 30.0 + 10.0 * (mean_residual / cap) - 20.0 * (progress * progress);
        // but allow new bin if no open bin fits well
        if fitting_bins_count == 0 {
            score -= 100.0;
        }
    }

    // Mild diversity pressure: prefer bins with residual far from mean (consolidation)
    let dev = (bin_residual as f64 - mean_residual).abs() / cap;
    score += 4.0 * dev * dev;

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Harmonic class of post_residual: integer division into 10-wide classes.
    let class = post_residual / 10;
    score += match class {
        0 => -25.0,                 // near-perfect fit, strongly reward
        1 => -12.0,
        2 => -4.0,
        3 => 3.0,
        4 => 8.0,
        5 => 12.0,
        6 => 16.0,
        7 => 20.0,
        8 => 24.0,
        _ => 30.0,                  // large dead space, heavy penalty
    };

    // Reward tightness non-linearly: fraction of bin consumed.
    let fill = item_size as f64 / bin_capacity as f64;
    score -= 20.0 * fill * fill;

    // Lookahead coupling: if next item exactly fills the post residual, big reward.
    if next_item_size > 0 && next_item_size == post_residual {
        score -= 30.0;
    } else if next_item_size > 0 && next_item_size <= post_residual {
        // next item fits: mild reward scaled by how well it uses the leftover
        score -= 8.0 * (next_item_size as f64 / post_residual.max(1) as f64);
    } else if next_item_size > 0 {
        // next item won't fit here: leftover likely dead space, penalize
        score += 6.0 * (post_residual as f64 / bin_capacity as f64);
    }

    // Last-chance bin: if this is the only bin that fits, avoid opening a new bin.
    if fitting_bins_count == 1 && bin_residual != bin_capacity {
        score -= 15.0;
    }

    // New-bin candidate: penalize opening new bins unless current bins are crowded.
    if bin_residual == bin_capacity {
        let pressure = mean_residual / bin_capacity as f64;
        score += 40.0 - 45.0 * pressure.min(1.0);
        if open_bins_count == 0 {
            score -= 100.0; // must open first bin
        }
    }

    // Late-stream consolidation: prefer packing into existing bins as stream ends.
    let progress = step_index as f64 / total_items.max(1) as f64;
    score -= 10.0 * progress * (bin_residual != bin_capacity) as i32 as f64;

    // Slight preference for bins with residual close to item (best-fit sharpening).
    let gap = (bin_residual - item_size) as f64;
    score += 0.1 * gap * gap / bin_capacity as f64;

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Strict dead-space avoidance: penalize small unusable gaps harshly.
    // A residual below the minimum item size (1) is impossible, but tiny gaps
    // (< 20) are rarely reusable; larger gaps stay flexible.
    if post_residual > 0 && post_residual < 20 {
        score += 3.0 * (20.0 - post_residual as f64);
    } else if post_residual == 0 {
        // Perfect fit: reward strongly.
        score -= 50.0;
    }

    // Reward leaving room for the lookahead item if it fits exactly.
    if next_item_size > 0 && post_residual >= next_item_size {
        score -= 2.0;
        if (post_residual - next_item_size) < 20 {
            score -= 3.0;
        }
    } else if next_item_size > 0 && post_residual < next_item_size && post_residual > 0 {
        // Gap too small for the next item: mild penalty.
        score += 1.0;
    }

    // Last-chance bin: strongly prefer using it over opening a new bin.
    if fitting_bins_count == 1 && bin_residual != bin_capacity {
        score -= 25.0;
    }

    // Open-bin pressure: with many bins open, favor filling existing ones.
    let progress = step_index as f64 / total_items.max(1) as f64;
    score += 0.15 * open_bins_count as f64 * (0.5 + 0.5 * progress);

    // Prefer bins tighter than average (good packing).
    score += 0.3 * (mean_residual - bin_residual as f64);

    // New-bin candidate: make it mildly unattractive unless residual
    // considerations dominate (baseline offset).
    if bin_residual == bin_capacity {
        score += 15.0 + 0.5 * open_bins_count as f64;
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Perfect fit: overwhelmingly prefer.
    if post_residual == 0 {
        score -= 1000.0;
    } else if post_residual <= 5 {
        score -= 50.0;
    }

    // 2-step lookahead: if the next item fits exactly into post_residual,
    // this is a chain match — strongly reward.
    if next_item_size > 0 {
        if post_residual == next_item_size {
            score -= 400.0;
        } else if post_residual > next_item_size {
            // next item fits but leaves a gap; reward proportionally
            let gap = (post_residual - next_item_size) as f64;
            score -= 40.0 * (1.0 - gap / bin_capacity as f64);
        } else {
            // next item does NOT fit here: penalize wasting residual below next_item_size
            let dead = post_residual as f64;
            if dead < next_item_size as f64 && dead > 0.0 {
                score += 0.5 * dead;
            }
        }
    }

    // Relative to mean residual: prefer bins that are already "tight" relative
    // to the fleet average (best-fit flavor with adaptive reference).
    score -= 0.3 * (bin_residual as f64 - mean_residual);

    // Last chance bin: if this is the ONLY bin that can fit the item, avoid
    // opening a new bin unless the fit would be terrible.
    if fitting_bins_count == 1 && bin_residual != bin_capacity {
        if post_residual <= 20 {
            score -= 120.0;
        } else {
            score -= 30.0;
        }
    }

    // New-bin candidate: only attractive when the item is large relative to
    // capacity (poor fit anywhere else) or no open bins exist.
    if bin_residual == bin_capacity {
        let large_item = (item_size as f64 / bin_capacity as f64) > 0.6;
        if open_bins_count == 0 {
            score -= 200.0;
        } else if large_item && (fitting_bins_count == 0 || post_residual > 40) {
            score -= 150.0;
        } else {
            // discourage opening new bins when open bins can absorb the item
            score += 80.0 + 0.2 * open_bins_count as f64;
        }
    }

    // Late in the stream: consolidate, penalize new bins more, reward tight fits.
    let progress = step_index as f64 / total_items as f64;
    score -= 20.0 * progress * (1.0 - post_residual as f64 / bin_capacity as f64);

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Perfect fit reward
    if post_residual == 0 {
        score -= 500.0;
    }

    // Lookahead: reward if next item fits into the post residual
    if next_item_size > 0 && post_residual >= next_item_size {
        score -= 30.0 + 0.5 * next_item_size as f64;
    } else if next_item_size > 0 {
        // penalize dead space relative to next item's needs
        score += 0.3 * (next_item_size as f64 - post_residual as f64).min(50.0);
    }

    // Last chance: strongly prefer using the only bin that fits
    if fitting_bins_count == 1 && bin_residual >= item_size {
        score -= 80.0;
    }

    // Penalize leaving large residuals in already-well-filled bins is good;
    // but penalize wasting a large residual on a small item (dead space creation)
    let wasted = post_residual as f64 / bin_capacity as f64;
    score += 40.0 * wasted * wasted;

    // Favor bins whose residual is close to mean (avoid fragmenting outliers)
    score += 0.2 * (bin_residual as f64 - mean_residual).abs();

    // Time horizon: early in stream, be conservative (avoid too many bins);
    // late in stream, prioritize tight fits harder.
    let progress = step_index as f64 / total_items.max(1) as f64;
    score -= (1.0 - progress) * 0.1 * bin_residual as f64;
    score += progress * 0.05 * open_bins_count as f64;

    // New-bin candidate: neutralize its raw post_residual (=capacity) with a penalty
    if bin_residual == bin_capacity {
        score += 60.0 + 0.4 * mean_residual;
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let progress = step_index as f64 / total_items.max(1) as f64;
    let pr = post_residual as f64;
    let cap = bin_capacity as f64;
    let norm_pr = pr / cap;

    // Base: quadratic penalty on wasted space, modulated by stream progress
    let mut score = pr * (1.0 + progress * (1.0 - norm_pr));

    // Non-linear coupling: residual^2 scaled by progress and openness
    let open_frac = open_bins_count as f64 / (open_bins_count as f64 + 5.0);
    score += norm_pr * norm_pr * cap * (0.5 + progress) * (1.0 - open_frac);

    // Reward tight fits: subtract for small post_residual, stronger late in stream
    score -= (1.0 - norm_pr).powi(3) * (10.0 + 20.0 * progress);

    // Last-chance bonus: if this is the only fitting bin, strongly favor using it
    if fitting_bins_count == 1 {
        score -= 25.0 + 15.0 * progress;
    }

    // Lookahead: if next item fits in post_residual, reward this placement
    if next_item_size > 0 && (next_item_size as f64) <= pr {
        score -= 8.0 + 6.0 * (1.0 - pr / cap);
    } else if next_item_size > 0 {
        // Penalize leaving a residual that next item cannot use
        score += 4.0 * (pr / (pr + (next_item_size - post_residual.min(next_item_size)) as f64 + 1.0));
    }

    // Mean residual coupling: penalize deviating far from the mean residual state
    let dev = (pr - mean_residual) / cap;
    score += dev * dev * cap * 0.3;

    // New-bin candidate adjustment: mildly penalize opening new bins early,
    // favor it late when residuals are fragmented
    if bin_residual == bin_capacity {
        score += 6.0 * (1.0 - progress) - 4.0 * progress * open_frac;
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Harmonic class of post_residual: classify leftover space by integer division thresholds
    let post = post_residual as i64;
    let cap = bin_capacity as f64;
    let item = item_size as f64;
    let next = next_item_size as f64;

    // Fraction of capacity consumed by this placement
    let fill_frac = item / cap;

    // Base: reward tight fits strongly (lower score for small post_residual)
    score = (post as f64).powf(1.5) * 0.35;

    // Harmonic residue classes: leftover in {0, 5, 10} is "perfect harmony" — big bonus
    let r = post % 10;
    if post == 0 {
        score -= 60.0; // perfect fit
    } else if r == 0 {
        score -= 25.0; // multiple of 10 leftover is reusable
    } else if r <= 3 {
        score += 12.0; // tiny dead space penalty
    }

    // Class by integer division of post_residual into capacity bands
    let band = post / 20; // 0..5
    score += band as f64 * 4.0; // larger leftover mildly penalized (waste)

    // Lookahead coupling: does next item fit into post_residual?
    if next > 0.0 {
        if next <= post as f64 {
            // next fits: reward proportional to how snugly it nests
            let nest = (post as f64 - next) / cap;
            score -= 20.0 * (1.0 - nest);
            // harmonic class of the nested leftover
            let nested = post - next as i64;
            if nested % 10 == 0 { score -= 8.0; }
        } else {
            // next won't fit here: penalize bins whose leftover is "almost but not" fitting
            let gap = next - post as f64;
            score += (gap / cap) * 15.0;
        }
    }

    // Last-chance bin: strongly favor using the only fitting bin
    if fitting_bins_count == 1 && bin_residual != bin_capacity {
        score -= 30.0;
    }

    // New-bin candidate: neutral baseline; open a new bin only if existing bins are poor fits
    if bin_residual == bin_capacity {
        // New bin: score = capacity - item, i.e. large leftover; make it competitive
        score = (post as f64) * 0.9 + 20.0;
        if fitting_bins_count == 0 { score -= 50.0; }
    }

    // Fill fraction bonus: reward high utilization placements
    score -= fill_frac * 18.0;

    // Late-stream consolidation: prefer filling existing bins as stream progresses
    let progress = step_index as f64 / total_items.max(1) as f64;
    score += progress * (post as f64) * 0.25;

    // Mean residual context: if this bin is far below mean residual, it's an outlier — using it normalizes state
    let dev = (mean_residual - bin_residual as f64).abs();
    score += dev * 0.05;

    // Open bin count pressure: many open bins -> favor packing into existing ones
    score += open_bins_count as f64 * 1.5;

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Strict dead-space avoidance: tiny unusable gaps are the worst outcome.
    if post_residual > 0 && post_residual < 10 {
        score += 60.0 - 6.0 * post_residual as f64; // gap of 1 -> +54, gap of 9 -> +6
    } else if post_residual == 0 {
        score -= 25.0; // perfect fit: close the bin, ideal
    }

    // Reward residuals that can still host a typical future item.
    if post_residual >= 10 {
        score -= 8.0;
    }

    // Lookahead: if the next item fits exactly into post_residual, strongly favor.
    if next_item_size > 0 && next_item_size <= post_residual {
        score -= 10.0;
        if post_residual - next_item_size < 10 && post_residual != next_item_size {
            score += 6.0; // but avoid chaining into a dead gap
        }
    }
    if next_item_size > post_residual && post_residual > 0 && post_residual < 10 {
        score += 12.0; // leftover gap the known next item can't use
    }

    // Open-bin pressure: discourage spreading across many bins when fit is easy.
    if fitting_bins_count > 2 {
        score += 2.0 * (fitting_bins_count as f64 - 2.0).min(6.0);
    }
    // Last-chance bin: strongly prefer using it over opening a new bin.
    if fitting_bins_count == 1 && bin_residual != bin_capacity {
        score -= 30.0;
    }

    // New-bin candidate: keep it attractive only when open bins are few or fits are bad.
    if bin_residual == bin_capacity {
        score = 40.0 + 3.0 * open_bins_count as f64;
        if post_residual - item_size == 0 { score -= 10.0; }
    }

    // Late in the stream, prefer consolidating into existing bins.
    let progress = step_index as f64 / total_items.max(1) as f64;
    score += progress * mean_residual * 0.05;

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Perfect fit: reward strongly.
    if post_residual == 0 {
        score -= 1000.0;
    }

    // Aggressive 2-step lookahead: if the next item exactly fills the
    // post-residual, this placement creates a perfect two-item pairing.
    if next_item_size > 0 && post_residual > 0 {
        if next_item_size == post_residual {
            score -= 500.0;
        } else if next_item_size <= post_residual {
            // Next item fits: good, but prefer tighter pairings.
            score -= 150.0 * (next_item_size as f64 / post_residual as f64);
        } else {
            // Next item cannot use the leftover: penalize dead space,
            // scaled by how much of the residual is wasted.
            let waste = (next_item_size - post_residual) as f64;
            score += 0.5 * waste.min(80.0);
        }
    }

    // Compare post_residual against mean residual across open bins:
    // leaving more slack than average is wasteful when bins are plentiful.
    if mean_residual > 0.0 {
        let rel = post_residual as f64 / mean_residual;
        if rel > 1.0 {
            score += 20.0 * (rel - 1.0);
        } else {
            score -= 10.0 * (1.0 - rel);
        }
    }

    // Last-chance bin: strongly favor using it to avoid opening a new bin.
    if fitting_bins_count == 1 && bin_residual < bin_capacity {
        score -= 300.0;
    }

    // Penalize the brand-new empty bin candidate unless open bins are poor fits.
    if bin_residual == bin_capacity {
        // Base penalty so open bins are preferred.
        score += 250.0;
        // But if no open bin fits (only candidate), the penalty is irrelevant
        // since it's the sole call with residual == capacity; soften when the
        // item is large relative to capacity (tight packing elsewhere unlikely).
        let frac = item_size as f64 / bin_capacity as f64;
        score -= 200.0 * frac;
        // Late in the stream, opening fresh bins is less costly.
        let progress = step_index as f64 / total_items.max(1) as f64;
        score -= 50.0 * progress;
    }

    // Mild pressure to prefer bins with less residual overall.
    score += 0.1 * (bin_residual as f64 - post_residual as f64) * -0.0;

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Strong preference for tight fits: reward small post_residual non-linearly.
    score -= (bin_capacity as f64 - post_residual as f64) * 0.35;

    // Perfect-fit bonus: leaving nothing behind is ideal.
    if post_residual == 0 {
        score -= 60.0;
    } else if post_residual < 10 {
        score -= 25.0;
    }

    // Dead-space penalty: residuals that no typical item (1..=100) can pair with.
    if post_residual > 0 && post_residual < 10 {
        score += 30.0;
    }

    // Lookahead: if the next item fits exactly into post_residual, big bonus.
    if next_item_size > 0 {
        if next_item_size == post_residual {
            score -= 80.0;
        } else if next_item_size <= post_residual {
            score -= (post_residual - next_item_size) as f64 * 0.5;
        } else {
            // Next item won't fit here; mild penalty proportional to overshoot.
            score += (next_item_size - post_residual) as f64 * 0.15;
        }
    } else {
        // Last item: minimize waste aggressively.
        score += post_residual as f64 * 0.5;
    }

    // Last-chance bin: if this is the only bin that fits, strongly favor using it
    // over opening a new bin.
    if fitting_bins_count == 1 && bin_residual >= item_size && bin_residual != bin_capacity {
        score -= 40.0;
    }

    // New-bin candidate handling: opening a new bin wastes all current residual.
    // Penalize new bins unless mean residual across open bins is high (open bins
    // are fragmented anyway) or the item barely fits anywhere.
    if bin_residual == bin_capacity {
        let progress = if total_items > 0 { step_index as f64 / total_items as f64 } else { 0.0 };
        score += 55.0; // base cost of a new bin
        score -= mean_residual * 0.25; // if open bins are full-ish, new bin is fine
        score -= progress * 15.0; // late in stream, less concern about long-lived bins
        if fitting_bins_count == 0 {
            score -= 100.0; // nothing fits, must open
        }
    } else {
        // Existing bin: mild reward scaled by how full it already is.
        let fullness = (bin_capacity - bin_residual) as f64 / bin_capacity as f64;
        score -= fullness * 20.0;
    }

    // Slight preference to consolidate into fewer bins when many are open.
    score += open_bins_count as f64 * 0.5;

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let cap = bin_capacity as f64;
    let post = post_residual as f64;
    let progress = if total_items > 0 { step_index as f64 / total_items as f64 } else { 0.0 };

    // Base: minimize wasted post residual, but with diminishing penalty
    let mut score = post * post / cap;

    // Smooth non-linear coupling of post_residual with stream progress:
    // early on, waste matters less (bins get reused); late, waste is costly.
    let progress_term = post * (0.5 + 0.5 * progress * progress);
    score += progress_term;

    // Reward tight fits: quadratic bonus decaying with post_residual
    let tightness = 1.0 - post / cap;
    score -= tightness * tightness * item_size as f64;

    // Penalize post_residual that cannot fit the lookahead item (dead space)
    if next_item_size > 0 {
        let nxt = next_item_size as f64;
        let dead = (nxt - post).max(0.0);
        score += dead * dead / cap * (0.5 + progress);
        // Reward post residual that exactly accommodates next item
        let gap = (post - nxt).abs();
        score -= (1.0 - gap / cap).max(0.0) * 5.0;
    } else {
        // Last item: purely minimize waste
        score -= 10.0 * tightness;
    }

    // Last-chance bin bonus: if this is the only fitting bin, strongly favor it
    if fitting_bins_count == 1 && bin_residual >= item_size {
        score -= 8.0;
    }

    // Mild penalty proportional to number of open bins to encourage consolidation
    score += open_bins_count as f64 * 0.05 * (post / cap);

    // Nudge toward bins with residual above the current mean (keeps balance usable)
    let mean = mean_residual.max(0.0);
    if post > mean {
        score += (post - mean) * 0.1;
    } else {
        score -= (mean - post) * 0.05;
    }

    // New-bin candidate: penalize opening a new bin unless item is large
    if bin_residual == bin_capacity {
        let size = item_size as f64;
        let large_bonus = ((size - cap * 0.5).max(0.0)) / cap;
        score += 20.0 - 25.0 * large_bonus;
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Harmonic class of the post residual: classify leftover space by capacity fractions.
    let cap = bin_capacity as f64;
    let pr = post_residual as f64;

    // Integer-division threshold classes on post_residual (harmonic bands).
    let quarter = bin_capacity / 4;   // 25
    let half = bin_capacity / 2;      // 50
    let three_quarter = 3 * quarter;  // 75

    // Dead-space penalty grows superlinearly in the smallest harmonic band.
    if post_residual < quarter {
        score += (quarter - post_residual) as f64 * 1.5;
    } else if post_residual < half {
        score += 2.0;
    } else if post_residual < three_quarter {
        score -= 3.0; // generous leftover, still re-usable
    }

    // Modulo arithmetic: residuals that are multiples of small units pack well
    // with typical item granularities.
    if post_residual % 10 == 0 {
        score -= 2.0;
    }
    if post_residual % 5 == 0 && post_residual % 10 != 0 {
        score -= 0.5;
    }

    // Lookahead coupling: if next item fits exactly into post_residual, strong reward.
    if next_item_size > 0 {
        if next_item_size == post_residual {
            score -= 12.0;
        } else if next_item_size < post_residual {
            score -= (next_item_size as f64).min(pr) * 0.05;
        } else {
            // next item won't fit here; penalize wasting the slot if bin becomes near-full anyway
            score += 1.0;
        }
    }

    // Last-chance bin: strongly favor using it to avoid opening a new bin.
    if fitting_bins_count == 1 && bin_residual < bin_capacity {
        score -= 6.0;
    }

    // New-bin candidate: penalize opening a bin unless current fit is terrible.
    if bin_residual == bin_capacity {
        score += 25.0 + (open_bins_count as f64) * 0.5;
        // but if item is huge relative to mean residual space, opening fresh is fine
        let mean_fit = mean_residual / cap;
        if (item_size as f64) > mean_residual * 0.9 {
            score -= 20.0;
        }
        let _ = mean_fit;
    }

    // Stream progression: late in the stream, prefer tightening existing bins.
    let progress = step_index as f64 / total_items.max(1) as f64;
    score += pr * 0.1 * progress;

    // Reward near-perfect fills (harmonic closure).
    if post_residual == 0 {
        score -= 20.0;
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Strict dead-space avoidance: small unusable gaps (< 10) are heavily penalized,
    // since the interface allows items as small as 1, but tiny gaps below the
    // typical item scale are poor targets; gaps of exactly 0 are perfect.
    if post_residual == 0 {
        score -= 50.0; // perfect fit
    } else if post_residual < 10 {
        score += 30.0; // dead space: unusable sliver
    } else if post_residual < 20 {
        score += 10.0; // likely dead space
    }

    // Reward tight fits relative to bin size (fill ratio of the consumed space).
    let fill = item_size as f64 / bin_capacity as f64;
    score -= 20.0 * fill;

    // Lookahead: if the next item fits exactly in post_residual, strongly favor.
    if next_item_size > 0 && post_residual >= next_item_size {
        let slack = post_residual - next_item_size;
        if slack == 0 {
            score -= 25.0;
        } else if slack < 10 {
            score -= 10.0;
        }
    } else if next_item_size > 0 && post_residual > 0 && post_residual < next_item_size {
        // leftover can't host next item: mild penalty
        score += 8.0;
    }

    // Last-chance pressure: if this is the only fitting bin, avoid opening a new bin.
    if fitting_bins_count == 1 && bin_residual < bin_capacity {
        score -= 15.0;
    }

    // Open-bin pressure: penalize opening/spreading when many bins are already open,
    // pushing toward consolidation into existing bins.
    score += (open_bins_count as f64) * 1.5;

    // New-bin candidate handling: an empty bin has residual == capacity.
    if bin_residual == bin_capacity {
        // Opening a new bin is only attractive if existing bins would leave dead space
        // or no bin fits. Penalize the new bin by its would-be post_residual plus a fixed cost.
        score += 40.0;
        if fitting_bins_count == 0 {
            score -= 60.0; // no alternative: must open
        } else if post_residual < 10 {
            score -= 45.0; // perfect fit into fresh bin beats dead-space placements
        }
    }

    // Mean residual coupling: bins far below mean residual are "emptier" — prefer
    // filling emptier bins to keep a balanced set of usable residuals.
    score += (mean_residual - bin_residual as f64) * 0.3;

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Perfect 2-step chain: residual after placement exactly matches next item.
    if next_item_size > 0 && post_residual == next_item_size {
        score -= 200.0;
    }

    // Next item fits into post_residual: partial lookahead reward.
    if next_item_size > 0 && post_residual >= next_item_size {
        score -= 30.0 + 0.5 * (post_residual - next_item_size) as f64;
    } else if next_item_size > 0 {
        // Dead space: next item cannot use the leftover.
        score += 20.0;
    }

    // Reward tight fits relative to mean residual.
    let tightness = post_residual as f64 - mean_residual;
    score += 0.3 * tightness;

    // Last-chance bin: strongly prefer using it to avoid wasting capacity.
    if fitting_bins_count == 1 && bin_residual < bin_capacity {
        score -= 60.0;
    }

    // Penalize opening new bins when plenty of open bins exist.
    if bin_residual == bin_capacity {
        let progress = step_index as f64 / total_items.max(1) as f64;
        score += 40.0 + 30.0 * (1.0 - progress);
    }

    // Small leftovers are useless; large leftovers keep future options.
    if post_residual > 0 && post_residual < 10 {
        score += 25.0;
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let progress = step_index as f64 / (total_items.max(1) as f64);
    let mut score = post_residual as f64;

    // Reward tight fits (small post_residual) nonlinearly.
    score *= 1.0 + 0.02 * (post_residual as f64 / bin_capacity as f64).powi(2) * 100.0 / (1.0 + post_residual as f64);

    // Lookahead: if next item fits exactly in post_residual, strongly reward.
    if next_item_size > 0 && post_residual >= next_item_size {
        let slack = (post_residual - next_item_size) as f64;
        score -= 15.0 * (1.0 - slack / bin_capacity as f64);
    } else if next_item_size > 0 && post_residual < next_item_size {
        // Dead space that can't host the next item: penalize proportionally.
        score += 0.15 * post_residual as f64 * (0.5 + 0.5 * progress);
    }

    // Last-chance bin: strongly favor using it to avoid opening a new bin.
    if fitting_bins_count == 1 && bin_residual < bin_capacity {
        score -= 25.0;
    }

    // New-bin candidate: prefer it only when no open bin fits well.
    if bin_residual == bin_capacity {
        let mean_fit = if fitting_bins_count > 0 {
            (mean_residual - item_size as f64).abs()
        } else {
            100.0
        };
        // Penalize opening new bins mildly, more late in the stream.
        score += 12.0 + 20.0 * progress;
        // But if existing fits are terrible (huge leftovers), new bin is fine.
        score -= (mean_fit / bin_capacity as f64) * 10.0;
        // With many open bins, encourage consolidation into existing bins.
        score += 0.5 * open_bins_count as f64;
    }

    // Slight preference for bins below mean residual (balance spreading).
    if bin_residual < bin_capacity {
        score += 0.05 * (bin_residual as f64 - mean_residual).max(-50.0).abs() * 0.1;
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let cap = bin_capacity as f64;
    let pr = post_residual as f64;
    let progress = step_index as f64 / total_items.max(1) as f64;
    let fill = 1.0 - pr / cap;

    // Base: prefer tight fits (small post_residual), weighted by stream progress.
    let mut score = pr * (0.5 + 1.5 * progress * progress);

    // Non-linear dead-space penalty: cubic in normalized post_residual.
    let pr_norm = pr / cap;
    score += 30.0 * pr_norm * pr_norm * pr_norm;

    // Interaction: fill fraction coupled with progress — later in stream, reward fuller bins more.
    score -= 25.0 * fill * fill * (0.3 + 0.7 * progress);

    // Lookahead coupling: reward residual that can still host the next item, penalize otherwise.
    if next_item_size > 0 {
        let nxt = next_item_size as f64;
        if pr >= nxt {
            score -= 8.0 * (nxt / cap) * (1.0 - progress);
        } else {
            score += 6.0 * (1.0 - nxt / cap) * progress;
        }
    }

    // Last-chance bonus: strongly favor the only fitting bin to avoid opening new bins.
    if fitting_bins_count == 1 && bin_residual < bin_capacity {
        score -= 20.0 * (0.5 + progress);
    }

    // Mild penalty proportional to congestion (many open bins with slack).
    score += 0.5 * open_bins_count as f64 * (mean_residual / cap - fill).abs();

    // New-bin candidate: neutral-ish baseline, slightly penalized early, allowed late.
    if bin_residual == bin_capacity {
        score = cap * (1.2 - 0.6 * progress) + 10.0 * (1.0 - progress);
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Harmonic class of the post-residual: classify leftover space into
    // residue classes modulo a small quantum. Small post-residuals are
    // "dead space" classes; large ones remain reusable.
    let quantum: u32 = 10;
    let class = post_residual / quantum;             // 0..=10 harmonic class
    let residue = post_residual % quantum;           // within-class remainder

    // Reward tiny post-residuals (perfect/near-perfect fills).
    if post_residual == 0 {
        score -= 500.0;                              // perfect fit
    } else if post_residual <= 5 {
        score -= 200.0 + (5 - post_residual) as f64 * 20.0;
    } else if class <= 2 {
        // 1..20 leftover: marginal utility, penalize lightly beyond base
        score += (2 - class) as f64 * 8.0;
    } else if class >= 7 {
        // 70..100 leftover: very reusable space, reward
        score -= (class - 6) as f64 * 12.0;
    }

    // Within-class residue: smooth tie-breaking.
    score -= residue as f64 * 0.5;

    // Compatibility: can the lookahead item fit into the post-residual?
    // If yes, this placement chains nicely; reward proportional to how
    // tightly the next item will nest.
    if next_item_size > 0 {
        if next_item_size <= post_residual {
            let slack = post_residual - next_item_size;
            let tightness = 1.0 - (slack as f64 / bin_capacity as f64);
            score -= 60.0 * tightness;
            // Harmonic coupling: next item's own class matters
            let next_class = next_item_size / quantum;
            if next_class >= 5 {
                score -= 10.0; // big next item nesting into big leftover
            }
        } else {
            // Next item cannot use this bin's leftover: mild penalty,
            // stronger if leftover is mid-range (worst dead space zone).
            if class >= 3 && class <= 5 {
                score += 15.0;
            }
        }
    } else {
        // Last item: strongly prefer zero-waste placements.
        score -= 100.0;
    }

    // Last-chance bin: if this is the only fitting bin, avoid opening a
    // new bin unless the fit is terrible.
    if fitting_bins_count == 1 && bin_residual != bin_capacity {
        score -= 40.0 + item_size as f64 * 0.2;
    }

    // New-bin candidate handling: prefer keeping residual mass concentrated.
    if bin_residual == bin_capacity {
        // Fresh bin: neutral base; penalize when many open bins already
        // exist with plenty of mean residual space (fragmentation guard).
        score += 30.0;
        if mean_residual > 30.0 && open_bins_count > 2 {
            score += (mean_residual - 30.0) * 1.5;
        }
        // Late in the stream, opening new bins is cheap since streams are long.
        let progress = step_index as f64 / total_items.max(1) as f64;
        score -= progress * 10.0;
    } else {
        // Existing bin: reward using bins with residual close to mean
        // (balanced packing keeps harmonic classes predictable).
        let dev = (bin_residual as f64 - mean_residual).abs();
        score += dev * 0.3;
    }

    // Global harmonic tiebreak on item class vs bin class alignment.
    let item_class = item_size / quantum;
    let bin_class = bin_residual / quantum;
    if bin_class >= item_class {
        score -= (bin_class - item_class) as f64 * 2.0;
    } else {
        score += (item_class - bin_class) as f64 * 2.0;
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Strict dead-space avoidance: small unusable gaps are heavily penalized.
    // A gap is "unusable" if it cannot hold even the smallest plausible item (<= 20)
    // or cannot hold the lookahead item.
    if post_residual > 0 {
        if post_residual < 20 {
            score += 60.0; // tiny dead space
        } else if next_item_size > 0 && post_residual < next_item_size {
            score += 25.0; // gap too small for lookahead item
        } else {
            score -= 10.0; // gap remains reusable
        }
    } else {
        score -= 40.0; // perfect closure
    }

    // Reward tight fits (fill ratio of the residual before placement).
    let fill = item_size as f64 / bin_residual.max(1) as f64;
    score -= 30.0 * fill;

    // Last chance: strongly prefer using the only bin that fits.
    if fitting_bins_count == 1 {
        score -= 50.0;
    }

    // Open-bin pressure: discourage spreading across many bins.
    score += open_bins_count as f64 * 1.5;

    // Prefer bins with residuals below the mean (compact bins), avoid wasteful ones.
    score += (bin_residual as f64 - mean_residual) * 0.3;

    // New-bin candidate handling: opening a new bin is only attractive when no
    // existing bin fits well. New bin has bin_residual == bin_capacity.
    if bin_residual == bin_capacity {
        // Base penalty so we prefer reusing bins, unless they fit badly.
        score += 55.0;
        if open_bins_count == 0 {
            score -= 200.0; // must open first bin
        }
        if fitting_bins_count == 0 {
            score -= 100.0; // no alternative
        }
        // If next item is large, a fresh bin is useful.
        if next_item_size >= 60 {
            score -= 15.0;
        }
    }

    // Mild stream progression: early on, be more willing to open bins.
    let progress = step_index as f64 / (total_items.max(1) as f64);
    score -= (1.0 - progress) * 5.0;

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Perfect lookahead match: post_residual equals next item size -> strong reward.
    if next_item_size > 0 {
        let nxt = next_item_size as f64;
        let diff = (post_residual as f64 - nxt).abs();
        if diff < 0.5 {
            score -= 45.0;
        } else if post_residual >= next_item_size {
            // Bin can still host the next item: mild reward, closer match is better.
            score -= 12.0 * (1.0 - diff / bin_capacity as f64);
        } else {
            // Dead space relative to lookahead: penalize proportionally.
            score += 8.0 * (1.0 - post_residual as f64 / nxt);
        }
    } else {
        // Last item: just minimize waste; exact-fill bonus.
        if post_residual == 0 {
            score -= 60.0;
        }
    }

    // Tight fit reward relative to capacity.
    let tightness = item_size as f64 / bin_residual as f64;
    score -= 15.0 * tightness * tightness;

    // Last-chance bin: strongly favor using it to avoid opening a new bin.
    if fitting_bins_count == 1 && bin_residual != bin_capacity {
        score -= 20.0;
    }

    // Penalize bins with unusually large residuals compared to mean (avoid hoarding space).
    score += 0.5 * (bin_residual as f64 - mean_residual).max(0.0);

    // New-bin candidate: neutral-ish baseline, only chosen when open bins are bad.
    if bin_residual == bin_capacity {
        score += 25.0 + (open_bins_count as f64).sqrt() * 2.0;
        // Prefer opening a new bin early in the stream when many bins are open poorly.
        if next_item_size > 0 && post_residual >= next_item_size {
            score -= 10.0;
        }
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Fraction of the stream completed — dynamic time horizon.
    let t = if total_items > 0 { step_index as f64 / total_items as f64 } else { 0.0 };

    // Core best-fit baseline: minimize post residual.
    // Sharpen preference for very tight fits with a quadratic bonus.
    let tightness = 1.0 - (post_residual as f64 / bin_capacity as f64);
    score -= 0.5 * tightness * tightness * (bin_capacity as f64);

    // Penalize dead space that nothing can use: residual below the
    // minimum plausible item size (1) is fine, but residual smaller
    // than the NEXT item is wasted if next item could have fit here.
    if next_item_size > 0 {
        if post_residual >= next_item_size {
            // Lookahead synergy: leaving room for the next item is good.
            score -= 3.0;
            // Extra reward for near-exact chaining: post_residual ~= next_item_size
            let chain_gap = (post_residual as f64 - next_item_size as f64).abs();
            score -= 2.0 * (1.0 - chain_gap / bin_capacity as f64);
        } else {
            // Post residual too small for next item: dead space penalty,
            // scaled by how dead it is relative to smallest possible item.
            let deadness = 1.0 - (post_residual as f64 / 1.0_f64.max(post_residual as f64));
            score += 2.0 * (post_residual as f64 / bin_capacity as f64) + deadness;
        }
    }

    // Last-chance bin: if this is the ONLY bin that fits, strongly favor
    // using it rather than opening a new bin (unless fit is terrible).
    if fitting_bins_count == 1 && bin_residual < bin_capacity {
        score -= 6.0;
        // But if the fit leaves a huge unusable hole, soften the bonus.
        if post_residual > bin_capacity / 2 {
            score += 3.0;
        }
    }

    // Competition among fitting bins: with many candidates, tighten
    // discrimination via a mild best-fit sharpening term.
    if fitting_bins_count > 1 {
        score += 0.25 * (fitting_bins_count as f64).ln() * (post_residual as f64 / bin_capacity as f64);
    }

    // Global state: prefer filling bins when many bins are open
    // (consolidation pressure grows with open_bins_count).
    score -= 0.05 * (open_bins_count as f64).sqrt() * (1.0 - post_residual as f64 / bin_capacity as f64);

    // Mean residual coupling: placing into a bin far below the mean
    // residual (i.e., a large bin) is encouraged early, discouraged late.
    let residual_gap = mean_residual - post_residual as f64;
    score += (0.3 - 0.6 * t) * residual_gap * 0.1;

    // Early stream: keep bins balanced to preserve flexibility.
    // Late stream: greedily fill the emptiest usable space (best fit dominates).
    score += (1.0 - t) * 0.5 * (post_residual as f64 - mean_residual).abs() * 0.1;

    // New-bin candidate handling: opening a new bin should only win when
    // no open bin offers a decent fit. Base cost of a fresh bin grows
    // with stream progress (early on, spreading is cheaper).
    if bin_residual == bin_capacity {
        score = (bin_capacity as f64) * (0.9 + 0.3 * t)
            + 4.0 * (open_bins_count as f64).sqrt()
            - 2.0 * (1.0 - t);
        // If some open bin fits and the item is small relative to capacity,
        // make the new bin less attractive.
        if fitting_bins_count >= 1 && (item_size as f64) <= 0.5 * bin_capacity as f64 {
            score += 8.0;
        }
        // If the next item is large and current bins are all tight,
        // a fresh bin is more reasonable.
        if next_item_size > 60 && mean_residual < 20.0 {
            score -= 5.0;
        }
    }

    // Small tie-breaker noise-free deterministic jitter based on step,
    // to break exact ties consistently.
    score += ((step_index % 7) as f64) * 0.01;

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let progress = if total_items > 0 { step_index as f64 / total_items as f64 } else { 0.0 };
    let cap = bin_capacity as f64;
    let pr = post_residual as f64;
    let norm_pr = pr / cap;

    // Base: waste after placement, softened non-linearly
    let mut score = 100.0 * norm_pr.powf(1.3);

    // Smooth polynomial coupling of post_residual with stream progress:
    // waste is tolerated early, penalized more as stream advances
    let progress_coupling = norm_pr * (0.5 + 1.5 * progress * progress);
    score += 60.0 * progress_coupling;

    // Cubic interaction: small residuals late in stream are valuable
    let small_residual_term = (1.0 - norm_pr).powi(3);
    score -= 40.0 * small_residual_term * (0.3 + 0.7 * progress);

    // Lookahead: if next item fits in post_residual, reward this bin smoothly
    if next_item_size > 0 {
        let fits_next = if post_residual >= next_item_size { 1.0 } else { 0.0 };
        let tightness = 1.0 - ((post_residual - next_item_size) as f64 / cap).min(1.0);
        score -= 25.0 * fits_next * tightness * (0.5 + 0.5 * progress);
    }

    // Last-chance bonus: only bin that fits -> strong smooth reward
    if fitting_bins_count == 1 {
        score -= 35.0 * (1.0 - 0.5 * progress);
    }

    // Penalize opening new bins when many bins already open and mean residual is low
    let mean_norm = mean_residual / cap;
    let new_bin = if bin_residual == bin_capacity { 1.0 } else { 0.0 };
    score += new_bin * (20.0 + 30.0 * (1.0 - mean_norm).powi(2) + 10.0 * progress);

    // Mild penalty for very tight fits creating near-zero residual (dead space risk)
    score += 5.0 * (norm_pr * (1.0 - norm_pr)).powi(2);

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let cap = bin_capacity as f64;
    let mut score = post_residual as f64;

    // Harmonic class of the post residual: exact-fill and micro-slack classes are gold.
    let pr = post_residual;
    let class = match pr {
        0 => 0.0,                       // perfect fit
        1..=5 => 1.0,                   // near-perfect
        6..=15 => 2.0,
        16..=30 => 3.0,
        31..=50 => 4.0,
        _ => 5.0,                       // large dead space
    };
    score += class * 8.0;

    // Reward tight fits proportionally to how much slack is consumed.
    let fill_ratio = (item_size as f64) / cap;
    score -= fill_ratio * 20.0;

    // Integer-division thresholds on post_residual: multiples of common item classes (10,20,25,50)
    if pr % 10 == 0 { score -= 6.0; }
    if pr % 20 == 0 && pr > 0 { score -= 4.0; }
    if pr % 25 == 0 && pr > 0 { score -= 3.0; }
    if pr == 50 { score -= 8.0; }

    // Lookahead coupling: if the next item can use the post residual, reward it.
    if next_item_size > 0 {
        if next_item_size <= pr {
            let slack_match = (pr - next_item_size) as f64;
            score -= 10.0 - slack_match * 0.3;   // exact chain fit is best
            if next_item_size == pr { score -= 8.0; }
        } else {
            // next item cannot use the slack: penalize leaving big unusable residue
            score += (pr as f64) * 0.15;
        }
    } else {
        // last item: prefer zero residual
        score += (pr as f64) * 0.5;
    }

    // Last-chance bin: strongly favor using the only bin that fits.
    if fitting_bins_count == 1 && bin_residual < bin_capacity {
        score -= 15.0;
    }

    // New-bin candidate handling: only attractive when no open bin is a decent fit
    if bin_residual == bin_capacity {
        let progress = step_index as f64 / (total_items.max(1) as f64);
        if fitting_bins_count == 0 {
            score -= 30.0;
        } else if mean_residual < item_size as f64 * 1.1 {
            score -= 5.0 + progress * 5.0;
        } else {
            score += 25.0;  // a fitting open bin exists with decent slack: avoid new bin
        }
    }

    // Mild pressure to consolidate when many bins are open
    score += (open_bins_count as f64) * 0.05;
    // Nudge toward bins below average residual (use the emptier bins)
    if (bin_residual as f64) > mean_residual {
        score += 2.0;
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    // Base: dead space after placement, with a superlinear penalty for
    // "unusable" small gaps (too small for the smallest plausible item).
    let min_item = 1.0f64;
    let pr = post_residual as f64;

    let mut score = pr;

    // Strict dead-space avoidance: gaps below the useful threshold are
    // heavily penalized (they will likely never be filled).
    if pr > 0.0 && pr < min_item + 9.0 {
        score += 25.0 * (1.0 - pr / (min_item + 9.0));
    }

    // Reward near-perfect fits strongly.
    if pr == 0 {
        score -= 40.0;
    } else if pr <= 5.0 {
        score -= 15.0;
    }

    // Reward filling large fractions of the bin.
    let fill_ratio = item_size as f64 / bin_capacity as f64;
    score -= 10.0 * fill_ratio;

    // Lookahead: if the next item fits the post residual, reward this placement.
    if next_item_size > 0 {
        if (post_residual as u64) >= next_item_size as u64 {
            score -= 12.0;
        } else if next_item_size as f64 > pr && pr > 0.0 {
            // next item cannot use the gap: mild penalty for wasting it
            score += 4.0;
        }
    }

    // Last-chance bin: strongly favor using it before opening a new one.
    if fitting_bins_count == 1 && bin_residual >= item_size {
        score -= 20.0;
    }

    // Open-bin pressure: discourage opening new bins when many bins are open,
    // but allow it when the fit here is terrible (large post_residual).
    if bin_residual == bin_capacity {
        // New-bin candidate: penalize proportionally to open bins count,
        // but less when current best fits would leave big dead space.
        score += 18.0 + 2.0 * open_bins_count as f64;
        // If this item is huge, opening a fresh bin is often fine.
        if item_size as f64 / bin_capacity as f64 > 0.7 {
            score -= 15.0;
        }
    } else {
        // Mild bonus for consolidating into fewer bins.
        score += 0.05 * open_bins_count as f64;
    }

    // Deviation from mean residual: prefer bins with residual close to item
    // (tight fit) rather than very loose or very tight bins.
    let dev = (bin_residual as f64 - item_size as f64) - mean_residual;
    score += 0.1 * dev.abs();

    // Slight progression bias: later in the stream, be more conservative
    // about leaving dead space (fewer chances to recover).
    let progress = step_index as f64 / total_items.max(1) as f64;
    score += 3.0 * progress * (pr / bin_capacity as f64);

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Progress fraction of the stream.
    let progress = if total_items > 0 { step_index as f64 / total_items as f64 } else { 0.0 };

    // --- 2-step lookahead matching ---
    if next_item_size > 0 {
        let next = next_item_size as f64;
        // Perfect chain: next item exactly fills the post residual.
        if (post_residual as f64 - next).abs() < 0.5 {
            score -= 60.0 + 25.0 * progress;
        } else if next_item_size <= post_residual {
            // Next item still fits: reward proportionally to how much of the
            // post residual the next item consumes (tight chaining).
            let use_ratio = next / post_residual as f64;
            score -= 40.0 * use_ratio + 10.0 * progress * use_ratio;
        } else {
            // Next item will NOT fit in the residual: penalize dead space,
            // scaled by how badly it misses.
            let miss = next - post_residual as f64;
            score += miss * 0.5;
            // If next item is large and this bin leaves a small unusable gap,
            // extra penalty (dead space trap).
            if next >= 50.0 && post_residual < 10.0 {
                score += 15.0;
            }
        }
    } else {
        // Last item: just minimize residual waste.
        score -= 5.0;
    }

    // --- Tightness reward: prefer bins where the item fills most of the residual ---
    let fill = item_size as f64 / bin_residual as f64;
    score -= 30.0 * fill * fill;

    // --- Mean residual coupling: placing into a bin far below mean residual
    // (very full bin) is good; leaving large residuals spread around is bad ---
    let resid_f = post_residual as f64;
    if mean_residual > 0.0 {
        let dev = (mean_residual - resid_f) / mean_residual;
        score -= 8.0 * dev;
    }

    // --- Last-chance bin: if this is the only fitting bin, strongly prefer it
    // over opening a new bin ---
    if fitting_bins_count == 1 && bin_residual != bin_capacity {
        score -= 45.0;
    }

    // --- New-bin candidate handling ---
    if bin_residual == bin_capacity {
        // Brand-new empty bin baseline: keep it attractive only when current
        // open bins have poor fitting prospects, otherwise discourage it so we
        // consolidate into open bins.
        let avg_waste_after = (bin_capacity - item_size) as f64;
        score = avg_waste_after + 25.0;
        if next_item_size > 0 && next_item_size as f64 <= avg_waste_after {
            score -= 20.0;
        }
        // Late in the stream, prefer closing out open bins rather than opening new ones.
        score += 20.0 * (1.0 - progress);
        // Many open bins already: discourage proliferation.
        score += 3.0 * open_bins_count as f64;
    }

    // --- Small absolute residual bonus: near-perfect closures ---
    if post_residual > 0 && post_residual <= 5 {
        score -= 35.0;
    }
    if post_residual == 0 {
        score -= 50.0;
    }

    // Mild penalty for opening bins early when few bins are open and residuals are large.
    if open_bins_count > 0 && resid_f > 40.0 && next_item_size > 0 && (next_item_size as f64) > resid_f {
        score += 5.0;
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Lookahead: reward bins that can also host the next item (chain packing).
    if next_item_size > 0 && next_item_size <= post_residual {
        score -= 8.0 + 6.0 * (next_item_size as f64 / bin_capacity as f64);
    } else if next_item_size > 0 && post_residual > 0 && next_item_size > post_residual {
        // Penalize leaving slivers that the known next item cannot use.
        score += 3.0 * (1.0 - post_residual as f64 / bin_capacity as f64);
    }

    // Last-chance bin: strongly favor using it before opening a new bin.
    if fitting_bins_count == 1 && bin_residual < bin_capacity {
        score -= 10.0;
    }

    // Prefer filling bins with large items (dense packing).
    score -= 5.0 * (item_size as f64 / bin_capacity as f64);

    // Coupling with global state: if mean residual is high, be pickier
    // about leaving large residuals behind (avoid wasting open capacity).
    let progress = if total_items > 0 { step_index as f64 / total_items as f64 } else { 0.0 };
    score += (post_residual as f64 - mean_residual) * (0.05 + 0.15 * progress);

    // Late in the stream, consolidate: mildly prefer already-open bins.
    if bin_residual < bin_capacity {
        score -= 4.0 * progress;
    }

    // New-bin candidate handling.
    if bin_residual == bin_capacity {
        let mut nb = 18.0;
        // Large items justify opening a fresh bin.
        nb -= 0.25 * item_size as f64;
        // If the next item is also large, a fresh bin pairs them well.
        if next_item_size >= 50 && item_size >= 50 {
            nb -= 10.0;
        }
        // Early stream: opening bins is cheaper; late stream: avoid sprawl.
        nb *= 1.0 - 0.4 * progress;
        // Many open bins with slack: discourage yet another bin.
        nb += 0.5 * open_bins_count as f64 * (mean_residual / bin_capacity as f64);
        score += nb.max(0.0);
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let progress = if total_items > 1 { step_index as f64 / (total_items as f64 - 1.0) } else { 0.0 };
    let cap = bin_capacity as f64;
    let post = post_residual as f64;
    let norm_post = post / cap; // 0..1 residual fraction after placement
    let fit = item_size as f64 / cap; // normalized item size

    // Base: post residual, with non-linear polynomial shaping.
    // Waste grows super-linearly in leftover space.
    let mut score = post * (1.0 + 1.5 * norm_post * norm_post);

    // Smooth coupling of tightness with stream progress:
    // late in the stream, tight fits (small post_residual) are rewarded more strongly.
    let tightness = 1.0 - norm_post;
    score -= 20.0 * tightness.powf(3.0) * (0.5 + progress);

    // Penalize large leftover space, more so as the stream advances (fewer chances to fill it).
    score += 15.0 * norm_post.powf(2.0) * (0.5 + progress);

    // Interaction: how well the NEXT item could use the post residual.
    // Reward when next item fits snugly into the leftover (post >= next_size).
    if next_item_size > 0 {
        let next = next_item_size as f64;
        let next_norm = next / cap;
        if post >= next {
            let snug = 1.0 - ((post - next) / cap);
            score -= 12.0 * snug * snug * (0.5 + progress) * next_norm;
        } else {
            // leftover too small for next item: penalize proportionally to how close it was
            let miss = (next - post) / cap;
            score += 8.0 * miss * (1.0 - progress);
        }
    }

    // Last-chance bin: strongly favor using it rather than opening a new bin.
    if fitting_bins_count == 1 && bin_residual < bin_capacity {
        score -= 25.0;
    }

    // New-bin candidate (empty bin): penalize more when many open bins exist or
    // when the stream is early (bins likely to be reused later), reward slightly
    // late in the stream when open bins are fragmented.
    if bin_residual == bin_capacity {
        let fragmentation = (mean_residual / cap).clamp(0.0, 1.0);
        let open_pressure = (open_bins_count as f64).ln().max(0.0) / 5.0;
        score += 30.0 + 10.0 * open_pressure + 20.0 * (1.0 - progress) - 25.0 * progress * fragmentation;
    } else {
        // Mild preference for bins whose residual is near the mean (balanced packing),
        // with a smooth quadratic deviation term.
        let dev = (bin_residual as f64 - mean_residual) / cap;
        score += 4.0 * dev * dev * (1.0 - progress);
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Harmonic class of the post residual: classify leftover space into
    // coarse buckets via integer division on capacity fractions.
    let cap = bin_capacity as f64;
    let post_f = post_residual as f64;
    let frac = post_f / cap; // 0..1

    // Harmonic class index: 0 = perfect/near-perfect fill, higher = more wasted
    let class = (post_residual * 4) / bin_capacity; // 0..3 buckets
    score += match class {
        0 => -30.0, // residual < 25% of capacity: excellent fill
        1 => -8.0,  // 25-50%: decent
        2 => 6.0,   // 50-75%: wasteful
        _ => 18.0,  // >75%: very wasteful
    };

    // Fine harmonic bonus: residual exactly divisible by common item sizes
    // (modulo arithmetic) means a future small item can perfectly fill it.
    if post_residual > 0 {
        let mut harmonic_bonus = 0.0;
        for d in [10u32, 15, 20, 25, 30, 40, 50] {
            if post_residual % d == 0 {
                harmonic_bonus += 6.0;
            }
        }
        // Perfect fill of the bin
        if post_residual == 0 {
            harmonic_bonus += 40.0;
        }
        score -= harmonic_bonus;
    }

    // Lookahead coupling: if the next item fits exactly in post_residual,
    // strongly reward this bin (chained perfect packing).
    if next_item_size > 0 {
        if next_item_size == post_residual {
            score -= 35.0;
        } else if next_item_size <= post_residual {
            // next item fits: penalize proportional to leftover-after-next
            let after_next = post_residual - next_item_size;
            score += (after_next as f64) * 0.35;
        } else {
            // next item will NOT fit here: mild bonus for keeping bin open
            // with small residual that other small items could use
            score -= (frac * 10.0).min(5.0);
        }
    }

    // Last-chance bin: if this is the only fitting bin, avoid opening a new bin
    if fitting_bins_count == 1 && bin_residual != bin_capacity {
        score -= 25.0;
    }

    // New-bin candidate handling: only attractive early in the stream or when
    // all existing bins are poor fits (large mean residual spread).
    if bin_residual == bin_capacity {
        let progress = step_index as f64 / total_items.max(1) as f64;
        // New bins get more attractive when open bins are mostly empty-ish
        let mean_gap = (mean_residual - post_f).abs();
        score = cap * 0.9 + progress * 20.0 - mean_gap * 0.2;
        // Discourage new bins when many bins already fit the item
        score += (fitting_bins_count as f64) * 15.0;
        // Perfect fill check never applies to new bin; base penalty high
        score += 10.0;
    }

    // Mild tie-breaker favoring tighter bins
    score += (bin_residual as f64) * 0.05;

    // Mean residual coupling: prefer bins below mean residual (tighter than average)
    score += (mean_residual - post_f).max(0.0) * -0.15;

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // --- Strict dead-space avoidance ---
    // Post-residual gaps below the minimum item size are pure dead space: heavy penalty.
    // Gaps in a "usable" band are mildly rewarded (they can still host future items).
    let min_item = 1u32;
    if post_residual < min_item {
        // cannot happen with sizes >= 1, but keep guard cheap
        score += 1000.0;
    }
    // Dead space severity: non-linear blow-up for tiny unusable gaps.
    if post_residual > 0 && post_residual < 10 {
        score += 25.0 * (10.0 - post_residual as f64);
    } else if post_residual >= 10 && post_residual < 30 {
        // mid-range leftover: small bonus to encourage using such bins fully
        score -= 3.0;
    }

    // --- Tight-fit reward ---
    let fill_ratio = item_size as f64 / bin_residual.max(1) as f64;
    score -= 20.0 * fill_ratio * fill_ratio;

    // --- Last-chance pressure ---
    if fitting_bins_count == 1 && bin_residual != bin_capacity {
        score -= 15.0; // strongly prefer the only bin that fits
    } else if fitting_bins_count > 1 {
        // among many candidates, prefer the fullest (smallest residual) one
        score += (fitting_bins_count as f64 - 1.0) * 2.0;
    }

    // --- Open-bin pressure: discourage proliferation of bins ---
    score += open_bins_count as f64 * 0.5;

    // --- New-bin candidate handling ---
    if bin_residual == bin_capacity {
        // Opening a new bin is only attractive when nothing fits well anywhere.
        // Penalize new bins moderately so tight fits in open bins win,
        // but if the item barely fits the best open bin (large post_residual),
        // the new-bin penalty is offset by that bin's high post_residual score.
        let progress = if total_items > 0 { step_index as f64 / total_items as f64 } else { 0.0 };
        let mut new_bin_score = 18.0 + open_bins_count as f64 * 0.3;
        // lookahead: if next item is large, a fresh bin is more valuable
        if next_item_size > 0 {
            new_bin_score -= (next_item_size as f64 / 100.0) * 10.0;
        }
        new_bin_score *= 1.0 - 0.3 * progress;
        score += new_bin_score;
    }

    // --- Lookahead synergy: reward bins whose leftover matches the next item ---
    if next_item_size > 0 && post_residual >= next_item_size {
        score -= 6.0 * (next_item_size as f64 / (post_residual as f64 + 1.0));
    } else if next_item_size > 0 && post_residual > 0 && post_residual < next_item_size {
        // leftover too small for next item: mild dead-space penalty
        score += 4.0;
    }

    // --- Mean residual coupling: when open bins are on average roomy,
    // prefer consolidating into existing bins ---
    if bin_residual != bin_capacity {
        score -= (mean_residual - post_residual as f64).max(0.0) * 0.1;
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Strong reward if the next item fits exactly into the post-residual (perfect 2-step match).
    if next_item_size > 0 && post_residual >= next_item_size {
        let slack = (post_residual - next_item_size) as f64;
        score -= 60.0 - slack.min(60.0); // exact match => -60, larger slack => less reward
        // Extra bonus for a perfect zero-slack chain
        if post_residual == next_item_size {
            score -= 25.0;
        }
    } else if next_item_size > 0 {
        // Next item does NOT fit here: penalize by how much we miss a good fit.
        let miss = (next_item_size - post_residual) as f64;
        score += 0.5 * miss.min(50.0);
    }

    // Penalize dead space relative to mean residual: creating an outlier-tiny residual is bad.
    let pr = post_residual as f64;
    if pr < mean_residual * 0.4 {
        score += (mean_residual * 0.4 - pr) * 0.8;
    }

    // Last-chance bonus: if this is the only bin that fits, prefer using it.
    if fitting_bins_count == 1 && bin_residual < bin_capacity {
        score -= 30.0;
    }

    // New-bin candidate (empty bin): penalize mildly so we prefer reusing open bins,
    // unless the fit into open bins is poor (handled above by miss penalties).
    if bin_residual == bin_capacity {
        score += 40.0;
        // But if the item is large, opening a fresh bin is often right.
        if item_size > bin_capacity / 2 {
            score -= 55.0;
        }
        // If next item is large and current item is large, a fresh bin keeps room.
        if next_item_size > 0 && next_item_size + item_size > bin_capacity && post_residual == 0 {
            score -= 20.0;
        }
    }

    // Prefer filling bins tightly as the stream progresses (less time to recover).
    let progress = step_index as f64 / (total_items.max(1) as f64);
    score -= (bin_capacity - bin_residual) as f64 * 0.15 * (0.5 + 0.5 * progress);

    // Slight preference for bins below mean residual (keep large residuals for later large items).
    if bin_residual as f64 > mean_residual + 10.0 {
        score += 5.0;
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Tight fits are valuable: reward small post-residual nonlinearly.
    let tight = 1.0 - (post_residual as f64 / bin_capacity as f64);
    score -= 12.0 * tight * tight;

    // Perfect fit gets a strong bonus.
    if post_residual == 0 {
        score -= 40.0;
    }

    // Penalize leaving dead space that the lookahead item cannot use.
    if next_item_size > 0 {
        if post_residual >= next_item_size {
            // Residual usable by next item: good, encourage chain packing.
            let usable = 1.0 - (post_residual as f64 / next_item_size as f64);
            score -= 8.0 * (1.0 - usable);
        } else {
            // Dead space for the next item: penalize proportionally.
            score += 0.35 * (next_item_size as f64 - post_residual as f64);
        }
    }

    // Last-chance bin: strongly favor using it before opening a new bin.
    if fitting_bins_count == 1 && bin_residual < bin_capacity {
        score -= 25.0;
    }

    // Crowding: with many open bins, prefer consolidating into fuller bins.
    let crowd = (open_bins_count as f64 / (open_bins_count as f64 + 5.0)).sqrt();
    score += 6.0 * crowd * (post_residual as f64 / bin_capacity as f64);

    // Global residual pressure: if mean residual is low, waste hurts more.
    let pressure = 1.0 - (mean_residual / bin_capacity as f64).clamp(0.0, 1.0);
    score += 10.0 * pressure * (post_residual as f64 / bin_capacity as f64);

    // Time horizon: early in the stream, keep bins flexible (favor mid residuals);
    // late in the stream, drive toward closing bins tightly.
    let t = if total_items > 0 { step_index as f64 / total_items as f64 } else { 0.0 };
    let ideal_residual = bin_capacity as f64 * (0.35 + 0.45 * t);
    score += 0.12 * (post_residual as f64 - ideal_residual).abs();

    // Mild bonus for filling a bin almost completely.
    if post_residual < 10 {
        score -= 6.0;
    }

    // New-bin candidate: make it attractive only when no open bin fits well.
    if bin_residual == bin_capacity {
        let desperate = if fitting_bins_count == 0 { 1.0 } else { 0.0 };
        score -= 18.0 * desperate;
        score += 15.0 * (1.0 - desperate);
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let cap = bin_capacity as f64;
    let pr = post_residual as f64;
    let progress = if total_items > 1 { step_index as f64 / total_items as f64 } else { 0.0 };
    let mut score = pr;

    // Smooth non-linear coupling: post_residual shaped by stream progress
    let prn = pr / cap;
    let shape = prn * prn * (1.0 - prn);
    score -= 120.0 * shape * (0.5 + progress);

    // Tight fits rewarded more as stream advances
    let tight = 1.0 - prn;
    score -= 30.0 * tight * tight * (1.0 + progress);

    // Penalize residuals too small for typical future items, smoothly
    let next = next_item_size as f64;
    if next > 0.0 {
        let gap = (pr - next) / cap;
        let fit_next = 1.0 / (1.0 + (-8.0 * gap).exp());
        score -= 25.0 * fit_next * (0.3 + progress);
    }

    // Last-chance bin bonus (smooth)
    if fitting_bins_count == 1 {
        score -= 40.0 * (1.0 - prn * prn);
    }

    // Mild pressure toward consolidating into fewer bins
    score += 2.0 * (open_bins_count as f64).ln().max(0.0) * prn;

    // Penalize deviation from mean residual (prefer balanced fills)
    let dev = (pr - mean_residual) / cap;
    score += 10.0 * dev * dev;

    // New-bin candidate: prefer it only when post_residual is large (waste is low)
    if bin_residual == bin_capacity {
        score += 15.0 * (1.0 - prn) * (1.0 - prn);
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Harmonic class of post_residual: quantize dead space into capacity/8 buckets.
    let class = post_residual / (bin_capacity / 8);
    score += class as f64 * 3.0;

    // Reward if the lookahead item fits into the post residual (chained fit).
    if next_item_size > 0 && next_item_size <= post_residual {
        score -= 12.0 + (post_residual - next_item_size) as f64 * 0.5;
    } else if next_item_size > post_residual {
        // Penalize dead space that cannot host the next item, scaled by how dead it is.
        score += (post_residual as f64) * 0.35;
    }

    // Last-chance bin: strongly favor using the only bin that can fit this item.
    if fitting_bins_count == 1 && bin_residual < bin_capacity {
        score -= 25.0;
    }

    // New-bin candidate handling: only attractive when existing fits are poor.
    if bin_residual == bin_capacity {
        // Base cost of opening a new bin, modulated by stream position and spread.
        let progress = step_index as f64 / (total_items.max(1) as f64);
        score = bin_capacity as f64 * 0.9 + progress * 10.0
            + (open_bins_count as f64) * 2.0
            + (mean_residual - item_size as f64).abs() * 0.1;
        // If item is huge relative to capacity, opening fresh is fine.
        if item_size > bin_capacity * 3 / 4 {
            score -= 15.0;
        }
    }

    // Modulo-16 harmony: residual divisible by small classes is more reusable.
    if post_residual % 16 == 0 && post_residual > 0 {
        score -= 4.0;
    }
    if post_residual % 10 == 0 && post_residual > 0 {
        score -= 2.0;
    }

    // Tight fits are excellent: residual barely above item size.
    if item_size > 0 && bin_residual >= item_size && (bin_residual - item_size) < 8 {
        score -= 8.0;
    }

    // Penalize bins whose residual deviates strongly from the mean (fragmentation).
    score += ((bin_residual as f64) - mean_residual).abs() * 0.15;

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Strict dead-space avoidance: residuals that are too small for any
    // future item (min item size = 1..=100, but small gaps < ~15 are
    // nearly unusable) are heavily penalized; perfect fits rewarded.
    let pr = post_residual as f64;
    if post_residual == 0 {
        score -= 60.0; // perfect fit: best possible outcome
    } else if post_residual < 15 {
        score += 45.0; // dead space: gap too small to be useful
    } else if post_residual < 30 {
        score += 12.0; // marginal gap
    } else {
        score -= 8.0;  // roomy residual stays attractive
    }

    // Reward tight relative fit (item fills a large fraction of residual).
    let fit_ratio = item_size as f64 / bin_residual.max(1) as f64;
    score -= 25.0 * fit_ratio * fit_ratio;

    // Open-bin pressure: when many bins are open, prefer consolidating
    // into existing bins; when few are open, opening new bins is cheap.
    let pressure = (open_bins_count as f64).ln().max(0.0);
    if bin_residual != bin_capacity {
        score -= 6.0 * pressure;
    } else {
        // New-bin candidate: penalize mildly, more when bin count is low
        // and stream is early; relax when existing fits are poor.
        score += 10.0 + 4.0 * pressure;
    }

    // Last-chance bin: if this is the only bin that fits, avoid opening
    // a new bin unless the fit is terrible.
    if fitting_bins_count == 1 && bin_residual != bin_capacity {
        score -= 18.0;
    }

    // Lookahead: if the next item fits exactly into the post residual,
    // strongly favor this placement (chaining).
    if next_item_size > 0 {
        if post_residual >= next_item_size {
            let slack = (post_residual - next_item_size) as f64;
            score -= 10.0 * (1.0 - slack / bin_capacity as f64);
        } else {
            score += 6.0; // next item won't fit here afterwards
        }
    }

    // Mild drift toward using mean residual as reference for waste.
    score += 0.15 * (pr - mean_residual).max(0.0);

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Aggressive 2-step lookahead: reward when next item exactly fits the post residual.
    if next_item_size > 0 && post_residual >= next_item_size {
        let slack = (post_residual - next_item_size) as f64;
        score -= 40.0 * (1.0 - slack / bin_capacity as f64);
        // Perfect chain: item + next item exactly fills the bin.
        if slack == 0.0 {
            score -= 60.0;
        }
    } else if next_item_size > 0 && post_residual < next_item_size {
        // Dead space: next item cannot use the leftover residual.
        // Penalize proportionally to wasted space, more so for small leftovers.
        let dead = post_residual as f64;
        score += 0.5 * dead + 10.0 * (dead / bin_capacity as f64);
    }

    // Compare against mean residual: prefer bins tighter than average (best-fit flavor),
    // penalize placing into bins that are already roomier than average.
    if (bin_residual as f64) > mean_residual {
        score += 0.3 * (bin_residual as f64 - mean_residual);
    } else {
        score -= 0.15 * (mean_residual - bin_residual as f64);
    }

    // Last chance: if this is the only bin that can fit the item, strongly prefer it
    // over opening a new bin (unless post residual would be tiny dead space).
    if fitting_bins_count == 1 {
        score -= 25.0;
        if next_item_size > 0 && post_residual < next_item_size && post_residual < 10 {
            score += 20.0; // tiny dead space: reconsider opening a new bin
        }
    }

    // New-bin candidate: only attractive when item is large and no good fit exists.
    if bin_residual == bin_capacity {
        score = item_size as f64 * 0.8 + 30.0;
        if next_item_size > 0 {
            // Favor a new bin if next item could pair with this one there.
            if item_size + next_item_size <= bin_capacity {
                score -= 15.0;
            }
        }
        if fitting_bins_count == 1 {
            score += 50.0; // don't open new bin when an existing fit exists
        }
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Tightness reward: prefer bins that become nearly full after placement.
    let tightness = 1.0 - (post_residual as f64 / bin_capacity as f64);
    score -= 55.0 * tightness * tightness;

    // Exact fill bonus.
    if post_residual == 0 {
        score -= 40.0;
    }

    // Lookahead coupling: if the next item fits the post-residual exactly, reward strongly.
    if next_item_size > 0 {
        if post_residual >= next_item_size {
            let slack = (post_residual - next_item_size) as f64;
            score -= 18.0 * (1.0 - slack / bin_capacity as f64);
        } else {
            // Post-residual too small for next item: penalize dead space, scaled by how close.
            let gap = (next_item_size - post_residual) as f64;
            score += 6.0 * (gap / item_size.max(1) as f64).min(2.0);
        }
    } else {
        // Last item: pure tightness matters most.
        score -= 25.0 * tightness;
    }

    // Last-chance bin: strongly favor using the only bin that fits.
    if fitting_bins_count == 1 && bin_residual >= item_size && bin_residual != bin_capacity {
        score -= 30.0;
    }
    if fitting_bins_count > 2 {
        // Plenty of alternatives; mild penalty to keep options open.
        score += 3.0 * (fitting_bins_count as f64 - 2.0).min(5.0);
    }

    // Global state: many open bins with high mean residual -> prefer filling existing bins.
    let progress = step_index as f64 / (total_items.max(1) as f64);
    let crowded = (open_bins_count as f64 / (1.0 + mean_residual / 10.0)).min(10.0);
    score -= 2.0 * crowded * (0.5 + 0.5 * progress);

    // New-bin candidate: penalize opening a new bin, more so early in the stream.
    if bin_residual == bin_capacity {
        score += 12.0 + 25.0 * (1.0 - progress);
        // But if mean residual of open bins is tiny (all nearly full), opening is fine.
        score -= (mean_residual / 20.0).min(20.0);
    }

    // Small residual penalty: leaving awkward small gaps wastes capacity.
    if post_residual > 0 && post_residual < 10 {
        score += 8.0;
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let cap = bin_capacity as f64;
    let pr = post_residual as f64;
    let progress = if total_items > 0 { step_index as f64 / total_items as f64 } else { 0.0 };
    let x = pr / cap; // normalized post residual

    // Base: quadratic penalty on wasted residual, softened by stream progress
    let mut score = x * x * cap * (1.0 + 0.5 * progress);

    // Smooth cubic coupling between residual and progress: late in stream,
    // tight fits are more valuable; loose residuals penalized more.
    score += 8.0 * x.powi(3) * cap * (0.5 + progress);

    // Reward filling the bin well (item_size relative to residual)
    let fill = item_size as f64 / bin_residual as f64;
    score -= 12.0 * fill * (1.0 - 0.3 * progress);

    // Penalty if post residual is small but nonzero (dead space) — smooth trough
    if pr > 0.0 {
        score += 6.0 * (-x * 12.0).exp() * (1.0 - x);
    }

    // Last-chance bin: strong reward to use it
    if fitting_bins_count == 1 && bin_residual != bin_capacity {
        score -= 25.0;
    }

    // Lookahead: if next item fits the post residual, reward this placement
    if next_item_size > 0 && next_item_size <= post_residual {
        let next_fit = next_item_size as f64 / post_residual as f64;
        score -= 10.0 * next_fit;
    } else if next_item_size > post_residual {
        score += 3.0;
    }

    // New-bin candidate: prefer opening a new bin when existing residuals are large
    // and stream is early (many items remain); penalize late-stream bin opening.
    if bin_residual == bin_capacity {
        let early = (1.0 - progress).powi(2);
        score = cap * (1.0 + 0.2 * open_bins_count as f64 * 0.05)
            - 15.0 * early
            + 10.0 * progress;
        if mean_residual > 0.0 {
            score += 0.05 * mean_residual * (1.0 + progress);
        }
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Harmonic class of the post residual: bins whose leftover falls into
    // "small residue classes" are more reusable, so reward them.
    let cap = bin_capacity as f64;

    // Perfect fit: overwhelming reward.
    if post_residual == 0 {
        score -= 1000.0;
    }

    // Tightness reward: residual below the smallest plausible item (1..=10)
    // is nearly a perfect fit for future packing.
    if post_residual > 0 && post_residual <= 10 {
        score -= 60.0;
    } else if post_residual <= 20 {
        score -= 25.0;
    }

    // Modulo-arithmetic harmonic classes on post_residual (wrt capacity 100).
    // Residues near multiples of common item sizes are reusable.
    let pr = post_residual;
    let harmonic_bonus = |r: u32| -> f64 {
        let mut b = 0.0;
        for m in [10u32, 20, 25, 50].iter() {
            let rem = r % m;
            let dist = (*m as f64 - rem as f64).min(rem as f64);
            b += (m as f64) / (1.0 + dist);
        }
        b
    };
    score -= harmonic_bonus(pr) * 0.35;

    // Penalize awkward dead space: residuals that no typical item (1..=50)
    // can use efficiently. Anything > 50 wastes at least half a bin slot.
    if pr > 50 {
        score += (pr as f64 - 50.0) * 1.5;
    }

    // Last-chance bin: if this is the only bin that fits, strongly prefer
    // using it over opening a new one (unless the fit is terrible).
    if fitting_bins_count == 1 && bin_residual != bin_capacity {
        score -= 40.0 + item_size as f64 * 0.5;
    }

    // New-bin candidate handling: opening a new bin is only attractive when
    // no open bin gives a decent fit. Penalize the empty bin mildly, scaled
    // by how many bins are already open and stream progress.
    if bin_residual == bin_capacity {
        let progress = step_index as f64 / (total_items.max(1) as f64);
        score += 30.0 + open_bins_count as f64 * 2.0 + progress * 10.0;
        // But if the item is large and fits badly anywhere, new bin is fine:
        if item_size >= bin_capacity / 2 {
            score -= 25.0;
        }
    }

    // Lookahead coupling: if the next item can exactly use this bin's
    // post-residual, big reward for reserving it.
    if next_item_size > 0 {
        if next_item_size == pr {
            score -= 200.0;
        } else if next_item_size <= pr {
            score -= (pr as f64 - next_item_size as f64).min(30.0) * 0.8;
        } else {
            // Next item won't fit here; slight penalty proportional to waste.
            score += (next_item_size - pr) as f64 * 0.1;
        }
    }

    // Prefer bins below the mean residual (fill fuller bins first),
    // a classic best-fit-with-memory coupling.
    score += (mean_residual - bin_residual as f64) * 0.3;

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Strict dead-space avoidance: penalize small unusable gaps harshly.
    // A residual that cannot fit even the smallest plausible item (<= 10)
    // is pure waste; smaller post_residuals in the "dead zone" get amplified.
    if post_residual > 0 && post_residual < 10 {
        score += 60.0 * (10.0 - post_residual as f64);
    } else if post_residual == 0 {
        // Perfect fit: strong reward.
        score -= 40.0;
    } else {
        // Non-linear penalty on leftover: favor tight fits quadratically.
        let pr = post_residual as f64;
        score += 0.05 * pr * pr / bin_capacity as f64;
    }

    // Lookahead coupling: reward bins whose leftover can host the next item.
    if next_item_size > 0 {
        if post_residual >= next_item_size {
            score -= 12.0;
        } else if post_residual > 0 {
            score += 8.0;
        }
    }

    // Last-chance pressure: if this is the only fitting bin, avoid forcing
    // a new bin unless the fit is terrible.
    if fitting_bins_count == 1 && bin_residual != bin_capacity {
        score -= 15.0;
    }

    // Open-bin pressure: with many open bins, discourage opening new ones
    // (penalize the empty-bin candidate) and encourage consolidating.
    let progress = step_index as f64 / total_items.max(1) as f64;
    if bin_residual == bin_capacity {
        score += 10.0 + 3.0 * open_bins_count as f64 + 10.0 * progress;
    } else {
        score -= 2.0 * open_bins_count as f64 * (1.0 - progress);
    }

    // Prefer bins with residual far from mean (tighter than average).
    score += 0.1 * (bin_residual as f64 - mean_residual);

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;
    let progress = if total_items > 0 { step_index as f64 / total_items as f64 } else { 0.0 };

    // Aggressive 2-step lookahead: reward exact match between post_residual and next item
    if next_item_size > 0 {
        let diff = (post_residual as i64 - next_item_size as i64).abs() as f64;
        score += 0.5 * diff;
        // Perfect chain: post_residual == next_item_size -> strong bonus
        if post_residual == next_item_size {
            score -= 60.0;
        } else if post_residual < next_item_size {
            // next item won't fit here; penalize dead space proportional to gap
            score += 0.3 * (next_item_size - post_residual) as f64;
        } else {
            // next item fits with leftover; bonus scaled by tightness
            score -= 10.0 * (1.0 - diff / bin_capacity as f64);
        }
    } else {
        // last item: prefer minimal post_residual strongly
        score += 0.2 * post_residual as f64;
    }

    // Relative to mean residual: prefer bins tighter than average
    score += 0.4 * (mean_residual - post_residual as f64);

    // Penalize tiny unusable residuals (dead space)
    if post_residual > 0 && post_residual < 10 {
        score += 15.0;
    }

    // Last-chance bin: strong reward to avoid opening a new bin
    if fitting_bins_count == 1 && bin_residual != bin_capacity {
        score -= 25.0 * (1.0 - progress);
    }

    // New-bin candidate: penalize unless current residuals are large relative to item
    if bin_residual == bin_capacity {
        let avg_fit = mean_residual;
        if avg_fit > item_size as f64 * 1.5 {
            score += 40.0; // keep using open bins
        } else {
            score -= 5.0; // opening fresh bin is reasonable
        }
    }

    // Mild preference to fill older/fuller bins as stream progresses
    score += 0.05 * progress * post_residual as f64;

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Reward tight fits: square the post-residual penalty so near-perfect fits dominate.
    score += (post_residual as f64 / bin_capacity as f64).powi(3) * 30.0;

    // Lookahead (k=2): if the next item fits exactly in the post-residual,
    // this bin is extra valuable -> strongly reward.
    if next_item_size > 0 {
        if post_residual == next_item_size {
            score -= 25.0;
        } else if post_residual >= next_item_size {
            // Next item fits but leaves more waste; mild reward proportional to fit quality.
            let slack = (post_residual - next_item_size) as f64;
            score -= 12.0 - (slack / bin_capacity as f64) * 12.0;
        } else {
            // Next item cannot use the leftover; penalize leaving a hole smaller than next item.
            let hole = post_residual as f64;
            if hole > 0.0 {
                score += (hole / next_item_size as f64) * 3.0;
            }
        }
    }

    // Last-chance bin: if this is the only open bin that can fit the item,
    // strongly favor using it over opening a new bin.
    if fitting_bins_count == 1 && bin_residual < bin_capacity {
        score -= 20.0;
    }

    // New-bin candidate handling: an empty bin should only win when open bins
    // are poor fits. Penalize the fresh bin based on how much residual capacity
    // currently exists across the open-bin pool.
    if bin_residual == bin_capacity {
        let progress = step_index as f64 / (total_items.max(1) as f64);
        // Early on, opening bins is cheap; later, prefer consolidating.
        let open_penalty = 8.0 + 14.0 * progress;
        score += open_penalty;
        // If mean residual across open bins is large, opening a new bin is wasteful.
        score += (mean_residual / bin_capacity as f64).max(0.0) * 15.0;
        // If many bins can already fit the item, definitely don't open a new one.
        if fitting_bins_count > 1 {
            score += 10.0 * fitting_bins_count as f64;
        }
    } else {
        // Mild preference for bins with less residual overall (denser bins).
        score += (bin_residual as f64 / bin_capacity as f64) * 2.0;
    }

    // Slight bonus for using bins as the stream progresses (consolidation pressure).
    score -= 1.0 * (step_index as f64 / (total_items.max(1) as f64));

    // Penalize extremely fragmented pools: encourage filling bins with big residuals.
    if (bin_residual as f64) > mean_residual && bin_residual < bin_capacity {
        score -= 1.5;
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let progress = if total_items > 0 { step_index as f64 / total_items as f64 } else { 0.0 };
    let cap = bin_capacity as f64;
    let pr = post_residual as f64;
    let mut score = pr;

    // Non-linear waste penalty: quadratic in normalized post-residual, amplified by progress
    let norm_pr = pr / cap;
    score += 18.0 * norm_pr * norm_pr * (0.5 + progress);

    // Reward tight fits (small post_residual) with a smooth saturating bonus
    score -= 14.0 * (-pr / (0.25 * cap)).exp() * (1.0 - 0.5 * progress);

    // Exact fill reward
    if post_residual == 0 {
        score -= 25.0;
    }

    // Lookahead coupling: if next item fits the post-residual, reward this placement smoothly
    if next_item_size > 0 {
        let fits_next = (post_residual >= next_item_size) as i32 as f64;
        let slack = (post_residual as i64 - next_item_size as i64).unsigned_abs() as f64 / cap;
        score -= 10.0 * fits_next * (-slack * 6.0).exp();
        score += 6.0 * (1.0 - fits_next) * norm_pr;
    }

    // Last-chance bin: strongly favor using it to avoid opening a new bin
    if fitting_bins_count == 1 && bin_residual < bin_capacity {
        score -= 20.0 * (1.0 - progress);
    }

    // New-bin candidate: penalize opening a bin early, less so late in the stream;
    // but allow it when the item would leave large dead space in any existing bin
    if bin_residual == bin_capacity {
        let dead_space_pressure = ((mean_residual - pr) / cap).max(0.0);
        score += 30.0 * (1.0 - progress) - 25.0 * dead_space_pressure * (0.3 + progress);
    }

    // Mild penalty proportional to number of open bins to discourage bin proliferation
    score += 0.4 * open_bins_count as f64 * norm_pr;

    // Mean-residual divergence: prefer bins whose residual is below mean (tighter bins)
    score += 3.0 * (pr as f64 - mean_residual) / cap;

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let cap = bin_capacity as f64;
    let mut score = post_residual as f64;

    // Harmonic class of the item: which capacity fraction band does it live in?
    let item_class = item_size / 10; // 0..=10 harmonic class
    let next_class = next_item_size / 10;

    // Reward near-perfect fits (harmonic pairing: post_residual matches a small class)
    if post_residual == 0 {
        score -= 1000.0;
    } else if post_residual <= 10 {
        score -= 120.0;
    } else if post_residual <= 20 {
        score -= 60.0;
    } else if post_residual <= 30 {
        score -= 25.0;
    }

    // Modulo logic: dead space in awkward residue classes is penalized more.
    let r = post_residual % 10;
    score += (r as f64) * 1.5;

    // Lookahead coupling: if the next item exactly fills the post_residual, huge reward.
    if next_item_size > 0 {
        if next_item_size == post_residual {
            score -= 400.0;
        } else if next_item_size <= post_residual {
            // next item fits: reward proportional to how well it fills
            let fill = next_item_size as f64 / post_residual as f64;
            score -= 80.0 * fill;
        } else {
            // next item cannot use this residual: penalize large leftovers
            score += (post_residual as f64) * 0.4;
            // extra penalty if next item is large and will need a fresh bin anyway
            if next_item_size > 50 {
                score += 10.0;
            }
        }
        // harmonic class match: next item in same class likes same bin family
        if next_class == item_class && post_residual >= next_item_size {
            score -= 15.0;
        }
    }

    // Last-chance bin: strongly favor using it to avoid opening a new bin.
    if fitting_bins_count == 1 && bin_residual >= item_size {
        score -= 90.0;
    }

    // New-bin candidate handling: opening a bin is only attractive when the item
    // is large and current bins are fragmented.
    if bin_residual == bin_capacity {
        let progress = step_index as f64 / total_items.max(1) as f64;
        let fragmentation = mean_residual / cap;
        // penalty grows with fragmentation (prefer reusing bins), shrinks for big items
        score += 70.0 * fragmentation + 30.0 * (1.0 - item_size as f64 / cap);
        // late in the stream, prefer closing out existing bins
        score += 25.0 * progress;
        if item_size >= 50 {
            score -= 20.0;
        }
    }

    // Mild preference for bins below mean residual (keep a spread of bin sizes)
    if (bin_residual as f64) < mean_residual {
        score -= 5.0;
    }

    // Tie-break noise-free nudge by class ordering to stabilize selection
    score += item_class as f64 * 0.01;

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Strict dead-space avoidance: gaps below the minimum item size are pure waste.
    let min_item = 1u32;
    if post_residual < min_item {
        score -= 50.0; // perfect fill, best possible outcome
    } else if post_residual <= 10 {
        // small unusable-ish gap: heavy penalty scaled by how close to zero
        score += (10 - post_residual) as f64 * 2.0;
    } else if post_residual <= 20 {
        score += 6.0;
    }

    // Reward tight fits: fraction of bin used by this placement.
    let fill_ratio = item_size as f64 / bin_capacity.max(1) as f64;
    score -= 12.0 * fill_ratio;

    // Last-chance bin: strongly prefer using it over opening a new bin.
    if fitting_bins_count == 1 && bin_residual != bin_capacity {
        score -= 25.0;
    }

    // Open-bin pressure: when many bins are open, favor consolidation.
    let progress = step_index as f64 / (total_items.max(1) as f64);
    score += open_bins_count as f64 * 0.8 * (0.5 + progress);

    // Prefer bins with below-average residual (more filled bins get priority).
    score += (bin_residual as f64 - mean_residual) * 0.15;

    // Lookahead: if the next item fits exactly in the post-residual, reward heavily.
    if next_item_size > 0 && next_item_size == post_residual {
        score -= 30.0;
    } else if next_item_size > 0 && next_item_size <= post_residual {
        score -= 5.0;
    }

    // New-bin candidate: only attractive when no open bin offers a decent fit.
    if bin_residual == bin_capacity {
        let decent_fit_exists = fitting_bins_count > 0 && post_residual <= bin_capacity / 4;
        if decent_fit_exists {
            score += 40.0; // discourage opening a new bin when a fit exists
        } else if fitting_bins_count == 0 {
            score -= 60.0; // must open a new bin
        } else {
            // fits exist but all poor: mild preference for new bin
            score -= 5.0;
        }
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Aggressive 2-step lookahead: reward when next item fits into post_residual
    if next_item_size > 0 {
        if post_residual >= next_item_size {
            // next item fits exactly or well: strong reward
            let perfect = (post_residual as i64 - next_item_size as i64).abs();
            score -= 30.0 + (bin_capacity as f64 - perfect as f64) * 0.3;
        } else {
            // next item won't fit: penalize wasted space
            score += (next_item_size as f64 - post_residual as f64) * 0.5;
        }
    }

    // Tight fit reward relative to bin capacity
    let tightness = item_size as f64 / bin_residual as f64;
    score -= tightness * 12.0;

    // Compare post_residual against mean residual of open bins
    if mean_residual > 0.0 {
        let rel = post_residual as f64 / mean_residual;
        if rel < 0.5 {
            score -= 8.0; // leaving less slack than average is good
        } else {
            score += (rel - 0.5) * 5.0;
        }
    }

    // Last-chance bin: strongly favor using it to avoid opening a new bin
    if fitting_bins_count == 1 && bin_residual != bin_capacity {
        score -= 40.0;
    }

    // Penalize opening a new bin when good fits exist
    if bin_residual == bin_capacity {
        score += 25.0 + open_bins_count as f64 * 0.5;
    }

    // Slight late-stream consolidation pressure
    let progress = step_index as f64 / total_items.max(1) as f64;
    score += progress * 4.0;

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
