            score -= 25.0;
        } else if next_item_size <= post_residual {
            let slack = (post_residual - next_item_size) as f64 / bin_capacity as f64;
            score -= 8.0 * (1.0 - slack);
        } else {
            // Next item won't fit here: mild penalty for creating near-dead space.
            if post_residual < 10 {
                score += 6.0;
            }
        }
    } else {
        // Last item: just minimize leftover.
        score -= 10.0 * fill;
    }

    // Scarcity: if this is the only bin that fits, strongly prefer using it.
    if fitting_bins_count == 1 {
        score -= 20.0;
    } else if fitting_bins_count > 3 {
        // Many alternatives: be picky, penalize mediocre fits.
        score += 3.0 * waste;
    }

    // Penalize bins whose residual is far above the mean (fragmentation).
    score += 0.15 * (bin_residual as f64 - mean_residual).abs();

    // Dynamic time horizon: early in stream, allow more bins (exploration);
    // late in stream, consolidate into existing bins.
    let progress = if total_items > 0 { step_index as f64 / total_items as f64 } else { 0.0 };
    let new_bin_bonus = 20.0 * (1.0 - progress);
    if bin_residual == bin_capacity {
        // New-bin candidate: attractive early, unattractive late.
        score -= new_bin_bonus;
        // But never open a new bin if existing bins fit well.
        if post_residual < 20 && fitting_bins_count >= 1 {
            score += 30.0;
        }
        // Avoid opening new bins when many bins are already open and mean residual is large.
        if open_bins_count > 2 && mean_residual > item_size as f64 * 1.5 {
            score += 12.0;
        }
    }

    // Slight preference to keep number of open bins low late in the stream.
    score += 0.5 * open_bins_count as f64 * progress;

    // Prefer placing into bins where this item leaves residual that is a common small size (10/20/30).
    if post_residual <= 30 {
        score -= 5.0;
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let progress = (step_index as f64 / total_items.max(1) as f64).clamp(0.0, 1.0);
    let pr = post_residual as f64;
    let cap = bin_capacity as f64;
    let pr_norm = pr / cap;

    // Base: penalize leftover space non-linearly (quadratic waste growth)
    let mut score = pr * (1.0 + pr_norm * (1.0 + progress));

    // Smooth non-linear coupling: waste matters more as stream progresses
    score += (pr_norm * pr_norm) * cap * (0.5 + 0.5 * progress) * (1.0 - (1.0 - progress) * (1.0 - progress));

    // Reward tight fits: smooth sigmoid-like term on fill ratio
    let fill = 1.0 - pr_norm;
    score -= (fill * fill) * (pr * 0.5) * (1.0 + progress);

    // Last-chance bonus: strongly favor the only bin that fits
    if fitting_bins_count == 1 {
        score -= 25.0 + 15.0 * progress;
    }

    // Lookahead: if next item fits into post_residual, reward this placement
    if next_item_size > 0 {
        if (next_item_size as f64) <= pr {
            score -= 8.0 + 6.0 * progress;
        } else {
            // penalize leaving residuals that are nearly-but-not fitting for next item
            let gap = pr - next_item_size as f64;
            if gap > 0.0 && gap < 10.0 {
                score += gap * (1.0 + progress);
            }
        }
    }

    // Mild penalty for residual close to mean residual (fragmentation spread)
    score += ((pr - mean_residual).abs() / cap) * (2.0 + 3.0 * progress);

    // New-bin candidate: baseline competitive score, cheaper early, costlier late
    if bin_residual == bin_capacity {
        score = 30.0 * (1.0 - progress) + 10.0 + 0.5 * mean_residual * progress;
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Harmonic class of post_residual: residual mod small integers
    // classify how "usable" the leftover space is for typical item sizes (1..100)
    let pr = post_residual;
    let m4 = pr % 4;
    let m5 = pr % 5;
    let m10 = pr % 10;
    let m20 = pr % 20;

    // Dead-space classes: residuals that are tiny but nonzero are worst
    if pr > 0 && pr < 5 {
        score += 60.0; // nearly unusable sliver
    } else if pr == 0 {
        score -= 80.0; // perfect fit
    } else if pr <= 10 {
        score += 25.0; // small but maybe usable
    }

    // Modulo harmonic penalties: residuals divisible by common item granularities are reusable
    if m10 == 0 && pr > 0 {
        score -= 15.0;
    }
    if m5 == 0 && pr > 0 && m10 != 0 {
        score -= 7.0;
    }
    if m4 == 0 && pr > 0 {
        score -= 4.0;
    }
    // awkward classes: prime-ish remainders
    if m20 != 0 && m10 != 0 && m5 != 0 && m4 != 0 && pr > 10 {
        score += 6.0;
    }

    // Lookahead: does the next item fit into post_residual?
    if next_item_size > 0 {
        if next_item_size <= pr {
            score -= 30.0 + 0.2 * next_item_size as f64;
            // harmonic bonus if post_residual is an exact multiple class for next item
            if pr % next_item_size.max(1) == 0 {
                score -= 10.0;
            }
        } else {
            // next item won't fit here; leftover becomes dead space for lookahead
            score += 12.0;
        }
    }

    // Last-chance bin: strongly favor using the only bin that fits
    if fitting_bins_count == 1 && bin_residual != bin_capacity {
        score -= 55.0;
    }

    // New-bin candidate handling
    if bin_residual == bin_capacity {
        // opening a new bin is penalized unless current bin leaves a terrible residual
        let bad_fit = pr > 0 && pr < 10;
        let many_open = open_bins_count as f64 > 8.0;
        if bad_fit {
            score -= 90.0; // prefer fresh bin over creating a sliver
        } else {
            score += 40.0 + 3.0 * open_bins_count as f64;
            if many_open {
                score += 10.0;
            }
        }
        // early stream: slightly discourage new bins to keep bins tight
        let progress = step_index as f64 / (total_items.max(1) as f64);
        score += 20.0 * (1.0 - progress);
    }

    // tightness reward: filling a bin well
    let fill = item_size as f64 / bin_capacity as f64;
    score -= 25.0 * fill * fill;

    // mean residual coupling: prefer bins below mean residual (tighter bins)
    score += 0.3 * (mean_residual - post_residual as f64);

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Strict dead-space avoidance: small unusable gaps are heavily penalized.
    if post_residual > 0 && post_residual < 10 {
        score += 40.0;
    } else if post_residual < 20 {
        score += 12.0;
    } else if post_residual < 30 {
        score += 4.0;
    } else {
        // Larger residuals are less harmful, mild quadratic penalty.
        score += (post_residual as f64) * 0.05;
    }

    // Perfect fit bonus.
    if post_residual == 0 {
        score -= 100.0;
    }

    // Last-chance bin: strongly favor using it to avoid opening a new bin.
    if fitting_bins_count == 1 {
        score -= 25.0;
    }

    // Open-bin pressure: with many open bins, prefer filling existing ones.
    let pressure = open_bins_count as f64 / (total_items as f64).max(1.0);
    score += pressure * 30.0;

    // Prefer bins below mean residual (tighter bins) when many bins are open.
    score += (mean_residual - bin_residual as f64) * 0.3 * (open_bins_count as f64).ln().max(1.0);

    // Lookahead: if next item fits the post residual, reward this placement.
    if next_item_size > 0 && post_residual >= next_item_size {
        score -= 15.0;
    }
    // If next item cannot fit in post residual but could fit in a fresh bin, penalize less when post_residual is large.
    if next_item_size > post_residual && post_residual > 0 {
        score += 5.0;
    }

    // New-bin candidate: only attractive if no open bin fits well.
    if bin_residual == bin_capacity {
        // Opening a new bin is penalized mildly; last-chance pressure on open bins usually wins.
        score += 10.0 + open_bins_count as f64 * 0.5;
        if fitting_bins_count == 0 {
            score -= 200.0;
        }
        // Early stream: allow new bins more freely.
        if (step_index as f64) / (total_items as f64).max(1.0) < 0.2 {
            score -= 8.0;
        }
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Perfect 2-step match: post_residual equals next item size exactly.
    if next_item_size > 0 && post_residual == next_item_size {
        score -= 60.0;
    } else if next_item_size > 0 && post_residual > next_item_size {
        // Post-residual leaves room for next item; closer match = better.
        let gap = (post_residual - next_item_size) as f64;
        score -= 40.0 * (1.0 - gap / bin_capacity as f64);
    } else if next_item_size > 0 {
        // Post-residual too small for next item: penalize dead space that
        // cannot absorb the lookahead, scaled by how close we missed.
        let miss = (next_item_size - post_residual) as f64;
        score += 15.0 * (1.0 - miss / bin_capacity as f64);
    }

    // Last-chance bin: strongly favor using it to avoid opening a new bin.
    if fitting_bins_count == 1 && bin_residual != bin_capacity {
        score -= 25.0;
    }

    // Reward bins tighter than the mean residual (good packing density).
    score -= 0.5 * (mean_residual - post_residual as f64);

    // Penalize opening a new bin when plenty of open bins exist,
    // but relax near the end of the stream (no need to hoard space).
    let progress = if total_items > 0 { step_index as f64 / total_items as f64 } else { 0.0 };
    if bin_residual == bin_capacity {
        score += 35.0 * (1.0 - progress) + (open_bins_count as f64).sqrt() * 5.0;
    }

    // Mild reward for very tight fits overall (low post-residual is convex-good).
    if post_residual <= 10 {
        score -= 10.0;
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let capacity = bin_capacity as f64;
    let mut score = post_residual as f64;

    // Perfect fit reward
    if post_residual == 0 {
        score -= 1000.0;
    }

    // Tightness: reward leaving small-but-usable residuals
    let t = post_residual as f64 / capacity;
    score += 30.0 * t * t;

    // Lookahead: if next item fits exactly in post_residual, strong reward
    if next_item_size > 0 {
        let nxt = next_item_size as f64;
        if next_item_size == post_residual {
            score -= 500.0;
        } else if next_item_size <= post_residual {
            score -= 50.0 * (1.0 - nxt / capacity);
        } else {
            // next item cannot use the leftover: penalize large leftovers
            score += 20.0 * t;
        }
    } else {
        // last item: prefer any fit
        score -= 200.0;
    }

    // Last-chance bin: strongly favor using the only bin that fits
    if fitting_bins_count == 1 && bin_residual < bin_capacity {
        score -= 150.0;
    }

    // Global pressure: many open bins with low mean residual -> prefer filling existing bins
    let progress = step_index as f64 / (total_items.max(1) as f64);
    let pressure = open_bins_count as f64 / (1.0 + mean_residual / capacity);
    score -= pressure * (0.5 + progress);

    // New-bin candidate handling: make empty bins moderately attractive only when
    // item is large relative to typical residuals or few fitting bins exist
    if bin_residual == bin_capacity {
        if fitting_bins_count == 0 {
            score -= 100.0;
        } else {
            score += 40.0 + 60.0 * (item_size as f64 / capacity) * (1.0 - progress);
        }
    }

    // Reward placing large items into bins with large residuals
    score -= 10.0 * (item_size as f64 / capacity) * (bin_residual as f64 / capacity);

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let progress = step_index as f64 / total_items.max(1) as f64;
    let cap = bin_capacity as f64;
    let pr = post_residual as f64;
    let pr_norm = pr / cap;

    // Base: prefer tight fits (small post_residual), with a non-linear
    // polynomial shaping that changes smoothly over stream progress.
    let mut score = pr_norm * (1.0 + 0.8 * progress) - 0.35 * pr_norm * pr_norm;

    // Quadratic coupling: mid-range residuals become increasingly costly
    // as the stream advances (dead space is less recoverable later).
    let mid = pr_norm * (1.0 - pr_norm); // peaks at 0.5 residual
    score += 0.25 * mid * mid * (1.0 - progress);

    // Cubic penalty for large leftover space, growing with progress.
    score += 0.15 * pr_norm.powi(3) * (0.5 + progress);

    // Last-chance bonus: strongly favor the unique bin that fits.
    if fitting_bins_count == 1 && bin_residual != bin_capacity {
        score -= 2.0;
    }

    // Lookahead: reward bins whose post_residual can host the next item.
    if next_item_size > 0 && post_residual >= next_item_size {
        let slack = (post_residual - next_item_size) as f64 / cap;
        score -= 0.4 * (1.0 - slack) * (1.0 - 0.5 * progress);
    } else if next_item_size > 0 {
        // Post-residual cannot host next item: penalize mildly.
        score += 0.1 * pr_norm;
    }

    // Global context coupling: when mean residual is high, prefer using
    // existing space rather than fragmenting further.
    let mean_norm = mean_residual / cap;
    score += 0.3 * pr_norm * mean_norm * (1.0 - progress);

    // New-bin candidate: acceptable early (bins are cheap) but increasingly
    // penalized as the stream progresses, with a smooth ramp.
    if bin_residual == bin_capacity {
        score = 0.6 + 1.2 * progress * progress + 0.05 * open_bins_count as f64;
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Harmonic class of post_residual: residues mod 10 define "dead space" quality.
    let pr = post_residual;
    let class = pr % 10;
    let class_penalty: f64 = match class {
        0 => -8.0,                       // perfect fit class
        1 | 2 => -4.0,                   // nearly perfect
        3 | 4 | 5 | 6 | 7 => 6.0,        // awkward dead zone
        8 | 9 => -1.5,                   // re-usable by small items
        _ => 0.0,
    };
    score += class_penalty;

    // Integer-division threshold: post_residual buckets by quarter capacity.
    let quarter = bin_capacity / 4;
    if pr == 0 {
        score -= 20.0;
    } else if pr < quarter / 2 {
        score += 4.0;                    // sliver: hard to fill
    } else if pr >= quarter && pr < 2 * quarter {
        score -= 3.0;                    // quarter-class residual is useful
    }

    // Lookahead coupling: reward when next item fits the post residual exactly-ish.
    if next_item_size > 0 && next_item_size <= pr {
        let next_post = pr - next_item_size;
        if next_post % 10 == 0 {
            score -= 9.0;
        } else if next_post < 10 {
            score += 5.0;                // next item would leave a sliver
        } else {
            score -= 2.0;
        }
    } else if next_item_size > pr && pr > 0 {
        score += 3.0;                    // next item cannot use leftover
    }

    // Last-chance bin: strongly favor using the only fitting bin.
    if fitting_bins_count == 1 && bin_residual < bin_capacity {
        score -= 15.0;
    }

    // New-bin candidate: only prefer when no open bin is a good harmonic fit.
    if bin_residual == bin_capacity {
        score = (bin_capacity as f64) * 0.75;
        if fitting_bins_count == 0 {
            score -= 40.0;
        }
    }

    // Progress-aware tightening: late in stream, prefer closing bins out.
    let progress = step_index as f64 / total_items.max(1) as f64;
    score += progress * 2.0 * (mean_residual - post_residual as f64).abs() / 10.0;

    // Prefer fullest bins (smallest residual before placement) mildly.
    score += (bin_residual as f64 - post_residual as f64) * 0.05;

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Strict dead-space avoidance: residuals that are too small for any
    // plausible future item (min size 1, but realistically small gaps < 12
    // are wasteful) get a heavy nonlinear penalty.
    if post_residual > 0 && post_residual < 12 {
        score += 60.0 * (12.0 - post_residual as f64);
    }
    // Mid-range dead space (12..30) is also hard to fill; moderate penalty.
    if post_residual >= 12 && post_residual < 30 {
        score += 8.0 + 0.5 * (30.0 - post_residual as f64);
    }

    // Reward perfect / near-perfect fits.
    if post_residual == 0 {
        score -= 40.0;
    } else if post_residual <= 5 {
        score -= 15.0;
    }

    // Reward bins whose residual is tightly consumed relative to the bin.
    let fill_ratio = (item_size as f64) / (bin_residual as f64).max(1.0);
    score -= 25.0 * fill_ratio;

    // Open-bin pressure: prefer packing into existing bins when many are open,
    // but the new-bin candidate (residual == capacity) gets a mild penalty so
    // we only open when existing fits are poor.
    if bin_residual == bin_capacity {
        score += 20.0 + 2.0 * open_bins_count as f64;
    } else {
        score -= 3.0 * open_bins_count as f64;
    }

    // Last-chance bin: if this is the only bin that fits, strongly favor it
    // to avoid opening a new bin.
    if fitting_bins_count == 1 && bin_residual != bin_capacity {
        score -= 30.0;
    }

    // Lookahead: if the next item fits the post-residual exactly, reward it.
    if next_item_size > 0 {
        if post_residual >= next_item_size {
            score -= 6.0;
            if post_residual - next_item_size < 10 {
                score -= 10.0;
            }
        } else {
            score += 4.0;
        }
    }

    // Late in the stream, consolidate harder (avoid leftover bins).
    let progress = step_index as f64 / total_items.max(1) as f64;
    score -= 10.0 * progress * (bin_residual - post_residual) as f64 / bin_capacity as f64;

    // Mild preference toward bins already below-average residual (tighter bins).
    score += 0.3 * (mean_residual - bin_residual as f64);

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Perfect 2-step match: post_residual exactly equals next item size -> strong reward.
    if next_item_size > 0 && post_residual == next_item_size {
        score -= 1000.0;
    }

    // Post-residual that can still fit the next item is valuable; waste is penalized more.
    if next_item_size > 0 {
        if post_residual >= next_item_size {
            score -= 0.5 * (post_residual as f64 - next_item_size as f64);
        } else {
            // Dead space that the next item cannot use: penalize quadratically.
            let waste = (next_item_size - post_residual) as f64;
            score += 1.5 * waste * waste / 100.0;
        }
    }

    // Prefer bins whose residual was tight relative to the mean (filling fuller bins).
    score -= 0.3 * (bin_residual as f64 - mean_residual);

    // Last-chance bin: if this is the only bin that fits, strongly prefer using it.
    if fitting_bins_count == 1 && bin_residual < bin_capacity {
        score -= 200.0;
    }

    // New-bin candidate (empty bin): penalize unless open bins are mostly unusable.
    if bin_residual == bin_capacity {
        let base = 250.0 + 2.0 * open_bins_count as f64;
        // If next item is large, a fresh bin is more attractive.
        let lookahead_bonus = next_item_size as f64 * 0.5;
        score += base + lookahead_bonus;
        // Late in the stream, avoid opening new bins.
        let progress = step_index as f64 / total_items.max(1) as f64;
        score += 100.0 * progress;
    }

    // Small absolute leftovers are worse than exact fits.
    if post_residual > 0 && post_residual < 10 {
        score += 20.0;
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Strong preference for tight fits (small post_residual).
    let fit_ratio = item_size as f64 / bin_residual as f64;
    score -= fit_ratio * 12.0;

    // Penalize large dead space non-linearly.
    if post_residual > 0 && post_residual < 10 {
        score -= 6.0; // tiny residual is nearly perfect
    } else if post_residual >= 10 && post_residual < 30 {
        score += (post_residual as f64 - 10.0) * 0.4;
    } else {
        score += (post_residual as f64).powi(2) * 0.02;
    }

    // Lookahead: reward bins whose residual can still host the next item.
    if next_item_size > 0 {
        if post_residual >= next_item_size {
            score -= 4.0 + next_item_size as f64 * 0.05;
        } else {
            score += 3.0;
        }
        // If next item fits this bin only after current item, extra reward.
        if bin_residual >= item_size + next_item_size {
            score -= 2.5;
        }
    }

    // Last-chance bin: strongly favor using it to avoid opening a new bin.
    if fitting_bins_count == 1 {
        score -= 15.0;
    } else if fitting_bins_count > 1 {
        // Among many candidates, prefer fuller bins (smaller residual).
        score += (bin_residual as f64 / bin_capacity as f64) * 5.0;
    }

    // Global state: many open bins with high mean residual -> consolidate.
    if open_bins_count > 4 && mean_residual > 20.0 {
        score += (mean_residual - 20.0) * 0.15;
    }

    // Time horizon: early in stream, be more open to new bins; later, pack tightly.
    let progress = step_index as f64 / total_items.max(1) as f64;
    score -= progress * 3.0 * fit_ratio;

    // New-bin candidate: only attractive when no open bin fits well.
    if bin_residual == bin_capacity {
        // Base cost of opening a new bin, discounted early in the stream.
        score = post_residual as f64 + 8.0 - progress * 5.0;
        if next_item_size > 0 && next_item_size <= bin_capacity {
            score -= 1.0;
        }
        if fitting_bins_count == 1 {
            // An open bin exists that fits; make new bin less attractive unless huge waste avoided.
            score += 6.0;
        }
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let cap = bin_capacity as f64;
    let pr = post_residual as f64;
    let progress = step_index as f64 / total_items.max(1) as f64;
    let mut score = pr;

    // Non-linear polynomial coupling of post_residual with stream progress
    let prn = pr / cap;
    let poly = prn * prn * (1.0 - prn) * (1.0 + progress);
    score -= 12.0 * poly;

    // Tight-fit reward: small post residual relative to capacity
    let tight = (1.0 - prn).powi(3);
    score -= 8.0 * tight * (0.5 + 0.5 * progress);

    // Lookahead coupling: reward if next item fits into post residual
    if next_item_size > 0 && (next_item_size as f64) <= pr {
        let snug = 1.0 - ((pr - next_item_size as f64) / cap).powf(0.5);
        score -= 6.0 * snug * (1.0 - progress * 0.5);
    } else if next_item_size > 0 {
        // penalize post residual that wastes space for the known next item
        score += 2.0 * (1.0 - prn) * progress;
    }

    // Penalize bins far from the mean residual (avoid fragmentation outliers)
    let dev = (pr - mean_residual).abs() / cap;
    score += 3.0 * dev * dev * (1.0 + progress);

    // Last-chance bin bonus: strongly favor the only fitting bin
    if fitting_bins_count == 1 {
        score -= 10.0 * (1.0 - prn);
    }

    // Mild preference for consolidating into fewer bins as stream progresses
    score += (open_bins_count as f64).ln().max(0.0) * 0.5 * progress;

    // New-bin candidate: penalize unless post residual would be very large and useful
    if bin_residual == bin_capacity {
        score += 4.0 * (1.0 - progress);
        if next_item_size > 0 && (next_item_size as f64) <= pr {
            score -= 3.0;
        }
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Harmonic decade classes on post_residual: reward near-closed bins,
    // penalize bins left with large unusable middles.
    let class = post_residual / 10;
    score += match class {
        0 => -9.0,           // post_residual 0..9: bin almost closed, excellent
        1 => -5.0,           // 10..19: still good
        2 => -2.0,           // 20..29: acceptable
        3 => 0.0,            // 30..39: neutral
        4 => 2.0,            // 40..49: dead-space risk
        5 => 5.0,            // 50..59: bad
        _ => 9.0,            // 60+: terrible leftover
    };

    // Fine harmonic modulation within the class (modulo arithmetic).
    score += (post_residual % 10) as f64 * 0.15;

    // Lookahead (k=2): reward if next item can also fit here (chain packing),
    // slight penalty if only this item fits and next will need another bin.
    if next_item_size > 0 {
        if next_item_size <= post_residual {
            score -= 3.5;
        } else if next_item_size <= bin_residual {
            score += 0.5;
        }
    }

    // Last-chance bonus: this is the only open bin that can take the item.
    if fitting_bins_count == 1 && bin_residual != bin_capacity {
        score -= 6.0;
    }

    // Brand-new empty bin candidate.
    if bin_residual == bin_capacity {
        score += 14.0; // default: prefer existing bins
        if item_size >= 60 {
            score -= 10.0; // large items are fine opening fresh bins
        }
        if item_size >= 80 {
            score -= 6.0;
        }
        if fitting_bins_count == 0 {
            score = -100.0; // no open bin fits: must open a new bin
        }
    }

    // Stream progression: later in the stream, be slightly more conservative
    // about leftovers (fewer chances to repair them).
    let progress = step_index as f64 / (total_items.max(1) as f64);
    score += progress * 2.0;

    // Coupling with mean residual: placing into a bin well below the mean
    // residual helps homogenize open bins (easier future fits).
    score += (mean_residual - post_residual as f64) * 0.05;

    // Mild pressure against hoarding too many open bins.
    score += open_bins_count as f64 * 0.05;

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Dead-space penalty: residuals too small for the smallest plausible item (<= 8)
    // are effectively wasted; penalize them heavily.
    if post_residual > 0 && post_residual < 8 {
        score += 60.0;
    } else if post_residual < 20 {
        // Small gaps (8..20) are hard to fill: moderate penalty.
        score += 25.0;
    } else if post_residual >= 50 {
        // Large residual left is fine — bin remains versatile.
        score -= 10.0;
    }

    // Reward near-perfect fits.
    if post_residual == 0 {
        score -= 80.0;
    } else if post_residual <= 5 {
        score -= 30.0;
    }

    // Lookahead: if the next item fits exactly in the post residual, big reward.
    if next_item_size > 0 && next_item_size == post_residual {
        score -= 70.0;
    } else if next_item_size > 0 && next_item_size < post_residual {
        score -= 12.0;
    }

    // Last-chance bonus: only one open bin fits this item — use it rather
    // than opening a new bin, unless the fit is terrible.
    if fitting_bins_count == 1 && bin_residual >= item_size {
        score -= 45.0;
    }

    // Open-bin pressure: penalize placements into bins when many bins are open,
    // pushing toward consolidation into few bins.
    score += (open_bins_count as f64) * 1.5;

    // Prefer filling bins with lower residual relative to mean (tighter bins first).
    score += (bin_residual as f64 - mean_residual) * 0.3;

    // Slight preference for keeping fresh bins (high residual) for later.
    score += (bin_residual as f64) * 0.1;

    // Stream progression: early on, be more conservative about dead space.
    let progress = step_index as f64 / total_items.max(1) as f64;
    score *= 1.0 + 0.2 * (1.0 - progress);

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let score = (post_residual as f64) * 1.18;
    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Reward tight fits (small post_residual relative to capacity).
    let tightness = 1.0 - (post_residual as f64 / bin_capacity as f64);
    score -= 12.0 * tightness;

    // Penalize dead space: post_residual too small for the smallest plausible item (1..100 stream).
    if post_residual > 0 && post_residual < 10 {
        score += 25.0;
    }

    // Lookahead: if the next item fits exactly into the post_residual, strongly reward.
    if next_item_size > 0 {
        if next_item_size == post_residual {
            score -= 40.0;
        } else if next_item_size > post_residual {
            // Wasted lookahead opportunity: penalize proportionally to unusable gap.
            score += 0.35 * (next_item_size as f64 - post_residual as f64).min(50.0);
        } else {
            score -= 0.15 * (post_residual as f64 - next_item_size as f64);
        }
    }

    // Last-chance bonus: if this is the only bin that fits, avoid opening a new bin
    // unless the fit is truly terrible.
    if fitting_bins_count == 1 && bin_residual != bin_capacity {
        score -= 20.0;
    }

    // New-bin candidate handling: only attractive when current bin fits are poor.
    if bin_residual == bin_capacity {
        // Base neutral score for a fresh bin; adjust with stream context.
        score = (bin_capacity - item_size) as f64;
        if fitting_bins_count > 0 {
            // If some open bin fits, opening a new bin must be justified by bad fits.
            let avg_post = mean_residual - item_size as f64;
            if avg_post > 25.0 {
                score -= 10.0; // open bins would leave lots of space anyway; prefer new bin
            } else {
                score += 15.0; // discourage opening when fits are decent
            }
        }
        // Late in the stream, prefer consolidating into open bins.
        let progress = step_index as f64 / total_items.max(1) as f64;
        score += 10.0 * progress;
    }

    // Global state: many open bins with low mean residual -> prefer filling existing bins.
    if open_bins_count > 2 && mean_residual < 30.0 {
        score -= 5.0;
    }

    // Mild time-horizon term: early stream, keep bins flexible (moderate residuals);
    // late stream, pack aggressively.
    let progress = step_index as f64 / total_items.max(1) as f64;
    score -= 6.0 * progress * tightness;

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let progress = step_index as f64 / total_items as f64;
    let cap = bin_capacity as f64;
    let pr = post_residual as f64;
    let fit_ratio = pr / cap;

    // Base: prefer small post-residual, with smooth non-linear shaping
    let mut score = pr;

    // Polynomial coupling: penalize mid-range residuals more as stream progresses
    let mid = fit_ratio * (1.0 - fit_ratio); // peaks at residual = cap/2
    score += 24.0 * mid * mid * (0.5 + progress);

    // Reward tight fits progressively more over the stream
    score -= 18.0 * (1.0 - fit_ratio) * (1.0 - fit_ratio) * (0.4 + 0.6 * progress);

    // Last-chance bonus: strongly favor the only fitting bin
    if fitting_bins_count == 1 {
        score -= 15.0 + 10.0 * progress;
    }

    // Lookahead: reward if next item fits the post-residual
    if next_item_size > 0 {
        let nxt = next_item_size as f64;
        if pr >= nxt {
            let slack = (pr - nxt) / cap;
            score -= 12.0 * (1.0 - slack) * (1.0 - slack);
        } else {
            score += 6.0 * (nxt - pr) / cap;
        }
    }

    // Mean-residual coupling: avoid bins far from the fleet average
    let dev = (bin_residual as f64 - mean_residual) / cap;
    score += 5.0 * dev * dev;

    // Mild penalty for bin proliferation early on
    score += (open_bins_count as f64).ln().max(0.0) * (1.0 - progress) * 2.0;

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let cap = bin_capacity as f64;
    let mut score = post_residual as f64;

    // Harmonic class of post_residual: waste bucketed by capacity fractions.
    let pr = post_residual;
    let quarter = bin_capacity / 4;
    let eighth = bin_capacity / 8;
    let sixteenth = bin_capacity / 16;

    // Penalize dead space in coarse harmonic bands.
    if pr < sixteenth {
        score -= 25.0; // near-perfect fill
    } else if pr < eighth {
        score -= 10.0;
    } else if pr < quarter {
        score += 3.0;
    } else {
        score += 8.0 + (pr as f64 - quarter as f64) * 0.15;
    }

    // Modulo arithmetic: post_residual divisible by small moduli indicates
    // "clean" leftover that pairs well with typical item sizes.
    let pr_f = pr as f64;
    if pr > 0 && (pr % 10 == 0) {
        score -= 4.0;
    } else if pr > 0 && (pr % 5 == 0) {
        score -= 2.0;
    }
    if pr > 0 && pr % 7 == 0 {
        score -= 1.5;
    }

    // Lookahead coupling: does next item fit into post_residual?
    if next_item_size > 0 {
        let ni = next_item_size as f64;
        if ni <= pr_f {
            // Next item nests perfectly: reward, stronger for exact/near-exact fit.
            let slack = pr_f - ni;
            score -= 12.0 - (slack / cap) * 10.0;
            // Harmonic class of the pair: next item modulo classes
            if next_item_size % 10 == 0 {
                score -= 2.0;
            }
        } else {
            // Next item cannot use this bin's leftover: penalize leftover size.
            score += (ni - pr_f) * 0.05;
        }
    } else {
        // Last item: just minimize waste.
        score += 5.0;
    }

    // Last-chance bin: strongly favor using it before opening a new bin.
    if fitting_bins_count == 1 && bin_residual < bin_capacity {
        score -= 15.0;
    }

    // Many open bins: discourage leaving large residuals scattered.
    if open_bins_count > 4 {
        score += (post_residual as f64 / cap) * (open_bins_count as f64).ln() * 4.0;
    }

    // Mean residual pressure: prefer bins below mean residual (tighter bins).
    score += (mean_residual - pr_f) * 0.08;

    // Progress: early on, prefer tighter packing; late, prefer consolidation.
    let progress = step_index as f64 / (total_items.max(1) as f64);
    score += (pr_f / cap) * (1.0 - progress) * 6.0 - (pr_f / cap) * progress * 4.0;

    // New-bin candidate: only attractive if no open bin fits well.
    if bin_residual == bin_capacity {
        score = cap * 0.9 + fitting_bins_count as f64 * 2.0;
        if next_item_size > 0 && next_item_size as f64 >= cap * 0.5 {
            score -= 5.0; // big next item: fresh bin may be fine
        }
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Strict dead-space avoidance: small unusable gaps (1..10) are heavily penalized,
    // mid gaps mildly penalized, large gaps (>= 20) are reusable and lightly rewarded.
    if post_residual > 0 && post_residual < 10 {
        score += 60.0 + (10 - post_residual) as f64 * 8.0;
    } else if post_residual < 20 {
        score += 12.0;
    } else if post_residual >= 30 {
        score -= 10.0;
    }

    // Perfect fit bonus.
    if post_residual == 0 {
        score -= 40.0;
    }

    // Tight fit reward: item fills most of the bin's residual.
    let fill_ratio = item_size as f64 / bin_residual.max(1) as f64;
    score -= fill_ratio * 15.0;

    // Open-bin pressure: discourage spreading across many bins; encourage closing bins out.
    score += open_bins_count as f64 * 2.5;

    // If this bin's residual is far below the mean residual, it's a laggard bin;
    // prefer filling it (its residual is hard to use later).
    if (bin_residual as f64) < mean_residual - 15.0 {
        score -= 8.0;
    }

    // Last-chance bin: if this is the only bin that fits, avoid forcing a bad
    // placement when the fit is loose; otherwise reward using it.
    if fitting_bins_count == 1 {
        if post_residual >= 20 {
            score -= 20.0;
        } else {
            score += 25.0;
        }
    }

    // Lookahead coupling: if the next item fits into this bin's post_residual,
    // reward the placement (chained packing).
    if next_item_size > 0 && next_item_size <= post_residual {
        score -= 12.0;
    }
    // If next item would exactly fill post_residual, extra reward.
    if next_item_size > 0 && next_item_size == post_residual {
        score -= 15.0;
    }

    // New-bin candidate handling: an empty bin has large post_residual; make it
    // attractive only when no good fit exists (many open bins, loose fits).
    if bin_residual == bin_capacity {
        let progress = step_index as f64 / (total_items.max(1) as f64);
        // Mild preference for new bins late in the stream (fewer future items to fill them).
        score -= 5.0 + 10.0 * progress;
        if fitting_bins_count == 0 {
            score -= 30.0;
        }
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // --- 2-step lookahead: reward perfect match of post_residual with next item ---
    if next_item_size > 0 {
        let next = next_item_size as f64;
        let diff = (post_residual as f64 - next).abs();
        // Perfect match: next item exactly fills this bin afterwards
        if diff < 0.5 {
            score -= 60.0;
        } else if diff <= 10.0 {
            score -= 25.0 * (1.0 - diff / 10.0);
        } else {
            // Dead space the next item cannot use
            score += 0.35 * diff;
        }
        // Bonus if post_residual can still fit next item (chained packing)
        if (post_residual as u32) >= next_item_size {
            score -= 8.0;
        }
    } else {
        // Last item: prefer tightest fill overall
        score -= 15.0;
    }

    // --- Penalize waste relative to mean residual of open bins ---
    let pr = post_residual as f64;
    if pr > mean_residual + 1.0 {
        score += 0.5 * (pr - mean_residual);
    } else if pr < mean_residual - 1.0 {
        score -= 0.4 * (mean_residual - pr);
    }

    // --- Last-chance bin: strongly favor using it before opening a new bin ---
    if fitting_bins_count == 1 && bin_residual >= item_size && bin_residual < bin_capacity {
        score -= 30.0;
    }

    // --- New-bin candidate handling: only attractive when open bins are crowded ---
    if bin_residual == bin_capacity {
        let crowding = mean_residual / bin_capacity as f64;
        // If open bins are mostly full, opening a new bin is reasonable
        if crowding < 0.25 {
            score -= 20.0 * (0.25 - crowding) * 4.0;
        } else {
            score += 25.0 + 10.0 * crowding;
        }
        // Never open a new bin when a perfect lookahead fit exists elsewhere
        if next_item_size > 0 && post_residual == 0 {
            score -= 40.0;
        }
    }

    // --- Mild reward for very tight placements ---
    if post_residual <= 5 {
        score -= 12.0;
    } else if post_residual <= 10 {
        score -= 6.0;
    }

    // --- Stream progression: later in stream, be more conservative with new bins ---
    if total_items > 0 {
        let progress = step_index as f64 / total_items as f64;
        if bin_residual == bin_capacity {
            score += 15.0 * progress;
        }
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Reward tight fits: low post-residual relative to capacity.
    let tightness = 1.0 - (post_residual as f64) / (bin_capacity as f64);
    score -= 18.0 * tightness;

    // Penalize dead space that is too small for the smallest plausible item (1..100 range).
    if post_residual > 0 && post_residual < 10 {
        score += 25.0;
    }

    // Lookahead coupling: if the next item fits into post_residual, reward this bin.
    if next_item_size > 0 && post_residual >= next_item_size {
        score -= 12.0 + 0.15 * next_item_size as f64;
    } else if next_item_size > 0 && post_residual > 0 {
        // Next item won't chain here: mildly penalize leaving stranded residual.
        score += 6.0;
    }

    // Last-chance pressure: if this is the only fitting bin, strongly favor using it.
    if fitting_bins_count == 1 && bin_residual < bin_capacity {
        score -= 30.0;
    }

    // Time horizon: early in stream, be more conservative (favor new bins for big residual waste);
    // late in stream, squeeze into existing bins.
    let progress = step_index as f64 / total_items.max(1) as f64;
    score -= progress * 10.0 * tightness;

    // Global state coupling: many open bins with high mean residual -> encourage filling.
    if open_bins_count > 2 && mean_residual > 30.0 {
        score -= 8.0 * (mean_residual / bin_capacity as f64);
    }

    // New-bin candidate: penalize opening a new bin unless current bin would be badly fragmented.
    if bin_residual == bin_capacity {
        score += 20.0;
        // But if no open bin fits well (large item), allow new bin.
        if item_size > bin_capacity / 2 && fitting_bins_count == 0 {
            score -= 45.0;
        }
        if next_item_size > 0 && next_item_size >= item_size {
            score -= 10.0; // pairing future similar items in fresh bin
        }
    }

    // Mild penalty for very large residual waste left behind.
    score += 0.05 * (post_residual as f64).powi(2) / bin_capacity as f64;

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let progress = if total_items > 0 { step_index as f64 / total_items as f64 } else { 0.0 };
    let cap = bin_capacity as f64;
    let pr = post_residual as f64;
    let mut score = pr;

    // Non-linear coupling of post_residual with stream progress:
    // early on, tolerate large residuals; later, penalize dead space quadratically.
    let tightness = (pr / cap).powi(2);
    score += tightness * (1.0 + 3.0 * progress) * 10.0;

    // Reward filling bins well: subtract a smooth saturating function of fill ratio.
    let fill = 1.0 - pr / cap;
    score -= (fill * fill) * 20.0 * (0.5 + progress);

    // Penalize near-new-bin residuals only mildly (wasted capacity).
    score += (pr / cap) * 5.0;

    // Last-chance bin bonus: strongly favor when this is the only fitting bin.
    if fitting_bins_count == 1 {
        score -= 25.0 + 30.0 * progress;
    }

    // Lookahead: if next item fits into post_residual, reward.
    if next_item_size > 0 && (next_item_size as f64) <= pr {
        score -= 8.0 + 6.0 * (1.0 - (next_item_size as f64 / pr));
    } else if next_item_size > 0 {
        score += 4.0 * (1.0 - pr / cap);
    }

    // Slight preference for consolidating into fewer bins.
    score += (open_bins_count as f64).ln().max(0.0) * 0.5;

    // Mean residual coupling: prefer bins below mean residual (tighter packs).
    score += 0.3 * (mean_residual - pr);

    // New-bin candidate: make it unattractive unless residual would be perfectly reusable.
    if bin_residual == bin_capacity {
        score += 15.0 - 10.0 * progress;
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Harmonic class of the residual: quantize post_residual into buckets of 10.
    // Residuals that fall into "useful" classes (multiples of common item sizes)
    // are rewarded; awkward small residuals are penalized.
    let class = post_residual / 10;
    let within = (post_residual % 10) as f64;

    // Reward residuals in harmonious classes (0, 2, 4 -> multiples of 20/40 etc.)
    match class {
        0 => score -= 12.0,                      // perfect or near-perfect fill
        1 => score += 6.0,                       // 10-19: worst dead space class
        2 => score -= 4.0,                       // 20-29: fits size-20 class items
        3 => score += 3.0,
        4 => score -= 3.0,                       // 40-49
        5 => score -= 1.0,                       // 50: half-fill, very reusable
        6 => score += 1.5,
        _ => score -= 1.0,                       // large residuals still flexible
    }

    // Fractional penalty for non-aligned residual (dead space within class).
    score += within * 0.15;

    // Lookahead coupling: if next item fits exactly into the post residual,
    // strongly reward this placement.
    if next_item_size > 0 {
        if next_item_size == post_residual {
            score -= 15.0;
        } else if next_item_size <= post_residual {
            score -= 4.0;
            // Harmonic match between next item and post residual class
            if post_residual % next_item_size == 0 {
                score -= 3.0;
            }
        } else {
            // next item won't fit here; slight penalty proportional to waste
            score += (next_item_size - post_residual) as f64 * 0.05;
        }
    } else {
        // Last item: finishing a bin is pure gain.
        score -= 20.0;
    }

    // Last-chance bin: if this is the only bin that fits, avoid opening a new one.
    if fitting_bins_count == 1 && bin_residual < bin_capacity {
        score -= 10.0;
    }

    // New-bin candidate handling: an empty bin has huge residual; make it
    // attractive only when existing bins would leave bad classes.
    if bin_residual == bin_capacity {
        // Base cost of opening a new bin, amortized by stream progress.
        let progress = step_index as f64 / (total_items.max(1) as f64);
        score = 55.0 - 10.0 * progress;

        // Open a new bin if current bins are crowded (low mean residual)
        // or if the item is large and would leave poor classes elsewhere.
        if mean_residual < item_size as f64 * 1.2 {
            score -= 25.0;
        }
        if item_size > 60 {
            score -= 8.0;
        }
        if fitting_bins_count == 0 {
            score -= 40.0;
        }
        // Don't open new bins too eagerly when few bins exist.
        if open_bins_count < 2 {
            score += 15.0;
        }
    }

    // Tight fit bonus: item consumes most of the bin.
    let fill_ratio = item_size as f64 / bin_capacity as f64;
    score -= fill_ratio * 5.0;

    // Slight preference for bins whose residual deviates below the mean
    // (consolidating space).
    score += ((post_residual as f64) - mean_residual) * 0.03;

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Strict dead-space avoidance: small leftover gaps are nearly unusable
    // (items are >= 1, but typical sizes make gaps < 15 hard to fill).
    if post_residual > 0 {
        if post_residual < 15 {
            score += (15 - post_residual) as f64 * 4.0; // heavy penalty for tiny dead space
        } else if post_residual < 30 {
            score += (30 - post_residual) as f64 * 1.5; // moderate penalty
        }
    }

    // Reward exact / near-exact fits strongly.
    if post_residual == 0 {
        score -= 50.0;
    } else if item_size as f64 / bin_residual as f64 > 0.9 {
        score -= 20.0;
    }

    // Lookahead: if the next item fits in the post residual, reward this placement.
    if next_item_size > 0 && post_residual >= next_item_size {
        score -= 12.0;
    } else if next_item_size > 0 && next_item_size > post_residual && post_residual > 0 {
        // Next item won't fit here; slightly penalize leaving a gap the next item can't use.
        score += 6.0;
    }

    // Open-bin pressure: with many open bins, prefer consolidating into existing bins
    // over spreading out; with few open bins, opening a new one is cheaper.
    let progress = step_index as f64 / (total_items.max(1) as f64);
    let pressure = open_bins_count as f64 * (0.5 + progress);
    score -= pressure * 0.8;

    // Last-chance bin: if this is the only bin that fits, strongly prefer using it
    // to avoid opening a new bin.
    if fitting_bins_count == 1 && bin_residual < bin_capacity {
        score -= 25.0;
    }

    // New-bin candidate handling: an empty bin has residual == capacity.
    // Only allow opening a new bin when existing bins would create bad dead space
    // or when open-bin pressure is low.
    if bin_residual == bin_capacity {
        let bad_fit_existing = mean_residual > 0.0 && (mean_residual - item_size as f64) < 10.0;
        if bad_fit_existing && open_bins_count < 6 {
            score -= 30.0; // opening fresh bin is better than wrecking a tight bin
        } else {
            score += 35.0; // default: discourage opening new bins
        }
    }

    // Mean-residual coupling: prefer bins whose residual is below mean (tighter bins),
    // penalize dumping into the loosest bins when it wastes space.
    if (bin_residual as f64) > mean_residual + 20.0 && post_residual > 25 {
        score += 8.0;
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Strong reward for near-exact fit (small post_residual is valuable dead-space avoidance)
    if post_residual == 0 {
        score -= 1000.0;
    } else if post_residual <= 10 {
        score -= 200.0;
    }

    // 2-step lookahead: reward when post_residual exactly matches next item
    if next_item_size > 0 {
        if post_residual == next_item_size {
            score -= 500.0;
        } else if post_residual >= next_item_size {
            // leftover after a hypothetical next placement
            let chain_left = post_residual - next_item_size;
            score -= (100.0_f64.min(chain_left as f64 * 8.0)).max(0.0);
            if chain_left == 0 {
                score -= 300.0;
            }
        } else {
            // next item can't fit here anyway; penalize unusable slivers
            if post_residual < 10 {
                score += 150.0;
            }
        }
    }

    // Relative to mean residual: prefer bins tighter than average
    score -= (mean_residual - post_residual as f64) * 2.0;

    // Last-chance bonus: only fitting bin -> avoid opening a new bin
    if fitting_bins_count == 1 && bin_residual != bin_capacity {
        score -= 400.0;
    }

    // New-bin candidate: only attractive when open bins are crowded or fit is bad
    if bin_residual == bin_capacity {
        let crowded = mean_residual < item_size as f64 * 0.5;
        let poor_fit = next_item_size > 0 && post_residual > 0
            && (post_residual as f64) < next_item_size as f64 * 0.4;
        if crowded || poor_fit {
            score -= 250.0;
        } else {
            score += 350.0; // prefer existing bins otherwise
        }
    }

    // Mild preference for consolidating into fewer bins early in the stream
    let progress = step_index as f64 / total_items.max(1) as f64;
    score += open_bins_count as f64 * (1.0 - progress) * 2.0;

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Strong reward for tight fits (small post_residual).
    let fit_ratio = item_size as f64 / bin_residual.max(1) as f64;
    score -= 12.0 * fit_ratio * fit_ratio;

    // Penalize leaving a tiny-but-unusable sliver (< 1, min item size is 1 here).
    if post_residual > 0 && post_residual < 3 {
        score += 15.0;
    }

    // Lookahead: reward if the next item fits exactly into post_residual (perfect chain).
    if next_item_size > 0 {
        if next_item_size == post_residual {
            score -= 25.0;
        } else if next_item_size <= post_residual {
            score -= 6.0 * (next_item_size as f64 / post_residual as f64);
        } else {
            // Next item won't fit here; penalize leaving large residuals that trap it.
            score += 0.05 * (post_residual as f64 - next_item_size as f64).min(30.0);
        }
    } else {
        // Last item: prefer fullest possible packing.
        score -= 20.0 * fit_ratio;
    }

    // Last-chance bin: strongly favor using the only bin that fits.
    if fitting_bins_count == 1 && bin_residual >= item_size {
        score -= 18.0;
    }

    // Global pressure: many open bins with high mean residual -> prefer filling existing bins.
    let pressure = mean_residual / bin_capacity as f64;
    if open_bins_count > 2 {
        score -= 4.0 * pressure;
    }

    // Time horizon: early in stream, be pickier (penalize loose fits); late, just fill.
    let t = step_index as f64 / (total_items.max(1) as f64);
    score += (1.0 - t) * 3.0 * (1.0 - fit_ratio);

    // New-bin candidate: only attractive when no open bin fits well
    // (large item relative to mean residual) or stream is early.
    if bin_residual == bin_capacity {
        let desperation = if next_item_size > 0 {
            (item_size as f64 / mean_residual.max(1.0)).min(2.0)
        } else { 0.0 };
        let openness = 1.0 - t;
        score += 20.0 - 14.0 * desperation - 6.0 * openness;
        // Never open a new bin when a unique fitting bin exists.
        if fitting_bins_count >= 1 {
            score += 30.0;
        }
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let progress = if total_items > 1 { step_index as f64 / (total_items as f64 - 1.0) } else { 0.0 };
    let cap = bin_capacity as f64;
    let pr = post_residual as f64;
    let is_new = (bin_residual == bin_capacity) as f64;

    // Base: post residual (waste), non-linearly coupled with stream progress
    let mut score = pr * (1.0 + 0.8 * progress);

    // Quadratic dead-space penalty: small post residuals are fine, mid-range bad
    let prn = pr / cap;
    score += 25.0 * prn * (1.0 - prn) * (1.0 - prn);

    // Tight fits rewarded, more so late in the stream
    score -= 12.0 * (1.0 - prn) * (1.0 - prn) * (0.5 + progress);

    // Penalize opening a new bin when existing bins fit (scaled by fitting availability)
    score += is_new * (20.0 + 15.0 * (fitting_bins_count as f64 / (open_bins_count as f64 + 1.0)).sqrt());

    // Last-chance bonus: strongly favor the only bin that fits
    if fitting_bins_count == 1 && is_new < 0.5 {
        score -= 15.0;
    }

    // Lookahead: if next item can use the post residual, reward; else penalize
    let nps = next_item_size as f64;
    if nps > 0.0 {
        let fits_next = (nps <= pr) as f64;
        let tight_next = (1.0 - ((pr - nps) / cap).abs()).max(0.0);
        score -= 10.0 * fits_next * tight_next;
        score += 5.0 * (1.0 - fits_next) * prn;
    }

    // Mean-residual coupling: prefer bins deviating toward usable (larger) residuals
    score -= 0.15 * (mean_residual - pr);

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Perfect fit: strong reward.
    if post_residual == 0 {
        score -= 1000.0;
    }

    // Harmonic classes: residual divisible by common small sizes is reusable.
    for h in [10u32, 20, 25, 50].iter() {
        if post_residual % h == 0 && post_residual > 0 {
            score -= 12.0 * (h / 10) as f64;
        }
    }

    // Lookahead coupling: does post_residual fit the next item exactly?
    if next_item_size > 0 && next_item_size <= post_residual {
        score -= 30.0;
        if post_residual % next_item_size == 0 {
            score -= 20.0;
        }
    } else if next_item_size > post_residual && next_item_size > 0 {
        // dead space relative to lookahead item
        score += 8.0;
    }

    // Last chance: only fitting bin, prefer keeping item here over new bin.
    if fitting_bins_count == 1 && bin_residual >= item_size {
        score -= 40.0;
    }

    // Penalize new-bin candidate when a decent fit exists elsewhere.
    if bin_residual == bin_capacity {
        if fitting_bins_count > 0 {
            score += 25.0 + 0.3 * mean_residual;
        }
        // early stream: allow opening bins freely
        let progress = step_index as f64 / total_items.max(1) as f64;
        score -= 20.0 * (1.0 - progress);
    }

    // Penalize tiny unusable dead space (wedge classes).
    if post_residual > 0 && post_residual < 10 {
        score += 15.0;
    }

    // Mild preference for tighter (smaller-residual) bins when many open.
    score += 0.05 * open_bins_count as f64 * (post_residual as f64 / bin_capacity as f64);

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Strict dead-space avoidance: small unusable gaps are heavily penalized.
    if post_residual > 0 {
        let dead = post_residual as f64;
        // Penalize gaps too small to be useful for typical future items.
        if dead < 20.0 {
            score += 60.0 * (20.0 - dead) / 20.0; // up to +60 for near-zero gaps
        }
        // Non-linear penalty on wasted fraction of the bin.
        let waste_frac = dead / bin_capacity as f64;
        score += 40.0 * waste_frac * waste_frac;
    } else {
        // Perfect fit: strong reward.
        score -= 50.0;
    }

    // Reward tight fits (small post_residual relative to item size).
    let tightness = item_size as f64 / (item_size + post_residual) as f64;
    score -= 15.0 * tightness;

    // Last-chance bin pressure: strongly favor using the only fitting bin.
    if fitting_bins_count == 1 && bin_residual != bin_capacity {
        score -= 30.0;
    }

    // Open-bin pressure: when many bins are open, discourage opening new ones.
    if bin_residual == bin_capacity {
        // New-bin candidate: penalize proportional to open bins and mean residual.
        score += 25.0 + 3.0 * open_bins_count as f64 + mean_residual * 0.5;
        // If only one fitting bin exists, opening a new bin is especially bad.
        if fitting_bins_count == 1 {
            score += 40.0;
        }
        // Early in stream, opening bins is cheaper.
        let progress = step_index as f64 / total_items.max(1) as f64;
        score += 20.0 * progress;
    }

    // Lookahead: if next item fits exactly into post_residual, reward this placement.
    if next_item_size > 0 {
        if next_item_size == post_residual {
            score -= 45.0;
        } else if next_item_size <= post_residual {
            score -= 10.0 * (post_residual - next_item_size) as f64 / 10.0;
        } else {
            // Next item cannot use the gap: penalize leaving medium gaps.
            score += 5.0;
        }
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Strong 2-step lookahead: perfect match between leftover space and next item.
    if next_item_size > 0 {
        let diff = (post_residual as i64 - next_item_size as i64).abs() as f64;
        // Reward exact/near matches aggressively.
        score -= 30.0 * (1.0 - diff / (bin_capacity as f64 * 0.5)).max(0.0);

        // Penalize if next item cannot follow into this bin while a small gap remains.
        if (post_residual as i64) < next_item_size as i64 && post_residual > 0 {
            score += 12.0;
        }
        // Bonus if next item fits exactly into post residual (chain packing).
        if post_residual == next_item_size {
            score -= 25.0;
        }
    }

    // Relative to mean residual: prefer bins tighter than the average.
    let mr = if mean_residual.is_finite() { mean_residual } else { bin_residual as f64 };
    score -= (bin_residual as f64 - mr) * 0.35;

    // Dead-space penalty: small unusable post residuals are bad.
    if post_residual > 0 && post_residual < 10 {
        score += 20.0;
    }

    // Last-chance bonus: only one bin fits, strongly prefer using it over opening a new bin.
    if fitting_bins_count == 1 && bin_residual < bin_capacity {
        score -= 40.0;
    }

    // New empty bin candidate: penalize moderately so it's chosen only when open bins are poor fits,
    // but attractive for very large items.
    if bin_residual == bin_capacity {
        let frac = item_size as f64 / bin_capacity as f64;
        score += 8.0 - 15.0 * frac;
    }

    // Progress coupling: early in stream, keep bins flexible; late, pack tightly.
    let progress = if total_items > 0 { step_index as f64 / total_items as f64 } else { 0.0 };
    score -= progress * (post_residual as f64) * 0.2;

    // Slight preference for denser bins when many bins are open.
    score += open_bins_count as f64 * 0.5;

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Strong reward for tight fits (small post_residual relative to capacity)
    let tightness = post_residual as f64 / bin_capacity as f64;
    score += tightness * tightness * 40.0;

    // Penalize leaving residuals that are too small for any plausible item (dead space)
    if post_residual > 0 && post_residual < 10 {
        score += 25.0;
    }

    // Lookahead: reward if the next item fits into the post residual
    if next_item_size > 0 {
        if next_item_size <= post_residual {
            score -= 18.0;
        } else if post_residual > 0 && next_item_size > post_residual {
            score += 8.0; // this bin would become dead space for the next item
        }
    }

    // Last chance: strongly prefer using the only bin that can fit this item
    if fitting_bins_count == 1 && bin_residual >= item_size {
        score -= 30.0;
    }

    // Prefer filling bins that are already relatively full (larger used fraction)
    let used_frac = (bin_capacity - bin_residual) as f64 / bin_capacity as f64;
    score -= used_frac * 12.0;

    // Mildly discourage opening new bins when many bins are open with slack
    if bin_residual == bin_capacity {
        // New-bin candidate: baseline cost plus penalty scaled by mean residual slack
        score += 15.0 + mean_residual * 0.35 + (open_bins_count as f64) * 1.5;
    } else {
        // Using an open bin reduces bin count pressure
        score -= 10.0;
    }

    // Time horizon: early in stream, be more conservative (favor consolidation);
    // late in stream, allow more flexible placement
    let progress = if total_items > 0 { step_index as f64 / total_items as f64 } else { 0.0 };
    score *= 1.0 + 0.15 * (1.0 - progress);

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let cap = bin_capacity as f64;
    let pr = post_residual as f64;
    let progress = step_index as f64 / total_items.max(1) as f64;
    let x = pr / cap; // normalized post-residual in [0,1)

    // Base: penalize leftover space, with a non-linear (quartic) coupling
    // that increasingly punishes mid-range residuals (awkward dead space)
    // while tolerating near-zero (perfect fit) and rewarding large residual
    // only mildly (still reusable).
    let mut score = pr * (1.0 + 2.0 * x * (1.0 - x) * (1.0 - progress));

    // Stream-progress coupling: later in the stream, tight fits matter more;
    // early on, large residuals are fine since future items can use them.
    let progress_weight = progress * progress;
    score += 30.0 * progress_weight * x * x;

    // Lookahead coupling: reward residuals that can still host the next item,
    // penalize residuals that strand the lookahead item.
    if next_item_size > 0 {
        let nx = next_item_size as f64 / cap;
        if pr >= next_item_size as f64 {
            // bin remains usable for the next item: smooth reward scaled by
            // how much slack remains after hypothetically placing it
            let slack = (pr - next_item_size as f64) / cap;
            score -= 12.0 * (1.0 - slack * slack) * (0.5 + progress);
        } else {
            // post-residual too small for next item: dead-space penalty,
            // stronger when the wasted gap is tiny (worst trade)
            let gap = (next_item_size as f64 - pr) / cap;
            score += 20.0 * (1.0 - gap) * (0.5 + progress);
        }
        // mild attraction if residual matches next item closely (harmonic fit)
        let diff = (x - nx).abs();
        score -= 8.0 * (1.0 - diff).max(0.0);
    }

    // Last-chance bonus: if this is the only fitting bin, strongly prefer
    // using it over opening a new bin (unless post-residual is terrible).
    if fitting_bins_count == 1 {
        score -= 25.0 * (1.0 - x * x);
    }

    // Scarcity pressure: few fitting bins -> favor placing into existing bins.
    if fitting_bins_count > 1 {
        score += 3.0 * (fitting_bins_count as f64).ln();
    }

    // Mean-residual context: if this bin's residual deviates below the mean
    // (it's the tightest), slightly prefer consuming it first.
    let dev = (bin_residual as f64 - mean_residual) / cap;
    score += 5.0 * dev * dev * (1.0 - progress);

    // New-bin candidate handling: an empty bin has post_residual == cap - item.
    // Prefer opening a new bin only when the item fits no open bin well,
    // i.e., when post-residual would be a large unusable sliver.
    if bin_residual == bin_capacity {
        // new-bin score: neutral base plus penalty that shrinks as the item
        // is large (large items deserve fresh bins)
        score = pr + 15.0 * (1.0 - item_size as f64 / cap);
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Harmonic class of the post residual: dead-space classes modulo capacity fractions.
    let cap = bin_capacity as f64;
    let pr = post_residual as f64;

    // Perfect fit reward
    if post_residual == 0 {
        score -= 40.0;
    }
    // Tiny unusable dead space penalty (harmonic class 1..=5)
    if post_residual >= 1 && post_residual <= 5 {
        score += 25.0;
    }

    // Classify post_residual by division into capacity eighths (harmonic tiers).
    let tier = (pr / (cap / 8.0)).floor() as i32; // 0..8
    score += match tier {
        0 => -6.0,
        1 => 4.0,
        2 => 2.0,
        3 => 0.0,
        4 => -1.0,
        5 => -2.0,
        6 => -3.0,
        _ => -4.0,
    };

    // Modulo-10 class of post residual: residuals divisible by 10 pair well with
    // typical item sizes drawn on a 10-grid.
    if post_residual % 10 == 0 && post_residual > 0 {
        score -= 5.0;
    }
    // Odd residuals are harder to fill later
    if post_residual % 2 == 1 && post_residual > 0 {
        score += 2.0;
    }

    // Lookahead coupling: does next item fit exactly in the post residual?
    if next_item_size > 0 {
        if next_item_size == post_residual {
            score -= 30.0; // chain perfect fit
        } else if next_item_size <= post_residual {
            let slack = post_residual - next_item_size;
            score -= 8.0 * (1.0 - slack as f64 / cap);
            if slack <= 5 {
                score += 6.0; // leaves near-dead space after next item
            }
        } else {
            // next item won't fit here; slightly favor bins that are "closed-shaped"
            score += 3.0;
        }
        // Harmonic gcd-like pairing: gcd(item, next) large => same-class items
        let a = item_size;
        let b = next_item_size;
        let mut x = a; let mut y = b;
        while y > 0 { let t = x % y; x = y; y = t; }
        if x >= 10 {
            score -= 2.0;
        }
    }

    // Last-chance bin: strongly prefer using it before opening a new bin.
    if fitting_bins_count == 1 && bin_residual < bin_capacity {
        score -= 35.0;
    }

    // New-bin candidate handling: only prefer a fresh bin when no open bin fits well.
    if bin_residual == bin_capacity {
        let pressure = if fitting_bins_count == 0 { 1.0 } else { 0.0 };
        if pressure > 0.0 {
            score = cap - 10.0; // must open a bin
        } else {
            score = cap + 60.0 + 0.5 * mean_residual; // discourage wasteful new bin
        }
        return score;
    }

    // Prefer tighter bins overall (relative fill fraction, harmonic in residual).
    score -= 12.0 * (1.0 - bin_residual as f64 / cap);

    // Late in the stream, consolidate aggressively.
    let progress = step_index as f64 / total_items.max(1) as f64;
    score -= 6.0 * progress * (1.0 - post_residual as f64 / cap);

    // Many open bins: favor bins below mean residual to compact the pool.
    if open_bins_count > 4 {
        if (bin_residual as f64) < mean_residual {
            score -= 3.0;
        } else {
            score += 2.0;
        }
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Strict dead-space avoidance: small unusable gaps are heavily penalized.
    if post_residual > 0 && post_residual <= 10 {
        score += 60.0 - 3.0 * post_residual as f64;
    } else if post_residual > 10 && post_residual < 25 {
        score += 8.0;
    } else if post_residual == 0 {
        // Perfect fit: strong reward.
        score -= 40.0;
    }

    // Reward using bins that would otherwise waste space (residual close to item).
    let tightness = bin_residual as f64 - item_size as f64;
    if tightness < 20.0 && post_residual > 0 {
        score -= (20.0 - tightness) * 1.5;
    }

    // Last-chance bin: strongly favor using it before opening a new bin.
    if fitting_bins_count == 1 && bin_residual != bin_capacity {
        score -= 30.0;
    }
    if fitting_bins_count > 1 {
        score += 2.0 * (fitting_bins_count as f64 - 1.0);
    }

    // New-bin candidate handling: only attractive when open bins fit poorly.
    if bin_residual == bin_capacity {
        let gap_to_next = if next_item_size > 0 {
            (bin_capacity as f64 - next_item_size as f64).abs()
        } else {
            0.0
        };
        if fitting_bins_count == 0 {
            score -= 25.0;
        } else {
            score += 35.0 + 3.0 * fitting_bins_count as f64;
        }
        // Favor a fresh bin if the next item would fit its full residual nicely.
        if next_item_size > 0 && next_item_size >= 60 {
            score -= 15.0;
        }
        if gap_to_next < 10.0 && next_item_size > 0 {
            score -= 10.0;
        }
    }

    // Open-bin pressure: many open bins -> prefer consolidating into existing bins.
    let progress = step_index as f64 / total_items.max(1) as f64;
    score += 0.8 * open_bins_count as f64 * (0.5 + progress);

    // Prefer bins whose residual deviates favorably from the mean (below-mean residual = tighter bin).
    score += 0.5 * (bin_residual as f64 - mean_residual);

    // Lookahead: if this bin's post residual can't host the next item but another gap could, mild penalty.
    if next_item_size > 0 && post_residual < next_item_size && post_residual > 0 {
        score += 6.0;
    }
    if next_item_size > 0 && post_residual >= next_item_size {
        score -= 4.0;
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Perfect 2-step lookahead match: post_residual exactly equals next item size
    if next_item_size > 0 && post_residual == next_item_size {
        score -= 1000.0; // chain two items perfectly -> ideal
    }

    // Near match: next item fits with small waste
    if next_item_size > 0 && post_residual >= next_item_size {
        let leftover = (post_residual - next_item_size) as f64;
        score -= 60.0 - leftover.min(60.0); // reward small leftover after chain
    } else if next_item_size > 0 {
        // next item cannot follow: dead space penalty scaled by dead space size
        let dead = post_residual as f64;
        score += dead * (dead / bin_capacity as f64) * 0.5;
    }

    // Penalize bins whose residual is far above mean (fragmented outliers)
    score += (bin_residual as f64 - mean_residual).abs() * 0.3;

    // Last-chance bin: strongly favor using it to avoid opening a new bin
    if fitting_bins_count == 1 && bin_residual != bin_capacity {
        score -= 40.0;
    }

    // New-bin candidate: prefer it only when item is large or fits poorly elsewhere
    if bin_residual == bin_capacity {
        let progress = step_index as f64 / (total_items.max(1) as f64);
        let tight = (item_size as f64) / bin_capacity as f64;
        let penalty = 120.0 - 80.0 * tight - 30.0 * progress;
        score += penalty.max(0.0);
    }

    // Early stream: tolerate loose packing; late stream: be frugal
    let progress = step_index as f64 / (total_items.max(1) as f64);
    score -= progress * 10.0;

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Reward tight fits: penalize relative waste quadratically.
    let waste = post_residual as f64 / bin_capacity as f64;
    score += 40.0 * waste * waste;

    // Reward perfect fits strongly.
    if post_residual == 0 {
        score -= 25.0;
    }

    // Last-chance bonus: if this is the only bin that fits, avoid opening a new bin
    // unless the fit is truly terrible.
    if fitting_bins_count == 1 && bin_residual >= item_size {
        score -= 18.0;
        // Extra bonus if the next item would also fit in the leftover space.
        if next_item_size > 0 && post_residual >= next_item_size {
            score -= 12.0;
        }
    }

    // Lookahead: penalize if placing here strands the next item
    // (leftover too small for the next item but nonzero).
    if next_item_size > 0 && post_residual > 0 && post_residual < next_item_size {
        score += 8.0 + 0.2 * post_residual as f64;
    }

    // Lookahead: reward if leftover exactly accommodates the next item.
    if next_item_size > 0 && post_residual == next_item_size {
        score -= 10.0;
    }

    // New-bin candidate handling: empty bin gets a mild penalty so we prefer
    // reusing open bins with decent fits, but it stays attractive when open
    // bins are very full or the item is large.
    if bin_residual == bin_capacity && bin_residual >= item_size {
        let progress = step_index as f64 / (total_items.max(1) as f64);
        let open_pressure = open_bins_count as f64 / (1.0 + mean_residual / 10.0);
        score += 15.0 + 10.0 * progress - 0.15 * open_pressure;
        // Large items with no good fit benefit from a fresh bin.
        if item_size > bin_capacity / 2 {
            score -= 6.0;
        }
    }

    // Prefer bins whose residual is below the mean (consolidate space).
    let res = bin_residual as f64;
    if res < mean_residual {
        score -= 0.1 * (mean_residual - res);
    } else {
        score += 0.05 * (res - mean_residual);
    }

    // Early in the stream, keep bins compact to build good structure.
    let progress = step_index as f64 / (total_items.max(1) as f64);
    score += (1.0 - progress) * 0.05 * post_residual as f64;

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let progress = step_index as f64 / (total_items.max(1) as f64);
    let cap = bin_capacity as f64;
    let post = post_residual as f64;
    let post_norm = post / cap;

    // Base: quadratic dead-space penalty (waste grows super-linearly)
    let mut score = post + 60.0 * post_norm * post_norm;

    // Smooth non-linear interaction: dead space matters more late in the stream
    let late = progress * progress;
    score += 80.0 * late * post_norm * post_norm;

    // Tight-fit reward: strongly favor small post_residual, especially mid/late stream
    let tight = 1.0 - post_norm;
    score -= 50.0 * tight * tight * (0.4 + 0.6 * progress);

    // Lookahead coupling: reward leaving room for the next item (smooth kernel)
    if next_item_size > 0 {
        let nxt = next_item_size as f64;
        let diff = (post - nxt) / cap;
        let kernel = (-8.0 * diff * diff).exp(); // peaks when post ~ next_item_size
        score -= 35.0 * kernel * (0.5 + 0.5 * progress);
        // Penalize post_residual that is just barely below next item size
        if post < nxt {
            score += 12.0 * (1.0 - post / nxt.max(1.0)) * (0.3 + 0.7 * progress);
        }
    }

    // Last-chance bonus: if this is the only fitting bin, avoid opening a new bin
    if fitting_bins_count == 1 {
        score -= 20.0 * (1.0 - progress);
    }

    // Mild pressure to consolidate when many bins are open
    let open_norm = open_bins_count as f64 / (open_bins_count as f64 + 5.0);
    score += 15.0 * open_norm * post_norm;

    // Alignment with mean residual: prefer bins near the average (balanced packing)
    let mean_gap = (post - mean_residual).abs() / cap;
    score += 10.0 * mean_gap * (1.0 - progress);

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Base: prefer small post_residual (tight fit).
    score = post_residual as f64 * 1.0;

    // Dead-space penalty: post_residual too small to ever be useful (min item size 1,
    // but tiny slivers under ~5 are hard to fill) get nonlinear penalty.
    if post_residual > 0 && post_residual < 5 {
        score += 60.0;
    }

    // Harmonic classes: classify post_residual by integer division into capacity fractions.
    // Residuals that are "clean" fractions of capacity (multiples of 10/20/25/50) are
    // easier to fill by future items -> reward them.
    let pr = post_residual;
    if pr > 0 {
        if pr % 50 == 0 { score -= 25.0; }
        else if pr % 25 == 0 { score -= 15.0; }
        else if pr % 20 == 0 { score -= 12.0; }
        else if pr % 10 == 0 { score -= 8.0; }
        else if pr % 5 == 0 { score -= 3.0; }
        else { score += 4.0; } // odd/awkward residual class
    }

    // Lookahead: if the next item fits exactly into the post_residual, strongly reward.
    if next_item_size > 0 && post_residual >= next_item_size {
        let slack = (post_residual - next_item_size) as f64;
        score -= 20.0 + 15.0 * (1.0 - slack / bin_capacity as f64);
        if slack == 0.0 { score -= 15.0; } // perfect chain fit
    } else if next_item_size > post_residual {
        // Next item cannot use this bin's remainder: penalize leftover.
        score += (post_residual as f64) * 0.5;
    }

    // Last-chance bin: if this is the only bin that fits, strongly prefer using it
    // over opening a new bin.
    if fitting_bins_count == 1 && bin_residual < bin_capacity {
        score -= 30.0;
    }

    // New-bin candidate handling: an empty bin has high residual; make it moderately
    // attractive only when current fit is bad, otherwise keep it as fallback.
    if bin_residual == bin_capacity {
        // Neutral-ish baseline: slightly worse than a decent fit, better than awful fits.
        score = 45.0
            - 10.0 * (step_index as f64 / (total_items.max(1) as f64)) // late stream: consolidate less
            + (open_bins_count as f64) * 0.5; // many open bins: prefer reusing
        if next_item_size > 0 && next_item_size >= 50 {
            score -= 8.0; // big next item: fresh bin is valuable
        }
        return score;
    }

    // Prefer bins with below-mean residual (consolidating fuller bins).
    score += (mean_residual - bin_residual as f64) * 0.3;

    // Progress-aware: early in stream, allow more bins; late, squeeze hard.
    let progress = step_index as f64 / (total_items.max(1) as f64);
    score += (1.0 - progress) * 3.0;

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // --- Strict dead-space avoidance ---
    // Small unusable gaps are the worst outcome: penalize them hard.
    let dead = post_residual as f64;
    if post_residual > 0 && post_residual <= 12 {
        score += (13.0 - dead) * 3.0; // steep penalty for tiny useless gaps
    }
    // Zero residual is perfect: big reward.
    if post_residual == 0 {
        score -= 40.0;
    }
    // Post residual that exactly fits the next item (lookahead) is valuable.
    if next_item_size > 0 && post_residual >= next_item_size {
        score -= 12.0;
        // Bonus if next item would fill this bin completely (perfect chain).
        if post_residual == next_item_size {
            score -= 20.0;
        }
    } else if next_item_size > 0 && post_residual > 0 {
        // Residual too small for next item: penalize proportionally to how close it is.
        let gap = next_item_size as f64 - dead;
        if gap < 15.0 {
            score += gap * 1.5;
        }
    }

    // --- Fit tightness reward: prefer bins where item dominates residual ---
    let fill_ratio = item_size as f64 / bin_residual as f64;
    score -= fill_ratio * 15.0;

    // --- Last-chance pressure ---
    if fitting_bins_count == 1 && bin_residual != bin_capacity {
        score -= 25.0; // strongly prefer using the only bin that fits
    }

    // --- New-bin candidate handling ---
    if bin_residual == bin_capacity {
        // Opening a new bin is only attractive when current open bins are crowded
        // or the fit would create dead space in an existing bin.
        let pressure = open_bins_count as f64 * 2.0;
        score = bin_capacity as f64 - pressure
            + (12.0 - dead.min(12.0)); // empty bin has max residual; make it competitive only under pressure
        if fitting_bins_count == 1 {
            score += 30.0; // never open a new bin when a last-chance fit exists
        }
    }

    // --- Open-bin count pressure: discourage bin sprawl ---
    score += open_bins_count as f64 * 0.8;

    // --- Mean residual coupling: if mean residual is high, avoid bins far from mean ---
    let dev = (bin_residual as f64 - mean_residual).abs();
    score += dev * 0.3;

    // --- Mild stream progression: late in stream, prefer exact fills even more ---
    let progress = step_index as f64 / total_items.max(1) as f64;
    score -= (1.0 - fill_ratio) * progress * 5.0;

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Aggressive 2-step lookahead: reward exact match of post_residual with next item
    if next_item_size > 0 {
        if post_residual == next_item_size {
            score -= 60.0; // perfect chain: bin filled exactly across two steps
        } else if post_residual >= next_item_size {
            let slack = (post_residual - next_item_size) as f64;
            // smaller slack after the next placement is better; non-linear penalty
            score -= 25.0 - (slack * 0.35).min(25.0);
            // bonus if next item leaves an exact fit too (perfect two-chain)
            if post_residual - next_item_size == 0 {
                score -= 10.0;
            }
        } else {
            // next item cannot follow into this bin: penalize proportionally
            let miss = (next_item_size - post_residual) as f64;
            score += 8.0 + miss * 0.25;
        }
    }

    // Penalize large dead space (unusable residuals) super-linearly
    if post_residual > 0 && post_residual < 10 {
        score += (10 - post_residual) as f64 * 1.5; // tiny crumbs are dead space
    }

    // Reward closing bins tightly: post_residual near 0 is great
    if post_residual == 0 {
        score -= 40.0;
    }

    // Last-chance bin: if this is the only fitting bin, strongly prefer using it
    if fitting_bins_count == 1 && bin_residual >= item_size {
        score -= 30.0;
    }

    // Compare against mean residual: prefer bins with residual below mean (tighter bins)
    score += (bin_residual as f64 - mean_residual) * 0.15;

    // New-bin candidate: penalize opening a new bin unless item is large and
    // no open bin offers a good chain (encourage packing into existing bins)
    if bin_residual == bin_capacity {
        let base_penalty = 55.0;
        let progress = if total_items > 0 { step_index as f64 / total_items as f64 } else { 0.0 };
        // later in the stream, be slightly more willing to open bins
        let mut new_bin_score = score + base_penalty - progress * 15.0;
        // if item is large relative to capacity, a fresh bin is more attractive
        new_bin_score -= (item_size as f64 / bin_capacity as f64) * 20.0;
        // if many bins are open already, discourage proliferation
        new_bin_score += open_bins_count as f64 * 2.0;
        // if next item also large, fresh bin keeps room for it
        if next_item_size >= 50 {
            new_bin_score -= 12.0;
        }
        return new_bin_score;
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Reward tight fits: exact fills are perfect, small residuals penalized quadratically.
    if post_residual == 0 {
        score -= 1000.0;
    } else {
        let pr = post_residual as f64;
        score += 0.15 * pr * pr / bin_capacity as f64;
    }

    // Penalize wasting a "last chance" bin when it's the only fitting bin
    // unless the fit is very tight (then reward it strongly).
    if fitting_bins_count == 1 && post_residual > 0 {
        score += 12.0;
        if post_residual <= item_size / 2 {
            score -= 18.0;
        }
    }

    // Lookahead: if the next item fits exactly in the post-residual, big bonus.
    if next_item_size > 0 {
        let nx = next_item_size as f64;
        if (post_residual as f64 - nx).abs() < 0.5 {
            score -= 60.0;
        } else if next_item_size <= post_residual {
            score -= 8.0;
        } else {
            // next item won't fit here; slight penalty for leaving awkward gap
            let waste = post_residual as f64;
            if waste > 0.0 && waste < nx {
                score += 0.3 * (waste - 30.0).abs();
            }
        }
    }

    // Time horizon: early in stream, be conservative (avoid fragmenting bins);
    // later, prefer filling existing bins to avoid opening new ones.
    let progress = if total_items > 0 { step_index as f64 / total_items as f64 } else { 0.0 };
    score -= 10.0 * progress;

    // Global state coupling: many open bins with high mean residual -> prefer
    // dumping into existing bins; few open bins -> new bin more acceptable.
    let ob = open_bins_count as f64;
    if bin_residual == bin_capacity {
        // new-bin candidate: base cost, adjusted by global pressure
        let mut new_score = 55.0;
        new_score -= 4.0 * ob;
        new_score += 0.25 * mean_residual;
        if next_item_size > 0 && next_item_size >= 60 {
            new_score -= 15.0; // large next item benefits from fresh bin
        }
        if progress > 0.7 {
            new_score += 20.0; // late stream: avoid opening bins
        }
        score = new_score;
    } else {
        // Existing bin: prefer bins with residual close to item (good fit)
        let fit_ratio = item_size as f64 / bin_residual as f64;
        score -= 20.0 * fit_ratio;
        // Prefer bins below mean residual (using up underfilled bins)
        if (bin_residual as f64) < mean_residual {
            score -= 5.0;
        }
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let cap = bin_capacity as f64;
    let progress = if total_items > 0 { step_index as f64 / total_items as f64 } else { 0.0 };
    let pr = post_residual as f64;
    let x = pr / cap; // normalized post residual

    // Base: reward tight fits via non-linear polynomial in normalized post residual
    let mut score = 2.0 * x * x - 1.5 * x + 0.5 * x * x * x * x;

    // Smooth stream-progress coupling: later in stream, penalize loose fits more
    let progress_coupling = progress * (x * x - 0.5 * x);
    score += 3.0 * progress_coupling;

    // Penalize dead space relative to mean residual (smooth interaction)
    score += 0.3 * (pr - mean_residual) * (1.0 - x) / cap;

    // Lookahead: reward bins whose post residual can host next item
    if next_item_size > 0 {
        let nx = next_item_size as f64;
        let fits_next = (pr >= nx) as i32 as f64;
        let gap = ((pr - nx).abs()) / cap;
        score -= 1.2 * fits_next * (1.0 - gap) * (1.0 + progress);
    }

    // Last-chance bonus: strongly favor the only fitting bin
    if fitting_bins_count == 1 && bin_residual < bin_capacity {
        score -= 5.0;
    }

    // Mild penalty for opening a new bin when good fits exist (new-bin candidate)
    if bin_residual == bin_capacity {
        score += 1.0 + 2.0 * progress;
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let cap = bin_capacity as f64;
    let mut score = post_residual as f64;

    // Harmonic class of the post-residual: perfect fits (0) heavily rewarded.
    if post_residual == 0 {
        score -= 60.0;
    } else if post_residual <= 5 {
        score -= 25.0;
    } else if post_residual % 10 == 0 {
        // residual in a "harmonic" class (multiple of 10) is reusable
        score -= 12.0;
    } else if post_residual < 10 {
        // dead space below smallest item size
        score += 20.0;
    }

    // Next item lookahead: reward if next item fits exactly into post_residual
    if next_item_size > 0 {
        if next_item_size == post_residual {
            score -= 45.0;
        } else if next_item_size < post_residual {
            let gap = post_residual - next_item_size;
            if gap <= 5 {
                score -= 18.0;
            } else if gap % 10 == 0 {
                score -= 8.0;
            }
            score += gap as f64 * 0.15;
        } else {
            // next item won't fit here; slight penalty for wasting large residual
            score += (post_residual as f64) * 0.05;
        }
    }

    // Last-chance bin: strongly favor using it to avoid opening a new bin
    if fitting_bins_count == 1 {
        score -= 30.0;
    }

    // New-bin candidate handling: empty bin gets a base penalty so we prefer
    // filling open bins, unless the fit in open bins is poor.
    if bin_residual == bin_capacity {
        score += 15.0;
        // opening a new bin is attractive for large items that would leave
        // awkward residuals elsewhere
        if item_size as f64 > 0.6 * cap {
            score -= 10.0;
        }
        if post_residual % 10 == 0 {
            score -= 5.0;
        }
    }

    // Prefer bins whose residual is close to the item (tight fit)
    let tightness = (bin_residual as f64 - item_size as f64) / cap;
    score += tightness * 25.0;

    // Mild pressure to consolidate when many bins are open
    score += open_bins_count as f64 * 0.5;

    // Deviation from mean residual: prefer below-mean residual bins (fuller bins)
    score += (mean_residual - bin_residual as f64) * 0.2;

    // Stream progression: later in stream, be greedier about tight fits
    let progress = if total_items > 0 { step_index as f64 / total_items as f64 } else { 0.0 };
    score *= 1.0 + 0.3 * progress;

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Strict dead-space avoidance: small leftover gaps are nearly unusable
    // (min item size is 1 in worst case, but tiny gaps waste capacity).
    if post_residual > 0 {
        if post_residual <= 10 {
            // Very small gap: heavy penalty (dead space).
            score += (11 - post_residual) as f64 * 12.0;
        } else if post_residual <= 20 {
            // Small gap: moderate penalty.
            score += (21 - post_residual) as f64 * 3.0;
        } else if post_residual >= 60 {
            // Large residual is flexible; mild reward.
            score -= 8.0;
        }
    } else {
        // Perfect fit: strongly reward.
        score -= 60.0;
    }

    // Reward tight fits (item fills most of the bin).
    let fill_ratio = item_size as f64 / bin_residual as f64;
    score -= fill_ratio * 25.0;

    // Lookahead: if next item fits exactly in post_residual, big reward.
    if next_item_size > 0 {
        if next_item_size == post_residual {
            score -= 45.0;
        } else if next_item_size <= post_residual {
            score -= 10.0;
        } else {
            // Next item won't fit here: penalize leaving awkward residual.
            score += (next_item_size - post_residual) as f64 * 0.3;
        }
    }

    // Last-chance bin: if this is the only bin that fits, prefer using it
    // to avoid opening a new bin.
    if fitting_bins_count == 1 && bin_residual != bin_capacity {
        score -= 20.0;
    }

    // Open-bin pressure: many open bins -> discourage spreading, favor
    // filling existing bins; few open bins -> new bins are cheaper.
    let pressure = (open_bins_count as f64).ln().max(0.0);
    score += pressure * 4.0;

    // New-bin candidate: neutral baseline, slightly discouraged unless
    // current item is large or residual gaps elsewhere are bad.
    if bin_residual == bin_capacity {
        score += 15.0;
        // Large items start fresh bins cheaply (avoids fragmenting).
        if item_size >= 50 {
            score -= 25.0;
        }
        // If mean residual across open bins is small (all bins tight),
        // opening a new bin is reasonable.
        if mean_residual < item_size as f64 {
            score -= 18.0;
        }
    }

    // Mean residual coupling: penalize bins far below mean residual
    // (creating outliers wastes flexibility).
    score += ((mean_residual - post_residual as f64).abs()) * 0.15;

    // Slight preference early in stream to keep bins balanced.
    if total_items > 0 {
        let progress = step_index as f64 / total_items as f64;
        score += (1.0 - progress) * 2.0;
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Perfect fit reward: strongly favor bins where the item fills the bin exactly.
    if post_residual == 0 {
        score -= 1000.0;
    }

    // 2-step lookahead: if the next item exactly fits the post-residual,
    // this placement chains perfectly — reward heavily.
    if next_item_size > 0 && post_residual == next_item_size {
        score -= 500.0;
    }

    // Lookahead match: next item fits into the leftover space (not exact),
    // mild reward proportional to how tight the chain is.
    if next_item_size > 0 && post_residual >= next_item_size {
        let tightness = next_item_size as f64 / post_residual as f64;
        score -= 60.0 * tightness;
    } else if next_item_size > 0 && post_residual < next_item_size {
        // Dead space for the next item: penalize leftover below smallest plausible item.
        if post_residual < 10 {
            score += 80.0;
        } else {
            score += 20.0;
        }
    }

    // Last-chance bin: if this is the only bin that fits, avoid opening a new bin
    // unless the fit is terrible.
    if fitting_bins_count == 1 && bin_residual != bin_capacity {
        score -= 45.0;
    }

    // Prefer bins tighter than the average residual (best-fit style),
    // scaled by deviation from mean residual.
    let dev = mean_residual - bin_residual as f64;
    score += 0.5 * dev;

    // Penalize new-bin opening when existing bins fit reasonably well,
    // unless the stream is early and many bins may be useful.
    if bin_residual == bin_capacity {
        let progress = step_index as f64 / (total_items.max(1) as f64);
        score += 30.0 + 40.0 * (1.0 - progress);
        // If no open bin fits at all, opening a new bin is necessary: soften penalty.
        if fitting_bins_count == 0 {
            score -= 200.0;
        }
    }

    // Mild preference for using fewer open bins (consolidation).
    score += 0.3 * open_bins_count as f64;

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Reward tight fits: post_residual small relative to capacity.
    let tightness = post_residual as f64 / bin_capacity as f64;
    score += tightness * tightness * 40.0;

    // Penalize leaving residuals that no plausible item can fill.
    // Items are 1..=100; residual below ~1 is dead. Penalize residuals
    // that are "just above" typical small items.
    if post_residual > 0 {
        let r = post_residual as f64;
        // dead-space curve: residuals just above small item sizes are wasteful
        score += 8.0 / r.sqrt();
    } else {
        // perfect fit: strong reward
        score -= 25.0;
    }

    // Lookahead: if the next item fits exactly in post_residual, big reward.
    if next_item_size > 0 && next_item_size <= post_residual {
        let gap = (post_residual - next_item_size) as f64;
        score -= 15.0 * (1.0 - gap / bin_capacity as f64);
    } else if next_item_size > 0 && next_item_size > post_residual {
        // next item won't fit here after placement: mild penalty
        score += 4.0;
    } else if next_item_size == 0 {
        // last item: just minimize waste
        score -= 5.0;
    }

    // Last chance bin: if this is the only fitting bin, avoid opening a new bin.
    if fitting_bins_count == 1 && bin_residual >= item_size {
        score -= 12.0;
    }

    // Global pressure: many open bins -> prefer filling existing ones.
    let pressure = open_bins_count as f64 / (mean_residual.max(1.0) / 10.0 + 1.0);
    score -= pressure.min(10.0);

    // Deviation from mean residual: prefer bins whose residual is close to
    // the mean (keeps bin states homogeneous, easier future packing).
    let dev = (bin_residual as f64 - mean_residual).abs();
    score += dev * 0.15;

    // Time horizon: early in stream, be more willing to open new bins
    // (long future benefits from flexibility); late, consolidate.
    let progress = if total_items > 0 { step_index as f64 / total_items as f64 } else { 0.0 };
    score += (1.0 - progress) * 6.0 - progress * 4.0;

    // New-bin candidate handling: empty bin has high post_residual,
    // which naturally scores high (bad). But early in stream or when
    // current bin fit is very poor, allow opening a new bin.
    if bin_residual == bin_capacity {
        // base cost of a new bin
        score += 30.0;
        // discount when progress is low (flexibility worth it)
        score -= (1.0 - progress) * 20.0;
        // discount when the alternative fit is terrible (post_residual tiny
        // but nonzero leaves awkward slivers)
        if post_residual > 0 && post_residual < 10 {
            score -= 25.0;
        }
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let progress = step_index as f64 / total_items.max(1) as f64;
    let pr = post_residual as f64;
    let cap = bin_capacity as f64;
    let norm_pr = pr / cap;
    let mut score = pr as f64;

    // Smooth non-linear coupling of post_residual with stream progress
    let poly = norm_pr * norm_pr * (1.0 - progress) - norm_pr * progress;
    score += 40.0 * poly;

    // Penalize near-empty-but-not-empty residuals as stream progresses (dead space)
    let waste = (norm_pr - 0.5) * (norm_pr - 0.5);
    score += 15.0 * waste * (0.5 + progress);

    // Reward tight fits
    let fit_ratio = item_size as f64 / bin_residual.max(1) as f64;
    score -= 25.0 * fit_ratio * fit_ratio * (1.0 - progress);

    // Last-chance bonus when only one bin fits
    if fitting_bins_count == 1 {
        score -= 30.0 * (1.0 - progress);
    }

    // Lookahead: reward residual that can hold the next item
    if next_item_size > 0 {
        let nx = next_item_size as f64;
        if pr >= nx {
            score -= 10.0 * (1.0 - pr / cap) * (1.0 - progress);
        } else {
            score += 8.0 * (nx - pr) / cap;
        }
    }

    // Mild pressure toward consolidation relative to mean residual
    score += 5.0 * (pr - mean_residual) / cap;

    // New-bin candidate: slight early-stream bias to open bins, late-stream bias to fill
    if bin_residual == bin_capacity {
        score -= 12.0 * (1.0 - progress);
        score += 10.0 * progress;
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // --- Harmonic class of the post residual: reward residuals that sit in
    // "useful" residue classes (multiples of small item sizes), punish odd ones.
    let pr = post_residual;
    let class_bonus = if pr == 0 {
        -60.0 // perfect fit: heavily reward closing the bin
    } else if pr % 10 == 0 {
        -18.0 // residual aligns with decimal harmonic grid
    } else if pr % 5 == 0 {
        -9.0
    } else if pr % 2 == 0 {
        -3.0
    } else {
        6.0 // odd residual: likely dead space
    };
    score += class_bonus;

    // --- Integer-division thresholds on post_residual: tiny slivers are dead space.
    if pr > 0 && pr < 10 {
        score += 25.0; // unusable sliver
    }
    if pr >= 10 && pr <= 25 {
        score += 10.0; // only smallest items can use it
    }

    // --- Capacity fraction coupling: how full will the bin be?
    let fill_frac = (bin_capacity - pr) as f64 / bin_capacity as f64;
    score -= 30.0 * fill_frac; // prefer filling bins deeper

    // --- Lookahead coupling: does the next item fit the post residual?
    if next_item_size > 0 {
        if pr >= next_item_size {
            // reward if post residual matches next item nicely (exact or harmonic)
            let slack = pr - next_item_size;
            if slack == 0 {
                score -= 22.0;
            } else if slack <= 10 {
                score -= 8.0;
            } else {
                score += slack as f64 * 0.15;
            }
        } else {
            // next item cannot use this bin's remainder: penalize proportionally
            score += (next_item_size - pr) as f64 * 0.25;
        }
    }

    // --- Last-chance pressure: if this is the only fitting bin, avoid forcing
    // a new bin unless this fit is truly bad.
    if fitting_bins_count == 1 && bin_residual != bin_capacity {
        score -= 20.0;
    }

    // --- New-bin candidate handling: an empty bin is a fallback; prefer it only
    // when all open bins would waste heavily.
    if bin_residual == bin_capacity {
        // base cost of opening a new bin, softened late in the stream or
        // when mean residual across open bins is small (poor reuse prospects).
        let progress = step_index as f64 / total_items.max(1) as f64;
        score = 40.0 + 25.0 * (1.0 - progress);
        if mean_residual < 20.0 {
            score -= 15.0; // open bins nearly full anyway -> new bin fine
        }
        if fitting_bins_count == 0 {
            score -= 60.0; // nothing fits anywhere: must open
        }
    } else {
        // Mild penalty for spreading across many open bins
        score += (open_bins_count as f64).ln() * 2.0;
    }

    // --- Modulo interplay between item size and residual class:
    // if item_size divides the original residual evenly, great fit.
    if item_size > 0 && bin_residual % item_size == 0 && bin_residual != bin_capacity {
        score -= 12.0;
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Strict dead-space avoidance: small nonzero gaps are the worst waste.
    if post_residual > 0 && post_residual < 10 {
        score += 60.0 - 5.0 * post_residual as f64; // tiny gap => heavy penalty
    } else if post_residual == 0 {
        score -= 40.0; // perfect fit strongly rewarded
    } else {
        // Larger gaps are less "dead": mild reward proportional to gap size
        score -= 0.15 * post_residual as f64;
    }

    // Gap utility: if a known next item fits exactly into the gap, reward heavily.
    if next_item_size > 0 && post_residual >= next_item_size {
        let slack = (post_residual - next_item_size) as f64;
        score -= 30.0 - 0.3 * slack;
    }
    // If gap is too small for the next item, it is likely dead space.
    if next_item_size > 0 && post_residual < next_item_size && post_residual > 0 {
        score += 12.0;
    }

    // Last-chance pressure: if this is the only bin that fits, strongly prefer using it.
    if fitting_bins_count == 1 && bin_residual < bin_capacity {
        score -= 25.0;
    }

    // Open-bin pressure: discourage opening new bins when many are open.
    if bin_residual == bin_capacity {
        // brand-new bin candidate: base cost + pressure from open bins
        score += 45.0 + 6.0 * open_bins_count as f64;
        // late in the stream, opening a fresh bin is less attractive
        let progress = step_index as f64 / (total_items.max(1) as f64);
        score += 20.0 * progress;
        // but if mean residual across open bins is small (all crowded), new bin is fine
        score -= 0.4 * mean_residual;
    } else {
        // mild preference for fuller bins (lower residual chosen naturally)
        score += 0.05 * (bin_residual as f64 - mean_residual);
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Strong reward for near-perfect fit
    if post_residual == 0 {
        score -= 1000.0;
    } else if post_residual <= 5 {
        score -= 200.0;
    }

    // 2-step lookahead: reward post_residual that exactly matches next item
    if next_item_size > 0 {
        let nxt = next_item_size as f64;
        let pr = post_residual as f64;
        if pr >= nxt {
            // next item can also fit here: big bonus scaled by tightness
            let tight = (pr - nxt) / bin_capacity as f64;
            score -= 150.0 * (1.0 - tight) - 50.0;
        } else {
            // dead space: penalize unusable gap relative to next item
            score += 0.5 * (nxt - pr);
        }
    }

    // Prefer tight packing relative to mean residual of open bins
    score += 0.3 * (post_residual as f64 - mean_residual).abs();

    // Last-chance bin: strongly favor using it to avoid opening a new bin
    if fitting_bins_count == 1 && bin_residual != bin_capacity {
        score -= 120.0;
    }

    // Penalize opening a new bin when decent fitting bins exist
    if bin_residual == bin_capacity {
        let waste = post_residual as f64;
        score += 80.0 + 0.5 * waste;
        if fitting_bins_count > 0 && post_residual < 30 {
            score += 100.0; // don't open a new bin for a near-perfect existing fit
        }
    }

    // Late in the stream, consolidate aggressively
    let progress = step_index as f64 / total_items.max(1) as f64;
    score -= 40.0 * progress * (1.0 - post_residual as f64 / bin_capacity as f64);

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Reward tight fits (small post_residual relative to capacity).
    let tightness = 1.0 - (post_residual as f64 / bin_capacity as f64);
    score -= 25.0 * tightness * tightness;

    // Perfect fit bonus.
    if post_residual == 0 {
        score -= 60.0;
    } else if post_residual < 5 {
        score -= 30.0;
    }

    // Lookahead: penalize if the next item cannot use the leftover space.
    if next_item_size > 0 {
        if post_residual > 0 && next_item_size > post_residual {
            // Dead space for the next item: penalize proportionally to wasted gap.
            let waste = (next_item_size - post_residual) as f64;
            score += 0.35 * waste;
        } else if next_item_size <= post_residual && post_residual > 0 {
            // Next item chains nicely: reward.
            let chained = post_residual as f64 - next_item_size as f64;
            score -= 0.5 * (post_residual as f64) + 0.3 * (bin_capacity as f64 - chained).min(40.0);
        }
    } else {
        // Last item: strongly prefer minimal leftover.
        score -= 40.0 * tightness;
    }

    // Last-chance bin: if this is the only fitting bin, strongly prefer using it
    // over opening a new bin (unless fit is terrible).
    if fitting_bins_count == 1 && bin_residual < bin_capacity {
        score -= 45.0;
        // Extra reward for decent fits in a last-chance scenario.
        if post_residual as f64 <= mean_residual {
            score -= 15.0;
        }
    }

    // New-bin candidate: opening a new bin is only attractive when existing bins
    // fit poorly or the stream is early with few bins.
    if bin_residual == bin_capacity {
        // Base penalty: reusing bins is generally better.
        score += 70.0;
        // Early in the stream, having few bins open makes new bins cheaper.
        let progress = step_index as f64 / total_items.max(1) as f64;
        score -= 40.0 * (1.0 - progress) * (1.0 - open_bins_count as f64 / (open_bins_count as f64 + 3.0));
        // If the item is large, a fresh bin keeps flexibility for big future items.
        if item_size > bin_capacity / 2 {
            score -= 20.0;
        }
        // If mean residual across open bins is small (bins are nearly full),
        // opening a new bin is more reasonable.
        score -= 0.4 * (mean_residual.min(bin_capacity as f64));
        // If no open bin fits well (large post_residual would be wasted), new bin less bad.
        if post_residual == bin_capacity - item_size && item_size >= 70 {
            score -= 25.0;
        }
    } else {
        // Existing bin: mild penalty for spreading across many bins when residuals
        // are fragmented.
        if (post_residual as f64) > mean_residual * 1.5 && mean_residual > 0.0 {
            score += 8.0;
        }
    }

    // Time horizon: late in the stream, consolidation matters more (fewer bins).
    let progress = step_index as f64 / total_items.max(1) as f64;
    score -= 10.0 * progress * (bin_capacity as f64 - post_residual as f64) / bin_capacity as f64;

    // Penalize leaving residuals that are unusably small but nonzero.
    if post_residual > 0 && post_residual < 10 {
        score += 12.0;
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let progress = if total_items > 1 { step_index as f64 / total_items as f64 } else { 0.0 };
    let cap = bin_capacity as f64;
    let post = post_residual as f64;
    let pre = bin_residual as f64;
    let item = item_size as f64;

    // Base: prefer bins whose post-residual is small (tight fit).
    let mut score = post;

    // Non-linear dead-space penalty: residuals that are too small to hold
    // anything useful are penalized super-linearly (quartic coupling).
    let dead = (post / cap).powi(4) * cap;
    score += 2.0 * dead;

    // Reward tightness: normalized fill ratio of this placement, smoothly
    // coupled with stream progress (later in the stream, value tight fits more).
    let fill = item / cap;
    score -= (1.0 + progress) * fill * fill * cap * 0.6;

    // Perfect-fit bonus (post_residual near zero), stronger as stream advances.
    let perfect = 1.0 - (post / cap).powi(2);
    score -= perfect * (0.5 + 2.0 * progress) * 10.0;

    // Last-chance bin: if this is the only fitting bin, strongly prefer it
    // over opening a new bin, scaled by how much it helps.
    if fitting_bins_count == 1 {
        score -= 15.0 + 10.0 * progress;
    }

    // Lookahead coupling: if the next item fits exactly in the post-residual,
    // reward heavily (chained packing); if next item cannot fit, mild penalty
    // for leaving a residual that wastes future capacity.
    if next_item_size > 0 {
        let nxt = next_item_size as f64;
        if nxt <= post_residual as u32 {
            let chain_fit = 1.0 - ((post - nxt) / cap).powi(2);
            score -= chain_fit * 8.0 * (0.5 + progress);
        } else {
            score += 3.0 * (nxt - post) / cap;
        }
    }

    // Prefer bins below mean residual (consolidating space) with smooth coupling.
    score += 0.05 * (pre - mean_residual);

    // New-bin candidate handling: an empty bin gets a mild opening cost so it
    // is only chosen when open bins fit poorly; cost shrinks with progress.
    if bin_residual == bin_capacity {
        score += 12.0 * (1.0 - 0.5 * progress) + 0.1 * open_bins_count as f64;
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Harmonic class of the leftover space: post_residual buckets by tens.
    // Leftovers in low classes (tiny dead space) are heavily penalized.
    let class = post_residual / 10;
    score += match class {
        0 => 40.0,             // dead space < 10: nearly unusable
        1 => 18.0,
        2 => 8.0,
        3 => 0.0,
        4 => -6.0,
        5 => -10.0,
        6 => -14.0,
        7 => -18.0,
        8 => -22.0,
        _ => -26.0,            // large leftover: versatile
    };

    // Modulo-10 resonance: leftover matching common item-size residues is good.
    let m = post_residual % 10;
    if m == 0 { score -= 8.0; }
    else if m == 5 { score -= 3.0; }
    else if m >= 7 { score += 4.0; }

    // Lookahead coupling: if next item fits exactly into post_residual, reward strongly.
    if next_item_size > 0 && next_item_size == post_residual {
        score -= 30.0;
    } else if next_item_size > 0 && next_item_size <= post_residual {
        // harmonic class match between next item and leftover
        let nl = next_item_size / 10;
        if nl == class { score -= 6.0; }
        if post_residual % next_item_size.max(1) == 0 { score -= 4.0; }
    } else if next_item_size > post_residual {
        // leftover too small for next item: penalize proportional dead risk
        score += (post_residual as f64) * 0.15;
    }

    // Last-chance bin: avoid opening a new bin when this is the only fitting one.
    if fitting_bins_count == 1 && bin_residual >= item_size {
        score -= 12.0;
    }

    // New-bin candidate handling: prefer it only when stream is early and open bins
    // are collectively full, or when this placement creates a bad class.
    let progress = step_index as f64 / (total_items.max(1) as f64);
    if bin_residual == bin_capacity {
        // new bin: baseline equals full capacity; adjust by stream context
        score = bin_capacity as f64 - 20.0 * (1.0 - progress);
        if mean_residual < 15.0 && open_bins_count > 0 {
            score -= 10.0; // existing bins nearly full -> new bin attractive
        }
        if post_residual % 10 == 0 {
            score -= 5.0; // fresh bin leaves round residues
        }
    }

    // Prefer filling bins tighter than the mean residual.
    if (post_residual as f64) < mean_residual {
        score -= 5.0;
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Dead-space avoidance: small unusable gaps (1..=10) are heavily penalized.
    if post_residual > 0 && post_residual <= 10 {
        score += 60.0 - 5.0 * post_residual as f64;
    }
    // Medium awkward gaps (11..=25) mildly penalized.
    else if post_residual > 10 && post_residual <= 25 {
        score += 8.0 - 0.2 * post_residual as f64;
    }
    // Perfect / near-perfect fits strongly rewarded.
    if post_residual == 0 {
        score -= 40.0;
    } else if post_residual <= 3 {
        score -= 20.0;
    }

    // Reward filling a tight bin (high fill ratio).
    let fill_ratio = item_size as f64 / bin_capacity as f64;
    score -= 15.0 * fill_ratio;

    // Open-bins pressure: with many open bins, prefer existing bins; discourage new bins.
    let progress = step_index as f64 / (total_items.max(1) as f64);
    let pressure = open_bins_count as f64 / (1.0 + progress * 10.0);
    if bin_residual == bin_capacity {
        // New-bin candidate: base cost plus pressure, but cheaper if item is large
        // and no good existing fit exists.
        score += 25.0 + 2.0 * pressure;
        if item_size >= 60 && fitting_bins_count <= 1 {
            score -= 20.0;
        }
        // If lookahead item could pair with leftovers, opening a new bin is less bad.
        if next_item_size > 0 && post_residual >= next_item_size {
            score -= 10.0;
        }
    } else {
        // Existing bin: reward using bins whose residual is close to item (tight fit).
        let tightness = (bin_residual - item_size) as f64 / bin_capacity as f64;
        score -= 10.0 * (1.0 - tightness);
        // Last-chance bin: strongly prefer using it to avoid waste.
        if fitting_bins_count == 1 {
            score -= 12.0;
        }
        // Prefer bins below mean residual (consolidating emptier bins' usage).
        if (bin_residual as f64) < mean_residual {
            score -= 4.0;
        }
        // Lookahead synergy: if next item fits the post residual exactly-ish, reward.
        if next_item_size > 0 && post_residual >= next_item_size && post_residual - next_item_size <= 5 {
            score -= 15.0;
        }
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Perfect 2-step match: this bin will be exactly filled by the next item.
    if next_item_size > 0 {
        if post_residual == next_item_size {
            score -= 500.0;
        } else if post_residual > next_item_size {
            // Residual after next placement; reward tight chains.
            let chain_residual = post_residual - next_item_size;
            score -= 60.0 / (1.0 + chain_residual as f64);
            if chain_residual == 0 {
                score -= 250.0;
            }
        } else {
            // Next item cannot follow into this bin: penalize dead space creation.
            score += (next_item_size - post_residual) as f64 * 1.5;
        }
    } else {
        // Last item: prefer minimal leftover.
        score -= 100.0;
    }

    // Relative to mean residual: prefer bins tighter than average.
    score += (post_residual as f64 - mean_residual) * 0.8;

    // Last-chance bin: strong bonus to use it rather than open a new bin.
    if fitting_bins_count == 1 && bin_residual < bin_capacity {
        score -= 120.0;
    }

    // Slight preference to fill older bins when many are open.
    score += open_bins_count as f64 * 0.3;

    // Late in the stream, tighten packing harder.
    let progress = step_index as f64 / (total_items.max(1) as f64);
    score -= progress * 10.0;

    // New-bin candidate: only attractive when no open bin fits well.
    if bin_residual == bin_capacity {
        if next_item_size > 0 && item_size + next_item_size <= bin_capacity {
            // Opening a new bin allows a perfect pair with the next item.
            score -= 180.0;
        } else {
            score += 150.0;
        }
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Reward tight fits: prefer bins whose post residual is small relative to capacity.
    let tightness = (post_residual as f64) / (bin_capacity as f64);
    score += tightness * tightness * 40.0;

    // Perfect fit bonus.
    if post_residual == 0 {
        score -= 100.0;
    }

    // Lookahead: if the next item can fit into the post residual, reward this placement.
    if next_item_size > 0 && post_residual >= next_item_size {
        score -= 8.0 + 0.1 * (post_residual - next_item_size) as f64;
    }
    // If next item is small enough that any future bin fits it, mild penalty for wasting space now.
    if next_item_size > 0 && next_item_size < 20 && post_residual > 0 && post_residual < next_item_size {
        score += 5.0;
    }

    // Last-chance bin: strongly favor using it to avoid opening a new bin.
    if fitting_bins_count == 1 && bin_residual < bin_capacity {
        score -= 25.0;
    }

    // Crowding: with many open bins, prefer filling existing ones over opening new.
    let progress = step_index as f64 / (total_items.max(1) as f64);
    let crowding = (open_bins_count as f64).ln() + 1.0;
    if bin_residual < bin_capacity {
        score -= 6.0 / crowding;
    } else {
        // New-bin candidate: penalize opening a bin unless it's early or residuals are all tiny.
        score += 18.0 * (1.0 - progress) * 0.0 + 14.0 + 3.0 * crowding * progress;
        // If mean residual across open bins is small, opening a new bin is more acceptable.
        score -= (mean_residual / 10.0).min(10.0);
    }

    // Prefer bins whose residual was already small (compact bins first).
    if bin_residual < bin_capacity {
        score += (bin_residual as f64) * 0.05;
    }

    // Time horizon: late in the stream, be greedier about tight fits.
    score -= 10.0 * progress * (1.0 - tightness);

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let progress = step_index as f64 / total_items.max(1) as f64;
    let pr = post_residual as f64;
    let cap = bin_capacity as f64;
    let x = pr / cap; // normalized post residual

    // Base: prefer small post residual, with non-linear shaping
    let mut score = pr as f64 * (1.0 + 0.5 * x * x);

    // Smooth polynomial coupling with stream progress:
    // early on, tolerate larger residuals (keep bins flexible);
    // late in stream, aggressively minimize post residual.
    let coupling = 1.0 + 1.5 * progress * (1.0 - progress) * 4.0; // peaks mid-stream
    score *= 0.6 + 0.4 * coupling;

    // Dead-space penalty: residual too small to be useful (below mean item scale)
    let dead = (x - 0.05).max(0.0) * (0.10 - x).max(0.0);
    score += 40.0 * dead;

    // Last-chance bonus: strongly favor the only fitting bin to avoid opening a bin
    if fitting_bins_count == 1 {
        score -= 12.0 * (1.0 - progress);
    }

    // Lookahead: reward bins whose post residual can still host the next item
    if next_item_size > 0 {
        if (post_residual as u32) >= next_item_size {
            score -= 5.0;
        } else {
            score += 3.0 * (next_item_size - post_residual) as f64 / cap;
        }
    }

    // Slight preference for consolidating into fewer bins when many are open
    score += 0.02 * open_bins_count as f64 * (1.0 - x);

    // Deviation from mean residual: prefer bins near the mean (balanced packing)
    score += 0.05 * (pr - mean_residual).abs();

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Dead-space penalty: residual that cannot fit any plausible item (<=10) is wasted.
    if post_residual < 10 {
        score += 60.0;
    }

    // Harmonic class of post_residual: how many "size classes" of items (10..80 step 10)
    // can still fit. Fewer classes = tighter fit = better packing.
    let classes_fit = (post_residual / 10).min(8) as f64;
    score -= 14.0 * classes_fit;

    // Modulo-10 class penalty: prefer post_residual near multiples of 10 (clean splits),
    // penalize awkward odd residues that fragment space.
    let mod10 = (post_residual % 10) as f64;
    score += 0.8 * (mod10 * mod10) / 25.0;

    // Lookahead: if next item fits in post_residual, reward; if not, penalize slightly
    // unless this bin was the last chance anyway.
    if next_item_size > 0 {
        if next_item_size <= post_residual {
            score -= 8.0;
        } else {
            score += 5.0;
        }
        // Harmonic coupling: next item's own post-fit residual class
        if next_item_size <= post_residual {
            let next_post = post_residual - next_item_size;
            if next_post < 10 {
                score += 4.0; // would create new dead space for the following step
            } else {
                score -= (next_post / 10) as f64 * 2.0;
            }
        }
    }

    // Last-chance bonus: if this is the only fitting bin, strongly favor using it
    // over opening a new bin.
    if fitting_bins_count == 1 {
        score -= 35.0;
    }

    // New-bin candidate handling: empty bin has high raw score; make it attractive
    // only when current bin's post_residual would be unusable dead space.
    if bin_residual == bin_capacity {
        // Base cost of opening a new bin, softened by stream progress.
        score = 45.0 + 20.0 * (step_index as f64 / total_items.max(1) as f64);
        // More attractive if open bins are already quite full on average.
        score -= (mean_residual / bin_capacity as f64) * 15.0;
        // Discourage hoarding bins early in the stream.
        score += 3.0 * (open_bins_count as f64).sqrt();
        // If next item is huge and won't fit alongside typical residuals, new bin is safer.
        if next_item_size > 60 {
            score -= 10.0;
        }
    }

    // Global tightness: prefer bins whose residual is far below the mean (tighter bins
    // get filled first), keeping loose bins available for future awkward items.
    score += 0.3 * (mean_residual - bin_residual as f64).max(-100.0) * 0.1;

    // Small penalty for very large item relative to residual (near-exact fit is good,
    // but extreme tightness leaves nothing) — mild shaping.
    let fill = item_size as f64 / bin_residual.max(1) as f64;
    if fill > 0.9 {
        score -= 6.0;
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Strict dead-space avoidance: tiny leftover gaps are nearly unusable.
    if post_residual > 0 && post_residual < 10 {
        score += 40.0 * (10.0 - post_residual as f64) / 10.0;
    }
    // Perfect fit is strongly rewarded.
    if post_residual == 0 {
        score -= 30.0;
    } else if post_residual <= 15 {
        // Small-but-usable gap: mild penalty scaled by gap tightness.
        score += 0.6 * (15.0 - post_residual as f64);
    }

    // Reward bins whose residual can still host the lookahead item after placement.
    if next_item_size > 0 && post_residual >= next_item_size {
        score -= 8.0;
    } else if next_item_size > 0 && post_residual > 0 {
        // Leftover that cannot fit the next item: dead-space risk.
        score += 0.25 * post_residual as f64;
    }

    // Last-chance bin: strongly prefer using it over opening a new bin.
    if fitting_bins_count == 1 && bin_residual < bin_capacity {
        score -= 20.0;
    }

    // Open-bins pressure: with many open bins, discourage spreading; encourage filling.
    let progress = step_index as f64 / (total_items.max(1) as f64);
    score += 0.15 * open_bins_count as f64 * (0.5 + 0.5 * progress);

    // New-bin candidate: make it attractive only when current bin would leave a bad gap
    // and no other bin is a better host. Base new-bin score near mean residual.
    if bin_residual == bin_capacity {
        score = mean_residual.max(20.0) + 5.0;
        if next_item_size > 0 && next_item_size >= item_size {
            score -= 6.0; // opening fresh is fine when item stream is trending large
        }
        if fitting_bins_count <= 1 {
            score += 25.0; // don't open when this is the only fitting bin
        }
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Reward perfect 2-step lookahead: post_residual exactly matches next item.
    if next_item_size > 0 {
        let diff = (post_residual as i64 - next_item_size as i64).abs() as f64;
        score -= 30.0 * (1.0 - diff / (bin_capacity as f64)) * (1.0 - diff / (bin_capacity as f64));
        if diff == 0.0 {
            score -= 40.0;
        }
        // Penalize leaving residual that is too small for anything useful (dead space).
        if post_residual > 0 && post_residual < next_item_size && post_residual < 10 {
            score += 25.0;
        }
    }

    // Penalize large post residual relative to mean residual (wasteful fit).
    score += 0.3 * (post_residual as f64 - mean_residual).max(0.0);

    // Last-chance bin bonus: if this is the only fitting bin, strongly favor using it.
    if fitting_bins_count == 1 && bin_residual != bin_capacity {
        score -= 20.0;
    }

    // Strongly discourage opening a new bin when a decent fit exists.
    if bin_residual == bin_capacity {
        score += 15.0;
        if next_item_size > 0 && next_item_size >= item_size {
            score += 10.0;
        }
    }

    // Slight preference for tighter bins as stream progresses.
    let progress = step_index as f64 / (total_items.max(1) as f64);
    score -= progress * (bin_residual as f64 - post_residual as f64);

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Reward tight fits: bonus grows as post_residual approaches zero.
    let tightness = 1.0 - (post_residual as f64) / (bin_capacity as f64);
    score -= 12.0 * tightness * tightness;

    // Lookahead: if the next item fits exactly into post_residual, strongly reward.
    if next_item_size > 0 && post_residual > 0 {
        if next_item_size == post_residual {
            score -= 40.0;
        } else if next_item_size <= post_residual {
            // Reward if next item can still fit, scaled by how much room it leaves.
            let after_next = post_residual - next_item_size;
            score -= 8.0 * (1.0 - (after_next as f64) / (bin_capacity as f64));
        } else {
            // Penalize leaving a gap just larger than the next item (dead space).
            let waste = (post_residual - next_item_size.min(post_residual)) as f64;
            if next_item_size > post_residual {
                score += 4.0 * (next_item_size - post_residual) as f64 / 100.0;
            }
            let _ = waste;
        }
    }

    // Last-chance bin: strongly favor using the only bin that fits, avoiding a new bin.
    if fitting_bins_count == 1 && bin_residual >= item_size {
        score -= 25.0;
    }

    // New-bin candidate handling: penalize opening a new bin when good fits exist,
    // but allow it if the item leaves a large residual in every existing bin.
    if bin_residual == bin_capacity {
        // Base penalty for opening a new bin; reduced when item is large
        // (packing a big item in a fresh bin leaves a clean residual).
        let size_frac = item_size as f64 / bin_capacity as f64;
        score += 30.0 - 20.0 * size_frac;
        // Late in the stream, opening bins is more acceptable (fewer future items to strand).
        let progress = step_index as f64 / (total_items.max(1) as f64);
        score -= 15.0 * progress;
        // If many bins are open with scattered residuals, a fresh bin is fine.
        score -= (open_bins_count as f64).min(10.0) * 0.5;
        // If mean residual is large but fragmented (much larger than item), prefer new bin.
        if mean_residual > item_size as f64 + 30.0 {
            score -= 10.0;
        }
    }

    // Prefer placing into bins whose residual is already small (consolidate).
    let res_frac = bin_residual as f64 / bin_capacity as f64;
    score += 6.0 * res_frac;

    // Mild penalty for spreading across many bins when residuals are similar.
    score += 0.3 * (open_bins_count as f64);

    // Exact-fill reward.
    if post_residual == 0 {
        score -= 50.0;
    }

    // Penalize leaving residuals in the awkward small gap (1..10) that few items fit.
    if post_residual > 0 && post_residual < 10 {
        score += 15.0;
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;
    let cap = bin_capacity as f64;
    let pr = post_residual as f64;
    let prog = step_index as f64 / total_items.max(1) as f64;
    let x = pr / cap;

    // Non-linear polynomial coupling of post_residual with stream progress
    let poly = x * x * (1.0 - x) * (1.0 - x);
    score -= 40.0 * poly * (0.5 + prog);

    // Penalize large residuals late in the stream (dead space matters more)
    score += 12.0 * x * x * x * prog;

    // Reward tight fits: small post_residual relative to item size
    let fit_ratio = item_size as f64 / bin_residual.max(1) as f64;
    score -= 25.0 * fit_ratio * fit_ratio;

    // Last-chance bonus: only one bin can fit this item
    if fitting_bins_count == 1 && bin_residual != bin_capacity {
        score -= 30.0;
    }

    // Lookahead: if next item fits the post-residual, reward this placement
    if next_item_size > 0 {
        let nxt = next_item_size as f64;
        if pr >= nxt {
            let slack = (pr - nxt) / cap;
            score -= 15.0 * (1.0 - slack) * (1.0 - prog);
        } else {
            score += 8.0 * (nxt - pr) / cap;
        }
    }

    // Mild pressure to consolidate when many bins are open
    let density = open_bins_count as f64 / (open_bins_count as f64 + 4.0);
    score += 6.0 * density * x;

    // Mean-residual deviation: prefer bins whose residual is near the mean
    let dev = (pr - mean_residual) / cap;
    score += 5.0 * dev * dev;

    // New-bin candidate: penalize opening a new bin unless existing fits are bad
    if bin_residual == bin_capacity {
        score += 18.0 + 10.0 * (1.0 - fit_ratio);
        if fitting_bins_count <= 1 {
            score -= 35.0;
        }
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Harmonic class of the post-fit residual: residues modulo 10 and 20
    let r20 = post_residual % 20;
    let r10 = post_residual % 10;
    let half = bin_capacity / 2;

    // Reward residuals that are "harmonically compatible" with common item sizes:
    // residuals divisible by 20 or 10 are more reusable.
    if post_residual == 0 {
        score -= 60.0; // perfect fill
    } else if r20 == 0 {
        score -= 12.0;
    } else if r10 == 0 {
        score -= 6.0;
    } else {
        // Penalize awkward residuals in a graded way
        score += (r20.min(20 - r20)) as f64 * 0.8;
    }

    // Dead-space penalty: small unusable residuals (below min item size 1..100 unknown,
    // but assume small items exist) get a mild bump, big waste gets a strong bump.
    if post_residual > 0 && post_residual <= 10 {
        score += 5.0;
    } else if post_residual > half {
        score += (post_residual - half) as f64 * 0.5;
    }

    // Lookahead: if the next item fits exactly into the post residual, strongly favor this bin.
    if next_item_size > 0 {
        if next_item_size == post_residual {
            score -= 45.0;
        } else if next_item_size <= post_residual {
            let slack = post_residual - next_item_size;
            // Harmonic check: does the pair leave a clean residue?
            let pair_res = post_residual % next_item_size.max(1);
            score -= 10.0 - (slack as f64 * 0.25) - if pair_res == 0 { 8.0 } else { 0.0 };
        } else {
            // next item won't fit here; slight penalty proportional to overflow
            score += (next_item_size - post_residual) as f64 * 0.15;
        }
    }

    // Last-chance bin: if this is the only bin that fits, strongly favor using it
    // over opening a new bin — unless the fit is terrible (huge post residual).
    if fitting_bins_count == 1 && bin_residual < bin_capacity {
        if post_residual <= half {
            score -= 30.0;
        } else {
            score -= 8.0;
        }
    }

    // New-bin candidate: penalize opening a new bin, scaled by how many bins exist
    // and how well the item would fit elsewhere. Empty bin has post_residual = capacity.
    if bin_residual == bin_capacity {
        let progress = step_index as f64 / total_items.max(1) as f64;
        let mut open_penalty = 25.0 + open_bins_count as f64 * 2.0;
        // Early in the stream, opening bins is cheaper (more future items to fill them)
        open_penalty *= 1.0 - 0.4 * progress;
        // If next item is large and would combine with this item, a fresh bin is attractive
        if next_item_size > 0 && next_item_size + item_size <= bin_capacity {
            open_penalty -= 12.0;
        }
        score += open_penalty;
    }

    // Prefer bins whose residual is closest to the mean (keep residuals homogeneous),
    // mildly, so packing stays balanced across bins.
    score += ((post_residual as f64 - mean_residual).abs()) * 0.1;

    // Tiny tie-break noise-free nudge by index to stabilize selection deterministically
    score += (step_index % 7) as f64 * 0.01;

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Strict dead-space avoidance: harshly penalize small unusable gaps.
    if post_residual <= 5 {
        score += 200.0; // nearly perfect fit is great, but tiny gap is dead space
    } else if post_residual < 20 {
        score += 60.0 * (1.0 - post_residual as f64 / 20.0);
    } else if post_residual < 40 {
        score += 12.0;
    }

    // Reward exact / tight fits.
    if post_residual == 0 {
        score -= 150.0;
    } else if post_residual <= 10 {
        score -= 40.0;
    }

    // Last-chance bin: strongly prefer using it over opening a new bin.
    if fitting_bins_count == 1 {
        score -= 80.0;
    }

    // Open-bin pressure: with many open bins, prefer filling existing ones.
    let progress = step_index as f64 / (total_items.max(1) as f64);
    let pressure = open_bins_count as f64 * (1.0 + progress);
    score += pressure * 0.5;

    // Lookahead: if next item fits in the post residual, reward this placement.
    if next_item_size > 0 && post_residual >= next_item_size {
        score -= 25.0;
        // Extra reward if next item fills it nearly exactly.
        let gap = post_residual - next_item_size;
        if gap <= 5 {
            score -= 20.0;
        }
    }
    // Penalize leaving a gap the next item barely cannot use.
    if next_item_size > post_residual && post_residual > 0 && post_residual < next_item_size {
        score += 15.0;
    }

    // Prefer bins tighter than the mean (waste-averse selection).
    score += (bin_residual as f64 - mean_residual) * 0.3;

    // New-bin candidate: only attractive when no open bin is a good home.
    if bin_residual == bin_capacity {
        if fitting_bins_count == 0 {
            score -= 60.0;
        } else {
            // Opening a new bin competes with existing bins: mild penalty
            // unless the best existing fit would be poor.
            if item_size <= 30 {
                score += 30.0; // small items should go into open bins
            } else {
                score += 10.0;
            }
        }
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Perfect 2-step lookahead match: post_residual exactly equals next item
    if next_item_size > 0 && post_residual == next_item_size {
        score -= 40.0;
    }

    // Near-match: next item fits with small slack left afterwards
    if next_item_size > 0 && post_residual >= next_item_size {
        let slack = post_residual - next_item_size;
        if slack <= 5 {
            score -= 25.0;
        } else {
            score -= 12.0 * (1.0 - slack as f64 / post_residual as f64);
        }
    }

    // Penalize dead space that the next item cannot use
    if next_item_size > 0 && post_residual < next_item_size {
        let unusable = (next_item_size - post_residual) as f64;
        score += 0.35 * unusable;
    }

    // Strongly reward near-full bins (post residual below min item size)
    if post_residual < 10 {
        score -= 30.0;
    }

    // Last-chance bin: if this is the only fitting bin, prefer using it
    if fitting_bins_count == 1 && bin_residual != bin_capacity {
        score -= 20.0;
    }

    // Penalize opening a new bin when existing bins fit reasonably well
    if bin_residual == bin_capacity {
        score += 15.0;
        if next_item_size > 0 && post_residual >= next_item_size {
            score -= 10.0; // fresh bin still useful for lookahead chain
        }
    }

    // Contextual coupling with mean residual: prefer bins tighter than average
    score += 0.5 * (mean_residual - post_residual as f64);

    // Late in the stream, consolidate aggressively
    let progress = step_index as f64 / total_items as f64;
    score -= 10.0 * progress * (1.0 - post_residual as f64 / bin_capacity as f64);

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Prefer tight fits: reward small post_residual nonlinearly.
    let tightness = 1.0 - (post_residual as f64 / bin_capacity as f64);
    score -= 12.0 * tightness * tightness;

    // Penalize dead space that no future item can use.
    if post_residual > 0 && post_residual < 10 {
        score += 20.0; // tiny unusable sliver
    }

    // Lookahead: bonus if next item fits exactly in post_residual.
    if next_item_size > 0 {
        if next_item_size == post_residual {
            score -= 30.0; // perfect chain fit
        } else if next_item_size <= post_residual {
            score -= 8.0 * (next_item_size as f64 / post_residual as f64);
        } else {
            score += 5.0; // next item won't fit here anyway
        }
    }

    // Last-chance bin: strongly favor using it before opening a new bin.
    if fitting_bins_count == 1 && bin_residual < bin_capacity {
        score -= 25.0;
    }

    // Time horizon: later in stream, consolidate more aggressively.
    let progress = step_index as f64 / total_items.max(1) as f64;
    score -= 6.0 * progress * tightness;

    // Global state: many open bins with high mean residual -> prefer filling existing bins.
    if open_bins_count > 2 {
        score -= 0.5 * (mean_residual / bin_capacity as f64).min(1.0);
    }

    // New-bin candidate handling: opening a new bin is only attractive when
    // current item is large and no open bin fits well.
    let is_new_bin = bin_residual == bin_capacity;
    if is_new_bin {
        let no_good_fit = fitting_bins_count == 0 || (post_residual as f64) < 0.15 * bin_capacity as f64;
        if no_good_fit {
            score -= 15.0; // encourage fresh bin for large items
        } else {
            score += 40.0; // discourage wasting a fresh bin on a good existing fit
        }
    }

    // Mild penalty for very large item in nearly full bin (fragmentation risk).
    if item_size as f64 > 0.7 * bin_capacity as f64 && post_residual > 0 {
        score += 3.0;
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    let progress = if total_items > 0 { step_index as f64 / total_items as f64 } else { 0.0 };

    // Quadratic decay of post_residual value as stream progresses:
    // late in the stream, leftover space is worth less -> penalize large residuals more.
    let pr = post_residual as f64;
    let norm_pr = pr / bin_capacity as f64;
    let poly = norm_pr * norm_pr * (1.0 + progress) + norm_pr * (0.5 * progress);
    score += 40.0 * poly;

    // Reward tight fits: subtract a smooth function of post_residual that peaks near zero.
    let tight = (1.0 - norm_pr).max(0.0);
    score -= 30.0 * tight * tight * (1.0 + 0.5 * progress);

    // Last-chance bonus: if this is the only fitting bin, strongly favor using it.
    if fitting_bins_count == 1 {
        score -= 25.0 * (1.0 + progress);
    }

    // Lookahead coupling: if next item fits exactly in the post residual, reward;
    // if post residual is slightly too small for next item, penalize (dead space trap).
    if next_item_size > 0 {
        let nxt = next_item_size as f64;
        if pr >= nxt {
            let slack = (pr - nxt) / bin_capacity as f64;
            score -= 20.0 * (1.0 - slack) * (1.0 - slack);
        } else {
            let gap = (nxt - pr) / bin_capacity as f64;
            score += 15.0 * gap * (1.0 - progress);
        }
    }

    // Mild penalty for spreading across many bins when mean residual is high.
    let mean_norm = mean_residual / bin_capacity as f64;
    score += 5.0 * mean_norm * (open_bins_count as f64).ln().max(0.0) * (0.5 + 0.5 * progress);

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Base: prefer tight fits, but reward small post_residual non-linearly.
    let frac = post_residual as f64 / bin_capacity as f64;
    score += 12.0 * (frac * frac);

    // Harmonic class of post_residual: mod-10 buckets — residuals divisible by 10
    // are more reusable by typical item sizes, so reward them.
    if post_residual % 10 == 0 {
        score -= 3.0;
    } else {
        score += 2.0;
    }
    // Fine-grained classes: residuals that are multiples of 5 are semi-reusable.
    if post_residual % 5 == 0 {
        score -= 1.0;
    }

    // Integer-division thresholds: tiny dead space (< 10) is essentially dead.
    if post_residual < 10 && post_residual > 0 {
        score += 6.0;
    }

    // Lookahead coupling: if next item fits exactly in post_residual, big reward.
    if next_item_size > 0 {
        if next_item_size == post_residual {
            score -= 10.0;
        } else if next_item_size <= post_residual {
            let nxt_frac = (post_residual - next_item_size) as f64 / bin_capacity as f64;
            score -= 4.0 * (1.0 - nxt_frac * nxt_frac);
        } else {
            // Next item won't fit here; mild penalty proportional to overflow gap.
            score += 0.05 * ((next_item_size - post_residual) as f64);
        }
        // Harmonic pair: item + next divisible by capacity chunks (mod classes).
        let pair = item_size + next_item_size;
        if pair % 100 == 0 {
            score -= 6.0;
        } else if pair % 50 == 0 {
            score -= 3.0;
        }
    }

    // Last-chance bin: strongly favor using it rather than opening a new bin.
    if fitting_bins_count == 1 {
        score -= 8.0;
    } else if fitting_bins_count > 1 {
        score += 0.5 * (fitting_bins_count as f64 - 1.0);
    }

    // New-bin candidate handling: empty bin should only win when open bins are bad.
    if bin_residual == bin_capacity {
        // Base cost of opening a new bin, decaying with stream progress.
        let progress = step_index as f64 / total_items.max(1) as f64;
        score = 20.0 - 6.0 * progress;
        // If item fits nothing else, opening a bin is mandatory.
        if fitting_bins_count == 0 {
            score -= 50.0;
        }
        // If mean residual across open bins is large, opening new bins is wasteful.
        score += 0.4 * mean_residual;
        // Harmonic: if item_size class pairs well with common residuals, discourage new bin.
        if item_size % 10 == 0 {
            score += 4.0;
        }
    }

    // Slight pressure to consolidate when many bins are open.
    score += 0.02 * open_bins_count as f64;

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Strict dead-space avoidance: small unusable gaps are the worst outcome.
    if post_residual > 0 && post_residual < 10 {
        score += 40.0;
    } else if post_residual == 0 {
        // Perfect fit: strongly rewarded.
        score -= 25.0;
    } else {
        // Larger leftover space is mildly penalized relative to tight fits.
        score += 0.15 * (post_residual as f64).powf(0.5);
    }

    // Reward bins whose residual was already small (tight packing tendency).
    score += 0.05 * (bin_residual as f64);

    // Open-bin pressure: discourage spreading across many bins.
    if bin_residual != bin_capacity {
        score -= 2.0 * (open_bins_count as f64).ln().max(0.0);
    }

    // Last-chance bin: strongly favor using it before opening a new one.
    if fitting_bins_count == 1 && bin_residual != bin_capacity {
        score -= 15.0;
    }

    // Lookahead: if next item fits the post-residual, reward this placement.
    if next_item_size > 0 && post_residual >= next_item_size {
        score -= 6.0;
    }
    // If next item is almost the post-residual (near-perfect chain), extra reward.
    if next_item_size > 0 && post_residual >= next_item_size && post_residual - next_item_size < 10 {
        score -= 5.0;
    }
    // Penalize leaving a gap that the next item cannot use.
    if next_item_size > post_residual && post_residual > 0 {
        score += 8.0;
    }

    // New-bin candidate: only attractive when open bins are crowded or fit is poor.
    if bin_residual == bin_capacity {
        let pressure = mean_residual / bin_capacity as f64;
        if pressure < 0.35 || fitting_bins_count == 0 {
            score -= 12.0;
        } else {
            score += 10.0 + 10.0 * pressure;
        }
    }

    // Late-stream consolidation: prefer reusing bins as the stream nears its end.
    let progress = step_index as f64 / (total_items.max(1) as f64);
    if bin_residual != bin_capacity {
        score -= 4.0 * progress;
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Aggressive 2-step lookahead: reward when the next item fits the post-residual exactly.
    if next_item_size > 0 {
        if post_residual == next_item_size {
            score -= 60.0; // perfect chain: bin becomes exactly full after next item
        } else if post_residual >= next_item_size {
            let left = (post_residual - next_item_size) as f64;
            score -= 30.0 * (1.0 - left / bin_capacity as f64); // good chain, tighter is better
        } else {
            // next item cannot use this bin's leftover: penalize dead space
            score += 0.6 * (post_residual as f64 - next_item_size as f64).abs();
        }
    }

    // Penalize residuals far from mean (outliers create unusable space)
    score += 0.15 * ((post_residual as f64 - mean_residual).abs());

    // Last-chance bin: strongly favor using it to avoid opening a new bin
    if fitting_bins_count == 1 && bin_residual < bin_capacity {
        score -= 25.0;
    }

    // Prefer filling existing bins tightly over opening new ones
    if post_residual == 0 {
        score -= 40.0;
    }

    // Mild preference for opening new bins early in the stream (spread load)
    let progress = step_index as f64 / total_items.max(1) as f64;
    if bin_residual == bin_capacity {
        score += 10.0 * (1.0 - progress); // new bin more attractive early
        score -= 5.0 * progress;          // discourage new bins late
    }

    // Small bonus for compact bins relative to how many bins are open
    score -= 0.05 * open_bins_count as f64 * (1.0 - post_residual as f64 / bin_capacity as f64);

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let cap = bin_capacity as f64;
    let item = item_size as f64;
    let post = post_residual as f64;
    let mut score = post;

    // Tightness reward: fraction of the bin consumed by this item.
    let fill = item / cap;
    score -= 45.0 * fill * fill;

    // Dead-space penalty: small post-residuals that can't hold typical items.
    if post > 0.0 && post < 10.0 {
        score += 60.0 * (1.0 - post / 10.0);
    }

    // Lookahead: reward if the next item fits into the post residual.
    if next_item_size > 0 {
        let nxt = next_item_size as f64;
        if nxt <= post {
            // perfect chain: next item exactly consumes leftover
            let chain_fit = 1.0 - (post - nxt) / cap;
            score -= 30.0 * chain_fit;
        } else {
            // next item won't fit here; penalize proportionally to wasted space
            let progress = if total_items > 0 { step_index as f64 / total_items as f64 } else { 0.0 };
            score += 12.0 * (post / cap) * (0.5 + 0.5 * progress);
        }
    }

    // Last-chance bin: strongly favor using the only bin that fits.
    if fitting_bins_count == 1 {
        score -= 25.0;
    }

    // Congestion-aware: many open bins with slack -> prefer filling slack bins.
    if open_bins_count > 1 {
        let slack = (mean_residual - post).abs();
        score += 0.15 * slack;
        score -= 1.5 * (open_bins_count as f64).ln() * (post / cap);
    }

    // New-bin candidate: penalize opening a fresh bin unless item is huge
    // (nothing else would fit well) — big items should get fresh bins.
    if bin_residual == bin_capacity {
        let big = (item - 10.0) / 70.0; // 0..1
        score += 40.0 - 55.0 * big * big;
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let cap = bin_capacity as f64;
    let pr = post_residual as f64;
    let progress = step_index as f64 / (total_items.max(1) as f64);
    let fit = fitting_bins_count as f64;

    // Base: minimize wasted space, with mild convexity (quadratic coupling)
    let mut score = pr + 0.05 * (pr * pr) / cap;

    // Stream-progress coupling: early on, prefer tight fits more strongly
    // (bins opened early get reused longer); later, tolerate slack.
    let tightness = 1.0 - (pr / cap);
    score -= (1.0 + 2.0 * (1.0 - progress)) * tightness * tightness * 8.0;

    // Scarcity pressure: if this is the last fitting bin, reward using it
    if fitting_bins_count == 1 {
        score -= 15.0 * (1.0 - progress);
    } else {
        score += 0.5 * fit;
    }

    // Mean-residual coupling: penalize bins far below/above mean residual
    // (prefer bins whose residual matches the fleet average, smooth quadratic)
    let dev = pr - mean_residual;
    score += 0.02 * dev * dev;

    // Lookahead: penalize if post-residual can't fit the next item
    // (smoothly, since next_item_size == 0 at end)
    let nx = next_item_size as f64;
    let gap = (nx - pr).max(0.0);
    score += 0.1 * gap * gap / cap;

    // Mild penalty for leaving very small unusable slivers (dead space)
    let sliver = (pr / cap) * (1.0 - pr / cap);
    score -= 4.0 * sliver;

    // Open-bin count pressure: with many open bins, favor consolidation
    score += 0.3 * (open_bins_count as f64).ln() * (pr / cap);

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Perfect fit is always ideal.
    if post_residual == 0 {
        score -= 1000.0;
    }

    // Harmonic classes: partition post_residual into usability bands.
    // Dead space (very small residual) is worthless — penalize it heavily.
    if post_residual > 0 && post_residual <= 10 {
        score += 60.0;
    } else if post_residual <= 25 {
        score += 10.0;
    } else if post_residual <= 50 {
        score -= 15.0;
    } else {
        // Large residual left: flexible bin, reward proportionally.
        score -= 25.0;
    }

    // Modulo-arithmetic coupling: residuals that are multiples of common
    // small sizes (1,2,4,5,10) are more likely reusable by future items.
    let r = post_residual;
    if r > 0 && (r % 10 == 0 || r % 5 == 0) {
        score -= 8.0;
    }
    if r > 0 && r % 2 == 0 {
        score -= 2.0;
    }

    // Lookahead: if the next item fits exactly in the post residual,
    // this is a chained perfect fit — strongly reward.
    if next_item_size > 0 {
        if next_item_size == post_residual {
            score -= 120.0;
        } else if next_item_size < post_residual {
            let next_post = post_residual - next_item_size;
            if next_post <= 10 {
                score += 20.0; // creates new dead space after chain
            } else {
                score -= 12.0;
            }
        } else {
            // next item won't fit here anyway; residual value is its own.
            score += 3.0;
        }
    }

    // Last-chance bin: if this is the only bin that fits, avoid opening
    // a new bin unless the fit is terrible (huge dead space).
    if fitting_bins_count == 1 {
        score -= 30.0;
        if post_residual > 0 && post_residual <= 5 {
            score += 25.0; // but not if it wastes nearly everything
        }
    }

    // New-bin candidate handling: an empty bin has maximal residual.
    // Prefer it only when no open bin offers a decent fit.
    if bin_residual == bin_capacity {
        // Neutral base; slight penalty so decent existing fits win.
        score += 5.0;
        if fitting_bins_count == 0 {
            score -= 200.0;
        }
        if next_item_size > 0 && next_item_size >= item_size {
            score -= 10.0; // good for pairing large items together
        }
    }

    // Progress-based tightening: late in the stream, minimize bin count
    // aggressively; early, keep flexibility.
    let progress = step_index as f64 / (total_items.max(1) as f64);
    score -= 10.0 * progress;

    // Mean residual coupling: if this bin's residual is far below the mean,
    // it's already fragmented; penalize using it for loose fits.
    let dev = mean_residual - bin_residual as f64;
    score += 0.15 * dev;

    // Many open bins: encourage consolidation into tight fits.
    if open_bins_count > 8 {
        score -= 0.5 * (post_residual as f64);
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Strict dead-space avoidance: small unusable gaps (< 10) are the worst outcome.
    if post_residual > 0 && post_residual < 10 {
        score += 60.0;
    } else if post_residual == 0 {
        // Perfect fit: strongly reward closing the bin.
        score -= 40.0;
    } else {
        // Larger leftover gaps are progressively less harmful.
        score -= (post_residual as f64 / bin_capacity as f64) * 12.0;
    }

    // Reward fitting into the bin if it's the last chance before opening a new bin.
    if fitting_bins_count == 1 && bin_residual != bin_capacity {
        score -= 25.0;
    }

    // Open-bin pressure: with many open bins, prefer consolidating into existing bins.
    let open_pressure = open_bins_count as f64 / (open_bins_count as f64 + 5.0);
    if bin_residual != bin_capacity {
        score -= open_pressure * 15.0;
    } else {
        // Opening a new bin is penalized more as open_bins_count grows.
        score += open_pressure * 20.0;
    }

    // Lookahead: if the next item fits in the post residual, reward this placement.
    if next_item_size > 0 && post_residual >= next_item_size {
        score -= 18.0;
    }
    // If next item nearly fits (small shortfall), mild penalty for blocking it.
    if next_item_size > 0 && post_residual < next_item_size && post_residual + 10 >= next_item_size {
        score += 8.0;
    }

    // Mean residual coupling: prefer bins below mean residual (tighter bins) when many bins are open.
    if bin_residual != bin_capacity {
        let dev = mean_residual - bin_residual as f64;
        score -= dev * 0.3 * open_pressure;
    }

    // Early in the stream, be slightly more willing to open bins (build diversity).
    let progress = step_index as f64 / total_items.max(1) as f64;
    if bin_residual == bin_capacity {
        score -= (1.0 - progress) * 10.0;
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Aggressive 2-step lookahead: reward exact match with next item size.
    if next_item_size > 0 {
        let post = post_residual as f64;
        let nxt = next_item_size as f64;

        if post == nxt {
            // Perfect 2-chain: heavily reward.
            score -= 60.0;
        } else if post > nxt {
            // Next item still fits after this placement: mild reward,
            // stronger the closer post_residual is to next_item_size.
            let gap = post - nxt;
            score -= 25.0 - 0.3 * gap;
        } else {
            // Next item won't fit: penalize dead space relative to how
            // far off we are, scaled by how small the leftover is.
            let dead = nxt - post;
            score += 0.5 * dead;
            if post < 10.0 {
                // Nearly unusable sliver.
                score += 15.0;
            }
        }
    }

    // Compare post_residual against the mean residual of open bins:
    // leaving this bin near the average keeps flexibility.
    let post = post_residual as f64;
    let dev = post - mean_residual;
    score += 0.15 * dev.abs();

    // Last-chance bin: strongly favor using it before opening a new bin.
    if fitting_bins_count == 1 && bin_residual < bin_capacity {
        score -= 40.0;
    }

    // Late in the stream, prefer tight packing (small post_residual).
    let progress = step_index as f64 / total_items as f64;
    score -= progress * (bin_capacity - post_residual) as f64 * 0.2;

    // Discourage opening new bins when a decent fit exists in an open bin.
    if bin_residual == bin_capacity {
        // New-bin candidate: penalize unless post_residual would be tiny.
        score += 10.0;
        if next_item_size > 0 && post_residual >= next_item_size {
            score -= 5.0;
        }
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Reward tight fits strongly: post_residual near 0 is best.
    let tightness = 1.0 - (post_residual as f64) / (bin_capacity as f64);
    score -= 30.0 * tightness * tightness;

    // Penalize dead space that no future item can plausibly use.
    // Smallest plausible item ~ 1, but weight by how "orphaned" the residual is.
    if post_residual > 0 {
        let orphan = (post_residual as f64) / (bin_capacity as f64);
        score += 12.0 * orphan * orphan;
    }

    // Perfect fit gets a big bonus.
    if post_residual == 0 {
        score -= 25.0;
    }

    // Lookahead coupling: if the next item fits exactly into the post residual,
    // this placement is doubly valuable.
    if next_item_size > 0 {
        if post_residual == next_item_size {
            score -= 20.0;
        } else if post_residual >= next_item_size {
            // Next item still fits: mild reward proportional to leftover after it.
            let two_step_left = post_residual - next_item_size;
            score -= 8.0 * (1.0 - two_step_left as f64 / bin_capacity as f64);
        } else {
            // Next item will NOT fit here: penalize leaving awkward residual
            // that is smaller than the next item (wasted space).
            if post_residual < next_item_size {
                score += 6.0 * (1.0 - post_residual as f64 / next_item_size.max(1) as f64);
            }
        }
    }

    // Last-chance bonus: if this is the only bin that fits the item,
    // strongly prefer using it over opening a new bin.
    if fitting_bins_count == 1 && bin_residual >= item_size {
        score -= 15.0;
    }

    // New-bin candidate logic: an empty bin should only win when open bins
    // are badly fragmented. Penalize opening a new bin when open bins exist
    // and mean residual is healthy.
    if bin_residual == bin_capacity {
        if open_bins_count > 0 {
            // Compare this fresh capacity to the mean residual of open bins.
            // If mean residual comfortably exceeds item, opening new bin is wasteful.
            let waste = (mean_residual - item_size as f64).max(0.0);
            score += 10.0 + 0.5 * waste + 0.3 * open_bins_count as f64;
            // Early in the stream, be more generous with new bins (build capacity).
            let progress = if total_items > 0 { step_index as f64 / total_items as f64 } else { 0.0 };
            score -= 8.0 * (1.0 - progress);
        } else {
            // No open bins: always open the first bin.
            score -= 100.0;
        }
    }

    // Mild pressure to consolidate: bins with residual close to mean_residual
    // are "typical" and preferred, balancing load across bins.
    if bin_residual != bin_capacity {
        let dev = (bin_residual as f64 - mean_residual).abs();
        score += 0.05 * dev;
    }

    // Late-stream conservatism: as the stream ends, avoid leaving many
    // nearly-empty open bins; favor bins whose post residual stays useful.
    let progress = if total_items > 0 { step_index as f64 / total_items as f64 } else { 0.0 };
    if progress > 0.7 {
        score += 5.0 * progress * (post_residual as f64 / bin_capacity as f64);
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let cap = bin_capacity as f64;
    let pr = post_residual as f64;
    let it = item_size as f64;
    let progress = step_index as f64 / total_items.max(1) as f64;
    let norm_pr = pr / cap;
    let norm_it = it / cap;

    // Smooth non-linear polynomial coupling of post_residual with stream progress
    let mut score = norm_pr;

    // Quadratic/cubic coupling: dead space penalized more later in the stream
    let coupling = norm_pr * norm_pr * (0.5 + 1.5 * progress)
                 + norm_pr * norm_pr * norm_pr * (1.0 + 2.0 * progress);
    score += coupling * cap;

    // Reward tight fits (small post_residual) with a smooth saturating bonus
    let tight = (1.0 - norm_pr).powi(3);
    score -= 12.0 * tight * (1.0 + 0.5 * progress);

    // Lookahead: if next item fits into post_residual, reward this placement smoothly
    if next_item_size > 0 {
        let nx = next_item_size as f64;
        let fits_next = (nx / pr.max(1.0)).min(1.0);
        score -= 8.0 * fits_next * fits_next;
    }

    // Last-chance bin: strongly favor using it (smooth exponential pressure)
    if fitting_bins_count == 1 {
        score -= 15.0 * (1.0 + progress);
    } else {
        score += 2.0 * (fitting_bins_count as f64).ln().max(0.0);
    }

    // Mean residual interaction: prefer bins close to the mean (balanced packing)
    let dev = (pr - mean_residual) / cap;
    score += 4.0 * dev * dev;

    // New-bin candidate: smooth penalty that relaxes early and tightens late
    if bin_residual == bin_capacity {
        score += 6.0 + 18.0 * progress * progress;
    }

    // Mild preference for consolidating into fewer bins
    score += 0.3 * (open_bins_count as f64) * norm_pr;

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let cap = bin_capacity as f64;
    let post = post_residual as f64;
    let mut score = post;

    // --- Harmonic class of post_residual (integer division thresholds) ---
    // Dead space classes: tiny residue (1..=5) is nearly worthless, small (6..=15)
    // is bad, medium (16..=35) acceptable, large is fine.
    let cls = post_residual / 5; // harmonic bucket of width 5
    let dead_penalty = match post_residual {
        0 => -60.0,                       // perfect fit: huge reward
        1..=5 => 45.0 - cls as f64,       // worst dead space
        6..=15 => 25.0 - cls as f64,      // bad
        16..=35 => 8.0 - cls as f64,      // mild
        _ => 0.0,                          // roomy residual, fine
    };
    score += dead_penalty;

    // --- Modulo arithmetic on post_residual vs common size classes ---
    // Sizes cluster mod 10; residues 0 and 5 are "harmonic" (likely reusable).
    let r = post_residual % 10;
    if post_residual > 0 {
        score += match r {
            0 => -6.0,
            5 => -3.0,
            _ => (r as f64) * 0.4,
        };
    }

    // --- Lookahead pairing: does next_item_size fit into post_residual? ---
    if next_item_size > 0 && post_residual > 0 {
        if next_item_size == post_residual {
            score -= 35.0; // perfect two-item packing: strongly favor
        } else if next_item_size <= post_residual {
            // fraction of residual consumed by next item
            let frac = next_item_size as f64 / post;
            score -= 18.0 * frac;
            // harmonic coupling: next item leaves again a multiple-of-10 residue
            let nr = (post_residual - next_item_size) % 10;
            if nr == 0 { score -= 6.0; }
        } else {
            // next item cannot use this residual: penalize by overflow gap
            let gap = (next_item_size - post_residual) as f64;
            score += (gap / 40.0).min(10.0);
        }
    }

    // --- Last-chance bin before opening a new one ---
    if fitting_bins_count == 1 && bin_residual != bin_capacity {
        score -= 12.0;
    }

    // --- Stream progression: be greedier (tighter fits) early, more
    //     conservative about residual quality late ---
    let prog = if total_items > 0 { step_index as f64 / total_items as f64 } else { 0.0 };
    score += dead_penalty * 0.5 * prog;

    // --- Crowd pressure: many open bins -> prefer filling existing ones ---
    score -= (open_bins_count as f64).ln().max(0.0) * 2.0;

    // --- Mean residual coupling: if this bin is far below mean residual it is
    //     the "driest" bin, favor using it ---
    score -= (mean_residual - post).max(0.0) * 0.15;

    // --- New empty bin candidate: must be strictly worse than any reasonable
    //     reuse, unless reuse would create tiny dead space while a fresh bin
    //     could host the lookahead item better ---
    if bin_residual == bin_capacity {
        let fresh_base = cap * 0.55; // inherent cost of opening a bin
        let mut fresh = fresh_base;
        if next_item_size > 0 {
            // fresh bin can always host the next item: small discount
            fresh -= 8.0;
            if next_item_size >= item_size {
                fresh -= 6.0;
            }
        }
        if fitting_bins_count == 0 { fresh -= 30.0; }
        // late in stream, avoid spawning bins with little work left
        fresh += prog * 30.0;
        score = fresh + post; // post = 100 for empty bin, keeps ordering sane
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Strict dead-space avoidance: penalize small unusable gaps harshly.
    if post_residual > 0 && post_residual < 10 {
        score += 60.0;
    } else if post_residual < 20 {
        score += 25.0 * (1.0 - post_residual as f64 / 20.0);
    }

    // Reward perfect and near-perfect fits.
    if post_residual == 0 {
        score -= 100.0;
    }

    // Last-chance bin: strongly favor using it before opening a new one.
    if fitting_bins_count == 1 && bin_residual != bin_capacity {
        score -= 40.0;
    }

    // Pressure from many open bins: discourage spreading, but keep new-bin
    // option viable when fit is poor (post_residual large).
    let open_pressure = open_bins_count as f64 * 0.5;
    if bin_residual == bin_capacity {
        // New-bin candidate: baseline slightly above a good fit, below a bad one.
        score += open_pressure + 5.0;
        if next_item_size > 0 && next_item_size <= bin_capacity {
            score -= 3.0; // new bin useful for the lookahead item
        }
    } else {
        score += open_pressure * 0.3;
    }

    // Lookahead synergy: prefer bins whose post_residual can host next item.
    if next_item_size > 0 && post_residual >= next_item_size {
        score -= 8.0;
    } else if next_item_size > 0 && post_residual > 0 {
        score += 5.0;
    }

    // Slight preference for tight residual relative to mean residual.
    score += (post_residual as f64 - mean_residual) * 0.2;

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Perfect 2-step match: post_residual exactly equals next item size.
    if next_item_size > 0 && post_residual == next_item_size {
        score -= 1000.0;
    }
    // Near-perfect lookahead match: next item fits with tiny leftover.
    else if next_item_size > 0 && post_residual >= next_item_size {
        let slack = (post_residual - next_item_size) as f64;
        score -= 300.0 - slack * 2.5;
    }
    // Next item cannot use the leftover: penalize dead space proportional to how
    // far below the next item the residual falls.
    else if next_item_size > 0 && post_residual < next_item_size {
        let gap = (next_item_size - post_residual) as f64;
        score += gap * 1.5;
    }

    // Penalize residuals that are too small to ever be useful (below min item size).
    if post_residual < 10 && post_residual > 0 {
        score += 80.0;
    }

    // Last-chance bin: strongly favor using it to avoid opening a new bin.
    if fitting_bins_count == 1 && bin_residual != bin_capacity {
        score -= 250.0;
    }

    // Prefer bins tighter than the mean residual (compact packing).
    score += (post_residual as f64 - mean_residual) * 0.8;

    // Early in the stream, prefer tighter fits to build dense bins.
    let progress = step_index as f64 / (total_items.max(1) as f64);
    score *= 1.0 + 0.3 * (1.0 - progress);

    // Mild penalty for the brand-new empty bin candidate, so it's only chosen
    // when open bins score very badly (poor fits).
    if bin_residual == bin_capacity {
        score += 60.0;
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Tight fit bonus: reward small post-residual relative to capacity.
    let tightness = 1.0 - (post_residual as f64) / (bin_capacity as f64);
    score -= 2.5 * tightness * (item_size as f64);

    // Lookahead: penalize leaving residual that next item could have used,
    // reward residual that next item fits into nicely.
    if next_item_size > 0 {
        if post_residual >= next_item_size {
            // next item can still fit here -> good chain
            let chain_waste = post_residual - next_item_size;
            score -= 0.6 * (chain_waste as f64).min(30.0);
        } else {
            // post-residual becomes dead space for the lookahead item
            let dead = post_residual as f64;
            score += 0.35 * dead;
            // extra penalty if next item barely misses fitting
            let miss = (next_item_size - post_residual) as f64;
            if miss <= 10.0 {
                score += 1.2 * (10.0 - miss);
            }
        }
    }

    // Last-chance bin: strongly favor using the only bin that fits the item.
    if fitting_bins_count == 1 && bin_residual >= item_size && bin_residual != bin_capacity {
        score -= 40.0;
    }

    // New-bin candidate handling: opening a fresh bin is wasteful early and
    // when the item fits well somewhere; encourage it only for large items
    // or when existing residuals are poor.
    let is_new_bin = bin_residual == bin_capacity;
    if is_new_bin {
        let progress = step_index as f64 / (total_items.max(1) as f64);
        let fill_frac = (item_size as f64) / (bin_capacity as f64);
        // base cost of a new bin, discounted for large items
        let new_bin_cost = 55.0 - 40.0 * fill_frac;
        // late in stream, prefer consolidating into open bins
        let late_penalty = 25.0 * progress;
        // many open bins with low residuals -> opening new bin less attractive
        let crowd = 0.5 * (open_bins_count as f64).min(20.0);
        score += new_bin_cost + late_penalty + crowd;
        // if mean residual is large, new bin is relatively fine
        score -= 0.2 * mean_residual.min(60.0);
    }

    // Mild preference for bins whose residual deviates favorably from mean
    // (pack into emptier bins to consolidate fullness elsewhere).
    score += 0.15 * (bin_residual as f64 - mean_residual);

    // Fragmentation guard: penalize leaving tiny unusable residuals
    if post_residual > 0 && post_residual < 10 {
        score += 8.0 * (10 - post_residual) as f64;
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let progress = step_index as f64 / (total_items.max(1) as f64);
    let cap = bin_capacity as f64;
    let pr = post_residual as f64;
    let norm_pr = pr / cap;

    // Base: prefer tight fits (small post residual), with smooth polynomial shaping
    let mut score = norm_pr * (1.0 + 2.0 * norm_pr * norm_pr);

    // Smooth coupling: waste penalized more as stream progresses
    score += 3.0 * progress * norm_pr * norm_pr;

    // Interaction with mean residual: if this bin's post residual is below mean, reward
    let mean_norm = mean_residual / cap;
    score -= 1.5 * (mean_norm - norm_pr) * (1.0 - progress);

    // Last-chance bonus: strongly favor using the only fitting bin
    if fitting_bins_count == 1 {
        score -= 2.0 + 2.0 * progress;
    }

    // Lookahead: if next item fits exactly in post residual, reward strongly (smooth kernel)
    if next_item_size > 0 {
        let ns = next_item_size as f64;
        if ns <= pr {
            let fit_quality = 1.0 - ((pr - ns) / cap).abs();
            score -= 1.8 * fit_quality * fit_quality;
        } else {
            let gap = (ns - pr) / cap;
            score += 1.2 * gap * gap;
        }
    }

    // Slight penalty for many open bins, encouraging consolidation
    score += 0.05 * (open_bins_count as f64).ln().max(0.0);

    // New-bin candidate: keep it slightly unattractive unless residuals are all bad
    if bin_residual == bin_capacity {
        score += 0.8 + 2.0 * mean_norm;
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // --- Harmonic class of the post-residual (dead-space taxonomy) ---
    // Classes: 0 = perfect closure, 1 = micro-waste, 2 = small, 3 = medium, 4 = large, 5 = huge.
    let pr = post_residual;
    let class: u32 = if pr == 0 {
        0
    } else if pr <= 10 {
        1
    } else if pr <= 20 {
        2
    } else if pr <= 30 {
        3
    } else if pr <= 50 {
        4
    } else {
        5
    };
    // Non-linear class penalty: quadratic in class index to punish deep classes.
    score += (class * class) as f64 * 1.5;

    // --- Integer-division harmonic: how many "unit cells" of 10 fit the leftover ---
    let cells = pr / 10;
    score -= cells as f64 * 2.0; // mildly reward reusable leftover structure
    score += (pr % 10) as f64 * 0.25; // penalize ragged non-aligned waste

    // --- Lookahead coupling: does the next item nest into the post-residual? ---
    if next_item_size > 0 && next_item_size <= pr {
        let nested_leftover = pr - next_item_size;
        // Reward nesting, stronger when it closes the bin almost perfectly.
        score -= 18.0 - nested_leftover as f64 * 0.35;
        if nested_leftover == 0 {
            score -= 12.0; // perfect two-item closure
        }
    } else if next_item_size > pr && pr > 0 && pr <= 10 {
        // leftover too small for anything: pure dead space
        score += 4.0;
    }

    // --- Last-chance bin: if this is the only bin that fits, strongly favor it ---
    if fitting_bins_count == 1 && bin_residual != bin_capacity {
        score -= 15.0;
    }

    // --- New-bin candidate handling ---
    if bin_residual == bin_capacity {
        // Base aversion to opening new bins, scaled by existing slack in the system.
        score += 6.0 + mean_residual * 0.06 + open_bins_count as f64 * 0.5;
        // If next item is large, a fresh bin may be strategically valuable.
        if next_item_size >= 50 {
            score -= 4.0;
        }
    }

    // --- Stream progression: tighten criteria late in the stream ---
    let t = step_index as f64 / (total_items.max(1) as f64);
    score *= 1.0 + 0.25 * t;

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Strict dead-space avoidance: residuals in (0,10) are unusable for any item.
    if post_residual > 0 && post_residual < 10 {
        score += 60.0;
    }
    // Perfect fit is heavily rewarded.
    if post_residual == 0 {
        score -= 40.0;
    }

    // Reward tight fits: small post_residual relative to capacity.
    let tightness = 1.0 - (post_residual as f64 / bin_capacity as f64);
    score -= 25.0 * tightness;

    // Pressure from number of open bins: prefer consolidating into existing bins
    // when many bins are open; encourage new-bin use when few bins are open.
    let progress = step_index as f64 / (total_items.max(1) as f64);
    score += (open_bins_count as f64).ln().max(0.0) * 4.0 * (1.0 - progress);

    // Last-chance bin: if this is the only fitting bin, strongly favor using it
    // over opening a new bin (unless post_residual is dead space).
    if fitting_bins_count == 1 && bin_residual != bin_capacity {
        score -= 30.0;
    }

    // New-bin candidate handling: opening a new bin is only attractive when the
    // item would leave large dead space in every existing bin or mean residual is low.
    if bin_residual == bin_capacity {
        let dead_space_elsewhere = if post_residual as f64 > mean_residual { 1.0 } else { 0.0 };
        score += 15.0 - 20.0 * dead_space_elsewhere - 5.0 * (mean_residual / bin_capacity as f64);
    }

    // Lookahead: if next item can use this bin's post-residual, reward placement here.
    if next_item_size > 0 && post_residual >= next_item_size {
        score -= 12.0;
    }
    // Penalize if post_residual is too small for the next item (fragmentation).
    if next_item_size > 0 && post_residual > 0 && post_residual < next_item_size {
        score += 8.0;
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Base: prefer tight fit (small post_residual), but scale by fill ratio
    let fill_ratio = item_size as f64 / bin_capacity as f64;
    score -= 40.0 * fill_ratio;

    // 2-step lookahead: reward if the next item fits exactly in post_residual
    if next_item_size > 0 {
        if post_residual == next_item_size {
            // Perfect chain: this bin becomes exactly reusable
            score -= 60.0;
        } else if post_residual >= next_item_size {
            // Next item fits: good, reward proportionally to how well it fits
            let slack = (post_residual - next_item_size) as f64;
            score -= 30.0 - slack.min(30.0);
        } else {
            // Next item does NOT fit in this bin's remainder: dead space penalty
            let gap = (next_item_size - post_residual) as f64;
            score += 0.5 * gap;
        }
    }

    // Penalize creating unusable dead space (small odd remainders)
    if post_residual > 0 && post_residual < 10 {
        score += 25.0;
    }

    // Last-chance bin: strongly favor using it to avoid opening a new bin
    if fitting_bins_count == 1 && bin_residual != bin_capacity {
        score -= 45.0;
    }

    // New-bin candidate handling: make it attractive only when open bins fit poorly
    if bin_residual == bin_capacity {
        // New bin baseline: neutral-ish, penalize when many bins already fit well
        if fitting_bins_count > 0 {
            let best_open_post = if post_residual >= item_size { post_residual - item_size } else { post_residual };
            let _ = best_open_post;
            score += 20.0 + 5.0 * (fitting_bins_count as f64).sqrt();
        } else {
            score -= 10.0; // no open bin fits: new bin is right
        }
        // Late in stream, prefer consolidating into open bins
        let progress = step_index as f64 / total_items.max(1) as f64;
        score += 15.0 * progress;
    }

    // Relative to mean residual: prefer bins with residual below mean (tighter bins)
    score -= 0.3 * (mean_residual - bin_residual as f64);

    // Prefer using more-occupied bins among many open bins
    score += 2.0 * (open_bins_count as f64).log2();

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Reward tight fits (low post residual) with a non-linear bonus.
    let tightness = 1.0 - (post_residual as f64) / (bin_capacity as f64);
    score -= 40.0 * tightness * tightness;

    // Penalize dead space that no plausible future item can use:
    // residuals below the minimum item size are pure waste.
    if post_residual < 10 && post_residual > 0 {
        score += 25.0;
    }

    // Lookahead coupling: if the next item exactly fits the post residual,
    // strongly favor this bin (perfect chaining).
    if next_item_size > 0 {
        if next_item_size == post_residual {
            score -= 60.0;
        } else if next_item_size <= post_residual {
            // partial chain bonus, decaying with leftover after next item
            let chain_left = post_residual - next_item_size;
            score -= 20.0 * (1.0 - chain_left as f64 / bin_capacity as f64);
        } else {
            // next item cannot use this bin's leftover: mild penalty,
            // worse when the leftover is large (wasted capacity).
            score += 8.0 * (next_item_size - post_residual) as f64 / 100.0;
        }
    }

    // Last-chance logic: if this is the only bin that can fit the item,
    // strongly prefer using it over opening a new bin.
    if fitting_bins_count == 1 && bin_residual < bin_capacity {
        score -= 45.0;
    }

    // When many bins are open, consolidate; when few are open, new bins
    // are cheaper so soften the waste penalty on the empty-bin candidate.
    let pressure = (open_bins_count as f64).ln() + 1.0;
    score += 6.0 * pressure * (post_residual as f64 / bin_capacity as f64);

    // Time horizon: late in the stream, avoid opening new bins
    // (leftover space in a fresh bin likely never gets used).
    let progress = if total_items > 0 { step_index as f64 / total_items as f64 } else { 0.0 };
    if bin_residual == bin_capacity {
        // new-bin candidate: base penalty grows with progress and open bins
        score += 30.0 + 50.0 * progress + 2.0 * open_bins_count as f64;
    } else {
        // existing bin: small late-stream bonus for reusing space
        score -= 10.0 * progress;
    }

    // Deviation from mean residual: prefer bins that are either much fuller
    // or keep residual near the stream's typical usable size.
    let dev = (bin_residual as f64 - mean_residual).abs();
    score += 0.05 * dev;

    // Prefer filling bins whose residual is close to the item (minimal slack).
    let slack = (bin_residual - item_size) as f64;
    score += 0.15 * slack;

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let progress = if total_items > 0 { step_index as f64 / total_items as f64 } else { 0.0 };
    let cap = bin_capacity as f64;
    let post = post_residual as f64;
    let post_norm = post / cap;

    // Base: prefer tight fits (small post_residual), with non-linear sharpening.
    let mut score = post_norm * (1.0 + 2.0 * post_norm * post_norm);

    // Smooth polynomial coupling of post_residual with stream progress:
    // later in the stream, dead space matters more.
    score += 3.0 * post_norm * post_norm * progress * (1.0 - progress + 0.25);

    // Reward bins whose residual aligns with the lookahead item (k=2 lookahead).
    if next_item_size > 0 {
        let nxt = next_item_size as f64;
        let gap = ((post - nxt) / cap).abs();
        score -= 1.5 * (1.0 - gap.min(1.0)) * (1.0 - progress);
    }

    // Last-chance bonus: if this is the only fitting bin, strongly favor using it.
    if fitting_bins_count == 1 && bin_residual != bin_capacity {
        score -= 4.0 * (1.0 + progress);
    }

    // Penalize spreading across many open bins mildly; encourage consolidation.
    score += 0.05 * open_bins_count as f64 * post_norm;

    // Discourage opening a new bin unless the item is large relative to capacity
    // (i.e., placing into an existing bin would leave a large awkward residual).
    let is_new_bin = bin_residual == bin_capacity;
    if is_new_bin {
        let fill = item_size as f64 / cap;
        // new bin attractive only when item is big and few bins fit it
        let pressure = if fitting_bins_count > 0 { 1.0 / (1.0 + fitting_bins_count as f64) } else { 1.0 };
        score += 2.5 * (1.0 - fill) * (1.0 + progress) - 2.0 * pressure * fill;
    } else {
        // Favor bins tighter than the mean residual (good fits).
        let mean_norm = mean_residual / cap;
        score += 0.8 * (post_norm - mean_norm);
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Harmonic classes: bins whose post_residual lies in "useful" residue classes
    // (multiples of small denominators) are more likely to absorb future items.
    let cap = bin_capacity as f64;
    let post = post_residual as f64;

    // Dead-space penalty grows super-linearly for small, awkward residuals.
    if post_residual > 0 {
        let awkward = (post_residual % 10 == 0) as f64; // exact multiples are "clean"
        score -= 12.0 * awkward;
        // Penalize residuals in dead zones (1..10) heavily: almost nothing fits.
        if post_residual < 10 {
            score += 40.0 + 4.0 * (10 - post_residual) as f64;
        }
    } else {
        // Perfect fit: strong reward.
        score -= 60.0;
    }

    // Harmonic residue-class bonus: post_residual divisible by 20/25/50 pairs
    // well with common item sizes.
    let harmonic = match post_residual % 50 {
        0 => 3.0,
        _ => match post_residual % 25 {
            0 => 2.0,
            _ => match post_residual % 20 {
                0 => 1.5,
                _ => match post_residual % 10 {
                    0 => 1.0,
                    _ => 0.0,
                },
            },
        },
    };
    score -= 6.0 * harmonic;

    // Lookahead coupling: reward when next_item_size fits exactly or harmonically.
    if next_item_size > 0 {
        if next_item_size == post_residual {
            score -= 35.0; // exact lookahead fit
        } else if post_residual >= next_item_size {
            let leftover = post_residual - next_item_size;
            score -= 10.0 * ((leftover % 10 == 0) as f64);
            if leftover < 10 {
                score += 15.0; // leaves a dead sliver after the lookahead item
            }
        } else {
            score += 8.0; // lookahead item cannot follow in this bin
        }
    }

    // Last-chance bin: strongly prefer using it before opening a new bin.
    if fitting_bins_count == 1 && bin_residual < bin_capacity {
        score -= 25.0;
    }

    // New-bin candidate: it should only win when open bins are genuinely bad.
    if bin_residual == bin_capacity {
        // Base new-bin score = full capacity; add mild pressure so that decent
        // fits in open bins beat it, but terrible fits do not.
        score += 10.0 * (open_bins_count as f64).sqrt();
        // Late in the stream, discourage proliferation of new bins.
        let progress = step_index as f64 / total_items.max(1) as f64;
        score += 30.0 * progress;
    } else {
        // Tightness bonus: prefer fullest bins (small residual).
        score -= 5.0 * (1.0 - bin_residual as f64 / cap);
        // Prefer bins below the mean residual (filling emptier ones keeps balance).
        if (bin_residual as f64) > mean_residual {
            score += 3.0;
        }
    }

    // Item-size harmonic classes: large items (>=50) benefit from tight bins.
    if item_size >= 50 {
        score -= 4.0 * (1.0 - post_residual / bin_capacity.max(1) as f64);
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Strict dead-space avoidance: small unusable gaps are heavily penalized.
    let dead_threshold = 10u32;
    if post_residual > 0 && post_residual < dead_threshold {
        score += (dead_threshold - post_residual) as f64 * 12.0;
    }
    // Perfect fit gets a large reward.
    if post_residual == 0 {
        score -= 40.0;
    }

    // Reward residual that could still fit a typical future item.
    if post_residual >= 20 {
        score -= 6.0;
    }

    // Lookahead: if the next item fits exactly in the post-residual, reward strongly.
    if next_item_size > 0 && post_residual >= next_item_size && post_residual - next_item_size < 10 {
        score -= 15.0;
    }
    // Penalize if next item cannot fit in post residual (wasted capacity for lookahead).
    if next_item_size > post_residual && post_residual > 0 {
        score += 5.0;
    }

    // Last-chance bin: strongly favor using it to avoid opening a new bin.
    if fitting_bins_count == 1 && bin_residual != bin_capacity {
        score -= 20.0;
    }

    // Open-bin pressure: with many open bins, discourage opening new ones.
    let progress = step_index as f64 / (total_items.max(1) as f64);
    if bin_residual == bin_capacity {
        // New-bin candidate: penalize more when many bins are open or late in stream.
        score += 10.0 + 2.0 * open_bins_count as f64 + 20.0 * progress;
    } else {
        // Slight preference for bins below mean residual (keeps bins balanced).
        if (bin_residual as f64) < mean_residual {
            score -= 3.0;
        }
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Strongly prefer tight fits: exact fill is ideal.
    if post_residual == 0 {
        score -= 1000.0;
    }

    // 2-step lookahead: reward bins whose post_residual can host the next item.
    if next_item_size > 0 {
        if post_residual >= next_item_size {
            // Slack left over that the next item can still use.
            let chain_slack = (post_residual - next_item_size) as f64;
            score -= 40.0 - 0.5 * chain_slack.min(40.0);
        } else {
            // Leftover dead space the next item cannot use: penalize,
            // worse when the leftover is tiny (unusable) but nonzero.
            let dead = post_residual as f64;
            let unusable = dead / next_item_size as f64;
            score += 15.0 + 25.0 * (1.0 - unusable.min(1.0));
        }
        // Perfect two-item chain fill is excellent.
        if post_residual == next_item_size {
            score -= 60.0;
        }
    } else {
        // Last item: pure best-fit behavior.
        score -= 30.0;
    }

    // Compare fit quality relative to the mean residual across open bins.
    // A residual much larger than the mean means this bin is roomy; placing
    // a small item there wastes its space. Prefer below-mean-residual bins.
    let fit_gap = mean_residual - post_residual as f64;
    score += 0.6 * fit_gap.max(0.0) - 0.2 * (-fit_gap).max(0.0);

    // Last-chance bonus: if this is the only bin that fits, avoid opening a new bin
    // unless the fit is terrible.
    if fitting_bins_count == 1 {
        score -= 25.0;
        // But if it would strand a large dead space, soften the bonus.
        if post_residual > 0 && post_residual < 10 {
            score += 20.0;
        }
    }

    // New-bin candidate handling: an empty bin has huge residual, so its raw
    // score is already high; add a mild penalty so we only open new bins when
    // no open bin gives a decent fit.
    if bin_residual == bin_capacity {
        let progress = if total_items > 0 { step_index as f64 / total_items as f64 } else { 0.0 };
        score += 35.0 + 30.0 * progress;
        // If next item is large and this bin is empty, opening fresh is fine.
        if next_item_size > 0 && next_item_size >= post_residual {
            score -= 45.0;
        }
    }

    // Mild penalty on wasting large items in near-full bins handled by post_residual itself.
    // Slight normalization by item size: bigger items tolerate more slack.
    score -= 0.05 * item_size as f64;

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Strong best-fit preference: exact or near-exact fits.
    if post_residual == 0 {
        score -= 1000.0;
    } else {
        // Reward tight fits non-linearly (post_residual small => big bonus).
        let tightness = 1.0 / (post_residual as f64 + 1.0);
        score -= 40.0 * tightness.sqrt();
        // Penalize large unusable dead space relative to capacity.
        let waste_ratio = post_residual as f64 / bin_capacity as f64;
        score += 60.0 * waste_ratio * waste_ratio;
    }

    // Lookahead: if the next item fits in the post-residual, favor this bin.
    if next_item_size > 0 && post_residual >= next_item_size {
        score -= 30.0 + 0.5 * next_item_size as f64;
    } else if next_item_size > 0 {
        // Next item won't fit here after placement: mild penalty scaled by gap.
        let gap = next_item_size as f64 - post_residual as f64;
        score += 0.3 * gap;
    }

    // Last-chance bin: strongly prefer using the only bin that fits.
    if fitting_bins_count == 1 && bin_residual >= item_size {
        score -= 80.0;
    }

    // Prefer fuller bins (smaller residual) slightly.
    score += 0.1 * bin_residual as f64;

    // Time horizon: late in the stream, avoid opening new bins / spreading.
    let progress = step_index as f64 / total_items.max(1) as f64;
    score += 20.0 * progress;

    // New-bin candidate handling: only attractive when no good fit exists.
    if bin_residual == bin_capacity {
        // Base cost of opening a bin, modulated by global state.
        let mut open_cost = 50.0;
        // If existing bins have plenty of room on average, discourage new bins.
        open_cost += 0.2 * mean_residual;
        // Many open bins: discourage adding more unless late in stream.
        open_cost += 2.0 * open_bins_count as f64 * (1.0 - progress);
        // If this bin is a last chance elsewhere, opening is costly.
        if fitting_bins_count == 1 {
            open_cost += 100.0;
        }
        // If next item is large and current bin can't chain, new bin slightly better.
        if next_item_size > 0 && next_item_size + item_size > bin_capacity {
            open_cost -= 15.0;
        }
        // Late in stream, heavily penalize new bins.
        open_cost += 30.0 * progress;
        score = open_cost + post_residual as f64;
    }

    // Global pressure: when mean residual is low, tighten selection.
    score += 0.05 * (mean_residual - post_residual as f64).abs();

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let progress = if total_items > 0 { step_index as f64 / total_items as f64 } else { 0.0 };
    let cap = bin_capacity as f64;
    let pr = post_residual as f64;
    let norm_pr = pr / cap;

    // Base: minimize post residual, with smooth polynomial shaping
    let mut score = pr;

    // Smooth polynomial coupling of post_residual with stream progress:
    // early on, large residuals are less painful; later, they waste capacity.
    let progress_weight = progress * progress * (3.0 - 2.0 * progress); // smoothstep
    score += progress_weight * 25.0 * norm_pr * norm_pr * cap;

    // Penalize residuals that cannot fit the lookahead item (smooth quadratic mismatch)
    if next_item_size > 0 {
        let nxt = next_item_size as f64;
        let mismatch = ((nxt - pr) / cap).max(0.0);
        score += 30.0 * mismatch * mismatch * cap * (1.0 - progress_weight * 0.5);
        // Reward when post_residual exactly accommodates the next item
        let fit_gap = (pr - nxt).abs();
        if fit_gap < 1.0 {
            score -= 20.0 * (1.0 - progress_weight);
        }
    }

    // Last-chance bonus: smooth reward scaled by scarcity of fitting bins
    if fitting_bins_count == 1 {
        score -= 15.0 * (1.0 - norm_pr) * (1.0 + progress_weight);
    }

    // Mild penalty for spreading across many open bins (encourages consolidation),
    // smoothly scaled by how far this bin's residual deviates from the mean.
    let dev = (pr - mean_residual).abs() / cap;
    score += 5.0 * dev * dev * (open_bins_count as f64).ln().max(1.0);

    // Slight preference for tighter fits overall (non-linear in fill ratio)
    let fill = (cap - pr) / cap;
    score -= 10.0 * fill * fill * fill;

    // New-bin candidate: penalize mildly so it only wins when open bins are poor fits
    if bin_residual == bin_capacity {
        score += 12.0 + 8.0 * progress_weight;
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Harmonic class of the post-residual: residuals divisible by common item
    // sizes are more reusable, so reward them.
    let post = post_residual as u32;
    let mut harmony_bonus = 0.0f64;
    if post > 0 {
        if post % 10 == 0 { harmony_bonus += 6.0; }
        if post % 20 == 0 { harmony_bonus += 4.0; }
        if post % 25 == 0 { harmony_bonus += 3.0; }
        if post % 50 == 0 { harmony_bonus += 3.0; }
        if post % 5 == 0  { harmony_bonus += 1.0; }
    } else {
        // Perfect fit is the best outcome.
        harmony_bonus += 25.0;
    }

    // Lookahead coupling: does the residual harmonically fit the next item?
    if next_item_size > 0 && post >= next_item_size {
        let gap = post - next_item_size;
        if gap == 0 {
            harmony_bonus += 18.0; // next item will close this bin perfectly
        } else if gap % 10 == 0 {
            harmony_bonus += 8.0;
        } else if gap <= 5 {
            harmony_bonus += 5.0;
        } else {
            // penalize leaving an awkward non-harmonic gap
            score += (gap as f64) * 0.15;
        }
    } else if next_item_size > 0 {
        // residual too small for next item: dead space penalty scaled by how dead
        score += (post as f64) * 0.25;
    }

    // Integer-division threshold classes on post_residual / capacity fractions.
    let quarter = bin_capacity / 4;
    let half = bin_capacity / 2;
    if post == quarter || post == half || post == 3 * quarter {
        harmony_bonus += 2.5;
    }

    // Last-chance bin: strongly favor using it before opening a new bin.
    if fitting_bins_count == 1 && bin_residual < bin_capacity {
        harmony_bonus += 12.0;
    }

    // Early in the stream, keep bins tight; late, prefer consolidation.
    let progress = step_index as f64 / total_items.max(1) as f64;
    score -= harmony_bonus * (0.7 + 0.6 * progress);

    // Prefer filling fuller bins (small residual before placement).
    score -= (bin_capacity.saturating_sub(bin_residual)) as f64 * 0.05;

    // Slight penalty proportional to number of open bins to encourage reuse.
    score += open_bins_count as f64 * 0.1;

    // If this bin is much fuller than average, it is a good consolidation target.
    if mean_residual > 0.0 {
        let relative = (post as f64) / mean_residual;
        if relative < 1.0 {
            score -= (1.0 - relative) * 4.0;
        }
    }

    // New-bin candidate: penalize mildly so it's chosen only when no open bin fits well.
    if bin_residual == bin_capacity {
        score += 15.0;
        // Opening a new bin is attractive when the item is huge (poor fits elsewhere)
        if item_size > bin_capacity * 3 / 4 {
            score -= 10.0;
        }
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
