    } else {
        // Reward small post_residual nonlinearly (dead space penalty grows fast).
        score += (post_residual as f64).powf(1.7) * 0.05;
    }

    // Lookahead: if the next item fits exactly in post_residual, big bonus.
    if next_item_size > 0 && post_residual >= next_item_size {
        let gap = post_residual - next_item_size;
        score -= 40.0 - (gap as f64).min(40.0); // exact next-fit bonus up to 40
    }
    // If next item cannot fit in post_residual, mild penalty for wasting space.
    if next_item_size > post_residual && post_residual > 0 {
        score += 5.0;
    }

    // Last-chance bin: strongly prefer using the only bin that fits,
    // avoiding opening a new bin.
    if fitting_bins_count == 1 && bin_residual < bin_capacity {
        score -= 60.0;
    }

    // New-bin candidate handling: penalize opening a new bin unless
    // existing residuals are all poor fits for the item.
    if bin_residual == bin_capacity {
        // Base cost of a fresh bin.
        score += 30.0;
        // Attractive if item is large and nothing fits well.
        let tightness = item_size as f64 / bin_capacity as f64;
        if tightness > 0.6 {
            score -= 25.0 * (tightness - 0.6) / 0.4;
        }
        // Few fitting bins -> new bin less wasteful.
        score -= (fitting_bins_count as f64).recip() * 10.0;
        // Early in stream: opening bins is cheap (more future structure).
        let t = step_index as f64 / (total_items.max(1) as f64);
        score -= (1.0 - t) * 10.0;
    }

    // Global state: prefer bins with residual far from mean (balance spread),
    // but only mildly.
    let dev = (bin_residual as f64 - mean_residual).abs();
    score += dev * 0.05;

    // Many open bins: encourage consolidation into emptier bins.
    score += (open_bins_count as f64).ln().max(0.0) * 2.0;

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    let progress = step_index as f64 / total_items as f64;
    let cap = bin_capacity as f64;

    // Non-linear polynomial coupling of post_residual with stream progress.
    let pr = post_residual as f64;
    let pr_norm = pr / cap; // in [0,1]

    // Base: reward small post_residual quadratically (tight fit).
    score -= 3.0 * (1.0 - pr_norm) * (1.0 - pr_norm) * (1.0 + 2.0 * progress);

    // Penalize wasted residual that can't fit typical future items,
    // coupled smoothly with progress (late stream => dead space worse).
    let dead = (pr_norm * pr_norm * (3.0 - 2.0 * pr_norm)) * 20.0; // smoothstep
    score += dead * (0.5 + progress);

    // Lookahead: if next item fits exactly in post_residual, big reward.
    if next_item_size > 0 {
        let nxt = next_item_size as f64;
        if post_residual as f64 == nxt {
            score -= 15.0;
        } else if post_residual >= next_item_size {
            // partial reward, scaled by how well it fills
            let fill = nxt / pr;
            score -= 6.0 * fill * fill;
        } else {
            // post_residual too small for next item: penalize proportionally
            score += 4.0 * (1.0 - pr / nxt.max(1.0));
        }
    }

    // Last-chance bin: strongly favor using it to avoid opening a new bin.
    if fitting_bins_count == 1 {
        score -= 25.0;
    } else {
        // Mild crowding penalty spread over many fitting bins.
        score += 0.5 * (fitting_bins_count as f64).ln().max(0.0);
    }

    // Mean residual context: prefer bins below mean residual (tighter bins first).
    score += 0.3 * (mean_residual - bin_residual as f64);

    // New-bin candidate handling: empty bin has pr_norm == 1.
    let is_new_bin = (bin_residual == bin_capacity) && (post_residual as f64 == cap - item_size as f64 || item_size == 0);
    if is_new_bin {
        // Opening a new bin costs a fixed overhead, modulated by progress
        // and how many bins are open (encourage consolidation early,
        // allow new bins late when residuals are fragmented).
        let fragmentation = (mean_residual / cap).clamp(0.0, 1.0);
        let open_cost = 10.0 + 20.0 * progress * (1.0 - fragmentation);
        // Reward new bin if the item fills it well (item large).
        let fill_bonus = (item_size as f64 / cap) * 8.0;
        score = open_cost - fill_bonus + (cap - item_size as f64);
        // If no open bin is a good fit (post_residual large in others is
        // captured by their scores), new bin may win naturally.
    }

    // Cubic interaction: very small post_residual late in stream is excellent.
    score -= (1.0 - pr_norm).powi(3) * 10.0 * progress;

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Harmonic class of post_residual: exact fits (0) and tiny residues (1..=5) are gold.
    let residue_class = post_residual % 10;
    if post_residual == 0 {
        score -= 60.0;
    } else if residue_class <= 2 {
        score -= 18.0;
    } else if residue_class >= 8 {
        score += 8.0; // residue just below a class boundary: dead space risk
    }

    // Dead-space penalty grows non-linearly for unusable gaps.
    if post_residual > 0 && post_residual < 10 {
        score -= 12.0; // small gap likely fillable later
    } else if post_residual >= 10 && post_residual < 20 {
        score += 6.0;
    } else if post_residual >= 20 {
        score += (post_residual as f64 - 20.0) * 0.35;
    }

    // Lookahead: if the next item fits exactly into post_residual, strongly favor.
    if next_item_size > 0 {
        if next_item_size == post_residual {
            score -= 45.0;
        } else if next_item_size <= post_residual {
            score -= (post_residual - next_item_size).min(15) as f64 * 0.8;
        } else {
            score += 5.0; // next item won't fit here anyway
        }
    }

    // Last-chance bin: if this is the only bin that fits, avoid opening a new one
    // unless the fit is terrible.
    if fitting_bins_count == 1 && bin_residual != bin_capacity {
        score -= 25.0 + (bin_residual - item_size).min(30) as f64 * 0.5;
    }

    // New-bin candidate: penalize opening a new bin, more when many bins are open
    // and mean residual is large (existing capacity is being wasted).
    if bin_residual == bin_capacity {
        score += 40.0 + 3.0 * open_bins_count as f64 + mean_residual * 0.4;
    }

    // Late in stream: consolidate aggressively into existing bins.
    let progress = step_index as f64 / total_items.max(1) as f64;
    if bin_residual != bin_capacity {
        score -= progress * 10.0;
    }

    // Prefer tighter bins: closeness of fit bonus.
    score -= (bin_residual - item_size) as f64 * 0.1;

    // Mean-residual coupling: bins far below mean residual are worth filling.
    if (bin_residual as f64) > mean_residual {
        score += 3.0;
    } else {
        score -= 2.0;
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Dead-space penalty: residuals that are too small to hold even the
    // smallest plausible item are pure waste; punish them quadratically.
    let dead_threshold = 10u32;
    if post_residual > 0 && post_residual < dead_threshold {
        score += (dead_threshold - post_residual) as f64 * 4.0;
        score += 15.0; // flat penalty for creating an unusable sliver
    }

    // Perfect fit reward: strongly favor bins that are exactly filled.
    if post_residual == 0 {
        score -= 40.0;
    }

    // Reward tight fits relative to capacity (low post_residual ratio).
    let tightness = post_residual as f64 / bin_capacity as f64;
    score += tightness * 30.0;

    // If this bin can also fit the lookahead item well after placement,
    // reward the pairing; penalize if the leftover would strand the next item.
    if next_item_size > 0 {
        if post_residual >= next_item_size {
            let pair_waste = post_residual - next_item_size;
            if pair_waste < dead_threshold {
                score -= 10.0; // near-perfect two-item packing
            } else {
                score -= 5.0;
            }
        } else {
            score += 8.0; // placement strands the lookahead item
        }
    }

    // Open-bin pressure: when many bins are open, prefer consolidation
    // into existing bins over spreading; mild additive term.
    score += open_bins_count as f64 * 0.5;

    // Last-chance bin: if this is the only bin that fits, strongly favor it
    // over opening a new bin (unless fit is terrible).
    if fitting_bins_count == 1 && bin_residual >= item_size {
        score -= 12.0;
    }

    // Penalize bins whose residual deviates far below mean (encourages
    // balancing usage across open bins toward fuller bins first).
    score += (mean_residual - bin_residual as f64).max(0.0) * 0.3;

    // Slight bias toward using bins earlier in the stream (keeps fresh
    // bins available for large items later).
    let progress = step_index as f64 / (total_items.max(1) as f64);
    score -= progress * 2.0;

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Strong reward for perfect 2-step match: post_residual exactly fits next item.
    if next_item_size > 0 {
        let diff = (post_residual as i64 - next_item_size as i64).abs() as f64;
        score -= 40.0 * (1.0 - diff / (bin_capacity as f64));
        // Exact match bonus
        if post_residual == next_item_size {
            score -= 25.0;
        }
        // Penalize leaving residuals smaller than the smallest plausible next item
        if post_residual < next_item_size {
            score += 0.35 * (next_item_size - post_residual) as f64;
        }
    } else {
        // Last item: minimize waste directly
        score += 10.0;
    }

    // Prefer bins whose residual is tight relative to mean residual
    score += 0.5 * (bin_residual as f64 - mean_residual);

    // Last-chance bin: strongly favor using it to avoid opening a new bin
    if fitting_bins_count == 1 && bin_residual >= item_size {
        score -= 15.0;
    }

    // Late in the stream, consolidate into existing bins
    let progress = step_index as f64 / total_items.max(1) as f64;
    score += progress * 8.0;

    // New-bin candidate: penalize mildly unless current bins fit poorly
    if bin_residual == bin_capacity {
        score += 20.0;
        if next_item_size > 0 && next_item_size <= bin_capacity {
            score -= 5.0;
        }
    }

    // Penalize large dead space that nothing can use later
    if post_residual > 0 && post_residual < 10 {
        score += 12.0;
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
