pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    let progress = if total_items > 0 { step_index as f64 / total_items as f64 } else { 0.0 };
    let pr = post_residual as f64;
    let cap = bin_capacity as f64;
    let norm_pr = pr / cap;

    // Smooth polynomial coupling of post_residual with stream progress:
    // early on, prefer tight fills (minimize post_residual); later, tolerate slack
    // to keep residual space flexible for future items.
    let progress_weight = 1.0 + 0.8 * progress * progress;
    score *= progress_weight;

    // Non-linear dead-space penalty: residuals that are too small to fit
    // typical future items are penalized super-linearly.
    let dead_threshold = 0.15 * cap;
    if pr < dead_threshold {
        let t = 1.0 - pr / dead_threshold;
        score += 12.0 * t * t * t;
    }

    // Reward near-perfect fits with a smooth quadratic bonus.
    let fit_ratio = item_size as f64 / bin_residual.max(1) as f64;
    score -= 8.0 * fit_ratio * fit_ratio;

    // Last-chance bin: strongly favor using it to avoid opening a new bin.
    if fitting_bins_count == 1 {
        score -= 6.0 + 4.0 * progress;
    }

    // Lookahead: if the next item fits the post-residual, reward this placement.
    if next_item_size > 0 && next_item_size <= post_residual {
        let coupling = (next_item_size as f64 / cap) * (1.0 - progress);
        score -= 5.0 + 10.0 * coupling;
    } else if next_item_size > post_residual {
        // Smooth penalty when lookahead item cannot use leftover space.
        let excess = (next_item_size as f64 - pr) / cap;
        score += 6.0 * excess * excess;
    }

    // Mean-residual divergence: penalize bins far from the mean residual
    // with a smooth quadratic term (keeps residual distribution balanced).
    let dev = pr - mean_residual;
    score += 0.02 * dev * dev / (1.0 + progress);

    // New-bin candidate: mildly discourage opening a new bin unless
    // the current item is large relative to capacity.
    if bin_residual == bin_capacity {
        let size_ratio = item_size as f64 / cap;
        score += 3.0 + 10.0 * (1.0 - size_ratio) * (1.0 - size_ratio);
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
