pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Strict dead-space avoidance: penalize small unusable gaps hard.
    let dead_zone = 20.0;
    if (post_residual as f64) < dead_zone && post_residual > 0 {
        score += (dead_zone - post_residual as f64) * 3.0;
    }

    // Perfect fit reward.
    if post_residual == 0 {
        score -= 60.0;
    }

    // Reward keeping residual usable for typical item sizes (>= 10).
    if post_residual >= 10 {
        score -= 15.0;
    } else if post_residual > 0 {
        score += 25.0; // gap below min item size = dead space
    }

    // Lookahead: if next item fits the post-residual, reward this placement.
    if next_item_size > 0 && post_residual >= next_item_size {
        score -= 20.0;
    }
    // Penalize if next item would be blocked by the remaining gap.
    if next_item_size > 0 && post_residual > 0 && post_residual < next_item_size {
        score += 12.0;
    }

    // Last-chance bin: strongly prefer using it over opening a new bin.
    if fitting_bins_count == 1 && bin_residual != bin_capacity {
        score -= 35.0;
    }

    // Open-bin pressure: discourage opening new bins when many are open.
    if bin_residual == bin_capacity {
        score += open_bins_count as f64 * 4.0 + 30.0;
    } else {
        score -= 10.0;
    }

    // Mean residual coupling: prefer bins whose residual is below mean
    // (tightening nearly-full bins) when stream is progressing.
    let progress = step_index as f64 / (total_items.max(1) as f64);
    if (bin_residual as f64) < mean_residual {
        score -= 8.0 * (0.5 + progress);
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Base: prefer tight fits (low post_residual)
    let fit_ratio = post_residual as f64 / bin_capacity as f64;
    score += 30.0 * fit_ratio * fit_ratio;

    // Aggressive 2-step lookahead: reward if next item fits into post_residual
    if next_item_size > 0 && post_residual >= next_item_size {
        score -= 25.0 * (next_item_size as f64 / bin_capacity as f64);
        // Bonus scaled by how well next item also fits tightly
        let next_post = (post_residual - next_item_size) as f64;
        score -= 20.0 * (1.0 - next_post / bin_capacity as f64);
    } else if next_item_size > 0 {
        // Penalize leaving a gap that cannot host the next item
        score += 15.0 * (1.0 - next_item_size as f64 / bin_capacity as f64);
    }

    // Compare against mean residual: avoid bins far from the norm
    let dev = post_residual as f64 - mean_residual;
    score += 0.08 * dev * dev;

    // Last-chance bin: strongly prefer using it to avoid opening a new bin
    if fitting_bins_count == 1 && bin_residual < bin_capacity {
        score -= 40.0;
    }

    // New-bin candidate: penalize opening a new bin unless it is genuinely better
    if bin_residual == bin_capacity {
        score += 55.0;
        // Allow new bin if current bin would leave a big unusable gap
        if post_residual as f64 > 0.5 * bin_capacity as f64 {
            score -= 30.0;
        }
    }

    // Late in stream: consolidate, favor existing bins more
    let progress = step_index as f64 / total_items as f64;
    score *= 1.0 + 0.15 * progress;

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
