pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let cap = bin_capacity as f64;
    let post = post_residual as f64;
    let residual = bin_residual as f64;
    let size = item_size as f64;
    let progress = if total_items > 0 { step_index as f64 / total_items as f64 } else { 0.0 };

    // Base: prefer minimal post-fit waste, with non-linear penalty on mid-range waste.
    let mut score = post + 0.9 * (post * (cap - post) / cap);

    // Non-linear coupling of waste with stream progress: waste matters more later.
    let progress_curve = progress * progress * (3.0 - 2.0 * progress);
    score += 6.0 * progress_curve * (post / cap).sqrt() * post;

    // Fill ratio reward: strongly favor bins that become nearly full.
    let fill = size / residual.max(1.0);
    score -= 14.0 * fill * fill * fill;

    // Penalize consuming a large residual with a small item (dead-space creation).
    score += 0.05 * residual * (1.0 - fill);

    // Last-chance bin: strong reward to use it rather than open a new bin.
    if fitting_bins_count == 1 && bin_residual != bin_capacity {
        score -= 25.0;
    }

    // Lookahead: if the next item fits in post_residual, reward; else mild penalty.
    if next_item_size > 0 {
        let nxt = next_item_size as f64;
        if post_residual >= next_item_size {
            score -= 4.0 * (1.0 - (nxt / post.max(1.0)));
        } else {
            score += 3.0 * (1.0 - post / cap);
        }
    }

    // Prefer denser bins when many bins are open (bin consolidation pressure).
    score += 1.5 * ((open_bins_count as f64).ln().max(0.0)) * (post / cap);

    // Mean-residual deviation: favor bins whose residual is below average (tighter bins).
    score += 2.0 * ((residual - mean_residual) / cap).tanh();

    // New-bin candidate: neutral-ish baseline with slight early-stream preference.
    if bin_residual == bin_capacity {
        score = cap * (0.55 + 0.4 * progress_curve) - 8.0 * (1.0 - progress);
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let cap_f = bin_capacity as f64;
    let mut score = post_residual as f64;

    // Harmonic class of post_residual: bins whose leftover falls into small
    // "dead-space" classes are penalized; classes near multiples of common
    // item sizes are rewarded.
    let pr = post_residual;
    if pr > 0 {
        // dead-space penalty grows super-linearly for tiny residuals
        if pr <= 10 {
            score += (11 - pr) as f64 * 3.0;
        }
        // reward residuals that are "usable" classes: multiples of 5/10/20
        if pr % 10 == 0 {
            score -= 6.0;
        } else if pr % 5 == 0 {
            score -= 3.0;
        }
        // harmonic division classes: pr divisible by 3 or 4 gives more packing
        // options for arbitrary sizes
        if pr % 4 == 0 {
            score -= 1.5;
        } else if pr % 3 == 0 {
            score -= 1.0;
        }
        // integer-division thresholds: quotient of residual by typical size band
        let q = pr / 25; // how many "typical" 25-sized items still fit
        score -= q as f64 * 2.0;
    } else {
        // perfect fit: strongly reward
        score -= 25.0;
    }

    // Lookahead coupling: if next item fits exactly into post_residual,
    // reward heavily (chained fit).
    if next_item_size > 0 {
        if next_item_size == pr {
            score -= 12.0;
        } else if next_item_size < pr {
            let slack = pr - next_item_size;
            // penalize if the chain leaves another tiny dead space
            if slack <= 10 {
                score += slack as f64 * 1.2;
            } else {
                score -= 2.0;
            }
        } else {
            // next item cannot follow into this bin: mild penalty if it would
            // have to open a new bin anyway
            score += 1.0;
        }
    }

    // Last-chance bin: strongly favor using the only bin that fits.
    if fitting_bins_count == 1 && bin_residual >= item_size && bin_residual != bin_capacity {
        score -= 8.0;
    }

    // New-bin candidate handling: only prefer a fresh bin when all open bins
    // would create large dead space.
    let is_new_bin = bin_residual == bin_capacity;
    if is_new_bin {
        // baseline cost of opening a bin; offset by how bad existing fits are
        score += 18.0 + 0.05 * open_bins_count as f64;
        // early in stream, opening bins is cheaper (build a portfolio)
        let progress = step_index as f64 / total_items.max(1) as f64;
        score -= 10.0 * (1.0 - progress);
        // if next item is huge, a fresh bin is attractive
        if next_item_size >= bin_capacity / 2 {
            score -= 6.0;
        }
    } else {
        // prefer bins with residual far from capacity (tight packing)
        let tightness = 1.0 - (bin_residual as f64) / cap_f;
        score -= 5.0 * tightness;
    }

    // Mean-residual coupling: when open bins are on average roomy, prefer
    // filling them rather than opening more.
    score -= 0.05 * mean_residual;

    // mild preference to keep bin count low
    score += 0.02 * open_bins_count as f64;

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Perfect fit: strongly reward closing the bin exactly.
    if post_residual == 0 {
        score -= 50.0;
    }

    // Strict dead-space avoidance: penalize small unusable gaps.
    // A gap is "dead" if it is smaller than the smallest plausible item
    // (1..100 range => treat gaps <= 10 as waste) and not zero.
    if post_residual > 0 && post_residual <= 10 {
        score += 25.0 + (10 - post_residual) as f64 * 3.0;
    }
    // Medium gaps that cannot fit the lookahead item are also wasteful.
    if next_item_size > 0 && post_residual > 0 && post_residual < next_item_size {
        score += 8.0;
    }
    // Reward gaps that can still accommodate the next item.
    if next_item_size > 0 && post_residual >= next_item_size {
        score -= 5.0;
    }

    // Prefer tightest fit relative to residual (best-fit coupling).
    score += (item_size as f64 / bin_residual.max(1) as f64) * 10.0;

    // Last chance before opening a new bin: favor using it.
    if fitting_bins_count == 1 && bin_residual != bin_capacity {
        score -= 12.0;
    }

    // Open bins pressure: when many bins are open, discourage opening new ones.
    let progress = step_index as f64 / total_items.max(1) as f64;
    if bin_residual == bin_capacity {
        // New-bin candidate: penalize more when many bins are open,
        // relax near the end of the stream.
        score += 6.0 + open_bins_count as f64 * 1.5 * (1.0 - 0.5 * progress);
        // If no open bin fits well, allow a new bin.
        if fitting_bins_count == 0 {
            score -= 20.0;
        }
    } else {
        // Slight preference for existing bins as open count grows.
        score -= open_bins_count as f64 * 0.05;
    }

    // Mild tie-breaker: prefer bins below mean residual (consolidation).
    score += (mean_residual - bin_residual as f64) * 0.1;

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Perfect 2-step match: post_residual exactly equals next item size.
    if next_item_size > 0 && post_residual == next_item_size {
        score -= 60.0;
    }

    // Next item fits in the post-residual: strong reward scaled by how snugly it lands.
    if next_item_size > 0 && next_item_size <= post_residual {
        let slack_after_next = post_residual - next_item_size;
        score -= 25.0 + (post_residual as f64 - slack_after_next as f64) * 0.1;
    } else if next_item_size > post_residual && next_item_size > 0 {
        // Next item won't fit here: penalize proportionally to the overshoot.
        let overshoot = (next_item_size - post_residual) as f64;
        score += overshoot * 0.5;
    }

    // Reward bins whose residual is below the mean (denser bins first).
    if (post_residual as f64) < mean_residual {
        score -= (mean_residual - post_residual as f64) * 0.3;
    } else {
        score += (post_residual as f64 - mean_residual) * 0.15;
    }

    // Last-chance bin: strongly favor using it to avoid opening a new bin.
    if fitting_bins_count == 1 && post_residual <= bin_capacity {
        score -= 40.0;
    }

    // Penalize leaving large dead space (unusable slivers).
    if post_residual < 10 && post_residual > 0 {
        score += 15.0;
    }

    // Early in the stream, be more willing to spread items (keep residuals flexible).
    let progress = step_index as f64 / (total_items.max(1) as f64);
    if progress < 0.25 {
        score += 5.0 * (1.0 - progress * 4.0);
    }

    // Slight preference for filling existing bins when many are open.
    score -= open_bins_count as f64 * 0.05;

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Strongly reward tight fits (low post-residual).
    let fit_ratio = item_size as f64 / bin_residual as f64;
    score -= 12.0 * fit_ratio * fit_ratio;

    // Penalize leaving small unusable fragments (< 10) — dead space.
    if post_residual > 0 && post_residual < 10 {
        score += 25.0;
    }

    // Perfect closure bonus.
    if post_residual == 0 {
        score -= 40.0;
    }

    // Last-chance bin: strong incentive to use it rather than open a new bin.
    if fitting_bins_count == 1 && bin_residual != bin_capacity {
        score -= 30.0;
    }

    // New-bin candidate handling: penalize opening a bin unless the item is
    // large or the fit in open bins is poor.
    let is_new_bin = bin_residual == bin_capacity;
    if is_new_bin {
        let progress = if total_items > 0 { step_index as f64 / total_items as f64 } else { 0.0 };
        let avg_load = bin_capacity as f64 - mean_residual;
        let poor_fit_elsewhere = if open_bins_count > 0 {
            (bin_residual as f64 - item_size as f64) / bin_residual as f64
        } else { 1.0 };
        // Prefer new bin when existing fit would waste a lot and future items
        // are small (next_item_size small) or stream is early.
        let keep_new = poor_fit_elsewhere * (1.0 - progress)
            + (next_item_size as f64 / bin_capacity as f64) * 0.5;
        score += 45.0 - 60.0 * keep_new;
        // Discard the raw post-residual dominance for the empty bin.
        score -= (bin_capacity - post_residual) as f64 * 0.0;
        score += 5.0 * (open_bins_count as f64).ln().max(0.0);
    }

    // Lookahead coupling: if next item fits exactly in post_residual, big bonus.
    if next_item_size > 0 {
        if post_residual == next_item_size {
            score -= 35.0;
        } else if post_residual >= next_item_size {
            score -= 8.0 * (next_item_size as f64 / post_residual as f64);
        } else {
            score += 6.0 * (1.0 - post_residual as f64 / next_item_size as f64).min(1.0);
        }
    }

    // Global state: many open bins with high mean residual -> prefer packing
    // into existing bins to consolidate.
    if open_bins_count > 3 {
        let consolidation = mean_residual / bin_capacity as f64;
        score -= 10.0 * consolidation * (open_bins_count as f64 / 20.0).min(1.0);
    }

    // Time horizon: late in the stream, avoid leaving fragments.
    let progress = if total_items > 0 { step_index as f64 / total_items as f64 } else { 0.0 };
    score += 8.0 * progress * (post_residual as f64 / bin_capacity as f64);

    // Mild preference for bins already partially loaded vs near-empty open bins.
    let load_frac = (bin_capacity - bin_residual) as f64 / bin_capacity as f64;
    score -= 5.0 * load_frac;

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;
    let pr = post_residual as f64;
    let cap = bin_capacity as f64;
    let progress = if total_items > 0 { step_index as f64 / total_items as f64 } else { 0.0 };
    let norm_pr = pr / cap;

    // Smooth polynomial coupling: penalize large residuals non-linearly,
    // but relax the penalty as the stream progresses.
    let poly = norm_pr * norm_pr * (1.0 - norm_pr);
    score += 40.0 * poly * (0.5 + progress);

    // Reward tight fits (small post_residual) with a smooth quadratic bonus.
    score -= 25.0 * (1.0 - norm_pr) * (1.0 - norm_pr);

    // Last-chance bin: smooth sigmoid-like reward to avoid opening a new bin.
    if fitting_bins_count == 1 && bin_residual != bin_capacity {
        score -= 15.0 * (1.0 + progress);
    }

    // New-bin candidate: penalize mildly, more so early when bins are few.
    if bin_residual == bin_capacity {
        let bin_pressure = (open_bins_count as f64).ln().max(1.0);
        score += 8.0 + 10.0 / bin_pressure + 12.0 * (1.0 - progress);
    }

    // Lookahead: reward bins whose post_residual can host the next item.
    if next_item_size > 0 {
        let nx = next_item_size as f64;
        if pr >= nx {
            let slack = (pr - nx) / cap;
            score -= 10.0 * (1.0 - slack * slack);
        } else {
            score += 5.0 * (nx - pr) / cap;
        }
    }

    // Mean residual coupling: prefer bins near the mean (smooth deviation term).
    let dev = (pr - mean_residual) / cap;
    score += 6.0 * dev * dev;

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Harmonic class of post_residual: how "usable" is the leftover space?
    // Class 0: post_residual divisible by 10 (harmonic with typical item sizes) -> reward.
    let harmonic = post_residual % 10 == 0;
    let semi_harmonic = post_residual % 5 == 0;
    if harmonic {
        score -= 6.0;
    } else if semi_harmonic {
        score -= 2.5;
    } else {
        // Penalize awkward leftovers, worse for very small odd remainders
        score += ((post_residual % 10) as f64) * 0.15;
    }

    // Dead space: tiny leftover that nothing (min size 1) may exploit well
    if post_residual < 10 && post_residual > 0 {
        score += 8.0;
    }

    // Perfect fit reward
    if post_residual == 0 {
        score -= 25.0;
    }

    // Capacity fraction thresholds on post_residual
    let frac = post_residual as f64 / bin_capacity as f64;
    if frac < 0.2 {
        score += 3.0; // very tight bin, low utility remaining
    } else if frac > 0.6 {
        score -= 2.0; // still roomy, good
    }

    // Lookahead coupling: does next item fit into post_residual?
    if next_item_size > 0 {
        if next_item_size <= post_residual {
            score -= 5.0; // chain placement possible
            // extra reward if next item exactly fills the remainder (harmonic chain)
            if next_item_size == post_residual {
                score -= 10.0;
            }
        } else {
            score += 2.0; // next item won't chain here
            // modulo threshold: if next_item_size is in a "large" class (>60), leftover mismatch hurts more
            if next_item_size > 60 {
                score += 2.0;
            }
        }
    }

    // Last-chance bin: strongly favor using the only bin that fits, else penalize
    if fitting_bins_count == 1 && bin_residual != bin_capacity {
        score -= 12.0;
    }

    // New-bin candidate handling: empty bin gets a mild penalty so we prefer reusing
    // open bins unless they are poor fits (high score from dead space).
    if bin_residual == bin_capacity {
        score += 20.0;
        // Early in stream or many open bins already: opening new is cheaper
        let progress = step_index as f64 / total_items.max(1) as f64;
        if progress < 0.2 {
            score -= 5.0;
        }
        if open_bins_count > 8 {
            score -= 6.0;
        }
        // If next item is large and current item is small, a fresh bin may serve better
        if next_item_size > 70 && item_size < 30 {
            score -= 8.0;
        }
    }

    // Mean residual coupling: if this bin is far below mean residual, it's a straggler;
    // filling stragglers first is good.
    let dev = mean_residual - bin_residual as f64;
    if dev > 0.0 {
        score -= dev * 0.05;
    } else {
        score += (-dev) * 0.02;
    }

    // Integer division threshold: post_residual / item_size quotient classes
    let q = post_residual / item_size.max(1);
    if q >= 2 {
        score -= 1.5; // bin could host multiple such items
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Strict dead-space avoidance: penalize unusable small gaps harshly.
    // Gaps below the minimum item size (1..=10) are pure waste; weight them super-linearly.
    if post_residual > 0 && post_residual <= 10 {
        score += 40.0 * (11.0 - post_residual as f64);
    } else if post_residual > 10 && post_residual <= 20 {
        // Mid-range dead space: moderately risky, penalize proportionally.
        score += 6.0 * (21.0 - post_residual as f64) / 10.0;
    }

    // Reward near-perfect fits (small post_residual relative to item size).
    let fill_ratio = item_size as f64 / bin_residual.max(1) as f64;
    if fill_ratio > 0.8 {
        score -= 12.0 * fill_ratio;
    }

    // Open-bin pressure: with many open bins, prefer consolidating into existing bins
    // (penalize the new-bin candidate, which has bin_residual == bin_capacity).
    if bin_residual == bin_capacity {
        score += 25.0 + 3.0 * open_bins_count as f64;
    } else {
        // Slight reward for using existing bins when pressure is high.
        score -= 0.5 * open_bins_count as f64;
    }

    // Last-chance bonus: if this is the only bin that fits, strongly prefer using it
    // to avoid opening a new bin.
    if fitting_bins_count == 1 && bin_residual != bin_capacity {
        score -= 30.0;
    }

    // Lookahead coupling: if the next item would fit into the post_residual,
    // reward leaving that gap; otherwise penalize leaving a gap the next item can't use.
    if next_item_size > 0 {
        if post_residual >= next_item_size {
            score -= 5.0;
        } else if post_residual > 0 {
            score += 0.3 * (next_item_size - post_residual) as f64;
        }
    }

    // Stream progression: early in the stream, be slightly more willing to open bins
    // (flexibility); later, consolidate aggressively.
    let progress = if total_items > 0 { step_index as f64 / total_items as f64 } else { 0.0 };
    if bin_residual == bin_capacity {
        score -= 10.0 * (1.0 - progress);
    } else {
        score -= 5.0 * progress;
    }

    // Mean-residual coupling: prefer bins whose residual is below average
    // (tighter bins get priority, keeping looser bins available for large future items).
    if bin_residual != bin_capacity {
        if (bin_residual as f64) < mean_residual {
            score -= 4.0;
        } else {
            score += 2.0;
        }
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Base: prefer tight fits, but weight against mean residual.
    score -= 0.5 * (mean_residual - post_residual as f64);

    // Aggressive 2-step lookahead: strongly reward bins whose post_residual
    // can exactly/nearly host the next item.
    if next_item_size > 0 && post_residual >= next_item_size {
        let slack = (post_residual - next_item_size) as f64;
        score -= 25.0 * (1.0 - slack / bin_capacity as f64);
        if post_residual == next_item_size {
            score -= 20.0; // perfect 2-chain: item + next item fills bin
        }
    } else if next_item_size > 0 {
        // Next item cannot follow here: penalize proportionally to wasted
        // post_residual relative to the next item's size.
        let gap = (next_item_size - post_residual) as f64;
        score += 0.3 * gap.min(40.0);
    }

    // Last-chance bin: avoid stranding it unless fit is tight.
    if fitting_bins_count == 1 && bin_residual != bin_capacity {
        score -= 8.0 * (1.0 - post_residual as f64 / bin_capacity as f64);
    }

    // Penalize leaving large dead space (>30) that few items can use.
    if post_residual > 30 {
        score += 0.2 * (post_residual as f64 - 30.0);
    }

    // Slight preference for consolidating into fewer bins.
    score += 0.5 * open_bins_count as f64 * (post_residual as f64 / bin_capacity as f64);

    // New-bin candidate: only attractive when no open bin fits well.
    if bin_residual == bin_capacity {
        score += 35.0 + 0.1 * open_bins_count as f64;
        if next_item_size > 0 && next_item_size + item_size <= bin_capacity {
            score -= 15.0; // fresh bin can host a clean 2-item chain
        }
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let cap = bin_capacity as f64;
    let mut score = post_residual as f64;

    // Strong preference for tight fits: quadratic penalty on wasted space.
    score += 0.9 * (post_residual as f64 / cap) * (post_residual as f64 / cap) * cap;

    // Last-chance bin: heavily reward using it to avoid opening a new bin.
    if fitting_bins_count == 1 && bin_residual != bin_capacity {
        score -= 40.0;
    }

    // Lookahead: if the next item fits exactly in the post-residual, reward this placement.
    if next_item_size > 0 && next_item_size <= post_residual {
        let slack = (post_residual - next_item_size) as f64;
        score -= 8.0 * (1.0 - slack / cap);
    }
    // If next item would not fit here anyway, mild penalty for leaving mid-range residual.
    if next_item_size > post_residual && next_item_size > 0 && post_residual > 0 {
        score += 4.0;
    }

    // New-bin candidate: only attractive when existing bins are fragmented
    // (mean residual high relative to typical item sizes) or many bins open.
    if bin_residual == bin_capacity {
        let fragmentation = (mean_residual / cap).clamp(0.0, 1.0);
        let crowd = (open_bins_count as f64 / 10.0).min(2.0);
        let progress = step_index as f64 / (total_items.max(1) as f64);
        score = cap as f64 * 1.5 - 12.0 * fragmentation - 5.0 * crowd - 10.0 * (1.0 - progress);
        // If this bin is the only fitting option, opening a new bin is necessary.
        if fitting_bins_count == 0 {
            score -= 100.0;
        }
    }

    // Prefer bins whose residual is close to the mean (balanced usage) slightly.
    score += 0.05 * ((bin_residual as f64 - mean_residual).abs());

    // Time horizon: late in the stream, consolidate aggressively.
    let progress = step_index as f64 / (total_items.max(1) as f64);
    score -= 6.0 * progress * (1.0 - post_residual as f64 / cap);

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let progress = step_index as f64 / total_items.max(1) as f64;
    let pr = post_residual as f64;
    let cap = bin_capacity as f64;
    let norm_pr = pr / cap;

    // Base: post-residual with non-linear polynomial coupling to stream progress
    let mut score = pr * (1.0 + 0.5 * progress * (1.0 - norm_pr * norm_pr));

    // Penalize dead space quadratically, stronger late in the stream
    score += 2.0 * norm_pr * norm_pr * cap * (0.3 + 0.7 * progress);

    // Reward tight fits (small post_residual relative to item size)
    let tightness = item_size as f64 / bin_residual.max(1) as f64;
    score -= 8.0 * tightness * tightness;

    // Last-chance bonus: only one fitting bin -> strongly prefer using it
    if fitting_bins_count == 1 {
        score -= 15.0;
    } else {
        score += 0.5 * (fitting_bins_count as f64 - 1.0);
    }

    // Lookahead: reward leaving space for the next item
    if next_item_size > 0 {
        let nxt = next_item_size as f64;
        if pr >= nxt {
            let slack = (pr - nxt) / cap;
            score -= 5.0 * (1.0 - slack * slack);
        } else {
            score += 3.0;
        }
    }

    // Mild preference for filling bins when many bins are open
    score += 0.3 * open_bins_count as f64 * norm_pr;

    // Mean-residual coupling: prefer bins below mean residual (more filled)
    score += 0.2 * (mean_residual - bin_residual as f64);

    // New-bin candidate: neutral-ish baseline, discourage unless current bins are poor fits
    if bin_residual == bin_capacity {
        score = cap * 0.9 + 4.0 * norm_pr * cap;
        if fitting_bins_count == 1 {
            score += 20.0; // avoid opening new bin when a last-chance bin exists
        }
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Harmonic class of the leftover space: classify post_residual into
    // capacity-fraction buckets. Small classes (perfect fits) rewarded hard.
    let frac = post_residual as f64 / bin_capacity as f64;

    // Perfect fit: zero dead space -> strong reward.
    if post_residual == 0 {
        score -= 1000.0;
    } else {
        // Dead-space penalty grows non-linearly for unusable slivers.
        // Slivers below the smallest possible item can never be filled.
        if post_residual < 10 {
            score += 500.0;
        } else {
            // Harmonic weighting: score contribution ~ 1/(class index).
            // Classes: (0,10], (10,25], (25,50], (50,100]
            let class = if post_residual <= 10 { 1 }
                        else if post_residual <= 25 { 2 }
                        else if post_residual <= 50 { 3 }
                        else { 4 };
            score += (40.0 / class as f64) * (1.0 - frac);
        }
    }

    // Lookahead coupling: does next_item_size fit in post_residual?
    // If yes, this bin supports a chain -> reward proportionally to how snugly.
    if next_item_size > 0 && next_item_size <= post_residual {
        let snug = (post_residual - next_item_size) as f64;
        score -= 30.0 - snug.min(30.0) * 0.5;
    } else if next_item_size > post_residual {
        // Next item won't fit here; mildly penalize leaving awkward gaps.
        score += 5.0;
    }

    // Last-chance bin: if this is the only bin that can fit the item,
    // strongly prefer it over opening a new bin.
    if fitting_bins_count == 1 && bin_residual >= item_size {
        score -= 200.0;
    }

    // New-bin candidate handling: an empty bin has post_residual == capacity.
    // Only open a new bin if the item is large relative to typical residuals
    // or late in the stream; otherwise bias toward existing bins.
    if bin_residual == bin_capacity {
        let progress = step_index as f64 / total_items.max(1) as f64;
        let big_item = (item_size as f64 / bin_capacity as f64) > 0.6;
        // Reward opening a new bin for large items or when existing bins are crowded.
        if big_item || mean_residual < item_size as f64 * 0.5 {
            score -= 20.0 + 40.0 * progress;
        } else {
            score += 25.0; // prefer placing into an existing open bin
        }
    }

    // Mild pressure toward consolidating: fewer open bins -> prefer tight fits.
    score += (open_bins_count as f64).ln().max(0.0) * 2.0;

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Strict dead-space avoidance: small unusable gaps are heavily penalized.
    // A residual gap is "dead" if it's smaller than the smallest plausible item (1..100 range, use ~10 as practical floor).
    let min_useful_gap = 10.0f64;
    if (post_residual as f64) < min_useful_gap && post_residual > 0 {
        score += 60.0; // dead space: this bin is effectively closed after placement
    }

    // Reward near-perfect fits strongly.
    if post_residual == 0 {
        score -= 100.0;
    } else if post_residual <= 5 {
        score -= 40.0;
    }

    // Lookahead: if the next item fits in the post residual, reward this placement.
    if next_item_size > 0 && post_residual >= next_item_size {
        score -= 15.0;
    }
    // If next item cannot fit after this placement but could fit elsewhere, mild penalty.
    if next_item_size > 0 && post_residual > 0 && post_residual < next_item_size && post_residual < 10 {
        score += 10.0;
    }

    // Last-chance bin: if this is the only fitting bin, strongly prefer using it
    // rather than opening a new bin.
    if fitting_bins_count == 1 {
        score -= 25.0;
    }

    // Open-bin pressure: with many open bins, discourage opening new bins and
    // encourage filling existing ones (tighter fits preferred).
    let open_pressure = (open_bins_count as f64).ln().max(0.0) * 3.0;
    score += open_pressure * (post_residual as f64 / bin_capacity as f64);

    // Mean-residual coupling: if this bin's post residual is far below the mean,
    // it's a tight fit — reward it.
    score -= (mean_residual - post_residual as f64) * 0.3;

    // New-bin candidate handling: opening a new bin wastes capacity unless the
    // current bin would be left with bad dead space or bins are few.
    if bin_residual == bin_capacity {
        // Fresh bin: post_residual = capacity - item_size, large residual.
        // Penalize opening a new bin when there are already several open bins
        // that could fit the item.
        if open_bins_count > 0 {
            score += 30.0 + 5.0 * open_bins_count as f64;
        }
        // But allow new bins early in the stream or when few bins are open.
        if open_bins_count < 2 {
            score -= 20.0;
        }
        // If the item would leave dead space in every fitting bin, new bin is fine.
        if fitting_bins_count == 1 {
            score -= 10.0;
        }
    }

    // Slight progression effect: later in the stream, consolidation matters more.
    let progress = step_index as f64 / (total_items.max(1) as f64);
    score += progress * (post_residual as f64 * 0.2);

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // 2-step lookahead: perfect match of next item into the post residual
    if next_item_size > 0 {
        if post_residual == next_item_size {
            score -= 60.0; // exact two-item chain fill
        } else if post_residual >= next_item_size {
            // slack after placing both items
            let slack2 = (post_residual - next_item_size) as f64;
            score -= 15.0 * (1.0 - slack2 / bin_capacity as f64);
        } else {
            // next item cannot fit here; penalize leftover dead space
            score += 0.5 * (next_item_size - post_residual) as f64;
        }
    }

    // Favor tight fills relative to mean residual
    score -= 2.0 * (mean_residual - post_residual as f64);

    // Last-chance bin: strong reward to avoid opening a new bin
    if fitting_bins_count == 1 && post_residual < bin_capacity as f64 as u32 {
        score -= 20.0;
    }

    // Penalize very small unusable leftovers
    if post_residual < 10 && post_residual > 0 {
        score += 5.0;
    }
    if post_residual == 0 {
        score -= 25.0; // perfect closure
    }

    // Mild bias toward compacting when many bins are open
    score -= 0.1 * open_bins_count as f64 * (item_size as f64 / bin_capacity as f64);

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Tight fit reward: strongly favor bins where the item nearly fills the residual.
    let tightness = 1.0 - (post_residual as f64) / (bin_capacity as f64);
    score -= 8.0 * tightness * tightness * (item_size as f64);

    // Perfect-fit bonus: residual exactly consumed.
    if post_residual == 0 {
        score -= 25.0;
    } else if post_residual < 5 {
        score -= 10.0;
    }

    // Penalize leaving dead space that no plausible future item (min size ~1, typical) can use.
    if post_residual > 0 && post_residual < 10 {
        score += 6.0; // awkward sliver
    }

    // Lookahead coupling: reward bins whose post-residual can host the next item exactly.
    if next_item_size > 0 {
        if post_residual == next_item_size {
            score -= 30.0;
        } else if post_residual >= next_item_size {
            score -= 4.0 * (1.0 - (post_residual - next_item_size) as f64 / (bin_capacity as f64));
        } else {
            // next item won't fit here; mild penalty proportional to overflow gap
            score += 2.0 * (next_item_size - post_residual) as f64 / 20.0;
        }
    }

    // Last-chance bin: strongly prefer using the only bin that can fit the item.
    if fitting_bins_count == 1 && bin_residual >= item_size && bin_residual != bin_capacity {
        score -= 40.0;
    }

    // Global state: when many bins are open, discourage opening new ones implicitly
    // by rewarding use of existing bins proportional to open_bins_count.
    score -= 0.6 * (open_bins_count as f64).ln().max(0.0);

    // Mean-residual coupling: if this bin's residual is far below the mean, it's a
    // laggard bin — using it consolidates waste; reward that.
    let residual_f = bin_residual as f64;
    let dev = mean_residual - residual_f;
    if dev > 0.0 {
        score -= 0.15 * dev;
    } else {
        score += 0.10 * (-dev);
    }

    // Time horizon: early in the stream, keep bins flexible (mild penalty for very
    // low post-residual); late in the stream, pack aggressively.
    let progress = if total_items > 0 { step_index as f64 / total_items as f64 } else { 0.0 };
    if progress < 0.3 {
        score += 0.05 * (post_residual as f64).min(50.0) * (0.3 - progress) / 0.3;
    } else {
        score -= 6.0 * progress;
    }

    // New-bin candidate handling: an empty bin has residual == capacity. Prefer it
    // only when the item is large or no existing bin gives a good fit.
    if bin_residual == bin_capacity {
        let large_item = (item_size as f64) / (bin_capacity as f64);
        // Penalize opening a new bin unless the item is big or fitting options are scarce.
        score += 18.0 - 30.0 * large_item - 4.0 * (fitting_bins_count == 0) as i32 as f64;
        // Late in the stream, opening new bins is even less attractive.
        score += 10.0 * progress;
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let progress = if total_items > 1 { step_index as f64 / total_items as f64 } else { 0.0 };
    let cap = bin_capacity as f64;

    // Base: waste after placement, non-linearly penalized (quadratic + cubic softening)
    let pr = post_residual as f64;
    let mut score = pr * (1.0 + 0.02 * pr / cap) + 8.0 * (pr / cap).powi(3) * cap;

    // Smooth progress coupling: later in the stream, waste matters more (fewer chances to fill)
    score *= 1.0 + 0.8 * progress * (pr / cap);

    // Reward tight fits: subtract a smooth function of fill ratio
    let fill = (bin_residual as f64 - pr) / cap;
    score -= 30.0 * fill * fill;

    // Lookahead: if next item fits the post-residual, big reward (smooth in fit quality)
    if next_item_size > 0 && (next_item_size as f64) <= pr {
        let slack = (pr - next_item_size as f64) / cap;
        score -= 25.0 * (1.0 - slack) * (1.0 + progress);
    } else if next_item_size > 0 {
        // Penalize leaving residuals that no plausible next item can use
        score += 10.0 * (pr / cap) * (1.0 - progress);
    }

    // Last-chance bin: strongly favor using it rather than opening a new bin
    if fitting_bins_count == 1 && bin_residual < bin_capacity {
        score -= 40.0 * (1.0 + progress);
    }

    // Prefer bins below mean residual (consolidate waste into few bins)
    score += 0.15 * (mean_residual - bin_residual as f64).abs() * (1.0 - progress);

    // New-bin candidate: keep it moderately attractive early, discourage late
    if bin_residual == bin_capacity {
        score = 35.0 + 60.0 * progress + 0.5 * open_bins_count as f64;
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Harmonic class of the post residual: exact-fill classes are golden.
    let cap = bin_capacity as f64;
    let pr = post_residual as f64;

    // Perfect fit: massive reward.
    if post_residual == 0 {
        score -= 1000.0;
    } else {
        // Class of post_residual modulo small harmonic divisors.
        let mod4 = post_residual % 4;
        let mod10 = post_residual % 10;
        let mod25 = post_residual % 25;

        // Residuals that are "clean" multiples of common item sizes are more reusable.
        if post_residual % 10 == 0 { score -= 12.0; }
        if post_residual % 25 == 0 { score -= 8.0; }
        if post_residual % 20 == 0 { score -= 6.0; }
        if post_residual % 50 == 0 { score -= 10.0; }

        // Penalize awkward odd residuals (dead space risk).
        if post_residual % 2 == 1 { score += 3.0; }
        if mod4 == 1 || mod4 == 3 { score += 2.0; }

        // Integer-division thresholds: fraction of capacity consumed.
        let fill = (bin_residual as f64) / cap; // fraction used before placement
        let post_frac = pr / cap;

        // Reward high fill ratios (tight packing), especially in late stages.
        let progress = if total_items > 0 { step_index as f64 / total_items as f64 } else { 0.0 };
        score -= fill * fill * 30.0 * (0.5 + progress);

        // Penalize leaving a residual too small for typical items (dead zone).
        if post_residual < 10 && post_residual > 0 {
            score += 15.0 * (1.0 - post_frac);
        }

        // Dead zone: residual in [1,9] is nearly unusable given min item size 10
        // (interface allows sizes down to 1, so soften but still penalize).
        if post_residual > 0 && post_residual < 5 {
            score += 10.0;
        }

        // Harmonic class of next_item_size: if next item fits exactly in post_residual, big reward.
        if next_item_size > 0 {
            if next_item_size == post_residual {
                score -= 60.0;
            } else if next_item_size < post_residual {
                // Reward if next item fits with small slack (chained tight fits).
                let slack = post_residual - next_item_size;
                if slack <= 5 { score -= 25.0; }
                else if slack <= 15 { score -= 10.0; }
                // Penalize if next item cannot fit here (will need another bin anyway).
                else {
                    score += 5.0;
                    if post_residual % next_item_size.max(1) == 0 { score -= 6.0; }
                }
            } else {
                // Next item too big for this residual: residual is terminal.
                score += 8.0;
                // Unless residual itself is a clean harmonic class.
                if mod10 == 0 { score -= 9.0; }
            }
        }

        // Last-chance bin: strongly prefer using it over opening a new bin.
        if fitting_bins_count == 1 {
            score -= 20.0;
        } else if fitting_bins_count > 1 {
            // With many options, prefer the tightest; mild penalty to spread competition.
            score += (fitting_bins_count as f64 - 1.0).min(5.0);
        }

        // New-bin candidate: only attractive when open bins are all poor fits.
        if bin_residual == bin_capacity {
            // Base cost of opening a bin.
            score += 35.0;
            // Early stream: opening bins is cheaper to build a portfolio.
            score -= 30.0 * (1.0 - progress);
            // If mean residual of open bins is small (crowded), opening is more attractive.
            score -= (mean_residual / cap).min(1.0) * 10.0;
            // If the current bin is the only fitting one, discourage new bin.
            if fitting_bins_count == 1 { score += 25.0; }
            // Late stream: consolidate, avoid new bins.
            score += 20.0 * progress;
        }

        // Reward using bins with low residual relative to mean (balance avoidance of many half-full bins).
        if (bin_residual as f64) < mean_residual {
            score -= 4.0;
        } else {
            score += 3.0;
        }
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Strict dead-space avoidance: residuals below the minimum item size are pure waste.
    if post_residual > 0 {
        let dead = if post_residual < 10 { 3.0 } else if post_residual < 20 { 1.5 } else { 0.0 };
        score += dead * post_residual as f64;
    }

    // Perfect fit gets a strong reward.
    if post_residual == 0 {
        score -= 200.0;
    }

    // Last-chance bin: strongly favor using it before opening a new bin.
    if fitting_bins_count == 1 && bin_residual != bin_capacity {
        score -= 60.0;
    }

    // Open-bin pressure: with many bins open, prefer filling existing ones.
    score += (open_bins_count as f64) * 1.5;

    // Lookahead: if the next item fits exactly in the post-residual, reward this placement.
    if next_item_size > 0 && post_residual >= next_item_size {
        score -= 15.0;
    }
    // If the next item is nearly a fit, slight penalty for blocking it.
    if next_item_size > 0 && next_item_size > post_residual && post_residual > 0 {
        score += 10.0 * (1.0 - (next_item_size - post_residual) as f64 / 100.0);
    }

    // Mean-residual coupling: when average slack is high, tighten selection (penalize loose fits).
    score += (post_residual as f64 - mean_residual).max(0.0) * 0.5;

    // New-bin candidate: default moderate cost; only attractive when item barely fits anywhere.
    if bin_residual == bin_capacity {
        let base = 120.0;
        let desperation = if fitting_bins_count == 0 { 500.0 } else { 0.0 };
        score = base + desperation + (item_size as f64 * 0.2);
    }

    // Stream progression: later in stream, waste tolerance decreases.
    let progress = step_index as f64 / (total_items.max(1) as f64);
    score += post_residual as f64 * progress * 0.8;

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // 2-step lookahead: reward bins whose post_residual matches the next item.
    if next_item_size > 0 {
        let p = post_residual as f64;
        let n = next_item_size as f64;
        if next_item_size <= post_residual {
            // Next item fits exactly into the leftover: strongly favor.
            let gap = (p - n).abs();
            score -= 60.0 / (1.0 + gap);
            if (p - n).abs() < 1.0 {
                score -= 40.0; // perfect 2-chain
            }
        } else {
            // Leftover too small for next item: penalize dead space, worse when tiny.
            let dead = p / bin_capacity as f64;
            score += 30.0 * (1.0 - dead) * (1.0 - dead);
        }
    } else {
        // Last item: just minimize waste.
        score += 0.0;
    }

    // Relative to mean residual: prefer filling bins below-average (tighter bins).
    score -= 0.3 * (mean_residual - post_residual as f64);

    // Last-chance bin: if this is the only bin that fits, strongly prefer using it.
    if fitting_bins_count == 1 && bin_residual != bin_capacity {
        score -= 25.0;
    }

    // New-bin candidate: keep it attractive only when no open bin offers a good fit.
    if bin_residual == bin_capacity {
        let baseline = 55.0
            + 0.3 * mean_residual
            + if next_item_size > 0 && (next_item_size as u32) <= item_size { 0.0 } else { 10.0 };
        score = baseline + post_residual as f64 * 0.1;
        if open_bins_count == 0 {
            score -= 100.0; // must open first bin
        }
    }

    // Late-stream consolidation: prefer reusing open bins as stream progresses.
    let progress = step_index as f64 / (total_items.max(1) as f64);
    score += 15.0 * progress * (post_residual as f64 / bin_capacity as f64);

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let cap = bin_capacity as f64;
    let mut score = post_residual as f64;

    // Reward tight fits: post_residual near zero is best.
    let tightness = 1.0 - (post_residual as f64) / cap;
    score -= 12.0 * tightness * tightness;

    // Penalize dead space: residuals too small for any future item (min size 1, but
    // typical items are larger). Penalize residuals below the next item's need.
    if next_item_size > 0 && post_residual < next_item_size {
        score += 0.35 * (next_item_size - post_residual) as f64;
    }

    // Lookahead: if next item fits exactly in post_residual, strong bonus.
    if next_item_size > 0 && post_residual == next_item_size {
        score -= 15.0;
    }

    // Last-chance bonus: this is the only bin that fits the item.
    if fitting_bins_count == 1 && bin_residual != bin_capacity {
        score -= 25.0;
    }

    // Prefer fuller bins relative to the fleet mean residual.
    score += 0.5 * (mean_residual - bin_residual as f64).max(0.0);

    // Slight preference to use bins with low residual overall (consolidation).
    score += 0.1 * (bin_residual as f64 - mean_residual);

    // New-bin candidate: only attractive when no open bin fits well.
    let is_new_bin = bin_residual == bin_capacity;
    if is_new_bin {
        // Base penalty so open bins are preferred unless fits are poor.
        score += 30.0;
        // More open bins -> opening new bins less attractive.
        score += 2.0 * open_bins_count as f64;
        // If this bin is the last chance, discourage opening a new bin.
        if fitting_bins_count == 1 {
            score += 40.0;
        }
        // Late in the stream, avoid spawning bins with large residual waste.
        let progress = step_index as f64 / total_items.max(1) as f64;
        score += 10.0 * progress * (bin_capacity - item_size) as f64 / cap;
    } else {
        // Early stream: mildly encourage spreading into new bins when many bins fit.
        if fitting_bins_count > 3 {
            let progress = step_index as f64 / total_items.max(1) as f64;
            score += 8.0 * (1.0 - progress);
        }
    }

    // Small penalty for very large post residual that likely becomes dead space.
    if post_residual > 0 && post_residual < 10 {
        score += 6.0; // tiny unusable sliver
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let progress = step_index as f64 / total_items as f64;
    let pr = post_residual as f64;
    let cap = bin_capacity as f64;
    let norm_pr = pr / cap;
    let mut score = pr as f64;
    // Smooth polynomial coupling of post_residual with stream progress
    let poly = norm_pr * (1.0 + 2.0 * progress) - norm_pr * norm_pr * (1.0 - progress);
    score += 40.0 * poly;
    // Tight fits rewarded more strongly as stream progresses
    let tightness = 1.0 - norm_pr;
    score -= 25.0 * tightness * tightness * (0.5 + progress);
    // Last-chance bin bonus
    if fitting_bins_count == 1 {
        score -= 15.0;
    }
    // Penalize bins whose residual is far from mean (fragmentation)
    let dev = pr - mean_residual;
    score += 0.05 * dev * dev;
    // Lookahead: reward residual that can hold next item
    if next_item_size > 0 {
        let fits_next = pr >= next_item_size as f64;
        if fits_next {
            score -= 8.0 * (1.0 - (pr / cap));
        } else {
            score += 5.0;
        }
    }
    // Slight penalty on opening new bins when many are open
    if bin_residual == bin_capacity {
        score += 3.0 + 0.5 * open_bins_count as f64;
    }
    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let cap = bin_capacity as f64;
    let mut score = post_residual as f64;

    // Harmonic class of post_residual: dead-space classes via integer division
    let post = post_residual as f64;
    let class = (post_residual / 10) as f64; // decade class 0..10

    // Reward tight fits: nonlinear bonus for small post_residual
    score -= 40.0 * (-post / 25.0).exp();

    // Penalize "awkward" residuals: post_residual in ranges that few item sizes (1..100) can fill.
    // Items > post_residual cannot fit; small residuals only accept tiny items.
    let fillable = if post_residual == 0 { 100.0 } else {
        let p = post_residual.min(100) as f64;
        p // fraction of item sizes (1..=post) that could fill it, scaled
    };
    score += 0.6 * (100.0 - fillable);

    // Modulo / harmonic coupling: residuals that are multiples of 5 or 10 are more reusable
    if post_residual % 10 == 0 {
        score -= 8.0;
    } else if post_residual % 5 == 0 {
        score -= 4.0;
    } else {
        score += 3.0;
    }

    // Class-based dead-space penalty: mid-range residuals (20..50) are the worst traps
    if post_residual >= 20 && post_residual <= 50 {
        score += 6.0 + 0.15 * (35.0 - post).abs();
    }

    // Lookahead: if next item fits exactly into post_residual, big reward
    if next_item_size > 0 {
        if next_item_size == post_residual {
            score -= 60.0;
        } else if next_item_size <= post_residual {
            score -= 15.0 * (next_item_size as f64 / post.max(1.0));
        } else {
            score += 5.0;
        }
    }

    // Last-chance bin: strongly favor using it to avoid opening a new bin
    if fitting_bins_count == 1 && bin_residual != bin_capacity {
        score -= 45.0;
    }

    // New-bin candidate handling: only attractive when open bins are crowded
    if bin_residual == bin_capacity {
        let pressure = mean_residual / cap;
        let progress = step_index as f64 / (total_items.max(1) as f64);
        // Penalize opening new bins unless mean residual is low (bins too full)
        score = 70.0 - 80.0 * pressure + 10.0 * progress;
        if fitting_bins_count == 0 { score -= 50.0; }
    }

    // Slight preference for bins already below mean residual (balance load)
    score += 0.1 * (post - mean_residual);

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Strict dead-space avoidance: gaps too small for any item (1..=100 range,
    // but treat < 10 as near-dead) are heavily penalized.
    if post_residual < 10 {
        score += 60.0;
    } else if post_residual < 20 {
        score += 25.0;
    } else if post_residual < 30 {
        score += 10.0;
    }

    // Reward very tight fits (small post_residual relative to item size).
    let tightness = item_size as f64 / bin_residual.max(1) as f64;
    score -= 30.0 * tightness;

    // Exact fill bonus.
    if post_residual == 0 {
        score -= 50.0;
    }

    // Lookahead: if the next item fits into the post-residual, reward this bin.
    if next_item_size > 0 && post_residual >= next_item_size {
        score -= 20.0;
    }
    // If next item would NOT fit and post_residual is small, slight penalty.
    if next_item_size > 0 && post_residual < next_item_size && post_residual < 10 {
        score += 15.0;
    }

    // Last-chance pressure: if this is the only fitting bin, strongly favor using it.
    if fitting_bins_count == 1 && bin_residual < bin_capacity {
        score -= 40.0;
    }

    // Open-bin pressure: with many open bins, discourage spreading; prefer filling.
    let progress = if total_items > 0 { step_index as f64 / total_items as f64 } else { 0.0 };
    score += 2.0 * open_bins_count as f64 * (1.0 - progress);

    // Deviation from mean residual: prefer bins with residual close to item need
    // (i.e., avoid dumping into bins with large residuals when item is small).
    let mean_gap = (mean_residual - bin_residual as f64).abs();
    score += 0.15 * mean_gap;

    // New-bin candidate handling: only prefer a fresh bin when no open bin gives
    // a good fit (large post_residual everywhere) or few bins fit the item.
    if bin_residual == bin_capacity {
        // Base cost of opening a new bin, modulated by open-bin count and fit quality.
        let mut new_bin_cost = 55.0 + 3.0 * open_bins_count as f64;
        if fitting_bins_count == 0 {
            new_bin_cost -= 60.0; // no alternative: must open
        }
        // Late in stream, slightly cheaper to open than fragment.
        new_bin_cost -= 10.0 * progress;
        score = new_bin_cost + post_residual as f64;
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Base: prefer minimal post_residual (tight fit).
    score = post_residual as f64 * 1.0;

    // Exact fit bonus: strongly reward perfect packing.
    if post_residual == 0 {
        score -= 1000.0;
    }

    // 2-step lookahead: reward when post_residual exactly matches the next item.
    if next_item_size > 0 {
        if post_residual == next_item_size {
            score -= 300.0; // chain fit: this bin will be filled perfectly next step
        } else if post_residual > next_item_size {
            // Partial lookahead credit proportional to how close next item gets us to zero.
            let gap = (post_residual - next_item_size) as f64;
            score -= 150.0 * (1.0 - gap / bin_capacity as f64);
        } else {
            // Next item cannot fit here; penalize small unusable leftovers.
            let leftover = post_residual as f64;
            if leftover < 10.0 {
                score += 80.0 * (10.0 - leftover);
            }
        }
    } else {
        // Last item: strongly prefer exact/zero residual.
        score -= 200.0 * (1.0 - post_residual as f64 / bin_capacity as f64);
    }

    // Relative to mean residual: prefer bins that are already "below average" fullness
    // only when the fit is good; avoid dumping into bins far from mean (fragmentation risk).
    let dev = post_residual as f64 - mean_residual;
    score += 0.5 * dev;

    // Last-chance bin: if this is the only bin that fits, use it rather than opening a new bin
    // unless the fit is terrible.
    if fitting_bins_count == 1 && bin_residual != bin_capacity {
        score -= 120.0;
    }

    // New-bin candidate handling: empty bin should only win when no open bin fits well.
    if bin_residual == bin_capacity {
        // Neutral base for a fresh bin: its post_residual is large, which already
        // makes it unattractive; add a mild opening cost scaled by stream progress.
        let progress = if total_items > 0 { step_index as f64 / total_items as f64 } else { 0.0 };
        score += 30.0 + 40.0 * progress;
        // If many bins are open, opening another is worse.
        score += 5.0 * open_bins_count as f64;
    }

    // Penalize leaving dead space that nothing (min size 1..10) can ever use.
    if post_residual > 0 && post_residual < 5 {
        score += 50.0;
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let progress = (step_index as f64 / total_items.max(1) as f64).clamp(0.0, 1.0);
    let mut score = post_residual as f64;

    // Lookahead coupling: reward bins whose leftover can host the next item.
    if next_item_size > 0 {
        if next_item_size <= post_residual {
            // Chain placement possible: strong reward, stronger early in stream.
            score -= 6.0 + 5.0 * (1.0 - progress);
        } else {
            // Dead space that the next item cannot use: penalize proportionally.
            score += 3.0 + 6.0 * (post_residual as f64 / bin_capacity as f64);
        }
    }

    // Last-chance bin: strongly favor using it before opening a new bin.
    if fitting_bins_count == 1 && bin_residual < bin_capacity {
        score -= 5.0 + 4.0 * progress;
    }

    // New-bin candidate: mild penalty so reuse is preferred unless fits are bad.
    if bin_residual == bin_capacity {
        score += 2.0 + 0.15 * open_bins_count as f64 + 0.05 * mean_residual;
        if fitting_bins_count == 0 {
            // No open bin can host the item: new bin is the only option.
            score -= 12.0;
        }
    }

    // Slight time-coupled reward for bins already partially filled (keeps old bins closing out).
    score -= 0.03 * (bin_capacity - bin_residual) as f64 * progress;

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let progress = if total_items > 0 { step_index as f64 / total_items as f64 } else { 0.0 };
    let cap = bin_capacity as f64;
    let pr = post_residual as f64;
    let norm_pr = pr / cap;

    // Base: post residual, with smooth non-linear shaping.
    let mut score = pr * (1.0 + 0.35 * progress * (1.0 - progress) * 4.0);

    // Quadratic dead-space penalty: small post-residuals are costly waste.
    score += 18.0 * (1.0 - norm_pr) * (1.0 - norm_pr) * (0.5 + 0.5 * progress);

    // Cubic coupling: mid-range residuals are moderately useful.
    let mid = norm_pr * (1.0 - norm_pr);
    score -= 12.0 * mid * (1.0 + progress);

    // Perfect fit reward, smoothly weighted.
    if post_residual == 0 {
        score -= 30.0 + 10.0 * progress;
    }

    // Lookahead: favor bins whose post-residual fits the next item.
    if next_item_size > 0 && (post_residual as u32) >= next_item_size {
        let gap = (post_residual as f64 - next_item_size as f64) / cap;
        score -= 14.0 * (1.0 - gap) * (1.0 - gap);
    } else if next_item_size > 0 {
        score += 6.0 * (next_item_size as f64 / cap);
    }

    // Last-chance bin bonus: avoid opening a new bin when only one fits.
    if fitting_bins_count == 1 && bin_residual != bin_capacity {
        score -= 10.0 + 8.0 * progress;
    }

    // New-bin candidate: penalize mildly so it only wins when open bins are bad,
    // with smooth scaling by stream progress and mean residual.
    if bin_residual == bin_capacity {
        let mean_norm = mean_residual / cap;
        score = 55.0 + 25.0 * progress - 20.0 * mean_norm * (1.0 - mean_norm);
    }

    // Mild fragmentation penalty relative to mean residual.
    score += 4.0 * ((pr - mean_residual) / cap);

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Harmonic class of the post residual: how "usable" is the leftover space.
    // Residuals divisible by common item sizes (10, 20, 25, 50) are valuable.
    let pr = post_residual;
    let mut bonus = 0.0;
    if pr == 0 {
        bonus -= 60.0; // perfect fit
    } else if pr % 50 == 0 && pr > 0 {
        bonus -= 25.0;
    } else if pr % 25 == 0 {
        bonus -= 15.0;
    } else if pr % 20 == 0 {
        bonus -= 12.0;
    } else if pr % 10 == 0 {
        bonus -= 8.0;
    }
    score += bonus;

    // Penalize small dead space that nothing (min size 1..100) can use well:
    // tiny post residuals (< 10) are dead weight unless zero.
    if pr > 0 && pr < 10 {
        score += 20.0;
    }

    // Lookahead coupling: if next item fits exactly into post_residual, big reward.
    if next_item_size > 0 {
        if next_item_size == pr {
            score -= 40.0;
        } else if next_item_size <= pr {
            let slack = (pr - next_item_size) as f64;
            score -= 15.0 * (1.0 - slack / bin_capacity as f64);
        } else {
            // next item cannot use this bin's leftover; slight penalty scaled by gap
            let gap = (next_item_size - pr) as f64;
            score += 4.0 * (gap / bin_capacity as f64).min(1.0);
        }
    }

    // Last-chance bin: strongly favor using it to avoid opening a new bin.
    if fitting_bins_count == 1 && bin_residual < bin_capacity {
        score -= 30.0;
    }

    // New-bin candidate handling: brand-new empty bin.
    if bin_residual == bin_capacity {
        // Opening a new bin is attractive when current open bins are fragmented
        // (mean residual high relative to item) or item barely fits nothing well.
        let fragmentation = (mean_residual - item_size as f64) / bin_capacity as f64;
        if next_item_size > 0 && item_size as f64 > mean_residual * 0.9 {
            score -= 10.0 + 20.0 * fragmentation.max(0.0);
        } else {
            score += 15.0; // prefer existing bins by default
        }
    }

    // Prefer tighter fits generally: reward small post_residual via capacity fraction.
    let frac = pr as f64 / bin_capacity as f64;
    score += 10.0 * frac * frac;

    // Slight preference to fill older/more-filled bins as stream progresses.
    let progress = step_index as f64 / (total_items.max(1) as f64);
    score -= 5.0 * progress * (1.0 - frac);

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Strict dead-space avoidance: gaps too small for the smallest item (1) are
    // already counted by post_residual; gaps that can't fit the lookahead item
    // or typical small items are heavily penalized as dead space.
    if post_residual > 0 {
        if next_item_size > 0 && post_residual < next_item_size {
            score += 18.0; // dead space relative to lookahead
        }
        if post_residual <= 10 {
            score += 25.0; // tiny unusable sliver
        } else if post_residual <= 20 {
            score += 10.0;
        }
    } else {
        // Perfect fill: strong reward.
        score -= 40.0;
    }

    // Reward tight fits (small post_residual relative to capacity).
    let tightness = 1.0 - (post_residual as f64 / bin_capacity as f64);
    score -= 15.0 * tightness * tightness;

    // Lookahead coupling: if the next item fits exactly in the post residual,
    // strongly favor this bin.
    if next_item_size > 0 && post_residual >= next_item_size {
        let slack = (post_residual - next_item_size) as f64;
        score -= 12.0 / (1.0 + slack);
    }

    // Last-chance bonus: only one bin can fit the item; avoid opening a new bin.
    if fitting_bins_count == 1 && bin_residual >= item_size {
        score -= 30.0;
    }

    // Open-bin pressure: with many open bins, prefer consolidating into
    // existing bins over opening new ones.
    score += 2.0 * open_bins_count as f64;

    // Mean residual coupling: if this bin's residual is far below the mean,
    // it's already fragmented; slightly prefer using it.
    let dev = mean_residual - bin_residual as f64;
    score -= 0.3 * dev;

    // New-bin candidate (empty bin): penalize mildly so it's chosen only when
    // no open bin offers a decent fit, and more strongly early in the stream
    // when few bins exist consolidation is cheap.
    if bin_residual == bin_capacity {
        score += 35.0 + 20.0 * (step_index as f64 / total_items.max(1) as f64);
        // But if the item is large and nothing else fits well, new bin is fine.
        if item_size >= 60 && fitting_bins_count <= 1 {
            score -= 40.0;
        }
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let score = (post_residual as f64) * 0.82;
    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Strong best-fit core: reward tight fits non-linearly.
    let fit_ratio = post_residual as f64 / bin_capacity as f64;
    score += 12.0 * fit_ratio * fit_ratio;

    // Reward filling a bin nearly completely (perfect fit bonus).
    if post_residual == 0 {
        score -= 30.0;
    } else if post_residual <= 5 {
        score -= 15.0;
    } else if post_residual < 10 {
        score -= 6.0;
    }

    // Dead-space penalty: residuals below the smallest plausible item are wasted.
    if post_residual > 0 && post_residual < 10 {
        score += 20.0;
    }

    // Lookahead: if the next item fits the post-residual, this placement chains nicely.
    if next_item_size > 0 {
        if next_item_size <= post_residual {
            score -= 10.0 + 8.0 * (1.0 - next_item_size as f64 / post_residual as f64);
        } else {
            // Next item won't fit here: penalize leaving medium-sized gaps slightly more.
            score += 3.0 * (post_residual as f64 / bin_capacity as f64);
        }
    } else {
        // Last item: strongly prefer closing bins out completely.
        score -= 25.0 * (1.0 - post_residual as f64 / bin_capacity as f64);
    }

    // Last-chance bin: if this is the only bin that fits, strongly prefer using it.
    if fitting_bins_count == 1 && bin_residual < bin_capacity {
        score -= 20.0;
    }

    // New-bin candidate handling: opening a bin is only attractive when open bins fit poorly.
    if bin_residual == bin_capacity {
        // Base cost of opening a new bin.
        let mut new_bin_score = 45.0;
        // Early in stream, opening bins is cheap (need capacity pool).
        let progress = if total_items > 0 { step_index as f64 / total_items as f64 } else { 0.0 };
        new_bin_score -= 25.0 * (1.0 - progress);
        // If many open bins already, discourage proliferation.
        new_bin_score += 2.0 * (open_bins_count as f64).ln().max(0.0);
        // If mean residual is large, open bins have room; prefer them over new bin.
        new_bin_score += 0.3 * mean_residual;
        // If next item is large, a fresh bin is valuable.
        if next_item_size > 60 {
            new_bin_score -= 15.0;
        }
        // If only this new bin can fit the item, open it eagerly.
        if fitting_bins_count == 0 {
            new_bin_score -= 100.0;
        }
        score = score.max(new_bin_score) - new_bin_score + new_bin_score;
        score = new_bin_score;
        return score;
    }

    // Mild preference for bins with smaller residuals among open bins (tightest fit first).
    score += 0.1 * (bin_residual as f64 - post_residual as f64);

    // Slight global balance: prefer bins below mean residual (keeps variety of gaps).
    score += 0.05 * (bin_residual as f64 - mean_residual);

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let progress = step_index as f64 / total_items.max(1) as f64;
    let pr = post_residual as f64;
    let cap = bin_capacity as f64;
    let norm_pr = pr / cap;

    // Non-linear polynomial coupling of post_residual with stream progress.
    let mut score = pr * (1.0 + 0.8 * progress * norm_pr * norm_pr);

    // Smooth cubic damping: late in the stream, tighter fills matter more.
    score -= (1.0 - progress) * (1.0 - progress) * (pr * pr) / cap * 0.35;

    // Penalize residual that cannot fit the lookahead item (smooth sigmoid-like term).
    if next_item_size > 0 {
        let gap = (next_item_size as f64 - pr).max(0.0) / cap;
        score += gap * gap * cap * (0.5 + 0.5 * progress);
        // Reward residual that exactly accommodates the next item, smoothly.
        let fit_gap = (pr - next_item_size as f64).abs() / cap;
        score -= (1.0 - fit_gap.min(1.0)) * 4.0 * (1.0 - progress);
    }

    // Last-chance bonus: strongly favor using the only fitting bin.
    if fitting_bins_count == 1 {
        score -= 6.0 + 4.0 * progress;
    } else if fitting_bins_count > 1 {
        score += (fitting_bins_count as f64).ln() * 1.5 * (1.0 - progress);
    }

    // Coupling with mean residual: prefer bins deviating smoothly from the mean.
    score += ((pr - mean_residual) / cap).powi(2) * 3.0 * (0.3 + 0.7 * progress);

    // Mild pressure to consolidate when many bins are open (smooth quadratic).
    score += (open_bins_count as f64).sqrt() * 0.4 * norm_pr;

    // New-bin candidate: make it moderately attractive only when current fits are bad.
    if bin_residual == bin_capacity {
        score = cap - item_size as f64;
        score += 2.0 * progress * (1.0 - norm_pr);
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Harmonic class of the post residual: how "usable" is the leftover space?
    // Class the residual into buckets of 10 (capacity fraction classes).
    let res_class = (post_residual / 10) as f64;
    let res_mod = (post_residual % 10) as f64;

    // Reward small post-residuals super-linearly (perfect fits are gold).
    if post_residual == 0 {
        score -= 100.0;
    } else if post_residual <= 5 {
        score -= 30.0 + 10.0 / post_residual as f64;
    } else if post_residual <= 10 {
        score -= 12.0;
    }

    // Penalize dead space in awkward harmonic classes (11..19, 31..39 etc.):
    // residuals just above a small item size are hard to fill.
    let awkward = (11..=19).contains(&post_residual)
        || (31..=34).contains(&post_residual)
        || (41..=44).contains(&post_residual)
        || (61..=64).contains(&post_residual);
    if awkward {
        score += 15.0;
    }

    // Lookahead coupling: does the leftover post_residual fit the next item?
    if next_item_size > 0 {
        if post_residual >= next_item_size {
            // Great: bin stays useful for the next item.
            let slack = (post_residual - next_item_size) as f64;
            score -= 20.0 - 0.2 * slack;
            // Harmonic bonus if next item exactly fills the class boundary.
            if post_residual % 10 == next_item_size % 10 && post_residual >= next_item_size {
                score -= 8.0;
            }
        } else if post_residual > 0 {
            // Leftover too small for the lookahead item: dead space risk.
            score += 10.0 + 0.3 * (next_item_size - post_residual) as f64;
        }
    } else {
        // Last item: minimize waste aggressively.
        score += 0.5 * post_residual as f64;
    }

    // Last-chance bin: strongly favor using it rather than opening a new bin.
    if fitting_bins_count == 1 && bin_residual >= item_size {
        score -= 25.0;
    }

    // Many fitting bins: prefer tightest fit, dampen the base residual signal.
    if fitting_bins_count > 2 {
        score *= 0.85;
    }

    // New-bin candidate handling: only attractive when open bins are fragmented
    // or this item barely fits anywhere.
    if bin_residual == bin_capacity {
        let progress = step_index as f64 / total_items.max(1) as f64;
        let fragmentation = (mean_residual - post_residual as f64).abs();
        // Base cost of opening a bin.
        score = bin_capacity as f64 * 0.9;
        // Attractive early in the stream or when open bins are nearly full.
        score -= 30.0 * (1.0 - progress);
        if mean_residual < 20.0 {
            score -= 25.0;
        }
        if fragmentation > 40.0 {
            score -= 10.0;
        }
        // Never open a new bin for a tiny item when decent space exists.
        if item_size < 30 && mean_residual > item_size as f64 * 2.0 {
            score += 60.0;
        }
    }

    // Mild penalty for very full bins being consumed early in the stream,
    // keeping flexibility, unless the fit is near-perfect.
    let fill = (bin_capacity - bin_residual) as f64 / bin_capacity as f64;
    if fill > 0.9 && post_residual > 0 {
        score += 5.0 * res_mod * 0.1;
    }

    score += 0.01 * res_class;

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Strict dead-space avoidance: residuals that are too small to ever
    // accept a meaningful future item (below the minimum plausible size)
    // are pure waste — penalize them heavily.
    if post_residual > 0 && post_residual < 10 {
        score += 40.0 + (10.0 - post_residual as f64) * 6.0;
    }

    // Reward near-perfect fits (tight packing).
    if post_residual == 0 {
        score -= 60.0;
    } else if post_residual <= 5 {
        score -= 25.0;
    }

    // Reward residuals that can still accommodate the lookahead item,
    // otherwise penalize creating a gap that blocks the next item.
    if next_item_size > 0 {
        if post_residual >= next_item_size {
            score -= 12.0;
        } else {
            score += 8.0;
        }
    }

    // Open-bin pressure: discourage spreading across many bins; the
    // pressure grows superlinearly with the number of open bins.
    score += (open_bins_count as f64).powf(1.35) * 2.0;

    // Last-chance bin: strongly favor using the only bin that fits,
    // to avoid opening a new bin unnecessarily.
    if fitting_bins_count == 1 && bin_residual < bin_capacity {
        score -= 30.0;
    }

    // Progress-aware calibration: early in the stream, prefer compact
    // placement (keep bins closed); late in the stream, tolerate using
    // existing slack since fewer items remain.
    let progress = if total_items > 0 { step_index as f64 / total_items as f64 } else { 0.0 };
    score -= progress * 10.0;

    // Mean-residual coupling: if this bin's residual deviates from the
    // mean, prefer bins with larger residuals (absorb big gaps early).
    let bin_res_f = bin_residual as f64;
    if bin_res_f > mean_residual {
        score -= (bin_res_f - mean_residual) * 0.15;
    } else {
        score += (mean_residual - bin_res_f) * 0.10;
    }

    // New-bin candidate: neutral-ish baseline; opening a new bin is
    // penalized mildly so it only wins when fits are truly poor.
    if bin_residual == bin_capacity {
        score += 20.0;
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Exact fit reward
    if post_residual == 0 {
        score -= 1000.0;
    }

    // 2-step lookahead: perfect pair match
    if next_item_size > 0 && post_residual == next_item_size {
        score -= 500.0;
    }

    // Penalize residuals that are too small to hold any item (dead space)
    if post_residual > 0 && post_residual < 1 {
        score += 100.0;
    }

    // Small post residual is good (tight fit); scale relative to mean residual
    score -= (mean_residual - post_residual as f64) * 0.5;

    // Penalize bins whose residual is far above mean (wasteful bins)
    if post_residual as f64 > mean_residual {
        score += (post_residual as f64 - mean_residual) * 0.25;
    }

    // Last-chance bin: strongly favor using it to avoid opening a new bin
    if fitting_bins_count == 1 {
        score -= 200.0;
    }

    // New-bin candidate: penalize opening a new bin unless current bins fit poorly
    if bin_residual == bin_capacity {
        score += 50.0;
        // If item leaves huge residual in a fresh bin AND lookahead matches, still fine
        if next_item_size > 0 && (bin_capacity - item_size) >= next_item_size {
            score -= 20.0;
        }
        // Prefer new bin when item is large and leaves little usable space elsewhere
        if item_size >= bin_capacity * 3 / 4 {
            score -= 30.0;
        }
    }

    // Early in stream: be more conservative with new bins (pack tighter later)
    let progress = step_index as f64 / total_items.max(1) as f64;
    score -= progress * 10.0;

    // Reward fitting into bins with more open bins available (consolidation)
    score -= (open_bins_count as f64).ln().max(0.0);

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Reward tight fits: shrink score as post_residual approaches 0.
    let tightness = 1.0 - (post_residual as f64 / bin_capacity as f64);
    score -= 30.0 * tightness * tightness;

    // Penalize dead space that cannot plausibly be reused by future items.
    if post_residual > 0 && post_residual < 10 {
        score += 25.0; // tiny unusable sliver
    }

    // Lookahead: if the next item fits exactly in the post-residual, reward strongly.
    if next_item_size > 0 && post_residual >= next_item_size {
        let next_fit_quality = (post_residual - next_item_size) as f64;
        score -= 12.0 * (1.0 - next_fit_quality / bin_capacity as f64);
    } else if next_item_size > 0 && next_item_size > post_residual {
        // Next item won't fit here anyway; mild penalty for wasting space now.
        score += 4.0 * (post_residual as f64 / bin_capacity as f64);
    }

    // Last-chance bin: strongly favor using it to avoid opening a new bin.
    if fitting_bins_count == 1 {
        score -= 20.0;
    }

    // Prefer filling bins whose residual deviates below the mean (consolidate emptier space).
    let dev = bin_residual as f64 - mean_residual;
    score += 0.15 * dev;

    // Time horizon: late in the stream, be more conservative about waste.
    let progress = if total_items > 0 { step_index as f64 / total_items as f64 } else { 0.0 };
    score += 10.0 * progress * (post_residual as f64 / bin_capacity as f64);

    // New-bin candidate handling: opening a fresh bin is attractive early or when
    // many bins are open (fragmentation risk), but costly late in the stream.
    if bin_residual == bin_capacity {
        let new_bin_cost = 15.0 + 40.0 * progress + 0.5 * open_bins_count as f64;
        score += new_bin_cost;
        // But if this bin is the only fitting option's alternative (crowding), allow it.
        if fitting_bins_count <= 1 {
            score -= 10.0;
        }
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let progress = step_index as f64 / total_items.max(1) as f64;
    let pr = post_residual as f64;
    let cap = bin_capacity as f64;
    let norm_pr = pr / cap;

    // Base: prefer small post-residual, with non-linear shaping
    let mut score = pr * (1.0 + 0.8 * norm_pr * norm_pr);

    // Smooth polynomial coupling of post_residual with stream progress:
    // late in the stream, waste is more costly; early, tighter fits matter less
    let coupling = 1.0 + 1.5 * progress * progress + 0.5 * progress;
    score *= coupling;

    // Perfect-fit reward (smooth, non-linear)
    if post_residual == 0 {
        score -= 40.0 + 30.0 * progress;
    } else {
        // penalize residuals that are too small to ever be useful
        let min_next = 1.0f64;
        let usable = (pr - min_next).max(0.0) / cap;
        score -= 20.0 * usable * usable * (1.0 - progress);
    }

    // Lookahead: reward if next item fits the post-residual
    if next_item_size > 0 && (next_item_size as f64) <= pr {
        let fit_quality = (pr - next_item_size as f64) / cap;
        score -= 15.0 * (1.0 - fit_quality) * (1.0 + progress);
    } else if next_item_size > 0 {
        score += 6.0 * (1.0 - progress);
    }

    // Last-chance bin bonus: strongly favor the only bin that can fit
    if fitting_bins_count == 1 && bin_residual != bin_capacity {
        score -= 25.0;
    }

    // New-bin candidate handling: prefer opening a new bin early or when
    // existing residuals are already large and fragmented
    if bin_residual == bin_capacity {
        let fragmentation = (mean_residual / cap).clamp(0.0, 1.0);
        let open_penalty = (open_bins_count as f64).ln().max(0.0);
        let new_bin_cost = 10.0 + 8.0 * open_penalty * (1.0 - progress);
        score = new_bin_cost + 60.0 * fragmentation * progress;
        if next_item_size > 0 && next_item_size >= item_size {
            score -= 12.0;
        }
    } else {
        // mild penalty for using bins when many are open (spread vs. compact tradeoff)
        score += 0.3 * (open_bins_count as f64).sqrt();
        // favor bins below mean residual (compact bins first)
        score += 0.2 * (bin_residual as f64 - mean_residual);
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Harmonic class of post_residual: modulo-10 classes group residuals into
    // "dead-space bands". Residuals that are small multiples of 10 are more
    // reusable (many item sizes are multiples of 10), so reward them.
    let class = post_residual % 10;
    let class_bonus: f64 = match class {
        0 => 12.0,   // perfect harmonic class: highly reusable
        5 => 6.0,    // half-harmonic: moderately reusable
        1 | 9 => 2.0,
        2 | 8 => 0.0,
        _ => -3.0,   // awkward classes: penalize (odd dead space)
    };
    score -= class_bonus;

    // Integer-division threshold on post_residual: residuals <= 10 are
    // essentially dead space (min item size 1, but tiny slots rarely used).
    if post_residual <= 10 {
        score -= 15.0; // finishing a bin cleanly is excellent
    } else if post_residual <= 20 {
        score -= 6.0;
    } else if post_residual > 60 {
        score += 8.0; // leaving a huge hole suggests a bad pairing
    }

    // Coupling with lookahead: if next item fits exactly into the post
    // residual, this is a perfect chain — strong reward.
    if next_item_size > 0 {
        if next_item_size == post_residual {
            score -= 25.0;
        } else if next_item_size < post_residual {
            let slack = post_residual - next_item_size;
            // harmonic quality of the chained remainder
            if slack % 10 == 0 { score -= 8.0; }
            score -= (slack.min(30) as f64) * 0.15;
        } else {
            // next item won't fit here; slight penalty proportional to waste
            score += 2.0;
        }
    }

    // Last-chance bin: if this is the only bin that fits, strongly prefer it
    // to avoid opening a new bin.
    if fitting_bins_count == 1 && bin_residual < bin_capacity {
        score -= 20.0;
    }

    // New-bin candidate (bin_residual == bin_capacity): accept it only when
    // the item is large or the stream is early. Opening fresh with big items
    // preserves flexibility for later small items.
    if bin_residual == bin_capacity {
        let progress = step_index as f64 / (total_items.max(1) as f64);
        let large_item = (item_size as f64 / bin_capacity as f64) > 0.6;
        if large_item || open_bins_count == 0 {
            score -= 14.0 + 10.0 * (1.0 - progress);
        } else {
            score += 10.0 + 15.0 * progress;
        }
    }

    // Mean-residual coupling: when open bins are already tight on average,
    // prefer placements that keep residuals harmonically small.
    if mean_residual > 0.0 && bin_residual < bin_capacity {
        let tightness = mean_residual / bin_capacity as f64;
        score -= (bin_residual as f64 / bin_capacity as f64) * tightness * 5.0;
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Strict dead-space avoidance: tiny gaps are almost unusable.
    if post_residual > 0 && post_residual < 10 {
        score += 40.0 * (10.0 - post_residual as f64);
    }
    // Perfect fit: strong reward.
    if post_residual == 0 {
        score -= 60.0;
    } else {
        // Reward tight fits proportionally.
        score -= 30.0 * (1.0 - post_residual as f64 / bin_capacity as f64);
    }

    // Lookahead: if next item fits exactly in the post residual, big reward.
    if next_item_size > 0 && post_residual >= next_item_size {
        let slack = post_residual - next_item_size;
        if slack < 10 {
            score -= 35.0;
        } else {
            score -= 10.0;
        }
    } else if next_item_size > post_residual && post_residual > 0 {
        // Residual cannot host next item: mild penalty.
        score += 8.0;
    }

    // Open-bin pressure: discourage spreading when many bins already open.
    score += 2.0 * open_bins_count as f64;

    // Last-chance bin: strongly favor using it before opening a new one.
    if fitting_bins_count == 1 && bin_residual < bin_capacity {
        score -= 50.0;
    }

    // New-bin candidate: only attractive when item is huge relative to capacity
    // or current bins are badly fragmented.
    if bin_residual == bin_capacity {
        let fragmentation = (mean_residual - bin_capacity as f64).abs();
        let pressure = open_bins_count as f64 / (fitting_bins_count.max(1) as f64);
        score -= 20.0 + 5.0 * pressure;
        if item_size as f64 > 0.8 * bin_capacity as f64 {
            score -= 15.0;
        }
        if fragmentation > 30.0 {
            score -= 10.0;
        }
        // Penalize opening new bins early in the stream.
        score += 30.0 * (1.0 - step_index as f64 / (total_items.max(1) as f64));
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Aggressive 2-step lookahead: reward exact match of post_residual to next item
    if next_item_size > 0 {
        let diff = (post_residual as i64 - next_item_size as i64).abs() as f64;
        score -= 45.0 * (1.0 - diff / (bin_capacity as f64)) * (post_residual as f64 / bin_capacity as f64);
        // Perfect 2-chain: item + next item exactly fill the bin
        if post_residual == next_item_size {
            score -= 60.0;
        }
        // Penalize leaving residual that next item cannot use at all
        if next_item_size > post_residual && post_residual > 0 {
            let waste = post_residual as f64 * (next_item_size as f64 - post_residual as f64) / bin_capacity as f64;
            score += 25.0 * waste / 10.0;
        }
    } else {
        // Last item: prefer tightest fit
        score += 0.0;
    }

    // Relative to mean residual: prefer bins with residual below average (tighter bins)
    score += 0.35 * (bin_residual as f64 - mean_residual);

    // Last-chance bin: strongly favor using it to avoid opening a new bin
    if fitting_bins_count == 1 && bin_residual != bin_capacity {
        score -= 30.0;
    }

    // Penalize opening a new bin when it would be sparsely used early in stream
    let progress = step_index as f64 / (total_items.max(1) as f64);
    if bin_residual == bin_capacity {
        score += 12.0 * (1.0 - progress) + 0.15 * open_bins_count as f64;
        // New bin is fine if current item is large relative to capacity
        score -= 0.25 * item_size as f64;
    }

    // Discourage large dead space that few items can fit
    if post_residual > 0 && post_residual < 10 {
        score += 8.0; // tiny unusable slivers
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Strong preference for tight fits (best-fit core).
    let tightness = 1.0 - (post_residual as f64 / bin_capacity as f64);
    score -= 45.0 * tightness * tightness;

    // Penalize small unusable dead space: residual below typical small item threshold.
    if post_residual > 0 && post_residual < 10 {
        score += 30.0;
    } else if post_residual >= 10 && post_residual < 20 {
        score += 8.0;
    }

    // Lookahead: reward bins whose post-residual can host the next item exactly well.
    if next_item_size > 0 {
        if post_residual >= next_item_size {
            let chain_fit = 1.0 - ((post_residual - next_item_size) as f64 / bin_capacity as f64);
            score -= 12.0 * chain_fit;
        } else {
            // Post-residual too small for next item: dead space risk, but small leftover ok.
            score += 3.0;
        }
    }

    // Last-chance bonus: if this is the only fitting bin, strongly favor using it.
    if fitting_bins_count == 1 && bin_residual < bin_capacity {
        score -= 25.0;
    }

    // New-bin candidate handling: make empty bins moderately attractive only when
    // open bins are fragmented or the item fits nowhere tightly.
    if bin_residual == bin_capacity {
        let progress = step_index as f64 / total_items.max(1) as f64;
        let fragmentation = (mean_residual - post_residual as f64).abs();
        // Prefer new bin when mean residual is high (open bins are full-ish) or many bins open.
        score -= 5.0 + 10.0 * (mean_residual / bin_capacity as f64) + 2.0 * (open_bins_count as f64).ln() * progress;
        // But discourage opening new bins if this item would leave huge waste vs fragmentation.
        if post_residual as f64 > fragmentation + 20.0 {
            score += 15.0;
        }
    }

    // Mild penalty for wasting space in bins far below the mean residual (poor global harmony).
    score += 0.15 * (post_residual as f64 - mean_residual).abs();

    // Slight time decay: early in stream, be conservative with new bins (handled above);
    // late in stream, pack tighter.
    let progress = step_index as f64 / total_items.max(1) as f64;
    score *= 1.0 + 0.1 * progress;

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let progress = step_index as f64 / total_items as f64;
    let pr = post_residual as f64;
    let cap = bin_capacity as f64;
    let norm_pr = pr / cap;
    let item = item_size as f64;
    let next = next_item_size as f64;

    // Base: prefer small post-residual, with non-linear (quadratic/cubic) shaping
    let mut score = pr * (1.0 + 0.8 * norm_pr * norm_pr);

    // Smooth coupling of post-residual with stream progress:
    // early on, waste is cheap; later, waste is penalized more strongly
    score += 20.0 * norm_pr * norm_pr * (0.5 + progress);

    // Reward exact-ish fits with a smooth saturating term
    let fit_quality = 1.0 - norm_pr;
    score -= 10.0 * fit_quality * fit_quality * fit_quality;

    // Interaction: if the next item fits into post_residual, reward this bin smoothly
    if next > 0.0 {
        let gap = pr - next;
        if gap >= 0.0 {
            let ng = gap / cap;
            score -= 8.0 * (1.0 - ng * ng);
        } else {
            score += 0.02 * (-gap);
        }
    }

    // Last-chance bonus: smooth reward when this is the only fitting bin
    if fitting_bins_count == 1 {
        score -= 5.0 * (1.0 + progress);
    }

    // Slight penalty for spreading across many open bins, smoothed with mean residual
    score += 0.05 * open_bins_count as f64 * (mean_residual / cap);

    // Mild preference toward fuller bins as stream progresses (smooth sigmoid-like weight)
    score -= progress * item * 0.05;

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Harmonic class of post_residual: residues divisible into fine classes.
    // Perfect fits (post_residual == 0) get a strong reward.
    if post_residual == 0 {
        score -= 60.0;
    } else {
        // Classify dead space by integer division thresholds on capacity fractions.
        let cap_q = post_residual / (bin_capacity / 4); // 0..4 classes
        score += match cap_q {
            0 => 8.0,   // tiny sliver, nearly useless
            1 => 4.0,   // quarter-class residual, still usable for small items
            2 => 0.0,   // half-class, moderate
            _ => -2.0,  // large residual, fine
        };

        // Modulo arithmetic on post_residual: penalize awkward residues
        // (residuals that rarely match typical item sizes).
        let r = post_residual % 10;
        if r != 0 && r < 3 {
            score += 3.0; // awkward sliver like 1-2 units
        }

        // Lookahead: reward bins whose post_residual can host next_item_size.
        if next_item_size > 0 && post_residual >= next_item_size {
            score -= 12.0;
            // Extra harmonic coupling: post_residual exactly equals next item
            // (perfect chained fit).
            if post_residual == next_item_size {
                score -= 10.0;
            }
        } else if next_item_size > 0 && post_residual > 0 {
            score += 5.0; // dead end for the lookahead item
        }
    }

    // Last-chance bin: strongly favor using it to avoid opening a new bin.
    if fitting_bins_count == 1 && bin_residual < bin_capacity {
        score -= 25.0;
    }

    // New-bin candidate (empty bin): penalize so we prefer existing bins,
    // unless current fit would waste a lot (large post_residual on a small item).
    if bin_residual == bin_capacity {
        let waste = post_residual as f64;
        // Opening a new bin is attractive if the best existing fit would leave
        // more waste than (capacity - item) itself... but base cost of a new bin:
        score += 30.0;
        // If item is huge relative to capacity, new bin gives near-perfect fit;
        // counteract the base penalty proportionally.
        score -= waste * 0.4;
        // Late in the stream, be more conservative about opening bins.
        let progress = step_index as f64 / total_items.max(1) as f64;
        score += 15.0 * progress;
    }

    // Mild preference for fuller bins when many bins are open (reduce spread).
    score += (mean_residual - post_residual as f64) * 0.05;

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Strict dead-space avoidance: residuals too small for the smallest
    // plausible future item (<= 10) are pure waste; punish them hard.
    let dead_threshold = 10u32;
    if post_residual < dead_threshold {
        score += 60.0 * (dead_threshold - post_residual) as f64;
    } else if post_residual == 0 {
        // Perfect fit: strong reward.
        score -= 100.0;
    } else {
        // Usable gap: mild reward scaled by how well it could host the
        // lookahead item exactly.
        if next_item_size > 0 && post_residual >= next_item_size {
            score -= 8.0 + 0.05 * next_item_size as f64;
        }
    }

    // Tightness reward: the larger the fraction of the bin consumed,
    // the better (classic best-fit flavor, nonlinear).
    let fill = item_size as f64 / bin_capacity as f64;
    score -= 25.0 * fill * fill;

    // Open-bin pressure: discourage spreading across many bins unless
    // the fit is genuinely tight.
    score += 1.5 * open_bins_count as f64;

    // Mean-residual coupling: if this bin's residual is far below the
    // mean, it is already fragmented; prefer filling fragmented bins
    // rather than clean ones.
    let dev = mean_residual - bin_residual as f64;
    score += 0.3 * dev;

    // Last-chance bin: if this is the only bin that fits, strongly
    // prefer it over opening a new bin.
    if fitting_bins_count == 1 && bin_residual != bin_capacity {
        score -= 40.0;
    }

    // New-bin candidate: only attractive when the item leaves a large,
    // useful residual or no open bin fits well. Penalize opening a new
    // bin when tight fits exist elsewhere.
    if bin_residual == bin_capacity {
        score += 15.0 + 0.4 * open_bins_count as f64;
        if next_item_size > 0 && post_residual >= next_item_size {
            score -= 12.0;
        }
        if post_residual < dead_threshold {
            score += 30.0; // opening a bin that immediately dies
        }
    }

    // Late-stream consolidation: near the end, close out bins rather
    // than opening new ones.
    let progress = step_index as f64 / total_items as f64;
    if progress > 0.85 && bin_residual != bin_capacity {
        score -= 10.0 * progress;
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Aggressive 2-step lookahead: reward exact/near matches between post_residual
    // and the next item's size (this bin will be filled again next step).
    if next_item_size > 0 && post_residual > 0 {
        let diff = (post_residual as i64 - next_item_size as i64).abs() as f64;
        // Strong reward when next item fits exactly into the leftover space.
        if post_residual == next_item_size {
            score -= 40.0;
        } else if next_item_size <= post_residual {
            // Next item fits: reward proportional to tightness of the fit.
            score -= 30.0 * (1.0 - diff / bin_capacity as f64);
        } else {
            // Next item does not fit the leftover: mild penalty for dead space.
            score += 5.0 + diff / bin_capacity as f64 * 10.0;
        }
    }

    // Tight fit reward: penalize large post_residual relative to bin capacity
    // (wasting space), scaled by stream progression.
    let progress = step_index as f64 / total_items.max(1) as f64;
    score += (post_residual as f64 / bin_capacity as f64) * (10.0 + 15.0 * progress);

    // Compare against mean residual across open bins: prefer bins with residual
    // close to the item (best-fit flavor) and penalize outliers.
    let res = bin_residual as f64;
    if mean_residual > 0.0 {
        let rel = (res - mean_residual) / mean_residual;
        score += rel * 8.0;
    }

    // Last-chance bin: if this is the only bin that can fit the item, favor it
    // strongly to avoid opening a new bin.
    if fitting_bins_count == 1 && bin_residual != bin_capacity {
        score -= 25.0;
    }

    // New-bin candidate: only open a new bin when no open bin offers a decent fit
    // (i.e., when the item would leave a very large residual elsewhere or there
    // are no fitting bins). Otherwise penalize opening new bins.
    if bin_residual == bin_capacity {
        if fitting_bins_count == 0 {
            score -= 20.0; // no alternative: open new bin
        } else if post_residual as f64 > mean_residual + item_size as f64 * 0.5 {
            // Existing bins fit poorly (large leftovers), new bin may be better.
            score -= 12.0;
        } else {
            score += 30.0; // prefer reusing existing bins
        }
    }

    // Mild penalty for many open bins: encourage consolidation.
    score += open_bins_count as f64 * 0.3;

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Reward tight fits: post_residual is the base; amplify small post_residual advantage.
    let frac = post_residual as f64 / bin_capacity as f64;
    score += frac * frac * 40.0;

    // Penalize dead space that nothing can use (items are >= 1, so post_residual == 0 is perfect).
    if post_residual > 0 {
        score += 6.0;
    }

    // Last chance: strongly favor using the only bin that fits, avoiding a new bin.
    if fitting_bins_count == 1 && bin_residual >= item_size {
        score -= 25.0;
    }

    // Lookahead: reward bins whose post_residual can host the next item.
    if next_item_size > 0 && post_residual >= next_item_size {
        score -= 12.0;
    } else if next_item_size > 0 && post_residual > 0 {
        // Penalize leaving a gap too small for the next item (likely dead space).
        score += (next_item_size as f64 - post_residual as f64).max(0.0) * 0.3;
    }

    // Prefer fuller bins relative to the fleet's mean residual.
    score -= (mean_residual - bin_residual as f64) * 0.25;

    // Early in the stream, allow opening new bins more freely; late, prefer consolidation.
    let progress = if total_items > 0 { step_index as f64 / total_items as f64 } else { 0.0 };
    if bin_residual == bin_capacity {
        // New-bin candidate: base penalty so it's chosen only when open bins fit poorly.
        score = 55.0 + 30.0 * (1.0 - progress);
        // If no open bin can fit, opening a new bin is necessary.
        if fitting_bins_count == 0 {
            score -= 100.0;
        }
        // Lookahead: an empty bin can host anything, slight bonus late when consolidation matters.
        if next_item_size > 0 && next_item_size >= item_size {
            score += 5.0 * progress;
        }
    }

    // Mild penalty for spreading across many open bins late in the stream.
    score += open_bins_count as f64 * 0.15 * progress;

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let progress = if total_items > 0 { step_index as f64 / total_items as f64 } else { 0.0 };
    let cap = bin_capacity as f64;
    let pr = post_residual as f64;
    let norm_pr = pr / cap;

    // Base: quadratic penalty on post residual (waste), modulated by stream progress.
    let mut score = norm_pr * norm_pr * (1.0 + 0.8 * progress) * 100.0;

    // Smooth cubic coupling: large residuals matter more late in the stream.
    score += norm_pr.powi(3) * (30.0 + 70.0 * progress);

    // Reward tight fits (small post residual) more strongly as stream progresses.
    score -= (1.0 - norm_pr).powi(2) * (10.0 + 20.0 * progress);

    // Penalize bins whose residual deviates from mean residual (fragmentation signal),
    // smoothly weighted by progress.
    let dev = (pr - mean_residual) / cap;
    score += dev * dev * (5.0 + 15.0 * progress);

    // Lookahead: if the next item fits into the post residual, reward this bin;
    // smooth sigmoid-like factor via normalized gap.
    if next_item_size > 0 {
        let gap = (pr - next_item_size as f64) / cap;
        if gap >= 0.0 {
            score -= (gap / (1.0 + gap)) * (8.0 + 12.0 * progress);
        } else {
            score += (-gap / (1.0 - gap)) * (4.0 + 6.0 * progress);
        }
    }

    // Last-chance bonus: if this is the only fitting bin, strongly discourage
    // opening a new bin unless the fit is terrible (smooth interaction).
    if fitting_bins_count == 1 && bin_residual != bin_capacity {
        let fit_quality = (1.0 - norm_pr).max(0.0);
        score -= 15.0 + 25.0 * progress + 30.0 * fit_quality * fit_quality;
    }

    // New-bin candidate: mild penalty so empty bins are chosen only when
    // open bins would leave very poor fits; effect grows with progress.
    if bin_residual == bin_capacity {
        score += 20.0 + 30.0 * progress - 10.0 * (1.0 - progress);
    }

    // Mild penalty on excessive bin proliferation, smoothed by progress.
    score += (open_bins_count as f64).ln() * (2.0 + 4.0 * progress);

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let cap_f = bin_capacity as f64;
    let mut score = post_residual as f64;

    // Harmonic class of post_residual: integer division into bands of 10
    let post_class = post_residual / 10;
    // Dead-space penalty grows super-linearly for small but nonzero residuals
    // (residuals of 1..9 are nearly useless for items >= 10).
    if post_residual > 0 && post_residual < 10 {
        score += 25.0;
    } else if post_residual == 0 {
        // Perfect fit: strong reward
        score -= 30.0;
    }

    // Non-linear coupling: prefer bins whose post_residual class can host
    // a plausible next item. Lookahead harmony: if next item fits in the
    // post residual, reward; if next item barely misses, penalize.
    if next_item_size > 0 {
        if next_item_size <= post_residual {
            // Harmonic match: next item slots into this bin's leftover
            let slack = (post_residual - next_item_size) as f64;
            score -= 12.0 + 8.0 * (1.0 - slack / cap_f);
        } else {
            // Next item won't fit here; penalize proportionally to how close
            let miss = (next_item_size - post_residual) as f64;
            score += 4.0 + 6.0 * (miss / cap_f);
        }
    }

    // Modulo-arithmetic class: residuals congruent to 0 mod capacity/4 are
    // "harmonic" splits (25/50/75 leftover) — versatile for mid-size items.
    let quarter = bin_capacity / 4;
    if post_residual % quarter == 0 && post_residual > 0 {
        score -= 5.0;
    }
    // Odd/awkward residuals (prime-ish small classes) are less reusable
    if post_class >= 1 && post_class <= 2 && post_residual % 3 == 0 {
        score += 2.0;
    }

    // Last-chance bin: if this is the only bin that fits, strongly prefer
    // using it over opening a new bin (unless post fit is terrible).
    if fitting_bins_count == 1 {
        score -= 15.0;
    }

    // New-bin candidate handling: empty bin should only win when open bins
    // are crowded (high mean residual means little room left overall).
    if bin_residual == bin_capacity {
        // Base handicap so existing bins are usually preferred
        score += 10.0;
        // But if open bins are nearly full on average, opening is fine
        let crowded = mean_residual / cap_f;
        score -= 20.0 * crowded.max(0.0).min(1.0);
        // Late in the stream, avoid spawning bins for tiny gains
        let progress = step_index as f64 / total_items.max(1) as f64;
        score += 5.0 * progress;
        // If next item is large, a fresh bin preserves room for it
        if next_item_size > bin_capacity / 2 {
            score -= 8.0;
        }
    }

    // Mild preference for tighter bins overall (waste minimization)
    score += 0.05 * ((bin_residual as f64) - (post_residual as f64));

    // Slight penalty for fragmenting many open bins
    score += 0.01 * open_bins_count as f64;

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Strict dead-space penalty: small unusable gaps are the worst outcome.
    if post_residual > 0 && post_residual < 10 {
        score += 60.0;
    }
    // Zero residual is perfect packing.
    if post_residual == 0 {
        score -= 25.0;
    }

    // Dead space relative to capacity.
    score += (post_residual as f64 / bin_capacity as f64) * 20.0;

    // Open-bin pressure: prefer filling existing bins over opening new ones.
    score -= (open_bins_count as f64) * 2.0;

    // Last-chance bonus: if this is the only fitting bin, strongly prefer it.
    if fitting_bins_count == 1 && bin_residual != bin_capacity {
        score -= 40.0;
    }

    // Penalize new-bin candidate unless residuals of open bins are tight.
    if bin_residual == bin_capacity {
        score += 30.0 - mean_residual * 0.3;
        if post_residual < 10 && post_residual > 0 {
            score += 50.0; // opening a bin that will end with dead space
        }
    }

    // Lookahead: reward leaving room for the next item.
    if next_item_size > 0 && post_residual >= next_item_size {
        score -= 8.0;
    } else if next_item_size > 0 && post_residual > 0 {
        score += 5.0;
    }

    // Late in stream, tighten up: avoid spreading.
    let progress = step_index as f64 / total_items.max(1) as f64;
    score += progress * 5.0 * (post_residual as f64 / bin_capacity as f64);

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Strong reward: exact 2-step match (post_residual leaves room exactly for next item)
    if next_item_size > 0 {
        if post_residual == next_item_size {
            score -= 40.0;
        } else if post_residual >= next_item_size {
            // leftover after next item would also fit: penalize by slack
            score -= 8.0 * (1.0 - ((post_residual - next_item_size) as f64 / bin_capacity as f64));
        } else {
            // next item cannot fit here: penalize dead space nonlinearly
            let waste = (next_item_size - post_residual) as f64;
            score += 0.35 * waste * (1.0 + waste / bin_capacity as f64);
        }
    }

    // Reward tight fills relative to mean residual
    let pr = post_residual as f64;
    if pr < mean_residual {
        score -= 2.5 * (mean_residual - pr) / bin_capacity as f64;
    } else {
        score += 1.5 * (pr - mean_residual) / bin_capacity as f64;
    }

    // Last-chance bin: strongly favor using it to avoid opening a new bin
    if fitting_bins_count == 1 && bin_residual < bin_capacity {
        score -= 15.0;
    }

    // Penalize opening a brand-new bin unless it enables a very tight future chain
    if bin_residual == bin_capacity {
        score += 12.0;
        if next_item_size > 0 && post_residual >= next_item_size {
            score -= 6.0 * (1.0 - (post_residual - next_item_size) as f64 / bin_capacity as f64);
        }
        // late in the stream, avoid proliferating bins
        let progress = step_index as f64 / total_items.max(1) as f64;
        score += 8.0 * progress;
    }

    // Small penalty for very small residuals (unusable slivers)
    if post_residual < 10 && post_residual > 0 {
        score += 5.0;
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Progress through stream: early on, be picky; later, pack greedily.
    let progress = if total_items > 0 { step_index as f64 / total_items as f64 } else { 0.0 };

    // Perfect fit reward.
    if post_residual == 0 {
        score -= 500.0;
    } else {
        // Reward tight fits: fraction of residual consumed by the item.
        let fill_ratio = item_size as f64 / bin_residual as f64;
        score -= 120.0 * fill_ratio * fill_ratio;

        // Penalize small dead space that no future item (>=10) can use,
        // but only mildly early in the stream.
        if post_residual < 10 {
            score -= 200.0 * (1.0 - 0.5 * progress);
        } else {
            // Dead-space penalty grows with stream progress.
            score += (post_residual as f64 / bin_capacity as f64) * 60.0 * (0.5 + progress);
        }
    }

    // Lookahead: if the next item fits exactly into post_residual, strong reward.
    if next_item_size > 0 && next_item_size <= post_residual {
        if next_item_size == post_residual {
            score -= 250.0;
        } else {
            score -= 60.0 * (next_item_size as f64 / post_residual as f64);
        }
    } else if next_item_size > post_residual {
        // Next item won't fit here; if post_residual is unusable dead space, penalize.
        if post_residual < 10 {
            score += 80.0;
        } else {
            score += 20.0;
        }
    }

    // Last-chance bin: strongly favor using it rather than opening a new bin.
    if fitting_bins_count == 1 {
        score -= 150.0;
    }

    // Prefer bins below mean residual (i.e., more filled bins) to consolidate.
    score += (bin_residual as f64 - mean_residual) * 0.8;

    // Many open bins: encourage closing them out (favor tight placements more).
    if open_bins_count > 4 {
        score -= 2.0 * (post_residual as f64);
    }

    // New-bin candidate handling: an empty bin is attractive when no open bin
    // fits well (large item relative to residuals) or stream is early.
    if bin_residual == bin_capacity {
        // Base cost of opening a new bin, amortized over remaining stream.
        let remaining = (total_items.saturating_sub(step_index)) as f64;
        let amortized = 100.0 / (1.0 + remaining * 0.02);
        score = item_size as f64 + amortized;

        // If item is large and would leave a big hole in any open bin, new bin is good.
        if item_size as f64 > mean_residual {
            score -= 40.0;
        }
        // If this is the only fitting bin anyway, opening new bin is neutral-to-bad.
        if fitting_bins_count <= 1 {
            score += 120.0;
        }
        // Late in stream, avoid opening new bins.
        score += 150.0 * progress;
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let progress = if total_items > 0 { step_index as f64 / total_items as f64 } else { 0.0 };
    let cap = bin_capacity as f64;
    let post = post_residual as f64;
    let norm_post = post / cap; // 0..1 residual after placement

    // Base: prefer small post_residual (tight fit), with non-linear shaping.
    let mut score = norm_post * (1.0 + 2.0 * norm_post * (1.0 - norm_post));

    // Smooth polynomial coupling of tightness with stream progress:
    // early on, be more tolerant of loose fits; late, demand tight packing.
    let progress_coupling = progress * norm_post * norm_post;
    score += 8.0 * progress_coupling;

    // Reward using existing bins: penalize the new-bin candidate smoothly.
    let is_new_bin = (bin_residual as f64 - cap).abs() < 0.5;
    if is_new_bin {
        score += 6.0 + 10.0 * (1.0 - progress) * (1.0 - norm_post);
    } else {
        // Reward bins whose residual closely matches the item (smooth kernel).
        let fit_quality = 1.0 - ((bin_residual as f64 - item_size as f64) / cap).abs();
        score -= 3.0 * fit_quality * fit_quality;
    }

    // Last-chance bonus: if this is the only fitting bin, strongly favor it.
    if fitting_bins_count == 1 && !is_new_bin {
        score -= 12.0;
    }

    // Lookahead: if next item fits exactly into post_residual, reward heavily.
    if next_item_size > 0 {
        let gap = (post - next_item_size as f64).abs() / cap;
        score -= 5.0 * (1.0 - gap) * (1.0 - gap) * (1.0 - progress);
    }

    // Mild pressure to consolidate: fewer open bins relative to mean residual.
    score += 0.05 * (open_bins_count as f64).ln() * norm_post;
    score += 0.02 * (mean_residual - post).abs();

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Harmonic class of post_residual modulo common item-size divisors.
    let pr = post_residual;
    // Reward post-residuals that lie in "usable" harmonic classes:
    // multiples of 10 (common item sizes 10..80) are re-combinable.
    let mod10 = (pr % 10) as f64;
    score += mod10 * 0.8; // penalize off-class residuals (dead space)

    // Fine-grained harmonic classes modulo 5 and 4 for medium granularity.
    score += (pr % 5) as f64 * 0.3;
    score += (pr % 4) as f64 * 0.15;

    // Perfect-fit reward: post_residual zero is ideal.
    if pr == 0 {
        score -= 60.0;
    }

    // Tiny residual pockets are dead space: penalize 1..=5 leftovers.
    if pr > 0 && pr <= 5 {
        score += 25.0;
    }

    // Integer-division threshold: residual large enough for a "big" item (>= 50)
    let big_fits = pr / 50; // 0, 1 (or 2 if residual==100, i.e. new bin)
    score -= big_fits as f64 * 6.0;

    // Lookahead coupling: if next item fits exactly into post_residual, big reward.
    if next_item_size > 0 && next_item_size <= pr {
        let slack = (pr - next_item_size) as f64;
        if slack == 0.0 {
            score -= 45.0; // exact lookahead fit
        } else {
            score -= 12.0 - slack * 0.25;
            // harmonic match: next item leaves multiple-of-10 residual
            if ((pr - next_item_size) % 10) == 0 {
                score -= 8.0;
            }
        }
    } else if next_item_size > pr && next_item_size > 0 {
        // Next item won't fit here after placement: penalize mildly.
        score += 5.0;
    }

    // Last-chance bin: strongly favor using it to avoid opening a new bin.
    if fitting_bins_count == 1 {
        score -= 30.0;
    }

    // Congestion: many open bins with high mean residual -> prefer filling existing bins.
    let progress = step_index as f64 / (total_items.max(1) as f64);
    score -= mean_residual * 0.05 * (1.0 - progress);

    // New-bin candidate (residual == capacity): penalize unless item is huge
    // or no real alternative. Empty-bin residual minus item = post_residual.
    if bin_residual == bin_capacity {
        let frac = item_size as f64 / bin_capacity as f64;
        // Opening a new bin is good for large items (>= 3/4 capacity) or when
        // existing bins are fragmented (low mean residual).
        if frac >= 0.75 {
            score -= 20.0;
        } else {
            score += 18.0 + (1.0 - frac) * 25.0;
            if fitting_bins_count > 0 {
                score += 10.0;
            }
        }
        // Late in the stream, prefer closing out existing bins.
        score += progress * 15.0;
    }

    // Small penalty for very large post-residual waste relative to capacity.
    let waste_frac = post_residual as f64 / bin_capacity as f64;
    score += waste_frac * waste_frac * 10.0;

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Strict dead-space avoidance: small leftover gaps are nearly useless.
    if post_residual > 0 && post_residual < 10 {
        score += 40.0 - 2.0 * post_residual as f64; // gap of 1 is worst
    }

    // Perfect fit is golden.
    if post_residual == 0 {
        score -= 25.0;
    }

    // Reward tight fits relative to capacity.
    score -= 0.3 * (item_size as f64 / bin_capacity as f64) * 100.0;

    // Last chance bin: strongly prefer using it over opening a new bin.
    if fitting_bins_count == 1 && bin_residual != bin_capacity {
        score -= 30.0;
    }

    // Open-bin pressure: many open bins -> discourage spreading, favor filling.
    score += 0.15 * open_bins_count as f64;

    // New-bin candidate: make it attractive only when no open bin fits well.
    if bin_residual == bin_capacity {
        // baseline cost of opening a bin; rises with stream progress
        score = 55.0 + 20.0 * (step_index as f64 / total_items.max(1) as f64);
        // if this is the only fitting option, allow the new bin
        if fitting_bins_count == 1 {
            score -= 40.0;
        }
        // lookahead: if next item is large, a fresh bin is more valuable
        if next_item_size > 50 {
            score -= 10.0;
        }
    } else {
        // Lookahead synergy: placing here leaves room for the known next item.
        if next_item_size > 0 && post_residual as f64 >= next_item_size as f64 {
            score -= 5.0;
        }
        // Penalize bins far below mean residual (wasting fuller bins is bad? inverse:
        // prefer filling the emptiest bins first to consolidate)
        if (bin_residual as f64) > mean_residual {
            score -= 3.0;
        }
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Base: prefer tight fit via post_residual (already in score).

    // Aggressive 2-step lookahead: reward when next item exactly fills post_residual
    if next_item_size > 0 {
        let post = post_residual as f64;
        let nxt = next_item_size as f64;
        if post_residual == next_item_size {
            // Perfect chain: next item fills this bin completely
            score -= 60.0;
        } else if post_residual >= next_item_size {
            // Next item fits here too; reward proportional closeness
            let gap = post - nxt;
            score -= 40.0 * (1.0 - gap / bin_capacity as f64);
        } else {
            // Next item won't fit; penalize wasted potential
            let miss = nxt - post;
            score += 0.5 * miss.min(50.0);
        }
    }

    // Penalize large dead space if next item can't use it
    if post_residual > 0 && next_item_size > post_residual {
        score += 0.3 * post_residual as f64;
    }

    // Relative to mean residual: prefer bins tighter than average
    let post = post_residual as f64;
    if mean_residual > 0.0 {
        score += 0.4 * (post - mean_residual);
    }

    // Last-chance bin: strongly favor using it to avoid opening a new bin
    if fitting_bins_count == 1 && bin_residual != bin_capacity {
        score -= 25.0;
    }

    // New-bin candidate: penalize mildly unless current fit is terrible
    if bin_residual == bin_capacity {
        score += 20.0;
        // But if lookahead chains perfectly in a fresh bin, allow it
        if next_item_size > 0 && post_residual >= next_item_size {
            score -= 10.0;
        }
    }

    // Late in stream: be more conservative, keep bins tight
    let progress = step_index as f64 / total_items.max(1) as f64;
    score += progress * 0.2 * post;

    // Many open bins: discourage spreading, prefer filling existing ones
    if open_bins_count > 3 && bin_residual != bin_capacity {
        score -= 2.0;
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Reward tight fits: small post_residual is good, but only if not leaving
