        score -= 20.0;
    }

    // New-bin candidate: opening a new bin should only win when existing bins fit poorly.
    if bin_residual == bin_capacity {
        // base cost of opening a new bin
        score = bin_capacity as f64 * 0.6;
        // cheaper to open a new bin early in the stream (more future items to use it)
        let progress = if total_items > 0 { step_index as f64 / total_items as f64 } else { 0.0 };
        score *= 0.5 + progress;
        // if many bins are open with large mean residual, prefer reusing them
        score += (open_bins_count as f64).sqrt() * 2.0 + mean_residual * 0.15;
        // a big item into a fresh bin is fine (leaves room for more)
        if item_size >= bin_capacity / 2 {
            score -= 15.0;
        }
    } else {
        // Mild global pressure: when mean residual is low, conserve space (tight fits matter more)
        score += (mean_residual / bin_capacity as f64) * 5.0;
    }

    // Late in the stream, closing bins tightly matters more.
    let progress = if total_items > 0 { step_index as f64 / total_items as f64 } else { 0.0 };
    score -= (post_residual as f64 / bin_capacity as f64) * 10.0 * progress;

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let progress = if total_items > 0 { step_index as f64 / total_items as f64 } else { 0.0 };
    let mut score = post_residual as f64;

    // Non-linear polynomial coupling of post_residual with stream progress:
    // later in the stream, tighter fits (small post_residual) matter more.
    let pr = post_residual as f64 / bin_capacity as f64;
    let poly = pr * pr * (1.0 + 3.0 * progress) + 2.0 * progress * pr * (1.0 - pr);
    score += 20.0 * poly;

    // Reward when the next item fits exactly into the post residual (smooth gate).
    if next_item_size > 0 && post_residual >= next_item_size {
        let gap = (post_residual - next_item_size) as f64;
        let fit_quality = 1.0 - gap / bin_capacity as f64;
        score -= 12.0 * fit_quality * fit_quality * (0.5 + progress);
    }

    // Penalize waste when the next item cannot fit (dead space risk).
    if next_item_size > 0 && post_residual < next_item_size {
        score += 6.0 * (1.0 - post_residual as f64 / next_item_size as f64);
    }

    // Last-chance bin: strongly favor using it to avoid opening a new bin.
    if fitting_bins_count == 1 {
        score -= 15.0;
    }

    // Slight preference for consolidating into fewer bins.
    score += 0.05 * open_bins_count as f64;

    // Mild pull toward bins with residuals close to the mean (balanced packing).
    score += 0.1 * (bin_residual as f64 - mean_residual).abs();

    // New-bin candidate: keep it competitive only when existing fits are poor.
    if bin_residual == bin_capacity {
        score -= 8.0 + 10.0 * progress;
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Harmonic class of post_residual: bins whose leftover falls into "usable"
    // residue classes (multiples of common item sizes) are rewarded.
    let pr = post_residual;
    let harmonic_bonus: f64 = if pr == 0 {
        -60.0 // perfect fit: best possible outcome
    } else {
        let mut bonus = 0.0;
        // Residue classes modulo common item sizes (harmonic classes)
        if pr % 10 == 0 { bonus -= 18.0; }
        if pr % 20 == 0 { bonus -= 8.0; }
        if pr % 25 == 0 { bonus -= 6.0; }
        if pr % 50 == 0 { bonus -= 10.0; }
        // Dead-space penalty for small unusable remainders
        if pr < 10 { bonus += 45.0; }
        else if pr < 20 { bonus += 20.0; }
        bonus
    };
    score += harmonic_bonus;

    // Lookahead coupling: if the next item fits exactly in the post residual,
    // strongly favor this bin (chain fit).
    if next_item_size > 0 {
        if next_item_size == pr {
            score -= 55.0;
        } else if next_item_size <= pr {
            let slack = (pr - next_item_size) as f64;
            score -= 12.0 * (1.0 - slack / bin_capacity as f64);
            // penalize leaving a remainder the next item can't harmonize with
            if (pr - next_item_size) % 10 != 0 { score += 6.0; }
        } else {
            // next item won't fit here: mild penalty, bin likely closes
            score += 8.0;
        }
    }

    // Last-chance logic: if this is the only bin that fits, use it rather
    // than opening a new bin unless the fit is terrible.
    if fitting_bins_count == 1 && bin_residual != bin_capacity {
        score -= 25.0;
        if post_residual < 10 { score -= 10.0; } // closing a bin tightly is great
    }

    // New-bin candidate: penalize opening a new bin, but relax late in the
    // stream or when many bins are open and mean residual is low (fragmented).
    if bin_residual == bin_capacity {
        let progress = step_index as f64 / total_items.max(1) as f64;
        let fragmentation = 1.0 - (mean_residual / bin_capacity as f64).clamp(0.0, 1.0);
        score = 35.0 + 25.0 * fragmentation - 20.0 * progress;
        if next_item_size > 0 && next_item_size > bin_capacity - item_size {
            score += 15.0; // next item won't fit a fresh bin either way
        }
    }

    // Mild preference for tighter bins overall
    score += 0.05 * (bin_residual as f64 - post_residual as f64).recip();

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Strict dead-space avoidance: residuals too small for the smallest
    // plausible future item are "dead space" — penalize them hard.
    let dead_threshold = 12.0;
    if post_residual > 0 && (post_residual as f64) < dead_threshold {
        score += (dead_threshold - post_residual as f64) * 6.0;
    }
    // Perfect fit bonus.
    if post_residual == 0 {
        score -= 25.0;
    }

    // Reward tight fits: small post_residual relative to item size.
    if item_size > 0 {
        score -= 40.0 * (item_size as f64) / (bin_residual as f64 + 1.0);
    }

    // If this bin is the last chance to fit the item, strongly prefer it
    // over opening a new bin.
    if fitting_bins_count == 1 && bin_residual != bin_capacity {
        score -= 30.0;
    }

    // Lookahead: if next item fits exactly in the post residual, reward.
    if next_item_size > 0 {
        if next_item_size == post_residual {
            score -= 35.0;
        } else if next_item_size > post_residual {
            // next item won't fit here; large residual waste matters less
            score += 4.0;
        }
    }

    // Open-bins pressure: many open bins -> favor consolidating into
    // existing bins, penalize opening new ones.
    let progress = step_index as f64 / (total_items.max(1) as f64);
    let pressure = (open_bins_count as f64).ln() * 4.0;
    score += pressure * (0.5 + progress);

    // New-bin candidate handling: baseline for empty bin, adjusted by
    // pressure so it's chosen only when existing fits are bad.
    if bin_residual == bin_capacity {
        score += 55.0 + pressure * (0.5 + progress);
        // Opening a new bin is more attractive late in the stream when
        // mean residual across bins is small (bins are nearly full).
        score -= (mean_residual / bin_capacity as f64) * 20.0;
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Reward near-exact fits (post_residual close to zero).
    if post_residual == 0 {
        score -= 1000.0;
    } else if post_residual <= 5 {
        score -= 200.0;
    } else if post_residual <= 10 {
        score -= 80.0;
    }

    // Aggressive 2-step lookahead: if the next item fits exactly into post_residual,
    // strongly favor this bin (perfect 2-item packing).
    if next_item_size > 0 {
        if next_item_size == post_residual {
            score -= 1500.0;
        } else if next_item_size < post_residual {
            let slack = post_residual - next_item_size;
            if slack <= 10 {
                score -= 400.0 - (slack as f64) * 20.0;
            } else {
                // Penalize leaving a residual that the next item only partially fills,
                // scaled by how wasteful the leftover would be.
                score += (slack as f64) * 0.6;
            }
        } else {
            // Next item does NOT fit into post_residual: post_residual becomes dead
            // space (at least for the next step). Penalize proportionally, but less
            // if the residual is large enough to be useful later.
            if post_residual < 10 {
                score += 120.0;
            } else {
                score += 20.0;
            }
        }
    } else {
        // Last item: strongly prefer filling a bin as tightly as possible.
        score -= (bin_capacity - post_residual) as f64 * 2.0;
    }

    // Compare post_residual relative to mean residual across open bins.
    // Leaving a residual far below the mean creates an outlier sliver bin;
    // leaving one far above the mean suggests this bin is underused.
    score += (post_residual as f64 - mean_residual) * 0.35;

    // Last-chance bin: if this is the ONLY bin that can fit the item, avoid
    // opening a new bin unless the fit is terrible.
    if fitting_bins_count == 1 {
        score -= 150.0;
    }

    // New-bin candidate handling: an empty bin is a fresh resource. Prefer it
    // only when no open bin offers a good fit (large post_residual everywhere).
    if bin_residual == bin_capacity {
        // Mild penalty so open bins with decent fits win; the lookahead bonuses
        // above can overcome this when fits are poor.
        score += 90.0;
        // Late in the stream, opening fresh bins is less useful.
        let progress = step_index as f64 / total_items.max(1) as f64;
        score += progress * 60.0;
        // If many bins are open, discourage spreading further.
        score += open_bins_count as f64 * 3.0;
    }

    // Slight preference for consolidating into fewer bins when many are open.
    score += open_bins_count as f64 * 0.5;

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Reward tight fits strongly (small post_residual relative to capacity).
    let tightness = post_residual as f64 / bin_capacity as f64;
    score -= (1.0 - tightness) * 8.0;

    // Penalize unusable dead space: if next item cannot fit into post_residual.
    if next_item_size > 0 {
        if (post_residual as u32) < next_item_size {
            score += 6.0 + next_item_size as f64 * 0.05;
        } else {
            // Reward leaving room exactly useful for the next item.
            let slack = (post_residual as u32 - next_item_size) as f64;
            score -= (1.0 - slack / bin_capacity as f64).max(0.0) * 4.0;
        }
    } else {
        // Last item: prefer filling bins as fully as possible.
        score -= 10.0;
    }

    // Last-chance bonus: if this is the only bin that can fit the item,
    // strongly favor using it over opening a new bin.
    if fitting_bins_count == 1 && bin_residual < bin_capacity {
        score -= 12.0;
    }

    // Penalize opening new bins when plenty of open bins exist.
    if bin_residual == bin_capacity {
        let progress = step_index as f64 / total_items.max(1) as f64;
        score += 5.0 + 10.0 * (1.0 - progress) + open_bins_count as f64 * 0.3;
        // But if mean residual is small (open bins are nearly full), new bin is fine.
        score -= mean_residual * 0.05;
    }

    // Mild preference for bins with residual close to the current mean
    // (keeps residual distribution balanced).
    let dev = (bin_residual as f64 - mean_residual).abs();
    score += dev * 0.03;

    // Slight time horizon modulation: later in the stream, consolidate more.
    let progress = step_index as f64 / total_items.max(1) as f64;
    score += (1.0 - progress) * 2.0;

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    let progress = if total_items > 0 { step_index as f64 / total_items as f64 } else { 0.0 };
    let pr = post_residual as f64;
    let cap = bin_capacity as f64;

    // Non-linear polynomial coupling of post_residual with stream progress.
    // Early on: mildly discourage large residuals (keep bins flexible).
    // Later: strongly reward tight fits (small post_residual) since fewer
    // future items remain to fill leftover space.
    let tightness = 1.0 - (pr / cap).powi(2); // in (0,1], high for tight fits
    let coupling = tightness * (0.5 + 2.0 * progress * progress);

    score -= 8.0 * coupling;

    // Quadratic penalty on unusable dead space relative to mean residual.
    let dead = (pr - mean_residual) / cap;
    score += 4.0 * dead * dead;

    // Reward last-chance bins with a smooth saturating term.
    let last_chance = if fitting_bins_count <= 1 { 1.0 } else { 0.0 };
    score -= 6.0 * last_chance * (1.0 - (pr / cap).powi(3));

    // Lookahead: if next item fits the post-residual, reward this placement.
    if next_item_size > 0 && (next_item_size as f64) <= pr {
        score -= 5.0 * (1.0 - progress);
    }

    // Mild penalty for spreading across many open bins as stream progresses.
    score += (open_bins_count as f64).ln().max(0.0) * (1.0 + progress);

    // New-bin candidate: neutral-ish baseline with slight progress-dependent bias.
    if bin_residual == bin_capacity {
        score = cap * (1.0 - 0.3 * progress) + 2.0;
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Harmonic class of the post-residual: residues that are "usable"
    // for typical small items get rewarded, dead-space residues penalized.
    let cap = bin_capacity as f64;
    let pr = post_residual as f64;

    // Exact fit is perfect.
    if post_residual == 0 {
        score -= 1000.0;
    }

    // Modulo-class penalty: residuals that are awkward (e.g. 1..=5 dead space)
    // are heavily penalized; residuals in friendly classes (multiples of 10, 20)
    // are rewarded.
    let r = post_residual;
    if r > 0 && r <= 5 {
        score += 120.0; // near-dead space
    } else if r % 20 == 0 && r > 0 {
        score -= 60.0; // clean harmonic class
    } else if r % 10 == 0 && r > 0 {
        score -= 30.0;
    }

    // Integer-division thresholds: how many size-10 items still fit?
    let slots10 = (r / 10) as f64;
    score -= 8.0 * slots10;

    // Lookahead coupling: if the next item fits the post-residual exactly,
    // strongly reward this placement.
    if next_item_size > 0 && next_item_size == post_residual {
        score -= 400.0;
    } else if next_item_size > 0 && next_item_size <= post_residual {
        // partial harmony: next item fits with small leftover
        let left = post_residual - next_item_size;
        if left <= 5 {
            score -= 150.0;
        } else if left % 10 == 0 {
            score -= 80.0;
        }
    } else if next_item_size > post_residual {
        // next item cannot use this bin's remainder: penalize large leftovers
        score += 0.3 * pr;
    }

    // Last-chance bin: strongly favor using it before opening a new one.
    if fitting_bins_count == 1 && bin_residual < bin_capacity {
        score -= 250.0;
    }

    // New-bin candidate: penalize opening a new bin unless current residual
    // is truly tiny relative to capacity.
    if bin_residual == bin_capacity {
        score += 55.0;
        // but if the item is huge and next item is small, a fresh bin is fine
        if item_size >= 60 && next_item_size > 0 && next_item_size <= 20 {
            score -= 90.0;
        }
    }

    // Stream progression: late in the stream, prefer tighter packing.
    let progress = step_index as f64 / total_items.max(1) as f64;
    score += progress * 10.0 * (pr / cap);

    // Mean residual coupling: if this bin's residual is below mean, it's
    // already "used" — reward placing into tighter bins.
    let mean_gap = mean_residual - pr;
    if mean_gap > 0.0 {
        score -= 0.15 * mean_gap;
    }

    // Open-bin pressure: many open bins -> favor consolidation.
    score += 2.0 * open_bins_count as f64 * (pr / cap);

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Exact fit: perfect placement, strong reward.
    if post_residual == 0 {
        score -= 1000.0;
    }

    // Strict dead-space avoidance: residuals that are too small to be useful
    // (below the minimum item size of 1, effectively gaps <= 3) are heavily penalized.
    if post_residual > 0 && post_residual <= 3 {
        score += 250.0;
    } else if post_residual > 3 && post_residual <= 10 {
        score += 60.0;
    } else if post_residual > 10 && post_residual <= 25 {
        score += 15.0;
    }

    // Reward leaving a residual that exactly accommodates the lookahead item
    // (k=2 lookahead coupling).
    if next_item_size > 0 && post_residual == next_item_size {
        score -= 120.0;
    }
    // Penalize leaving a gap that cannot fit the next item but is small.
    if next_item_size > 0 && post_residual > 0 && post_residual < next_item_size {
        score += 20.0;
    }

    // Last-chance bin: strongly favor using the only bin that can fit the item
    // rather than opening a new bin.
    if fitting_bins_count == 1 && bin_residual < bin_capacity {
        score -= 80.0;
    }

    // Open-bin pressure: when many bins are open, prefer filling existing bins
    // over opening new ones; the new-bin candidate has bin_residual == bin_capacity
    // and thus gets no discount here.
    let progress = step_index as f64 / (total_items.max(1) as f64);
    if bin_residual < bin_capacity {
        score -= (open_bins_count as f64).sqrt() * 3.0 * (0.5 + progress);
    }

    // New-bin candidate calibration: only attractive when the current item is
    // large and would leave a big residual in any open bin, or when few bins fit.
    if bin_residual == bin_capacity {
        score += 40.0;
        if item_size >= 70 {
            score -= 30.0;
        }
        if fitting_bins_count == 0 {
            score -= 500.0;
        }
    }

    // Mild alignment with mean residual: prefer bins whose residual is close to
    // the mean (balanced packing), penalize outliers.
    let dev = (bin_residual as f64 - mean_residual).abs();
    score += dev * 0.1;

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Dead-space penalty: squared post-residual, normalized by capacity.
    let pr = post_residual as f64;
    score += 0.6 * (pr * pr) / bin_capacity as f64;

    // 2-step lookahead: reward exact/near match of post_residual to next item.
    if next_item_size > 0 {
        let nxt = next_item_size as f64;
        let diff = (pr - nxt).abs();
        if diff < 1.0 {
            score -= 40.0; // perfect chain: next item fills this bin exactly
        } else {
            score += 0.5 * diff; // mismatch penalty
        }
        // Penalize leaving residual too small for the next item (dead space).
        if pr > 0.0 && pr < nxt {
            score += 0.8 * pr;
        }
        // Reward residual large enough to host next item too.
        if pr >= nxt {
            score -= 3.0;
        }
    } else {
        // Last item: strongly prefer zero residual.
        score += 2.0 * pr;
    }

    // Relative-to-mean coupling: prefer bins tighter than average.
    score -= 0.3 * (mean_residual - pr);

    // Last-chance bonus: if this is the only fitting bin, avoid opening a new bin.
    if fitting_bins_count == 1 && bin_residual < bin_capacity {
        score -= 15.0;
    }

    // New-bin candidate handling: only attractive when no open bin fits well
    // (large item, few options) or stream is early.
    if bin_residual == bin_capacity {
        let progress = if total_items > 0 { step_index as f64 / total_items as f64 } else { 0.0 };
        let scarcity = if fitting_bins_count == 0 { 20.0 } else { 0.0 };
        // Base cost of a fresh bin grows with how much of it would sit idle.
        score += 10.0 + 0.2 * pr - scarcity - 5.0 * (1.0 - progress);
        // Opening a new bin is fine if the item is big relative to capacity.
        score -= 0.15 * item_size as f64;
    }

    // Slight preference for fuller bins overall.
    score -= 0.1 * item_size as f64;

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let score = (post_residual as f64) * 0.99;
    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let cap = bin_capacity as f64;
    let post = post_residual as f64;
    let progress = step_index as f64 / total_items as f64;

    // Base: penalize wasted residual quadratically (dead space grows in cost).
    let mut score = post * post / cap;

    // Reward tight fits: small post_residual relative to item size.
    let fill_ratio = item_size as f64 / cap;
    score -= fill_ratio * (cap - post) * 0.5;

    // Lookahead coupling: if next item fits in the post residual, reward this bin;
    // otherwise penalize leaving a residual that is almost-but-not-quite usable.
    if next_item_size > 0 {
        let nxt = next_item_size as f64;
        if nxt <= post {
            score -= (1.0 - post / cap) * nxt * 0.3;
        } else {
            let gap = (nxt - post) / cap;
            score += gap * gap * cap * 0.8;
        }
    }

    // Last-chance bonus: if this is the only bin that fits, strongly favor using it.
    if fitting_bins_count == 1 && bin_residual < bin_capacity {
        score -= cap * (0.5 + 0.5 * progress);
    }

    // Mean residual coupling: prefer bins whose residual deviates below the mean
    // (consolidate small leftovers), smoothly via tanh-like term.
    let dev = (bin_residual as f64 - mean_residual) / cap;
    score += dev * (1.0 + progress) * 10.0;

    // Stream-progress coupling: late in the stream, prefer packing into existing
    // bins over opening new ones (fewer bins at the end).
    score += (1.0 - progress) * (post / cap) * 15.0;

    // New-bin candidate: make an empty bin attractive only when its residual
    // genuinely beats alternatives; add a mild fixed opening cost that decays
    // with progress (late stream: reuse bins more aggressively).
    if bin_residual == bin_capacity {
        score += cap * (1.2 - 0.7 * progress);
    }

    // Mild penalty for spreading across many open bins.
    score += open_bins_count as f64 * 0.05;

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Harmonic class of post_residual: integer division thresholds (capacity = 100)
    let class = post_residual / 12; // 8 harmonic classes: 0..=8
    score += match class {
        0 => -40.0,                    // residual 0..11: nearly perfect fit, reward heavily
        1 => -18.0,                    // 12..23: still good
        2 => -6.0,                     // 24..35
        3 => 0.0,                      // 36..47 neutral
        4 => 8.0,                      // 48..59
        5 => 14.0,                     // 60..71
        6 => 20.0,                     // 72..83
        _ => 26.0,                     // 84..99: wasteful placement
    };

    // Modulo arithmetic on post_residual: odd/tiny slivers are dead space
    if post_residual > 0 && post_residual <= 9 {
        score += 22.0; // unusable sliver for most items
    }
    if post_residual % 2 == 1 && post_residual < 20 {
        score += 4.0;
    }

    // Lookahead coupling: does post_residual exactly fit the next item?
    if next_item_size > 0 {
        if next_item_size == post_residual {
            score -= 55.0; // perfect chain: reserve this bin for next item
        } else if next_item_size <= post_residual {
            score -= 10.0; // next item also fits: keep bin usable
        } else {
            score += 6.0;  // next item won't fit here: slight penalty for chaining
        }
        // harmonic class of next item vs post residual divisibility
        if post_residual % next_item_size.max(1) == 0 && next_item_size <= post_residual {
            score -= 8.0; // exact division: clean future packing
        }
    } else {
        // last item: only minimize waste
        score = post_residual as f64 - 60.0;
    }

    // Last-chance bin: strongly favor using it before opening a new bin
    if fitting_bins_count == 1 && bin_residual != bin_capacity {
        score -= 30.0;
    }

    // New-bin candidate: penalize so we only open when no decent fit exists
    if bin_residual == bin_capacity {
        score += 45.0 + 0.05 * open_bins_count as f64;
        // but allow opening if all fits would leave big waste
        if post_residual as f64 > mean_residual + 25.0 {
            score -= 20.0;
        }
        if fitting_bins_count == 0 {
            score -= 100.0; // must open a bin
        }
    }

    // Late in stream: consolidate, avoid spreading
    let progress = step_index as f64 / total_items.max(1) as f64;
    score += progress * 5.0 * (post_residual as f64 / bin_capacity as f64);

    // Prefer filling bins below mean residual (tighter bins first)
    if (bin_residual as f64) < mean_residual {
        score -= 5.0;
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Strict dead-space avoidance: small unusable gaps (<10) are heavily penalized.
    if post_residual > 0 && post_residual < 10 {
        score += 60.0;
    }
    // Medium dead space (10..=20) is only usable by small items; mild penalty.
    if post_residual >= 10 && post_residual <= 20 {
        score += 8.0;
    }

    // Reward tight fits (post_residual small but usable).
    if post_residual <= 5 && post_residual > 0 {
        score -= 25.0;
    }
    // Perfect fill.
    if post_residual == 0 {
        score -= 40.0;
    }

    // Last-chance bin: strongly favor using it before opening a new bin.
    if fitting_bins_count == 1 {
        score -= 35.0;
    }

    // Open-bin pressure: with many open bins, prefer consolidating into existing bins.
    let open_pressure = open_bins_count as f64;
    if bin_residual != bin_capacity {
        score -= open_pressure.min(20.0) * 1.5;
    } else {
        // New-bin candidate: penalize proportional to existing bins and mean residual availability.
        score += 15.0 + open_pressure * 2.0 + (mean_residual / 10.0).min(8.0);
    }

    // Lookahead coupling: if next item fits the post_residual, reward this placement.
    if next_item_size > 0 && post_residual >= next_item_size {
        score -= (next_item_size as f64) * 0.8;
    }
    // If next item would leave this bin's post_residual dead, penalize.
    if next_item_size > 0 && post_residual > 0 && post_residual < next_item_size && post_residual < 10 {
        score += 20.0;
    }

    // Stream progression: early on, be more willing to open bins (explore), later consolidate.
    let progress = step_index as f64 / (total_items.max(1) as f64);
    if bin_residual == bin_capacity {
        score -= (1.0 - progress) * 10.0;
    }

    // Mild preference for bins with low residual already (best-fit flavor).
    score += (bin_residual as f64) * 0.05;

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Reward tight fits: small post_residual relative to bin capacity.
    let tightness = 1.0 - (post_residual as f64 / bin_capacity as f64);
    score -= 8.0 * tightness;

    // 2-step lookahead: strongly reward if next item fits exactly or well into post_residual.
    if next_item_size > 0 {
        if post_residual >= next_item_size {
            let slack = (post_residual - next_item_size) as f64;
            // Perfect match for next item => big reward.
            if slack < 2.0 {
                score -= 30.0;
            } else {
                // Reward decays with slack; keep chain going.
                score -= 20.0 * (1.0 - slack / bin_capacity as f64);
            }
        } else {
            // Next item won't fit here: penalize leaving residual too small for next item.
            let gap = (next_item_size - post_residual) as f64;
            score += 0.3 * gap;
        }
    } else {
        // Last item: prefer minimal post_residual.
        score += 0.0;
    }

    // Compare against mean residual: placing into a below-average-residual bin
    // (a "tight" bin) is good; opening space in a loose bin wastes capacity.
    if (bin_residual as f64) < mean_residual {
        score -= 4.0;
    } else {
        score += 2.0;
    }

    // Last-chance bin: if this is the only bin that can fit the item, use it
    // to avoid opening a new bin.
    if fitting_bins_count == 1 && bin_residual != bin_capacity {
        score -= 15.0;
    }

    // New-bin candidate handling: only attractive when item is large relative
    // to capacity or no good open fit exists.
    if bin_residual == bin_capacity {
        // Slight penalty so open bins are preferred by default.
        score += 10.0;
        if item_size > bin_capacity / 2 {
            // Large items deserve fresh bins; discount the penalty.
            score -= 12.0;
        }
        if next_item_size > 0 && post_residual >= next_item_size {
            // Fresh bin also serves next item well.
            score -= 10.0;
        }
    }

    // Progression: late in the stream, consolidation matters more; avoid
    // leaving scattered residuals.
    let progress = step_index as f64 / total_items as f64;
    score += progress * (post_residual as f64 / bin_capacity as f64) * 6.0;

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;
    let progress = step_index as f64 / total_items.max(1) as f64;

    // Base: prefer tight fits (low post_residual).
    // Strong reward when the NEXT item also fits into the resulting gap (lookahead pairing).
    if next_item_size > 0 {
        if post_residual >= next_item_size {
            // Excellent: leaves room for the upcoming item.
            score -= 30.0 + 0.5 * (post_residual - next_item_size) as f64;
        } else {
            // Dead space that next item cannot use: penalize proportionally.
            score += 0.3 * (next_item_size - post_residual) as f64;
        }
    }

    // Last-chance bin: strongly favor using it to avoid opening a new bin.
    if fitting_bins_count == 1 && bin_residual < bin_capacity {
        score -= 25.0;
    }

    // New-bin candidate: penalize opening bins unless the fit is very tight.
    if bin_residual == bin_capacity {
        let tightness = 100.0 - post_residual as f64; // = item_size
        let mut nb = 40.0 - 0.4 * tightness;          // tight items open bins more cheaply
        nb += 5.0 * open_bins_count as f64;           // prefer reusing when many bins open
        nb -= 20.0 * (1.0 - progress);                // early stream: fresh bins are fine
        if fitting_bins_count == 0 {
            nb -= 100.0;                              // no alternative: must open
        }
        score += nb;
    }

    // Prefer bins whose residual is already below average (consolidating fragments).
    score += 0.1 * (mean_residual - bin_residual as f64);

    // Mild late-stream pressure to fill existing bins densely.
    score += 5.0 * progress * (post_residual as f64 / bin_capacity as f64);

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let progress = step_index as f64 / total_items as f64;
    let cap = bin_capacity as f64;
    let pr = post_residual as f64;
    let x = pr / cap;

    // Base: prefer tight fits (low post residual), with non-linear sharpening.
    let mut score = x * x * cap + pr * 0.5;

    // Smooth polynomial coupling of tightness with stream progress:
    // late in the stream, tight fits matter more; early, slack is acceptable.
    let tight_bonus = (1.0 - x) * (1.0 - x) * (1.0 + 2.0 * progress);
    score -= tight_bonus * 20.0;

    // Dead-space penalty: very small post-residuals that no future item can use.
    let dead = if pr > 0.0 && pr < 10.0 { (10.0 - pr) / 10.0 } else { 0.0 };
    score += dead * dead * 15.0 * (0.5 + progress);

    // Last-chance bin: reward using it to avoid opening a new bin.
    if fitting_bins_count == 1 {
        score -= 12.0 * (1.0 - progress * 0.5);
    }

    // Lookahead coupling: smooth quadratic interaction between post-residual
    // and next item size — reward residuals that plausibly host the next item.
    if next_item_size > 0 {
        let nx = next_item_size as f64;
        let gap = (pr - nx).abs() / cap;
        score += gap * gap * cap * (1.2 - 0.6 * progress);
        if pr >= nx {
            score -= 4.0 * (1.0 - gap);
        }
    }

    // Mild penalty for spreading across many bins relative to mean residual.
    let dev = (pr - mean_residual) / cap;
    score += dev * dev * 8.0 * (1.0 - progress);

    // New-bin candidate: discourage early in the stream, encourage late or
    // when the fit into existing bins is poor (high post residual relative).
    let new_bin = (bin_residual as u64 == bin_capacity as u64) as i32 == 1;
    if new_bin {
        score += 6.0 * (1.0 - progress) - 4.0 * x * (0.5 + progress);
    }

    // Slight preference for well-filled bins overall (low residual fraction).
    score += (1.0 - x) * (1.0 - x) * 5.0 * progress;

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Harmonic class of post_residual: bins whose leftover lies in a "usable"
    // residue class (multiples of 10) are favored, since typical item sizes
    // (1..100) more often tile round residual amounts.
    let post_class = post_residual % 10;
    score += match post_class {
        0 => -12.0,
        1 | 2 | 3 | 4 => 6.0 + post_class as f64,
        5 => 2.0,
        _ => 4.0,
    };

    // Reward tight fits: post_residual small relative to capacity.
    let tightness = post_residual as f64 / bin_capacity as f64;
    score -= (1.0 - tightness) * (1.0 - tightness) * 20.0;

    // Lookahead coupling: if the next item fits exactly into the post_residual,
    // strongly favor this bin; if next item cannot fit, penalize mildly.
    if next_item_size > 0 {
        if next_item_size == post_residual {
            score -= 30.0;
        } else if next_item_size <= post_residual {
            let gap = post_residual - next_item_size;
            score -= 10.0 - gap.min(20) as f64 * 0.3;
        } else {
            score += 8.0;
        }
    } else {
        // Last item: pure tightness matters, no future to plan for.
        score += post_residual as f64 * 0.5;
    }

    // Last-chance bin: if this is the only bin that fits, avoid opening a new bin
    // unless the fit is truly terrible.
    if fitting_bins_count == 1 && bin_residual >= item_size {
        score -= 15.0;
    }

    // New empty bin candidate: penalize so it's chosen only when no open bin
    // offers a decent fit (i.e., when all fits are bad).
    if bin_residual == bin_capacity {
        score += 25.0 + mean_residual * 0.1;
    }

    // Dead-space penalty: post_residual below the minimum item size is wasted.
    if post_residual > 0 && post_residual < 10 {
        score += 18.0;
    }

    // Late in the stream, be more conservative with open bins: prefer filling
    // nearly-full bins to close them out.
    let progress = step_index as f64 / total_items.max(1) as f64;
    score -= progress * (bin_capacity - bin_residual) as f64 * 0.15;

    // Mild pressure to prefer bins below mean residual (balance avoidance of
    // many half-empty bins).
    if (bin_residual as f64) > mean_residual {
        score += 3.0;
    } else {
        score -= 2.0;
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Strict dead-space avoidance: residuals too small for the smallest
    // possible future item (size 1..100, so anything < 100 is potentially
    // usable, but very small gaps are near-worthless). Penalize gaps that
    // are unusable for typical items.
    let progress = step_index as f64 / (total_items.max(1) as f64);
    let dead_threshold = 20.0 + 20.0 * progress;
    if (post_residual as f64) < dead_threshold {
        score += (dead_threshold - post_residual as f64) * 2.0;
    }

    // Reward near-perfect fits strongly.
    if post_residual == 0 {
        score -= 50.0;
    } else if post_residual <= 5 {
        score -= 30.0;
    } else if post_residual <= 10 {
        score -= 15.0;
    }

    // Coupling with mean residual: prefer bins whose residual deviates
    // favorably (tighter than average) to keep a spread of usable gaps.
    let residual_gap = mean_residual - post_residual as f64;
    score += 0.3 * residual_gap.max(0.0) - 0.3 * residual_gap.min(0.0);

    // Last-chance bonus: if this is the only bin that fits, avoid opening
    // a new bin unless the fit is terrible.
    if fitting_bins_count == 1 && bin_residual != bin_capacity {
        score -= 25.0 + 15.0 * progress;
    }

    // Open-bin pressure: many open bins -> discourage opening new bins,
    // encourage filling existing ones.
    if bin_residual == bin_capacity {
        // New-bin candidate: base cost plus pressure from open bins.
        score += 60.0 + 8.0 * open_bins_count as f64;
        // If lookahead item fits in the fresh residual, slight discount.
        if next_item_size > 0 && next_item_size <= post_residual {
            score -= 10.0;
        }
        // Late in stream, opening new bins is more acceptable.
        score -= 20.0 * progress;
    } else {
        // Reward bins whose leftover can host the lookahead item (chaining).
        if next_item_size > 0 && next_item_size <= post_residual {
            score -= 12.0;
        } else if next_item_size > post_residual && post_residual > 0 {
            // Leftover too small for lookahead: mild penalty.
            score += 5.0;
        }
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Strong reward for perfect 2-step lookahead match: bin becomes exactly ready for next item.
    if next_item_size > 0 && post_residual == next_item_size {
        score -= 100.0;
    }
    // Partial lookahead reward: next item still fits in the residual.
    if next_item_size > 0 && post_residual >= next_item_size {
        score -= 10.0 + (next_item_size as f64 / 10.0);
    }
    // Penalize dead space: residual too small for the next item (likely wasted).
    if next_item_size > 0 && post_residual < next_item_size && post_residual > 0 {
        score += 15.0;
    }
    // Penalize tiny unusable slivers harder when they can't hold even the minimum item.
    if post_residual < 10 && post_residual > 0 {
        score += 20.0;
    }
    // Last chance: if this is the only bin that fits, strongly prefer using it
    // over opening a new bin (avoid bin proliferation).
    if fitting_bins_count == 1 && bin_residual != bin_capacity {
        score -= 25.0;
    }
    // New-bin candidate: discourage opening a new bin unless the item fits badly
    // everywhere. Base penalty plus scaling with how many open bins exist.
    if bin_residual == bin_capacity {
        score += 30.0 + (open_bins_count as f64).sqrt() * 5.0;
        // But if a lookahead-perfect pairing exists for a fresh bin, soften slightly.
        if next_item_size > 0 && post_residual == next_item_size {
            score -= 40.0;
        }
    }
    // Favor bins tighter than the mean residual (good packing density).
    score -= (mean_residual - post_residual as f64) * 0.3;
    // Mild stream-progression term: later in the stream, prefer tighter fits more.
    if total_items > 0 {
        score += (step_index as f64 / total_items as f64) * (post_residual as f64) * 0.1;
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Reward tight fits (small post-residual gets extra discount)
    let tightness = 1.0 - (post_residual as f64) / (bin_capacity as f64);
    score -= 18.0 * tightness * tightness;

    // Penalize dead space that is too small for typical future items
    if post_residual > 0 && post_residual < 10 {
        score += 25.0;
    }

    // Lookahead: if next item fits exactly in the post residual, reward strongly
    if next_item_size > 0 {
        if next_item_size == post_residual {
            score -= 30.0;
        } else if next_item_size <= post_residual {
            score -= 8.0 * (next_item_size as f64 / post_residual as f64);
        } else {
            // next item won't fit here; slight penalty proportional to waste
            score += 4.0 * (post_residual as f64 / bin_capacity as f64);
        }
    } else {
        // Last item: prefer fullest packing
        score -= 15.0 * tightness;
    }

    // Last-chance bonus: if this is the only fitting bin, strongly favor using it
    if fitting_bins_count == 1 && bin_residual >= item_size {
        score -= 22.0;
    }

    // New-bin candidate handling: make empty bins moderately attractive only
    // when no good fit exists (high mean residual spread / many open bins)
    if bin_residual == bin_capacity {
        // Base cost of opening a new bin
        score += 12.0;
        // Cheaper to open new bin when open bins are crowded with small residuals
        score -= 0.15 * (open_bins_count as f64);
        // If mean residual is small (bins nearly full), new bin is more attractive
        score += 0.10 * (mean_residual - 50.0);
        // Early in stream, opening bins is fine; later, prefer consolidation
        let progress = if total_items > 0 { step_index as f64 / total_items as f64 } else { 0.0 };
        score += 20.0 * progress;
    }

    // Slight preference for bins with residuals close to the item (best-fit flavor)
    let gap = (bin_residual - item_size) as f64;
    score += 0.05 * gap;

    // Global balance: prefer placing into bins whose residual is above mean
    // (keeps a portfolio of medium residuals for future flexibility)
    score += 0.03 * (mean_residual - bin_residual as f64);

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let cap = bin_capacity as f64;
    let post = post_residual as f64;
    let item = item_size as f64;
    let progress = if total_items > 0 { step_index as f64 / total_items as f64 } else { 0.0 };
    let mut score = post;

    // Smooth polynomial coupling of post_residual with stream progress:
    // early on, tolerate leftover space; late, punish dead space quadratically.
    let dead_penalty = post * post / cap * (0.5 + 1.5 * progress);
    score += dead_penalty;

    // Reward tight fits: small post_residual relative to item size.
    let tightness = 1.0 - post / cap;
    score -= item * tightness * (0.8 + 0.6 * progress);

    // Lookahead coupling: if the next item fits exactly into the post residual,
    // strongly reward this placement; if next item barely misses, penalize.
    if next_item_size > 0 {
        let nxt = next_item_size as f64;
        let gap = (post - nxt).abs();
        let fit_bonus = (1.0 - gap / cap).max(0.0);
        score -= nxt * fit_bonus * fit_bonus * 0.9;
        score += gap * gap / cap * 0.3;
    }

    // Last-chance bin: heavily favor using it to avoid opening a new bin.
    if fitting_bins_count == 1 && bin_residual != bin_capacity {
        score -= 25.0 + 15.0 * progress;
    }

    // New empty bin candidate: penalize mildly early, more when many bins open,
    // but relax penalty when item is large (packing big items fresh is fine).
    if bin_residual == bin_capacity {
        let big_item = item / cap;
        score += 18.0 + 3.0 * (open_bins_count as f64).ln().max(0.0) - 20.0 * big_item;
    }

    // Prefer bins whose residual deviates below the mean (consolidate small leftovers).
    score -= (mean_residual - post) * 0.15;

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let cap = bin_capacity as f64;
    let mut score = post_residual as f64;

    // Perfect fit: overwhelming reward.
    if post_residual == 0 {
        score -= 1000.0;
        return score;
    }

    // Harmonic class of post_residual: how well does the leftover divide the capacity?
    // Residuals that are themselves "packable" (multiples of common item sizes) are good.
    let pr = post_residual;
    let harmonic_bonus: f64 = if pr % 10 == 0 {
        40.0
    } else if pr % 5 == 0 {
        25.0
    } else if pr % 20 == 0 {
        45.0
    } else if pr % 25 == 0 {
        35.0
    } else {
        0.0
    };
    score -= harmonic_bonus;

    // Dead-space penalty: leftover too small for the smallest plausible item (<=10).
    if pr < 10 {
        score += 60.0;
    } else if pr < 20 {
        score += 25.0;
    }

    // Coupling with lookahead: if next item fits exactly in post_residual, big reward.
    if next_item_size > 0 {
        if next_item_size == pr {
            score -= 120.0;
        } else if next_item_size <= pr {
            // next item fits: leftover still useful
            let slack = (pr - next_item_size) as f64;
            score -= 30.0 * (1.0 - slack / cap);
            // harmonic check on the double-leftover
            if (pr - next_item_size) % 10 == 0 {
                score -= 15.0;
            }
        } else {
            // next item cannot use this leftover: penalize proportionally
            score += 10.0 * (next_item_size as f64 - pr as f64) / cap;
        }
    }

    // Last-chance bin: strongly favor using it before opening a new one.
    if fitting_bins_count == 1 && bin_residual >= item_size {
        score -= 50.0;
    }

    // Fractional capacity thresholds: prefer filling bins past half capacity.
    let fill_frac = (bin_capacity - post_residual) as f64 / cap;
    if fill_frac >= 0.5 {
        score -= 20.0 * fill_frac;
    }

    // New-bin candidate: neutral-ish baseline, penalize slightly unless current
    // bin would leave a very awkward residual.
    if bin_residual == bin_capacity {
        score = cap * 0.35 + (open_bins_count as f64).sqrt() * 2.0;
        if next_item_size > 0 && next_item_size as f64 > cap * 0.7 {
            score -= 10.0; // big next item: fresh bin fine
        }
    }

    // Mild consolidation pressure: fewer open bins -> slightly lower scores for all,
    // relative effect via mean residual alignment.
    if (post_residual as f64 - mean_residual).abs() < 5.0 {
        score -= 5.0;
    }

    // Stream progression: late in stream, tighten up (avoid wasting near-full bins).
    let progress = step_index as f64 / total_items.max(1) as f64;
    score -= 5.0 * progress * (post_residual as f64 / cap);

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Strict dead-space avoidance: small unusable gaps (1..=9) are heavily penalized.
    if post_residual >= 1 && post_residual <= 9 {
        score += 60.0 - 5.0 * post_residual as f64; // worst at residual=1
    } else if post_residual <= 15 {
        score += 8.0; // awkward mid gap
    } else {
        // Larger residuals are more reusable: reward proportionally.
        score -= 0.15 * post_residual as f64;
    }

    // Perfect fit bonus.
    if post_residual == 0 {
        score -= 40.0;
    }

    // Reward bins whose residual after placement can host the lookahead item.
    if next_item_size > 0 {
        if post_residual >= next_item_size {
            score -= 12.0;
        } else if bin_residual >= next_item_size && post_residual < next_item_size {
            score += 10.0; // this placement destroys a slot for the next item
        }
    }

    // Last-chance bin: if this is the only bin that fits, avoid opening a new bin.
    if fitting_bins_count == 1 && bin_residual != bin_capacity {
        score -= 25.0;
    }

    // New-bin candidate: only attractive when current fit is bad.
    if bin_residual == bin_capacity {
        let fit_quality = item_size as f64 / bin_residual as f64;
        if fit_quality < 0.35 {
            score -= 30.0; // prefer fresh bin over wasting a large residual
        } else {
            score += 20.0; // discourage opening bins for good fits
        }
        score += 2.0 * open_bins_count as f64;
    }

    // Open-bins pressure: mildly discourage spreading across many bins.
    score += 0.5 * open_bins_count as f64;

    // Mean residual coupling: prefer bins near the mean residual (keeps bin profile uniform).
    score += 0.05 * (post_residual as f64 - mean_residual).abs();

    // Late-stream tightening: be less tolerant of dead space as stream ends.
    let progress = step_index as f64 / total_items.max(1) as f64;
    score += progress * 3.0;

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Perfect-fit bonus: exact fill leaves zero dead space.
    if post_residual == 0 {
        score -= 60.0;
    }

    // Aggressive 2-step lookahead: reward bins whose post_residual
    // matches the next item's size (chain packing).
    if next_item_size > 0 {
        let gap = (post_residual as i64 - next_item_size as i64).abs() as f64;
        score -= 40.0 / (1.0 + gap);
        // Exact chain match: post_residual == next_item_size
        if post_residual == next_item_size {
            score -= 35.0;
        }
        // Penalize dead space the next item cannot use
        if post_residual < next_item_size {
            score += 0.5 * (next_item_size - post_residual) as f64;
        }
    }

    // Relative-to-mean residual: prefer bins tighter than average.
    score -= 0.6 * (mean_residual - post_residual as f64);

    // Last-chance bin: strongly favor using it before opening a new bin.
    if fitting_bins_count == 1 && bin_residual < bin_capacity {
        score -= 25.0;
    }

    // New-bin candidate: keep it attractive only when item is large
    // relative to capacity or the fit is poor.
    if bin_residual == bin_capacity {
        let fill_ratio = item_size as f64 / bin_capacity as f64;
        score += 30.0 * (1.0 - fill_ratio);
        if next_item_size > 0 && post_residual >= next_item_size {
            score -= 15.0; // fresh bin can chain with next item
        }
    }

    // Late in the stream, tighten packing (avoid spreading into new bins).
    let progress = step_index as f64 / total_items as f64;
    score += 10.0 * progress * (post_residual as f64 / bin_capacity as f64);

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Reward tight fits strongly (post_residual small relative to item).
    let fit_ratio = item_size as f64 / bin_residual.max(1) as f64;
    score -= 12.0 * fit_ratio;

    // Penalize leaving awkward dead space that few typical items can fill.
    if post_residual > 0 && post_residual < 10 {
        score -= 6.0; // small gap still usable by tiny items
    } else if post_residual >= 10 && post_residual < 20 {
        score += 3.0; // awkward zone
    }

    // Last-chance bin: strongly prefer using it over opening a new bin.
    if fitting_bins_count == 1 && bin_residual != bin_capacity {
        score -= 25.0;
    }

    // Lookahead: if next item fits in the post residual, reward; if it would
    // exactly fill, reward more (perfect chaining).
    if next_item_size > 0 {
        if (next_item_size as u32) == post_residual {
            score -= 15.0;
        } else if next_item_size as u32 <= post_residual {
            score -= 5.0 * (next_item_size as f64 / post_residual.max(1) as f64);
        } else {
            // Next item won't fit here anyway; slight penalty for wasting space.
            score += 2.0;
        }
    }

    // New-bin candidate handling: only attractive when open bins are crowded
    // or residuals are large relative to item (poor fits everywhere).
    if bin_residual == bin_capacity {
        let crowding = open_bins_count as f64 / (1.0 + mean_residual / bin_capacity as f64);
        let poor_fits = (post_residual as f64 / bin_capacity as f64) - fit_ratio;
        score += 30.0 - 8.0 * crowding - 10.0 * poor_fits.max(0.0);
        // Early in the stream, opening bins is cheap; later, avoid bin sprawl.
        let progress = step_index as f64 / total_items.max(1) as f64;
        score += 10.0 * progress;
    }

    // Mild preference for bins already below mean residual (consolidate fullness).
    if (bin_residual as f64) < mean_residual {
        score -= 2.0;
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let capacity = bin_capacity as f64;
    let pr = post_residual as f64;
    let progress = if total_items > 0 { step_index as f64 / total_items as f64 } else { 0.0 };

    // Base: minimize leftover space (best-fit core).
    let mut score = pr;

    // Non-linear coupling: normalized waste grows quadratically — small residuals are cheap,
    // large residuals (dead space) are punished super-linearly.
    let norm_waste = pr / capacity;
    score += 8.0 * norm_waste * norm_waste * capacity * (0.5 + progress);

    // Reward tight fits: the closer the fill ratio, the bigger the bonus (smooth cubic).
    let fill = (bin_residual - post_residual) as f64 / capacity;
    score -= 12.0 * fill * fill * fill;

    // Last-chance bin: strongly favor using the only bin that fits, avoiding a new bin.
    if fitting_bins_count == 1 && bin_residual != bin_capacity {
        score -= 15.0 + 10.0 * progress;
    }

    // Scarcity pressure: when few bins fit the item, mildly favor any fitting open bin.
    if fitting_bins_count > 0 {
        score -= 3.0 / fitting_bins_count as f64;
    }

    // New-bin candidate (bin_residual == bin_capacity): penalize opening a new bin,
    // more so early in the stream and when open bins exist; relax late in the stream
    // or when mean residual across open bins is too small for the next item.
    let is_new_bin = (bin_residual as f64 - capacity).abs() < 0.5;
    if is_new_bin {
        let next_fits_now = next_item_size as f64 > 0.0 && next_item_size as f64 <= mean_residual;
        let mut penalty = 6.0 + 10.0 * (1.0 - progress) + 0.5 * open_bins_count as f64;
        if next_fits_now {
            penalty += 5.0;
        }
        // If the item would leave a very awkward residual in any bin, opening a fresh
        // bin becomes attractive: reduce the penalty smoothly.
        penalty *= 1.0 - 0.5 * norm_waste;
        score += penalty;
    }

    // Lookahead: if the next item fits exactly in the post-residual, reward this placement
    // (sets up a perfect follow-up fit).
    if next_item_size > 0 && next_item_size == post_residual {
        score -= 10.0;
    } else if next_item_size > 0 && next_item_size < post_residual {
        // Next item fits but not perfectly: small smooth reward proportional to its fit.
        let nf = next_item_size as f64 / pr;
        score -= 4.0 * nf * nf;
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Harmonic class of the post-fit residual: how "reusable" is the leftover space?
    // Class boundaries at capacity fractions 1/4, 1/2, 3/4.
    let cap = bin_capacity as f64;
    let post = post_residual as f64;
    let class_bonus = if post_residual == 0 {
        -30.0 // perfect fill, ideal
    } else if post_residual <= bin_capacity / 4 {
        -12.0 // small dead space, likely fillable by future small items
    } else if post_residual <= bin_capacity / 2 {
        -4.0
    } else if post_residual <= (3 * bin_capacity) / 4 {
        6.0
    } else {
        15.0 // large residual: wasteful unless it's a fresh bin
    };
    score += class_bonus;

    // Exact modulo alignment: residuals that are multiples of common size classes
    // (e.g. 10, 20, 25) are more likely to be exactly consumed later.
    let r = post_residual;
    if r > 0 && (r % 10 == 0 || r % 25 == 0) {
        score -= 3.0;
    }

    // Lookahead coupling: if the next item fits exactly into post_residual,
    // strongly reward; if next item can't fit, penalize slightly (dead end).
    if next_item_size > 0 {
        if next_item_size == post_residual {
            score -= 25.0;
        } else if next_item_size < post_residual {
            score -= (post_residual - next_item_size) as f64 * 0.15;
        } else {
            score += 5.0;
        }
    }

    // Last-chance bin: if this is the only bin that fits, avoid opening a new bin.
    if fitting_bins_count == 1 && bin_residual != bin_capacity {
        score -= 18.0;
    }

    // Fresh-bin candidate: only attractive when current item is large relative
    // to capacity or mean residual is already tight.
    if bin_residual == bin_capacity {
        let tight = mean_residual < cap * 0.25;
        if item_size >= bin_capacity / 2 || tight {
            score -= 8.0;
        } else {
            score += 20.0; // prefer filling existing bins with small items
        }
    }

    // Mild pressure to consolidate as the stream progresses and bins accumulate.
    let progress = step_index as f64 / total_items.max(1) as f64;
    score -= progress * (mean_residual - post) * 0.05;
    score += open_bins_count as f64 * 0.3;

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Strict dead-space avoidance: small unusable gaps (< smallest item) are wasted forever.
    let dead_threshold = 10.0;
    if (post_residual as f64) < dead_threshold {
        score += 60.0; // hard penalty for creating unusable sliver
    } else if post_residual as f64 <= 20.0 {
        // gap only usable by tiny items: partial penalty scaled by tightness
        score += (20.0 - post_residual as f64) * 1.5;
    }

    // Reward tight fits (small relative waste).
    let waste_ratio = post_residual as f64 / bin_capacity as f64;
    score -= (1.0 - waste_ratio) * 30.0;

    // Perfect fit bonus.
    if post_residual == 0 {
        score -= 40.0;
    }

    // Last-chance bin: strongly favor using it before opening a new bin.
    if fitting_bins_count == 1 && bin_residual < bin_capacity {
        score -= 35.0;
    }

    // Open-bins pressure: with many open bins, prefer consolidation;
    // with few open bins, opening a new bin is cheaper.
    let pressure = (open_bins_count as f64).ln().max(0.0) * 6.0;
    score += pressure;

    // New-bin candidate: penalize mildly so it's chosen only when open bins fit badly.
    if bin_residual == bin_capacity {
        score += 25.0 + (open_bins_count as f64) * 0.5;
        // but if lookahead item is large and this bin would be near-empty anyway,
        // a fresh bin is attractive
        if next_item_size > 0 && (next_item_size as f64) > post_residual as f64 + 30.0 {
            score -= 20.0;
        }
    }

    // Lookahead synergy: if next item fits exactly into the post-residual, big reward.
    if next_item_size > 0 && (next_item_size as u32) == post_residual {
        score -= 50.0;
    } else if next_item_size > 0 && (next_item_size as u32) < post_residual {
        score -= 8.0;
    }

    // Mean-residual coupling: prefer bins whose residual is below average
    // (fills fuller bins first, keeps large gaps open for big items).
    let my_residual = bin_residual as f64;
    if my_residual < mean_residual {
        score -= (mean_residual - my_residual) * 0.4;
    } else {
        score += (my_residual - mean_residual) * 0.4;
    }

    // Late-stream tightening: as the stream progresses, waste matters more.
    let progress = step_index as f64 / (total_items.max(1) as f64);
    score += progress * 10.0 * waste_ratio;

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Base: prefer tight fits (small post_residual)
    score = post_residual as f64 * 1.0;

    // Aggressive 2-step lookahead: reward bins whose post_residual matches next_item_size
    if next_item_size > 0 {
        let match_gap = (post_residual as i64 - next_item_size as i64).abs() as f64;
        // Perfect match bonus: next item exactly fills the bin
        if post_residual == next_item_size {
            score -= 25.0;
        } else {
            score -= 12.0 / (1.0 + match_gap);
        }
        // Penalize post_residual that is too small to fit next item (dead space risk)
        if post_residual < next_item_size {
            score += (next_item_size - post_residual) as f64 * 0.35;
        }
    }

    // Relative to mean residual: prefer bins tighter (below mean residual)
    score -= (mean_residual - bin_residual as f64) * 0.15;

    // Last-chance bin bonus: if this is the only fitting bin, strongly prefer it
    if fitting_bins_count == 1 && bin_residual != bin_capacity {
        score -= 15.0;
    }

    // New-bin candidate handling: penalize opening a new bin unless current fits are bad
    if bin_residual == bin_capacity {
        score += 20.0;
        // Opening new bin is more attractive early in the stream
        let progress = step_index as f64 / (total_items.max(1) as f64);
        score -= 10.0 * (1.0 - progress);
        // If next item is large, a fresh bin is valuable
        if next_item_size > bin_capacity / 2 {
            score -= 8.0;
        }
    }

    // Slight preference for keeping more bins open consolidated later in stream
    score += open_bins_count as f64 * 0.02;

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Reward tight fits: small post-residual relative to capacity.
    let tightness = 1.0 - (post_residual as f64) / (bin_capacity as f64);
    score -= 3.0 * tightness * tightness * item_size as f64;

    // Penalize dead space that no plausible future item can use.
    if post_residual > 0 && post_residual < 10 {
        score += 8.0; // tiny unusable slivers
    }

    // Lookahead coupling: bonus if next item fits the post-residual exactly-ish.
    if next_item_size > 0 {
        if next_item_size <= post_residual {
            let slack = (post_residual - next_item_size) as f64;
            score -= 6.0 * (1.0 - slack / bin_capacity as f64);
        } else {
            score += 2.0; // next item won't chain here
        }
    }

    // Last-chance bin: strongly prefer filling it rather than opening new.
    if fitting_bins_count == 1 && bin_residual < bin_capacity {
        score -= 15.0;
    }

    // New-bin candidate handling: only attractive when current bins are crowded
    // or mean residual is small (poor global slack).
    if bin_residual == bin_capacity {
        let pressure = mean_residual / bin_capacity as f64;
        let time_frac = step_index as f64 / (total_items.max(1) as f64);
        let bias = 20.0 * (1.0 - pressure) * (1.0 - 0.3 * time_frac);
        score += bias;
        if open_bins_count == 0 {
            score -= 50.0;
        }
    }

    // Mild penalty for spreading across too many open bins.
    score += 0.05 * open_bins_count as f64;

    // Slight preference for bins with residual close to item (best-fit flavor).
    let fit_gap = (bin_residual as f64 - item_size as f64).abs();
    score += 0.3 * fit_gap;

    // Penalize wasting a large bin on a tiny item late in the stream.
    let ratio = item_size as f64 / bin_residual as f64;
    if ratio < 0.3 {
        score += 5.0 * (0.3 - ratio);
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let cap = bin_capacity as f64;
    let pr = post_residual as f64;
    let progress = if total_items > 0 { step_index as f64 / total_items as f64 } else { 0.0 };

    // Base: prefer tight fits (small post_residual)
    let mut score = pr;

    // Non-linear polynomial coupling of post_residual with stream progress.
    // Early on, small residuals are acceptable; late in the stream, penalize
    // wasted space super-linearly to squeeze out extra placements.
    let pn = pr / cap; // normalized post residual in [0,1]
    let coupling = pn * pn * (1.0 + 3.0 * progress) + pn * pn * pn * (2.0 + 5.0 * progress);
    score += coupling * cap * 0.35;

    // Smooth interaction: residual vs mean residual (prefer bins tighter than average)
    let dev = (bin_residual as f64 - mean_residual) / cap;
    score += dev * dev * 12.0 - dev * 6.0 * (1.0 - progress);

    // Last-chance bonus: if this is the only fitting bin, strongly favor using it
    if fitting_bins_count == 1 {
        score -= 25.0 + 20.0 * progress;
    }

    // Lookahead: if the next item fits exactly in the post residual, reward this placement
    if next_item_size > 0 {
        let nxt = next_item_size as f64;
        let gap = (pr - nxt).abs();
        if pr >= nxt {
            score -= 10.0 * (1.0 - gap / cap);
        } else {
            score += 4.0 * (gap / cap);
        }
    }

    // Slight penalty for opening new bins when many bins are open (encourage consolidation)
    if bin_residual == bin_capacity {
        score += 6.0 + 10.0 * (1.0 - progress) + (open_bins_count as f64).sqrt();
    } else {
        score -= 2.0;
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let cap = bin_capacity as f64;
    let mut score = post_residual as f64;

    // Harmonic class of the post residual: how "well-shaped" is the leftover space?
    // Class 0: post_residual == 0 (perfect fit) -> strong reward.
    if post_residual == 0 {
        score -= 60.0;
    } else {
        // Integer-division thresholds on post_residual: leftover space is only
        // reusable if it can host a future item. Items are >= 1, but typical
        // classes come from capacity fractions.
        let pr = post_residual as f64;
        let frac = pr / cap;

        // Penalize dead space that is too small to be useful at all.
        if post_residual < 4 {
            score += 25.0;
        } else if post_residual <= 10 {
            // near-dead zone: barely usable
            score += 8.0;
        } else if post_residual <= bin_capacity / 4 {
            // quarter-class leftover: moderately reusable
            score += 2.0;
        } else if post_residual <= bin_capacity / 2 {
            // half-class leftover: good
            score -= 6.0;
        } else {
            // large leftover: very good, keep bins roomy
            score -= 12.0;
        }

        // Non-linear quadratic penalty on tiny fractions (dead-space curvature)
        score += (1.0 - frac) * (1.0 - frac) * 6.0;

        // Modulo arithmetic: residuals that are multiples of common size classes
        // (e.g. divisible by 10 or 25) pair better with typical item granularities.
        if post_residual % 10 == 0 {
            score -= 4.0;
        }
        if post_residual % 25 == 0 {
            score -= 3.0;
        }
        // Odd, prime-ish residuals are awkward targets
        if post_residual % 2 == 1 && post_residual < 20 {
            score += 3.0;
        }
    }

    // Lookahead coupling: does this bin's post-residual fit the next item?
    if next_item_size > 0 && post_residual >= next_item_size {
        // Reward leaving exactly enough (or near-exact) room for the next item
        let slack = (post_residual - next_item_size) as f64;
        if slack == 0.0 {
            score -= 30.0;
        } else if slack <= 10.0 {
            score -= 12.0;
        } else {
            score -= 4.0;
        }
    } else if next_item_size > 0 {
        // post residual cannot host next item: mild penalty scaled by how far off
        let gap = (next_item_size - post_residual) as f64;
        score += (gap / cap).min(1.0) * 10.0;
    }

    // Last-chance bonus: if this is the only bin that fits, prefer using it
    // over opening a new bin (unless the fit is terrible).
    if fitting_bins_count == 1 && bin_residual != bin_capacity {
        score -= 15.0;
    }

    // New-bin candidate: make it attractive only when open-bin fits are poor.
    // Base new-bin score slightly above a decent fit so we don't proliferate bins.
    if bin_residual == bin_capacity {
        // neutral-ish anchor: raw post residual (= capacity - item) plus offset
        score += 20.0 - (item_size as f64 / cap) * 10.0;
        // Early in the stream, opening bins is cheaper (diversification)
        let progress = step_index as f64 / total_items.max(1) as f64;
        score -= (1.0 - progress) * 8.0;
        // If many bins are open relative to items, discourage new bins
        score += (open_bins_count as f64).ln().max(0.0) * 3.0;
    }

    // Mean-residual context: if this bin's residual is far below the mean,
    // it is a "small hole" bin; filling it is good (reduce fragmentation).
    let res_f = bin_residual as f64;
    if mean_residual > 0.0 {
        let dev = (res_f - mean_residual) / mean_residual;
        if dev < 0.0 {
            score += dev * 5.0; // below-mean residual -> lower score -> prefer filling
        } else {
            score += dev * 2.0; // above-mean residual -> mild penalty
        }
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Dead-space penalty: residuals too small for the smallest plausible item are wasted.
    if post_residual > 0 && post_residual < 10 {
        score += 40.0;
    } else if post_residual >= 10 && post_residual < 20 {
        score += 12.0;
    }

    // Perfect / near-perfect fit reward.
    if post_residual == 0 {
        score -= 100.0;
    }

    // Reward residual that can still accommodate the lookahead item (keeps chains alive).
    if next_item_size > 0 && post_residual >= next_item_size {
        score -= 15.0;
    } else if next_item_size > 0 && post_residual > 0 {
        score += 8.0;
    }

    // Last-chance bin: strongly prefer using it before opening a new bin.
    if fitting_bins_count == 1 && bin_residual != bin_capacity {
        score -= 60.0;
    }

    // Open-bin pressure: discourage opening new bins when many are already open.
    let progress = step_index as f64 / (total_items.max(1) as f64);
    let new_bin_bonus = -30.0 * (1.0 - progress) - 2.0 * open_bins_count as f64;
    if bin_residual == bin_capacity {
        // New empty bin candidate: must beat good fits; make it unattractive unless
        // the best open fit would create severe dead space.
        score += 25.0 + new_bin_bonus.abs() * 0.5;
        if post_residual == 0 { score -= 0.0; }
    } else {
        score -= new_bin_bonus.abs() * 0.1;
    }

    // Mild preference for bins tighter than average (best-fit flavor).
    score -= (mean_residual - bin_residual as f64) * 0.05;

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Reward perfect-ish fits strongly (aggressive tight packing)
    if post_residual == 0 {
        score -= 60.0;
    } else if post_residual <= 5 {
        score -= 40.0;
    } else if post_residual <= 15 {
        score -= 15.0;
    }

    // 2-step lookahead: reward when next item fits the post-residual exactly
    if next_item_size > 0 {
        let next = next_item_size as f64;
        if post_residual as f64 == next {
            score -= 55.0;
        } else if next <= post_residual as f64 {
            // next item fits: penalize proportionally to wasted space after that
            let chain_waste = post_residual as f64 - next;
            score -= 20.0 * (1.0 - chain_waste / bin_capacity as f64);
        } else {
            // next item does NOT fit: penalize leaving a residual that blocks it
            let gap = next - post_residual as f64;
            score += 10.0 + 0.5 * gap.min(50.0);
        }
    }

    // Relative to mean residual: prefer bins that are tighter than average
    score -= 0.6 * (mean_residual - post_residual as f64);

    // Last-chance bin before opening a new bin: strong bonus
    if fitting_bins_count == 1 {
        score -= 25.0;
    }

    // Slight penalty for opening new bins early in the stream
    let progress = step_index as f64 / total_items.max(1) as f64;
    if bin_residual == bin_capacity {
        score += 15.0 * (1.0 - progress);
    }

    // Mild penalty when many bins are already open (encourage consolidation)
    score += 0.05 * open_bins_count as f64;

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
