pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let pr = post_residual as f64;
    let cap = bin_capacity as f64;
    let progress = if total_items > 0 { step_index as f64 / total_items as f64 } else { 0.0 };

    // Base: prefer small post-residual (tight fit)
    let mut score = pr;

    // Non-linear penalty on wasted capacity: quadratic in normalized post-residual
    let x = pr / cap;
    score += 12.0 * x * x * cap;

    // Smooth interaction: late in the stream, small residuals are less valuable to keep;
    // tighten preference as progress grows (cubic coupling)
    let tight_bias = (1.0 - progress) * (1.0 - progress) * (1.0 + progress);
    score -= 8.0 * tight_bias * (1.0 - x) * (1.0 - x);

    // Reward bins whose residual closely matches item (smooth gaussian-like fit term)
    let fit_gap = (bin_residual as f64 - item_size as f64) / cap;
    score -= 10.0 * (-30.0 * fit_gap * fit_gap).exp();

    // Lookahead: penalize leaving residual that neither helps nor blocks next item
    if next_item_size > 0 {
        let nx = next_item_size as f64;
        let usable = (pr - nx).abs() / cap;
        score += 6.0 * usable * usable;
        // reward exact chain fit smoothly
        score -= 8.0 * (-40.0 * usable * usable).exp();
    }

    // Last-chance bin: strongly favor using it
    if fitting_bins_count == 1 {
        score -= 25.0;
    } else if fitting_bins_count > 1 {
        // mild penalty spread across many fitting bins to keep best-fit discrimination
        score += 2.0 * (fitting_bins_count as f64).ln();
    }

    // New-bin candidate handling: empty bin gets neutral-ish score, opened only
    // if no open bin offers a decent fit
    if bin_residual == bin_capacity {
        score = 0.45 * cap + 15.0 * (1.0 - progress) - 5.0 * (open_bins_count as f64).ln();
        if next_item_size > 0 && next_item_size >= item_size {
            score -= 10.0;
        }
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let score = post_residual as f64 / bin_capacity.max(1) as f64;
