pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Strict dead-space avoidance: small unusable gaps are heavily penalized.
    if post_residual > 0 && post_residual < 10 {
        score += (10 - post_residual) as f64 * 8.0;
    }
    // Perfect fit is strongly rewarded.
    if post_residual == 0 {
        score -= 30.0;
    }

    // Reward tight fits relative to bin capacity.
    let tightness = item_size as f64 / bin_residual as f64;
    score -= tightness * 10.0;

    // Last-chance bin: strongly favor using it to avoid opening a new bin.
    if fitting_bins_count == 1 && bin_residual != bin_capacity {
        score -= 20.0;
    }

    // Open bins pressure: with many open bins, discourage spreading; prefer new bin on poor fits.
    let progress = step_index as f64 / (total_items.max(1) as f64);
    if bin_residual == bin_capacity {
        // New-bin candidate: attractive when few bins open or early in stream;
        // penalized when many bins are open (prefer filling existing ones).
        score -= 5.0 + 40.0 * (1.0 - progress);
        score += open_bins_count as f64 * 1.5;
        // If next item could pair with leftovers elsewhere, slightly favor new bin.
        if next_item_size > 0 && post_residual == bin_capacity {
            score -= 3.0;
        }
    } else {
        // Existing bin: mild penalty scaling with open bin count to encourage consolidation.
        score += open_bins_count as f64 * 0.3;
        // If next item fits exactly into post_residual, reward this placement (lookahead chaining).
        if next_item_size > 0 && post_residual == next_item_size {
            score -= 25.0;
        } else if next_item_size > 0 && next_item_size <= post_residual {
            score -= 8.0;
        } else if next_item_size > post_residual && post_residual > 0 {
            // Next item cannot use the leftover: penalize potential dead space.
            score += (post_residual.min(next_item_size - post_residual)) as f64 * 0.5;
        }
    }

    // Slightly prefer bins below mean residual (balancing load).
    score += ((bin_residual as f64) - mean_residual) * 0.1;

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Base: prefer tight fits (small post_residual).
    score = post_residual as f64 * 1.0;

    // Aggressive 2-step lookahead: reward exact match of post_residual with next item.
    if next_item_size > 0 {
        let nxt = next_item_size as f64;
        let diff = (post_residual as f64 - nxt).abs();
        if diff < 0.5 {
            score -= 60.0; // perfect two-step match
        } else {
            // Penalize post_residual that cannot fit the next item (dead space for k=2).
            if (post_residual as i64) < (next_item_size as i64) {
                score += (next_item_size - post_residual) as f64 * 1.5;
            } else {
                // Post-residual fits next item: mild reward proportional to closeness.
                score -= (10.0 - diff.min(10.0)) * 1.2;
            }
        }
    }

    // Relative-to-mean coupling: bins with residual far below mean are "tighter";
    // placing there is good if fit is tight, bad if it wastes scarce space.
    let rel = post_residual as f64 - mean_residual;
    score += rel * 0.25;

    // Last-chance bonus: if this is the only fitting bin, strongly prefer using it
    // over opening a new bin (avoid bin proliferation).
    if fitting_bins_count == 1 && bin_residual < bin_capacity {
        score -= 25.0;
    }

    // New-bin candidate handling: an empty bin should only win when no open bin
    // gives a decent fit. Penalize it based on how much of it stays unused
    // relative to the item (wasting a fresh bin is expensive early in the stream).
    if bin_residual == bin_capacity {
        let progress = step_index as f64 / total_items.max(1) as f64;
        // Waste penalty grows with progress (later in stream, conserve bins).
        let waste = (bin_capacity - item_size) as f64;
        score = waste * (0.5 + progress) + 40.0;
        // But if next item could pair with the leftover space, soften the penalty.
        if next_item_size > 0 && post_residual >= next_item_size {
            score -= 20.0;
        }
    }

    // Slight preference for filling nearly-full bins to completion.
    if post_residual < 10 && bin_residual < bin_capacity {
        score -= 8.0;
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Reward tight fits: small post_residual gets a strong discount.
    let tightness = 1.0 - (post_residual as f64) / (bin_capacity as f64);
    score -= 8.0 * tightness * tightness;

    // Penalize dead space: residuals too small for typical future items are waste.
    if post_residual < 10 {
        score += 15.0;
    } else if post_residual < 20 {
        score += 6.0;
    }

    // Lookahead coupling: reward if next item fits exactly in post_residual.
    if next_item_size > 0 {
        if next_item_size == post_residual {
            score -= 20.0; // perfect chain
        } else if next_item_size <= post_residual {
            let slack = (post_residual - next_item_size) as f64;
            score -= 6.0 * (1.0 - slack / (bin_capacity as f64));
        } else {
            // next item won't fit here; slightly penalize leaving awkward gap
            let gap = (next_item_size - post_residual) as f64;
            score += 0.05 * gap.min(50.0);
        }
    } else {
        // Last item: strongly prefer filling existing bins to the brim.
        score -= 5.0 * tightness;
    }

    // Last-chance bonus: if this is the only fitting bin, avoid opening a new bin.
    if fitting_bins_count == 1 && bin_residual < bin_capacity {
        score -= 12.0;
    }

    // New-bin candidate handling: make empty bins moderately attractive only
    // when open bins are crowded (high mean residual) or item barely fits anywhere.
    if bin_residual == bin_capacity {
        let crowd = mean_residual / (bin_capacity as f64);
        let scarcity = if fitting_bins_count == 0 { 1.0 } else { 1.0 / (fitting_bins_count as f64) };
        let time = step_index as f64 / (total_items.max(1) as f64);
        // base cost of opening a bin, discounted by crowding and scarcity
        score += 30.0 - 20.0 * crowd - 15.0 * scarcity - 5.0 * time;
    }

    // Mild preference to spread load when many bins are open and mean residual is low.
    let progress = step_index as f64 / (total_items.max(1) as f64);
    let spread = (mean_residual - post_residual as f64).abs();
    score += 0.02 * spread * (1.0 - progress);

    // Small penalty for using nearly-full bins when other options likely exist.
    if bin_residual <= item_size + 5 && bin_residual >= item_size {
        score -= 3.0;
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let progress = step_index as f64 / total_items.max(1) as f64;
    let pr = post_residual as f64;
    let cap = bin_capacity as f64;
    let pr_norm = pr / cap;

    // Base: prefer small post-residual, with smooth non-linear emphasis.
    let mut score = pr * (1.0 + 0.6 * pr_norm * pr_norm);

    // Stream progress coupling: tighter packing demanded as stream advances.
    score *= 1.0 + 0.5 * progress * pr_norm;

    // Reward filling bins deeply (item_size relative to capacity).
    score -= 12.0 * (item_size as f64 / cap) * (1.0 - pr_norm);

    // Last-chance bin: strong reward to use it.
    if fitting_bins_count == 1 {
        score -= 25.0 * (1.0 - pr_norm);
    }

    // Lookahead synergy: if next item fits the post-residual, big reward.
    if next_item_size > 0 {
        let nxt = next_item_size as f64;
        if nxt <= pr {
            score -= 18.0 * (1.0 - (pr - nxt) / cap);
        } else {
            // Dead space penalty scaled by how far next item misses.
            score += 6.0 * ((nxt - pr) / cap);
        }
    }

    // Mean residual context: penalize bins far from the fleet mean (fragmentation).
    let dev = pr - mean_residual;
    score += 0.15 * dev * dev / cap;

    // Mild penalty for spreading across many bins.
    score += 0.05 * open_bins_count as f64 * pr_norm;

    // New-bin candidate: neutral-ish baseline with slight preference early.
    if bin_residual == bin_capacity {
        score = cap * (0.9 + 0.3 * progress) + 0.05 * mean_residual;
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Harmonic class of the residual: how "nice" is the leftover space?
    // Residuals that are multiples of common item sizes (or divisible by small
    // integers) are more likely reusable, so reward them.
    let pr = post_residual;
    if pr > 0 {
        let mut bonus = 0.0;
        if pr % 10 == 0 { bonus -= 6.0; }
        if pr % 20 == 0 { bonus -= 3.0; }
        if pr % 25 == 0 { bonus -= 3.0; }
        if pr % 5 == 0 { bonus -= 1.5; }
        // divisibility by small integers as a soft reusability signal
        if pr % 3 == 0 { bonus -= 0.5; }
        if pr % 4 == 0 { bonus -= 0.5; }
        score += bonus;
    } else {
        // perfect fill: strongly reward
        score -= 40.0;
    }

    // Dead space penalty: tiny unusable leftovers (1..9) are almost worthless
    if pr > 0 && pr < 10 {
        score += 12.0;
    }

    // Lookahead coupling: if the next item fits exactly in the post residual,
    // this placement chains perfectly — big reward.
    if next_item_size > 0 {
        if next_item_size == pr {
            score -= 30.0;
        } else if next_item_size < pr {
            let slack = pr - next_item_size;
            // harmonic class of slack after the lookahead item
            if slack % 10 == 0 { score -= 5.0; }
            if slack == 0 { score -= 10.0; }
            score += (slack as f64) * 0.15;
        } else {
            // next item won't fit here; mild penalty proportional to overshoot
            score += ((next_item_size - pr) as f64) * 0.05;
        }
    }

    // Last-chance bin: if this is the only bin that fits, prefer using it
    // over opening a new bin, unless the fit is terrible.
    if fitting_bins_count == 1 && bin_residual != bin_capacity {
        score -= 8.0;
        if pr <= 5 { score -= 5.0; }
    }

    // New-bin candidate handling: an empty bin has residual == capacity.
    // Only prefer it when the current item fits badly everywhere else, or
    // when the stream is early and bin count is low.
    if bin_residual == bin_capacity {
        // baseline new-bin score: keep it moderately high so open bins win
        // when they give a decent fit.
        score = 55.0 + (item_size as f64) * 0.2;
        if next_item_size > 0 && next_item_size >= bin_capacity - item_size.min(bin_capacity) {
            // next item is huge; a fresh bin may be useful
            score -= 10.0;
        }
        let progress = step_index as f64 / (total_items.max(1) as f64);
        if open_bins_count == 0 { score -= 60.0; }
        if progress < 0.1 { score -= 5.0; }
    }

    // Tight-fit reward: item fills most of the bin
    let fill = item_size as f64 / bin_residual.max(1) as f64;
    if fill > 0.9 {
        score -= 10.0 * (fill - 0.9) / 0.1;
    }

    // Mild preference to balance residuals toward the mean (avoid many
    // near-empty and many near-full bins simultaneously).
    score += ((post_residual as f64) - mean_residual).abs() * 0.05;

    // Small penalty for spreading across too many open bins
    if open_bins_count > 8 {
        score += (open_bins_count as f64) * 0.1;
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Strict dead-space avoidance: small unusable gaps (1..10) are heavily penalized.
    if post_residual > 0 && post_residual < 10 {
        score += 40.0;
    }
    // Moderate penalty for gaps too small for the smallest plausible next item (1..=next_item_size).
    if next_item_size > 0 && post_residual > 0 && post_residual < next_item_size as f64 {
        score += 15.0;
    }

    // Reward tight fits: residual close to zero is good (already low base).
    if post_residual == 0 {
        score -= 30.0;
    }

    // Open-bin pressure: discourage spreading across many bins; favor filling existing ones.
    score += open_bins_count as f64 * 2.0;

    // Last-chance bonus: if this is the only bin that fits, strongly favor using it
    // over opening a new bin (unless dead space is severe).
    if fitting_bins_count == 1 && bin_residual != bin_capacity {
        score -= 25.0;
    }

    // New-bin candidate: penalize opening a new bin unless it enables a much better future fit.
    if bin_residual == bin_capacity {
        score += 20.0;
        // Opening a new bin is more acceptable when the current item is large
        // and existing residuals are small.
        score -= item_size as f64 * 0.15;
        score += mean_residual * 0.1;
    }

    // Lookahead coupling: if the next item fits exactly in post_residual, reward this placement.
    if next_item_size > 0 && post_residual as u32 == next_item_size {
        score -= 20.0;
    }

    // Slight progression term: late in the stream, prefer tighter packing.
    let progress = step_index as f64 / total_items as f64;
    score -= progress * 5.0;

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Base: prefer tight fits, penalize dead space non-linearly.
    let frac = post_residual as f64 / bin_capacity as f64;
    score += 6.0 * frac * frac;

    // 2-step lookahead: reward if the next item fits exactly into post_residual.
    if next_item_size > 0 {
        let gap = (post_residual as i64 - next_item_size as i64).abs() as f64;
        score -= 8.0 * (1.0 - gap / bin_capacity as f64).max(0.0);
        // Penalize leaving a residual that is awkward relative to next item.
        if next_item_size as u32 > post_residual {
            score += 3.0 * (next_item_size - post_residual) as f64 / bin_capacity as f64;
        }
    } else {
        // Last item: strongly prefer minimal leftover.
        score += 10.0 * frac;
    }

    // Compare residual against mean residual of open bins: avoid making bin outliers.
    score += 0.5 * (post_residual as f64 - mean_residual).abs();

    // Last-chance bin: strongly favor using it to avoid opening a new bin.
    if fitting_bins_count == 1 && bin_residual < bin_capacity {
        score -= 12.0;
    }

    // Slight preference to fill existing bins when many are open.
    score -= 0.3 * open_bins_count as f64 * frac;

    // Mild stream progression weighting: later in stream, be greedier about tight fits.
    let progress = step_index as f64 / total_items.max(1) as f64;
    score -= 4.0 * progress * (1.0 - frac);

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Reward tight fits: smaller post_residual relative to capacity is good.
    let tightness = 1.0 - (post_residual as f64 / bin_capacity as f64);
    score -= 12.0 * tightness * tightness;

    // Penalize leaving small unusable slivers (< smallest plausible item).
    if post_residual > 0 && post_residual < 10 {
        score += 25.0;
    }

    // Last-chance bin bonus: if this is the only fitting bin, strongly prefer it.
    if fitting_bins_count == 1 && bin_residual != bin_capacity {
