    // Lookahead coupling: if the next item fits in the post residual, reward.
    if next_item_size > 0 {
        if next_item_size <= post_residual {
            score -= 15.0;
        } else {
            // Penalize wasting space the next item could have used elsewhere.
            let wasted = (post_residual as f64 - if post_residual >= next_item_size { next_item_size as f64 } else { 0.0 }).max(0.0);
            score += 0.05 * wasted;
        }
    }

    // Global state: when many bins are open with high mean residual,
