    let progress = step_index as f64 / (total_items.max(1) as f64);
    if bin_residual == bin_capacity {
        // New-bin candidate: penalize more when open bins have plenty of room.
        score += 30.0 + 0.5 * (mean_residual - post_residual as f64).max(0.0);
        score += 10.0 * (open_bins_count as f64 / 10.0).min(3.0);
        // Early in stream, new bins are cheaper; later, penalize more.
        score += 20.0 * progress;
    } else {
        // Reward using bins whose residual is close to mean (balanced packing).
        let dev = (bin_residual as f64 - mean_residual).abs();
        score += 0.08 * dev;
    }

    // Slight preference for bins with larger residual when item is large.
    if item_size > bin_capacity / 2 {
        score += 0.1 * (bin_capacity - bin_residual) as f64;
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let t = step_index as f64 / total_items.max(1) as f64;
    let pr = post_residual as f64;
    let cap = bin_capacity as f64;
    let pr_norm = pr / cap;

    // Base: post-residual (tighter fit preferred => lower score).
    let mut score = pr;

    // Non-linear polynomial coupling of residual waste with stream progress.
    // Early on, waste matters less; late, squandering residual is heavily penalized.
    let progress_weight = 0.5 + 2.5 * t * t;
    score += progress_weight * pr_norm * pr_norm * cap;

    // Cubic coupling: penalize mid-sized dead space (unusable for typical items)
    // more than near-zero or large residuals, modulated by progress.
    let mid = (pr_norm - 0.5).abs();
    score += (1.0 - t) * 10.0 * (1.0 - mid * mid) * pr_norm;

    // Reward near-perfect fits smoothly.
    let perfect = 1.0 - pr_norm;
    score -= 15.0 * perfect * perfect * perfect * (0.3 + 0.7 * t);

    // Lookahead: bonus if next item fits the post-residual exactly-ish.
    if next_item_size > 0 {
        let gap = (pr - next_item_size as f64).abs();
        if pr >= next_item_size as f64 {
            score -= 8.0 * (1.0 - gap / cap) * (1.0 + t);
        } else {
            score += 4.0 * (gap / cap) * (1.0 + t);
        }
    }

    // Last-chance bin: strongly favor using it rather than opening a new one.
    if fitting_bins_count == 1 && bin_residual != bin_capacity {
        score -= 20.0 * (1.0 - pr_norm);
    }

    // New-bin candidate: penalize mildly so it is chosen only when open fits are bad,
    // with penalty easing as stream progresses (more bins amortized later).
    if bin_residual == bin_capacity {
        score += 6.0 + 10.0 * (1.0 - t) + 0.5 * open_bins_count as f64;
    }

    // Mean residual context: if this bin's residual deviates far below mean,
    // it's a good consolidation target.
    let dev = (pr - mean_residual) / cap;
    score -= 5.0 * dev * (1.0 - t);

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let cap = bin_capacity as f64;
    let mut score = post_residual as f64;

    // Harmonic class of the post residual: mod-10 buckets.
    let pr = post_residual;
    let harmonic = pr % 10;

    // Reward residuals that are "clean" multiples of 10 (likely reusable).
    if pr == 0 {
        score -= 50.0; // perfect fit
    } else if harmonic == 0 {
        score -= 12.0;
    } else if harmonic <= 2 || harmonic >= 8 {
        // ragged edge: dead space likely
        score += 6.0 + harmonic as f64;
    }

    // Penalize small unusable leftovers below the minimum item size.
    if pr > 0 && pr < 10 {
        score += 25.0;
    }

    // Coupling with next item: if the lookahead fits exactly into post_residual, big reward.
    if next_item_size > 0 {
        if next_item_size == pr {
            score -= 40.0;
        } else if next_item_size < pr {
            let nxt_res = pr - next_item_size;
            score -= 8.0;
            if nxt_res % 10 == 0 { score -= 10.0; }
            if nxt_res < 10 { score += 15.0; }
        } else {
            score += 5.0; // lookahead won't fit here
        }
    }

    // Tight fit reward: fraction of bin consumed by this item.
    let fill_frac = item_size as f64 / cap;
    score -= 10.0 * fill_frac;

    // Last-chance bin: strongly favor using it to avoid opening a new bin.
    if fitting_bins_count == 1 && bin_residual != bin_capacity {
        score -= 30.0;
    }

    // New-bin candidate: make it attractive only when existing bins fit poorly.
    if bin_residual == bin_capacity {
        score = 55.0 - 5.0 * mean_residual / cap;
        if next_item_size > 0 && next_item_size >= item_size {
            score -= 10.0; // pair large items together in fresh bins
        }
        if fitting_bins_count <= 1 {
            score -= 20.0;
        }
    }

    // Late in the stream, consolidate: prefer filling existing bins.
    let progress = step_index as f64 / total_items.max(1) as f64;
    score += 8.0 * progress * (open_bins_count as f64 / (open_bins_count.max(1) as f64 + 5.0));

    // Mean residual alignment: prefer bins near the mean residual (balanced packing).
    let dev = (bin_residual as f64 - mean_residual).abs();
    score += 0.05 * dev;

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Strict dead-space avoidance: residuals that are too small to be useful
    // for any realistic item (min size 1..100 stream, but typical items > 10)
    // are heavily penalized as unusable dead space.
    let dead_threshold: f64 = 12.0;
    if post_residual > 0 && (post_residual as f64) < dead_threshold {
        score += (dead_threshold - post_residual as f64) * 6.0;
    }

    // Bonus for near-perfect fills.
    if post_residual == 0 {
        score -= 40.0;
    }

    // Reward leaving room for the lookahead item if it could fit.
    if next_item_size > 0 && post_residual >= next_item_size {
        score -= 8.0;
    }
    // Penalize if next item would have fit before but not after.
    if next_item_size > 0 && bin_residual >= next_item_size && post_residual < next_item_size {
        score += 5.0;
    }

    // Tight-fit reward: item occupies most of the residual.
    let fill_ratio = item_size as f64 / bin_residual.max(1) as f64;
    if fill_ratio > 0.8 {
        score -= 10.0 * (fill_ratio - 0.8);
    }

    // Open-bin pressure: when many bins are open, discourage spreading;
    // prefer consolidating into existing bins over opening new ones.
    let progress = step_index as f64 / (total_items.max(1) as f64);
    let pressure = open_bins_count as f64 * (0.3 + 0.7 * progress);
    if bin_residual == bin_capacity {
        // New-bin candidate: penalize more when pressure is high.
        score += 15.0 + pressure * 2.0;
    } else {
        // Existing bins get a mild discount scaled by pressure.
        score -= 2.0 + pressure * 0.5;
    }

    // Last-chance bin: if this is the only bin that fits, strongly prefer it
    // over opening a new bin.
    if fitting_bins_count == 1 && bin_residual != bin_capacity {
        score -= 12.0;
    }

    // Prefer bins whose residual deviates from mean residual in a way that
    // reduces fragmentation: placing into below-mean-residual bins tightens
    // the residual distribution.
    if bin_residual != bin_capacity {
        let dev = (bin_residual as f64 - mean_residual).abs();
        score += dev * 0.15;
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Base: prefer tight fits (small post_residual already favored).

    // 2-step lookahead: strongly reward bins where the NEXT item also fits
    // the resulting residual (perfect chaining of two items).
    if next_item_size > 0 {
        if post_residual == next_item_size {
            // Exact two-item fill: ideal, big reward.
            score -= 60.0;
        } else if post_residual >= next_item_size {
            // Next item fits, but penalize leftover slack after it.
            let slack_after_next = post_residual - next_item_size;
            score -= 40.0 - 0.35 * slack_after_next as f64;
        } else {
            // Next item won't fit here: penalize proportionally to the miss.
            let miss = (next_item_size - post_residual) as f64;
            score += 0.25 * miss;
        }
    }

    // Relative-to-mean coupling: bins with residual far below mean are
    // already "cramped"; placing here is fine only if fit is tight.
    let dev = post_residual as f64 - mean_residual;
    score += 0.10 * dev;

    // Last-chance bin: if this is the only bin that fits, avoid opening
    // a new bin unless the fit is terrible.
    if fitting_bins_count == 1 && bin_residual != bin_capacity {
        score -= 15.0 + 0.2 * item_size as f64;
    }

    // New-bin candidate: neutral-ish baseline; only attractive when all
    // open fits are bad. Penalize slightly so we prefer reusing bins
    // with decent fits, but keep it competitive when post_residual is large.
    if bin_residual == bin_capacity {
        score += 12.0;
        // Late in the stream, opening fresh bins is less wasteful.
        let progress = step_index as f64 / total_items.max(1) as f64;
        score -= 8.0 * progress;
    }

    // Mild pressure against accumulating many open bins with large holes.
    if open_bins_count > 3 {
        score += 0.02 * (open_bins_count as f64 - 3.0) * (post_residual as f64 / bin_capacity as f64);
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Base: strongly prefer tight fits (low post_residual)
    let fit_ratio = post_residual as f64 / bin_capacity as f64;
    score += 40.0 * fit_ratio * fit_ratio;

    // Reward near-perfect fits
    if post_residual == 0 {
        score -= 100.0;
    } else if post_residual < 10 {
        score -= 30.0;
    }

    // Last-chance bin: strongly prefer using it before opening a new bin
    if fitting_bins_count == 1 && bin_residual != bin_capacity {
        score -= 60.0;
    }

    // Lookahead: penalize leaving a residual that exactly fits the next item badly,
    // reward leaving residual that can host the next item
    if next_item_size > 0 {
        let nx = next_item_size as f64;
        if post_residual as f64 >= nx {
            // next item can fit here too — good chaining
            score -= 15.0 * (1.0 - (post_residual as f64 - nx) / bin_capacity as f64);
        } else {
            // residual too small for next item: dead space penalty scaled by proximity
            let waste = post_residual as f64;
            if waste > 0.0 && waste < nx {
                score += 8.0 * (1.0 - waste / nx.max(1.0));
            }
        }
    } else {
        // Last item: just close bins as tightly as possible
        score -= 20.0;
    }

    // Global state: many open bins with large mean residual -> consolidate into existing bins
    let progress = if total_items > 0 { step_index as f64 / total_items as f64 } else { 0.0 };
    if bin_residual != bin_capacity {
        if mean_residual > 30.0 && open_bins_count > 3 {
            score -= 10.0 * (mean_residual / bin_capacity as f64);
        }
        // Late in stream: avoid opening new bins, prefer filling existing ones
        if progress > 0.7 {
            score -= 25.0 * progress;
        }
    } else {
        // New-bin candidate: penalize unless item is large or few fitting bins
        score += 30.0;
        if item_size > 50 {
            score -= 20.0;
        }
        if fitting_bins_count == 0 {
            score -= 50.0;
        }
        if progress > 0.7 {
            score += 15.0 * progress;
        }
    }

    // Mild penalty for very small leftovers that no realistic item (>=1) can use well
    if post_residual > 0 && post_residual < 5 {
        score += 12.0;
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let c = bin_capacity as f64;
    let pr = post_residual as f64;
    let progress = step_index as f64 / total_items as f64;
    let norm_pr = pr / c;

    // Base: prefer tight fits (small post_residual)
    let mut score = pr as f64;

    // Smooth polynomial coupling of post_residual with stream progress:
    // early on, tolerate larger residuals; late in the stream, penalize them harder.
    let t = progress * progress * (3.0 - 2.0 * progress); // smoothstep
    score += 40.0 * norm_pr * norm_pr * (1.0 + 2.0 * t);

    // Cubic interaction: residual vs mean residual coupling
    let mr = mean_residual / c;
    score += 15.0 * (norm_pr - mr) * (norm_pr - mr) * (norm_pr - mr) * c;

    // Lookahead: reward if next item fits in post_residual (smoothly)
    if next_item_size > 0 {
        let nx = next_item_size as f64;
        let gap = pr - nx;
        let fit_bonus = if gap >= 0.0 {
            20.0 * (1.0 - (gap / c).powi(2))
        } else {
            -10.0 * (gap.abs() / c)
        };
        score -= fit_bonus;
    }

    // Last-chance bin: strongly favor using it
    if fitting_bins_count == 1 {
        score -= 25.0;
    } else if fitting_bins_count > 1 {
        score += 3.0 * (fitting_bins_count as f64 - 1.0).sqrt();
    }

    // Mild penalty for too many open bins
    score += 1.5 * (open_bins_count as f64).ln();

    // Slight preference for opening a new bin early (empty-bin candidate has pr == c)
    let is_new = (bin_residual as f64 - c).abs() < 1e-6;
    if is_new {
        score += 5.0 * (1.0 - t) - 5.0 * t;
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // --- Harmonic class decomposition of post_residual ---
    // Class residuals into harmonic buckets: perfect fit, small remainder, half-bin, dead space.
    let pr = post_residual as f64;
    let cap = bin_capacity as f64;

    // Perfect fit: huge reward.
    if post_residual == 0 {
        score -= 1000.0;
    }

    // Harmonic thresholds: residual in {1..=5} tiny waste, {6..=15} small, {16..=30} medium, >30 dead.
    if post_residual >= 1 && post_residual <= 5 {
        score -= 40.0; // near-perfect packing, strongly favored
    } else if post_residual <= 15 {
        score -= 20.0;
    } else if post_residual <= 30 {
        score -= 5.0;
    } else {
        // Dead space: waste grows super-linearly beyond half-capacity.
        score += 0.6 * (pr - 30.0);
    }

    // --- Lookahead coupling (k=2) ---
    if next_item_size > 0 {
        let nxt = next_item_size as f64;
        if nxt <= pr {
            // Next item fits in this residual: strong reward scaled by tightness of the chain.
            score -= 60.0 * (nxt / (pr + 1.0));
        } else {
            // Next item won't fit: residual likely wasted; penalize large residuals.
            score += 0.25 * (pr - nxt).abs().min(pr);
            // If next item is large, prefer bins that keep flexible space.
            if nxt > 50.0 {
                score += 0.1 * pr;
            }
        }
    }

    // --- Modulo / integer-division harmonic classes on post_residual ---
    // Residuals that are near multiples of common small item sizes are more reusable.
    let harmonic_bonus = |r: u32| -> f64 {
        let mut b = 0.0;
        for m in [10u32, 20, 25, 50].iter() {
            let q = r / m;
            let rem = r % m;
            if rem <= 2 && q >= 1 {
                b += 8.0; // residual close to a harmonic class boundary: reusable
            }
        }
        b
    };
    score -= harmonic_bonus(post_residual);

    // --- Last-chance bin logic ---
    if fitting_bins_count == 1 && bin_residual < bin_capacity {
        // This is the only bin that fits: avoid opening a new bin unless residual is terrible.
        score -= 25.0;
    }

    // --- New-bin candidate handling ---
    if bin_residual == bin_capacity {
        // Opening a new bin: base penalty so it's chosen only when open bins fit poorly.
        score = cap * 0.5;
        // More open bins -> mild extra penalty (prefer consolidation).
        score += 2.0 * open_bins_count as f64;
        // Late in the stream, slightly prefer closing out bins.
        let progress = step_index as f64 / total_items.max(1) as f64;
        score += 10.0 * (1.0 - progress);
        // If item is huge relative to capacity, new bin is fine (fresh space).
        if item_size as f64 > 0.6 * cap {
            score -= 30.0;
        }
        // If next item is large and current open bins are tight, new bin attractive.
        if next_item_size > 0 && (next_item_size as f64) > mean_residual {
            score -= 15.0;
        }
    }

    // --- Mean residual coupling: prefer bins below mean residual (tighter bins) ---
    score += 0.15 * (pr - mean_residual);

    // --- Progress-aware waste tolerance ---
    let progress = step_index as f64 / total_items.max(1) as f64;
    score += 5.0 * progress * (pr / cap);

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Strict dead-space avoidance: residuals too small for the smallest
    // possible future item (<= 1..100 unknown, so treat < 10 as dead)
    // are heavily penalized, scaled by how dead they are.
    let dead_threshold: f64 = 10.0;
    let pr = post_residual as f64;
    if pr > 0.0 && pr < dead_threshold {
        score += (dead_threshold - pr) * 6.0;
    }

    // Semi-dead zone: residual too small for the lookahead item but not tiny
    if next_item_size > 0 && pr > 0.0 && pr < next_item_size as f64 {
        score += (next_item_size as f64 - pr) * 2.5;
    }
    // Reward leaving room exactly for the lookahead item
    if next_item_size > 0 && pr == next_item_size as f64 {
        score -= 8.0;
    }

    // Reward tight fits (small post_residual relative to bin capacity)
    let tightness = 1.0 - pr / bin_capacity as f64;
    score -= tightness * 12.0;

    // Last-chance bin: strongly favor using the only bin that fits
    if fitting_bins_count == 1 && bin_residual >= item_size {
        score -= 15.0;
    }

    // Open-bin pressure: with many open bins, prefer consolidation
    // (favor bins with below-mean residual, i.e. fuller bins)
    score += (mean_residual - bin_residual as f64) * 0.5;
    score += open_bins_count as f64 * 0.3;

    // New-bin candidate: make it attractive only when no open bin fits well.
    // Penalize opening a new bin mildly, more so late in the stream.
    let progress = step_index as f64 / total_items.max(1) as f64;
    if bin_residual == bin_capacity {
        score = bin_capacity as f64 * 0.9 + open_bins_count as f64 * 2.0 + progress * 10.0;
        // But if the current item nearly fills a fresh bin, a new bin is fine
        if item_size as f64 >= bin_capacity as f64 * 0.85 {
            score -= 30.0;
        }
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Strongly favor exact fits / tiny post residual (non-linear penalty).
    if post_residual == 0 {
        score -= 1000.0;
    } else {
        score += (post_residual as f64).powi(2) * 0.05;
    }

    // 2-step lookahead: reward bins whose post_residual matches next item exactly.
    if next_item_size > 0 {
        let lookahead_gap = (post_residual as i64 - next_item_size as i64).abs() as f64;
        if post_residual == next_item_size {
            score -= 500.0;
        } else if post_residual >= next_item_size {
            // Next item fits here after current placement: reward proportionally.
            score -= 100.0 * (next_item_size as f64 / post_residual as f64);
        } else {
            // Next item won't fit here: penalize wasted capacity relative to mean residual.
            score += lookahead_gap * 0.3;
        }
    }

    // Compare against mean residual: prefer bins tighter than average.
    score += (post_residual as f64 - mean_residual) * 0.2;

    // Last-chance bin: strongly prefer using it to avoid opening a new bin.
    if fitting_bins_count == 1 {
        score -= 150.0;
    } else if fitting_bins_count > 1 {
        // Among many candidates, mild preference for tighter fits.
        score += fitting_bins_count as f64 * 0.5;
    }

    // New-bin candidate handling: only open a new bin when current fits are poor.
    if bin_residual == bin_capacity {
        // Neutral base; becomes attractive only if item is large relative to mean residual.
        score = 50.0 + (item_size as f64 - mean_residual).max(0.0) * 0.4;
        if fitting_bins_count <= 1 {
            score -= 200.0; // no good alternative: new bin is fine
        }
    }

    // Late in stream: discourage opening new bins.
    let progress = step_index as f64 / total_items.max(1) as f64;
    if bin_residual == bin_capacity {
        score += progress * 100.0;
    } else {
        score -= progress * 10.0;
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Reward tight fits strongly (non-linear in post_residual).
    let tightness = 1.0 - (post_residual as f64 / bin_capacity as f64);
    score -= 24.0 * tightness * tightness * tightness;

    // Lookahead: bonus if the next item fits into the post-residual (good pairing).
    if next_item_size > 0 {
        if post_residual >= next_item_size {
            score -= 8.0 + 0.15 * next_item_size as f64;
        } else {
            // Penalize leaving residual that is too small to be useful.
            let dead = post_residual as f64;
            score += 0.5 * dead * (dead / 20.0).min(1.0);
        }
    }

    // Last-chance bin: strongly favor using it to avoid opening a new bin.
    if fitting_bins_count == 1 && bin_residual >= item_size && bin_residual != bin_capacity {
        score -= 15.0 + 0.2 * item_size as f64;
    }

    // Many open bins: encourage filling existing bins rather than spreading.
    if open_bins_count > 2 {
        score += 0.4 * open_bins_count as f64 * (mean_residual / bin_capacity as f64);
    }

    // New-bin candidate handling: penalize opening a new bin unless the item
    // is large relative to typical residuals or we are early in the stream.
    if bin_residual == bin_capacity {
        let progress = step_index as f64 / total_items.max(1) as f64;
        let large_item = item_size as f64 > mean_residual;
        if large_item || open_bins_count == 0 || progress < 0.05 {
            score -= 20.0; // opening a fresh bin is reasonable
        } else {
            score += 25.0; // discourage abandoning open bins with usable space
        }
    }

    // Mild time-horizon modulation: later in the stream, be greedier about
    // consolidation (favor bins that end up nearly full).
    let progress = step_index as f64 / total_items.max(1) as f64;
    score -= progress * 6.0 * (1.0 - post_residual as f64 / bin_capacity as f64);

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let progress = if total_items > 1 { step_index as f64 / (total_items - 1) as f64 } else { 0.0 };
    let cap = bin_capacity as f64;
    let pr = post_residual as f64;
    let norm_pr = pr / cap;
    let fit_ratio = item_size as f64 / bin_residual.max(1) as f64;

    let mut score = pr as f64;

    // Smooth non-linear coupling: penalize residual quadratically, more as stream progresses
    score += 6.0 * norm_pr * norm_pr * (0.5 + progress);

    // Reward tight fits (post residual near zero) with smooth decay
    score -= 14.0 * (1.0 - norm_pr).powi(3) * (1.0 + 2.0 * progress);

    // Penalize exact-fill waste potential via fit ratio coupling
    score += 4.0 * fit_ratio * fit_ratio * (1.0 - progress);

    // Lookahead: reward bins whose post-residual can host the next item
    if next_item_size > 0 {
        let nxt = next_item_size as f64;
        if pr >= nxt {
            score -= 5.0 * (1.0 - (pr - nxt) / cap) * (0.4 + 0.6 * progress);
        } else {
            score += 3.0 * (nxt - pr) / cap;
        }
    }

    // Last-chance bonus: if this is the only fitting bin, strongly favor using it
    if fitting_bins_count == 1 {
        score -= 10.0 * (1.0 - 0.5 * progress);
    }

    // Mild pressure to consolidate when many bins are open
    score += 0.8 * (open_bins_count as f64).ln().max(0.0) * norm_pr;

    // Mean residual coupling: prefer bins below mean residual (tighter bins)
    score += 2.0 * (pr - mean_residual) / cap;

    // New-bin candidate handling: make empty bins less attractive unless nothing fits well
    if bin_residual == bin_capacity {
        score += 12.0 - 6.0 * progress - 8.0 * (1.0 - fit_ratio);
        if fitting_bins_count == 0 {
            score -= 20.0;
        }
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Base: prefer tight fits
    let frac_used = (bin_capacity - post_residual) as f64 / bin_capacity as f64;
    score -= 40.0 * frac_used;

    // Harmonic class of post_residual: residues divisible by common item sizes
    // are "harmonic" (reusable dead space); odd primes are dead.
    let pr = post_residual;
    let mut harmonic = 0.0f64;
    for d in [10u32, 20, 25, 30, 40, 50, 80, 100] {
        if pr >= d && pr % d == 0 {
            harmonic += 1.0;
        }
    }
    score -= 6.0 * harmonic;

    // Integer-division threshold classes on post_residual
    let class = pr / 10; // 0..10
    score -= match class {
        0 => 25.0,          // near-perfect fit
        1 => 18.0,
        2 => 12.0,
        3 | 4 => 6.0,
        5 => 3.0,
        _ => 0.0,
    } as f64;

    // Lookahead compatibility: post_residual should pair well with next item
    if next_item_size > 0 {
        if next_item_size <= pr {
            // exact harmonic match with leftover
            if pr % next_item_size == 0 && pr > 0 {
                score -= 15.0;
            } else {
                score -= 5.0;
            }
        } else {
            // next item won't fit here: penalize proportional to overshoot
            let over = (next_item_size - pr) as f64;
            score += 0.3 * over;
        }
    }

    // Last-chance bin: strong reward to use it
    if fitting_bins_count == 1 && bin_residual != bin_capacity {
        score -= 30.0;
    }

    // New-bin candidate handling: only attractive late in stream or when
    // existing fits are poor (post_residual large relative to item)
    if bin_residual == bin_capacity {
        let progress = step_index as f64 / total_items.max(1) as f64;
        let poor_fit = (post_residual as f64) > 0.5 * bin_capacity as f64;
        if poor_fit || progress > 0.8 {
            score -= 8.0 + 10.0 * progress;
        } else {
            score += 20.0; // discourage opening new bins early on good fits
        }
    }

    // Mild pressure to consolidate: fewer open bins relative to items
    score += 0.5 * (open_bins_count as f64).ln().max(0.0);

    // Coupling with mean residual: if this bin is far from mean, slight penalty
    score += 0.05 * ((post_residual as f64 - mean_residual).abs());

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Strict dead-space avoidance: residuals that are too small to ever
    // hold a minimum-size item (1..=threshold) are pure waste.
    let dead_threshold = 8u32;
    if post_residual >= 1 && post_residual <= dead_threshold {
        score += (dead_threshold - post_residual + 1) as f64 * 25.0;
    }

    // Small-but-usable residuals are also risky: penalize proportionally
    // to how unlikely a future item fits exactly.
    if post_residual > dead_threshold && post_residual <= 20 {
        score += (20.0 - post_residual as f64) * 1.5;
    }

    // Reward tight fits (low post_residual) extra.
    if post_residual <= 5 {
        score -= 30.0;
    }

    // Perfect fit: huge reward.
    if post_residual == 0 {
        score -= 100.0;
    }

    // Last-chance bin: strongly favor using it to avoid opening a new bin.
    if fitting_bins_count == 1 && bin_residual != bin_capacity {
        score -= 40.0;
    }

    // Open-bin pressure: penalize placements that keep many bins open with
    // fragmented residuals; encourage consolidation.
    score += open_bins_count as f64 * 0.5;

    // If this bin's residual is well below the mean, it is a good filler;
    // if well above, placing here leaves a large gap elsewhere.
    let dev = bin_residual as f64 - mean_residual;
    if dev > 0.0 {
        score += dev * 0.3;
    } else {
        score -= 0.15 * (-dev);
    }

    // New-bin candidate handling: only attractive when no open bin fits well
    // or the stream is early and open-bin count is low.
    if bin_residual == bin_capacity {
        // Base cost of opening a new bin.
        score += 55.0 + open_bins_count as f64 * 2.0;

        // If the only fitting bin is a poor fit (large dead space), opening
        // a fresh bin becomes competitive.
        if fitting_bins_count == 1 && post_residual > 30 {
            score -= 70.0;
        }
        // Lookahead: if next item is large, a fresh bin is more flexible.
        if next_item_size > 0 && next_item_size > bin_capacity - 40 {
            score -= 25.0;
        }
    } else {
        // Lookahead synergy: if the next item fits exactly in the post
        // residual, reward placing the current item here.
        if next_item_size > 0 && next_item_size <= post_residual {
            let gap = post_residual - next_item_size;
            if gap <= 5 {
                score -= 20.0;
            }
        }
        // Avoid blocking a large next item by consuming residual it needs.
        if next_item_size > post_residual && post_residual < 15 {
            score += 10.0;
        }
    }

    // Late-stream consolidation: prefer filling existing bins as the
    // stream nears its end.
    let progress = step_index as f64 / (total_items.max(1) as f64);
    if bin_residual != bin_capacity {
        score -= progress * 10.0;
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Perfect 2-step match: post_residual exactly equals next item size.
    if next_item_size > 0 && post_residual == next_item_size {
        score -= 60.0;
    }
    // Near-match: next item fits with small slack left.
    else if next_item_size > 0 && next_item_size <= post_residual {
        let slack = (post_residual - next_item_size) as f64;
        score -= 40.0 / (1.0 + slack);
    }
    // Next item does NOT fit this residual: penalize proportionally to how
    // much of the residual is wasted relative to the next item's need.
    else if next_item_size > 0 && post_residual > 0 {
        let miss = next_item_size as f64 - post_residual as f64;
        score += miss * 0.35;
    }

    // Reward tight fits relative to mean residual across open bins.
    let pr = post_residual as f64;
    if mean_residual > 0.0 {
        score += (pr - mean_residual) * 0.25;
    }

    // Penalize dead space scaled by stream progression (late waste costs more).
    let progress = step_index as f64 / total_items.max(1) as f64;
    score += pr * 0.15 * progress;

    // Last-chance bin: strongly favor using it to avoid opening a new bin.
    if fitting_bins_count == 1 && bin_residual != bin_capacity {
        score -= 25.0;
    }

    // New-bin candidate: neutral base; encourage opening fresh bins only when
    // the current item is large and would leave an awkward residual.
    if bin_residual == bin_capacity {
        score = bin_capacity as f64 * 0.5 - item_size as f64 * 0.3;
        if next_item_size > 0 && next_item_size >= item_size {
            score -= 10.0; // pairing large items together in a fresh bin
        }
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Reward tight fits: square the post-residual so small leftovers dominate.
    score += (post_residual as f64).powi(2) / (bin_capacity as f64);

    // Perfect fit bonus.
    if post_residual == 0 {
        score -= 50.0;
    }

    // Last-chance bonus: if this is the only bin that fits, strongly prefer it.
    if fitting_bins_count == 1 && bin_residual < bin_capacity {
        score -= 40.0;
    }

    // Lookahead: if the next item fits the post-residual, reward chaining.
    if next_item_size > 0 {
        if next_item_size <= post_residual {
            score -= 15.0 + 0.2 * next_item_size as f64;
        } else if next_item_size <= bin_residual {
            // This bin could have taken the next item; penalize wasting that chance.
            score += 10.0;
        }
        // Penalize leaving a residual that is too small for the smallest plausible item.
        if post_residual > 0 && post_residual < 10 {
            score += 12.0;
        }
    }

    // Prefer filling bins with larger residuals among many open bins (reduce fragmentation).
    score -= 0.3 * (bin_residual as f64 - mean_residual);

    // Encourage consolidation when many bins are open.
    score += 0.5 * open_bins_count as f64 * (post_residual as f64 / bin_capacity as f64);

    // Time horizon: early in the stream, be more conservative about opening new bins
    // (a new-bin candidate has bin_residual == bin_capacity).
    let progress = step_index as f64 / (total_items.max(1) as f64);
    if bin_residual == bin_capacity {
        // New-bin candidate: penalize early, relax later.
        score += 30.0 * (1.0 - progress) + 10.0;
        // If no open bin fits at all (this is the only fitting option), soften the penalty.
        if fitting_bins_count <= 1 {
            score -= 45.0;
        }
    }

    // Slight preference for bins whose residual is close to item size (best-fit flavor).
    score -= 0.1 * (bin_residual as f64 - item_size as f64).abs();

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let progress = if total_items > 0 { step_index as f64 / total_items as f64 } else { 0.0 };
    let cap = bin_capacity as f64;
    let post = post_residual as f64;
    let x = post / cap; // normalized post residual in [0,1]

    // Base: reward tight fits with a smooth non-linear (quartic) penalty on waste.
    let mut score = post;

    // Non-linear coupling: waste is more costly as the stream progresses
    // (fewer future items to fill leftover gaps), scaled quartically.
    score += 40.0 * x * x * (0.5 + progress) * (1.0 + progress);

    // Perfect-fit reward (smooth bump near zero residual).
    score -= 25.0 * (1.0 - x).powi(6);

    // Lookahead coupling: if the next item fits the post residual, reward this bin;
    // smooth interaction of post residual with next item size.
    if next_item_size > 0 {
        let nxt = next_item_size as f64;
        let gap = post - nxt;
        if gap >= 0.0 {
            let g = gap / cap;
            score -= 18.0 * (1.0 - g) * (1.0 - progress * 0.5);
        } else {
            // post residual too small for next item: penalize unusable slivers
            score += 10.0 * (1.0 - x) * x;
        }
    }

    // Last-chance bonus: if this is the only bin that fits, strongly favor using it
    // rather than opening a new bin.
    if fitting_bins_count == 1 && bin_residual < bin_capacity {
        score -= 30.0;
    }

    // New-bin candidate handling: an empty bin has full residual; make it mildly
    // unattractive vs. tight fits, but attractive when existing bins are fragmented.
    if bin_residual == bin_capacity {
        score = cap - 15.0 + 10.0 * progress;
        // If no existing bin fits well (this call is the new-bin candidate), open it.
        if post_residual == bin_capacity && (fitting_bins_count == 0 || x * cap == cap as u32 as f64) {
            score -= 45.0;
        }
        // Prefer opening a new bin when mean residual of open bins is small/fragmented.
        score -= (mean_residual / cap) * 5.0;
    }

    // Mild penalty for spreading across many open bins when residuals are large.
    score += (open_bins_count as f64).ln() * 2.0 * x;

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let cap = bin_capacity as f64;
    let mut score = post_residual as f64;

    // Harmonic class of the post residual: residuals that are multiples of
    // common item-size classes (e.g. multiples of 10, or halves/quarters of
    // capacity) are more likely to be filled by future items.
    let pr = post_residual;
    let class_bonus = if pr == 0 {
        -60.0 // perfect fill: best possible outcome
    } else if pr % 10 == 0 {
        -12.0
    } else if pr % 5 == 0 {
        -6.0
    } else if cap / 2.0 as f64 == pr as f64 || pr * 2 == bin_capacity {
        -10.0
    } else {
        0.0
    };
    score += class_bonus;

    // Tightness reward: fraction of the bin used by this placement.
    let fill = item_size as f64 / cap;
    score -= 30.0 * fill * fill;

    // Lookahead: if the next item fits exactly in the post residual, reward strongly.
    if next_item_size > 0 {
        if next_item_size == pr {
            score -= 45.0;
        } else if next_item_size <= pr {
            // next item still fits: mild reward proportional to leftover after it
            let after_next = (pr - next_item_size) as f64;
            score -= 15.0 * (1.0 - after_next / cap);
        } else {
            // next item would be blocked by this placement: penalize,
            // but less if many other bins could host the next item.
            let blocking = 10.0 + 0.25 * next_item_size as f64;
            let escape = (fitting_bins_count as f64).min(6.0) / 6.0;
            score += blocking * (1.0 - escape);
        }
    }

    // Last-chance bin: if this is the only bin that can fit the item,
    // strongly prefer using it over opening a new bin.
    if fitting_bins_count == 1 && bin_residual != bin_capacity {
        score -= 25.0;
    }

    // New-bin candidate handling: an empty bin is a costly resource.
    if bin_residual == bin_capacity {
        // Base penalty for opening a new bin.
        score += 18.0;
        // If item fills a large fraction, a fresh bin is fine (perfect packing).
        if item_size as u32 == bin_capacity {
            score -= 100.0;
        } else if fill > 0.7 {
            score -= 12.0;
        }
        // If no open bin fits well (post residual small in existing bins is
        // already captured), discourage new bins when open bins are plentiful.
        score += 2.0 * (open_bins_count as f64).min(10.0);
        // Late in the stream, prefer consolidating into open bins.
        let progress = step_index as f64 / total_items.max(1) as f64;
        score += 10.0 * progress;
    } else {
        // Using an existing bin is generally good; scale with mean residual
        // dispersion: prefer bins whose residual deviates from the mean
        // (consume outliers first, keep uniform residuals flexible).
        let dev = (bin_residual as f64 - mean_residual).abs();
        score -= 3.0 * (dev / cap);
    }

    // Small global tie-breaker favoring earlier-opened (lower-residual) bins.
    score += 0.01 * (open_bins_count as f64);

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Strict dead-space avoidance: residuals that are too small to be useful
    // (below the minimum plausible item size) are heavily penalized.
    let min_item = 1u32;
    if post_residual > 0 && post_residual < min_item + 8 {
        score += 40.0 + (min_item + 8 - post_residual) as f64 * 6.0;
    }

    // Reward near-perfect fills.
    if post_residual == 0 {
        score -= 60.0;
    }

    // Perfect next-item chaining: if the lookahead fits exactly into the gap,
    // strongly favor this bin.
    if next_item_size > 0 && post_residual == next_item_size {
        score -= 45.0;
    } else if next_item_size > 0 && post_residual >= next_item_size {
        score -= 12.0;
    }

    // Last-chance bonus: if this is the only bin that fits, avoid opening a new bin.
    if fitting_bins_count == 1 && bin_residual >= item_size && bin_residual != bin_capacity {
        score -= 30.0;
    }

    // Open-bin pressure: with many open bins, prefer consolidating into existing
    // bins rather than spreading; penalize bins far from the mean residual.
    let progress = step_index as f64 / (total_items.max(1) as f64);
    score += open_bins_count as f64 * 1.5 * (0.5 + progress);
    score -= (bin_residual as f64 - mean_residual).clamp(-50.0, 50.0) * 0.15;

    // New-bin candidate: only attractive when existing bins would leave large
    // unusable gaps or no bin fits well.
    if bin_residual == bin_capacity {
        let base = bin_capacity as f64 * 0.62;
        score += base + open_bins_count as f64 * 2.0;
        if post_residual >= 60 {
            score -= 25.0; // a fresh bin with big usable space is fine
        }
        if fitting_bins_count == 0 {
            score -= 1000.0; // must open a new bin
        }
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Perfect fit reward: strong bonus when the item exactly fills the bin.
    if post_residual == 0 {
        score -= 1000.0;
    }

    // 2-step lookahead: if the next item exactly fits the post-residual,
    // this placement creates a chain, reward heavily.
    if next_item_size > 0 {
        if post_residual == next_item_size {
            score -= 400.0;
        } else if post_residual > next_item_size {
            // Next item fits inside remaining space; mild reward scaled by tightness.
            let slack = (post_residual - next_item_size) as f64;
            score -= 80.0 * (1.0 - slack / bin_capacity as f64);
        } else {
            // Next item cannot use the residual; penalize dead space proportionally.
            let dead = post_residual as f64;
            score += 0.5 * dead * (1.0 + dead / bin_capacity as f64);
        }
    }

    // Prefer bins whose residual is already small (tight packing).
    let tightness = 1.0 - (bin_residual as f64 / bin_capacity as f64);
    score -= 30.0 * tightness;

    // Relative to mean residual: placing into a below-average-residual bin
    // consolidates space; reward that.
    score -= 10.0 * (mean_residual - bin_residual as f64) / bin_capacity as f64;

    // Last-chance bin: if this is the only bin that fits, strongly prefer it
    // to avoid opening a new bin.
    if fitting_bins_count == 1 && bin_residual != bin_capacity {
        score -= 250.0;
    }

    // Penalize the brand-new empty bin candidate mildly, unless the item is
    // huge relative to capacity or many bins are open (bin-opening pressure).
    if bin_residual == bin_capacity {
        let item_frac = item_size as f64 / bin_capacity as f64;
        let pressure = open_bins_count as f64 / (1.0 + step_index as f64 / (total_items.max(1) as f64)).max(1.0);
        score += 120.0 - 100.0 * item_frac - 5.0 * pressure;
        // If next item is small, a fresh bin wastes capacity; extra penalty.
        if next_item_size > 0 && next_item_size < post_residual {
            score += 40.0;
        }
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Strong preference for tight fits (best-fit core with non-linear sharpening)
    let fit_ratio = post_residual as f64 / bin_capacity as f64;
    score += fit_ratio * fit_ratio * 30.0;

    // Lookahead: reward bins whose post-residual can host the next item
    if next_item_size > 0 {
        if post_residual >= next_item_size {
            score -= 12.0;
        } else {
            // penalize wasting space the next item could not use
            score += (post_residual as f64).min(next_item_size as f64) * 0.35;
        }
        // exact chaining bonus: residual becomes exactly the next item size
        if post_residual == next_item_size {
            score -= 15.0;
        }
    }

    // Last-chance bin: strongly favor using the only bin that fits
    if fitting_bins_count == 1 && bin_residual >= item_size {
        score -= 25.0;
    }

    // New-bin candidate logic: make empty bins moderately attractive only when
    // existing fits are bad or few bins fit the item
    let is_new_bin = bin_residual == bin_capacity;
    if is_new_bin {
        // baseline penalty so we prefer reusing bins with good fits
        score += 18.0;
        // if this item fits poorly everywhere else, new bin becomes competitive
        if fitting_bins_count <= 1 {
            score -= 30.0;
        }
        // early in stream: opening bins builds flexibility
        let progress = step_index as f64 / total_items.max(1) as f64;
        if progress < 0.3 {
            score -= 8.0 * (0.3 - progress) * 10.0;
        }
        // many open bins with large mean residual: reuse instead of opening
        if mean_residual > item_size as f64 * 1.5 {
            score += 10.0;
        }
        // avoid opening a new bin when the next item is large and would
        // benefit from a fresh bin anyway later
        if next_item_size > 60 && post_residual < next_item_size {
            score -= 6.0;
        }
    } else {
        // favor bins whose residual is close to mean (spread load evenly)
        let dev = (bin_residual as f64 - mean_residual).abs();
        score += dev * 0.15;
        // slightly prefer bins with larger residual among equals (keeps small bins for small items)
        score -= bin_residual as f64 * 0.05;
    }

    // Late-stream consolidation: discourage leaving many tiny residuals
    if post_residual < 10 && post_residual > 0 {
        score += 20.0;
    }
    // zero residual is perfect
    if post_residual == 0 {
        score -= 40.0;
    }

    // mild pressure against proliferating bins mid-stream
    if open_bins_count > 8 {
        score += 0.4 * open_bins_count as f64;
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let cap = bin_capacity as f64;
    let pr = post_residual as f64;
    let progress = step_index as f64 / total_items.max(1) as f64;
    let fit_ratio = item_size as f64 / cap;
    let tightness = 1.0 - pr / cap;

    // Base: prefer small post-residual, with smooth polynomial shaping
    let mut score = pr * (1.0 + 0.35 * tightness * tightness);

    // Non-linear coupling of post-residual with stream progress:
    // later in the stream, small residuals become more costly (dead space)
    let prog_coupling = pr * (progress * progress) * 0.6;
    score += prog_coupling;

    // Reward near-perfect fits smoothly (quadratic in tightness)
    score -= tightness * tightness * tightness * 12.0;

    // Lookahead: penalize if post-residual can't serve the next item (smooth)
    if next_item_size > 0 {
        let nxt = next_item_size as f64;
        let gap = (nxt - pr).max(0.0) / cap;
        score += gap * gap * (10.0 + 8.0 * (1.0 - progress));
        // reward exact lookahead match smoothly
        let match_q = 1.0 - ((nxt - pr).abs() / cap).min(1.0);
        score -= match_q * match_q * 6.0;
    }

    // Last-chance bin: strongly favor using it (smooth sigmoid-like weight)
    if fitting_bins_count == 1 {
        score -= 15.0 + 10.0 * fit_ratio;
    }

    // Mild penalty proportional to open bins to encourage consolidation
    score += open_bins_count as f64 * 0.05 * (1.0 - progress);

    // New-bin candidate: penalize unless the item is large and open bins are fragmented
    if bin_residual == bin_capacity {
        let fragmentation = (mean_residual / cap - 0.5).abs();
        score += 6.0 - 8.0 * fit_ratio - 5.0 * fragmentation * (0.5 + progress);
    }

    // Mean-residual deviation: prefer bins whose residual is near the mean (smooth)
    let dev = (pr as f64 - mean_residual).abs() / cap;
    score += dev * dev * 4.0;

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // --- Harmonic class of post_residual (capacity fractions / mod arithmetic) ---
    let cap = bin_capacity as f64;
    let pr = post_residual as f64;

    // Classify post_residual into harmonic classes: multiples of capacity/10
    let tenth = bin_capacity / 10;
    let residue_class = (post_residual % tenth.max(1)) as f64;
    // Penalize post_residuals that are not "harmonic" (poorly reusable sizes)
    let harmonic_bonus = if post_residual % 10 == 0 { -6.0 } else { 0.0 };
    score += harmonic_bonus;

    // Perfect fit: zero post_residual is ideal
    if post_residual == 0 {
        score -= 40.0;
    } else if post_residual < 10 {
        // Dead space: residual below minimum item size is wasted
        score += 25.0;
    }

    // Integer-division threshold: post_residual in [10, 20) is highly usable
    let usable_class = post_residual / 10;
    score -= (usable_class.min(4) as f64) * 4.0;

    // Penalize non-harmonic leftover (residue_class) mildly
    score += residue_class * 0.3;

    // --- Lookahead coupling (k=2) ---
    if next_item_size > 0 && next_item_size <= post_residual {
        // Next item fits here: strong reward, scaled by tightness of fit
        let tight = (post_residual - next_item_size) as f64;
        score -= 30.0 - tight * 0.5;
    } else if next_item_size > 0 && next_item_size > post_residual {
        // Next item won't fit: if this bin becomes dead, penalize
        if post_residual < 10 {
            score += 15.0;
        }
    }

    // --- Last-chance bin logic ---
    if fitting_bins_count == 1 && bin_residual != bin_capacity {
        // Only bin that fits the item: heavily favor using it
        score -= 35.0;
    }

    // --- New-bin candidate handling ---
    if bin_residual == bin_capacity {
        // Brand-new empty bin: baseline score = item placed leaves cap - item
        // Prefer new bin only when current bins are fragmented or item huge
        let fragmentation = (mean_residual - pr).abs();
        score += 10.0;
        if item_size >= 60 {
            score -= 12.0; // large items start fresh bins readily
        }
        if mean_residual < item_size as f64 * 0.5 {
            score -= 15.0; // open bins mostly unusable
        }
        if open_bins_count == 0 {
            score -= 100.0;
        }
        // Discourage hoarding many open bins late in stream
        let progress = step_index as f64 / total_items.max(1) as f64;
        score += (open_bins_count as f64) * (1.0 + progress) * 2.0;
        let _ = fragmentation;
    }

    // --- Mean residual coupling ---
    // Prefer bins whose residual is close to mean (balanced packing)
    score += ((bin_residual as f64) - mean_residual).abs() * 0.2;

    // Small tie-break toward fuller bins
    score += (cap - bin_residual as f64).recip() * 5.0;

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Strict dead-space avoidance: small unusable gaps are heavily penalized.
    // A residual gap is "dead" if it is smaller than the smallest plausible item (1..100 stream),
    // but more meaningfully: gaps below ~10 are almost certainly wasted.
    if post_residual > 0 && post_residual < 10 {
        score += 25.0 * (10.0 - post_residual as f64);
    }
    // Perfect fit: strongly reward.
    if post_residual == 0 {
        score -= 40.0;
    } else if post_residual <= 5 {
        score -= 15.0; // near-perfect fit still great
    }

    // Penalize large leftover gaps only mildly; prefer tight packing.
    let gap_ratio = post_residual as f64 / bin_capacity as f64;
    score += 10.0 * gap_ratio * gap_ratio;

    // Open-bins pressure: when many bins are open, discourage spreading into
    // fresh space; encourage filling existing bins.
    let progress = step_index as f64 / (total_items.max(1) as f64);
    let pressure = (open_bins_count as f64).ln() + 1.0;
    score += pressure * (1.0 - progress) * 3.0;

    // Last-chance bin: if this is the only bin that fits, reward using it
    // to avoid opening a new bin unnecessarily.
    if fitting_bins_count == 1 && bin_residual != bin_capacity {
        score -= 20.0;
    }

    // Lookahead: if the next item fits into the post-residual, reward keeping
    // that space available (this bin remains useful).
    if next_item_size > 0 && next_item_size <= post_residual {
        score -= 12.0;
    } else if next_item_size > 0 && post_residual > 0 {
        // dead space relative to the next item
        score += 6.0;
    }

    // New-bin candidate: baseline competitiveness. Prefer a new bin when all
    // open bins would leave very tight/awkward fits, otherwise make new bin
    // slightly worse than good existing fits.
    if bin_residual == bin_capacity {
        // New bin leaves residual = capacity - item_size; that's already in score.
        // Add a mild bias so we only open new bins when existing fits are bad.
        score += 8.0 + mean_residual * 0.15;
    }

    // Mean-residual coupling: if open bins are already roomy on average,
    // be more tolerant of leftover space here; if they are tight, penalize.
    score += (mean_residual - post_residual as f64) * 0.05;

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Aggressive 2-step lookahead: reward if next item fits perfectly into post_residual.
    if next_item_size > 0 {
        if next_item_size == post_residual {
            score -= 60.0; // perfect chain fit
        } else if next_item_size <= post_residual {
            let slack = (post_residual - next_item_size) as f64;
            score -= 40.0 * (1.0 - slack / bin_capacity as f64);
        } else {
            // next item cannot follow into this bin; penalize wasted residual
            let waste = (next_item_size - post_residual) as f64;
            score += 0.3 * waste;
        }
    }

    // Tight fits are valuable: penalize less when post_residual is small.
    let tightness = 1.0 - (post_residual as f64) / (bin_capacity as f64);
    score -= 25.0 * tightness * tightness;

    // Compare against mean residual: prefer bins whose post_residual is near/below mean.
    score += 0.4 * (post_residual as f64 - mean_residual);

    // Last-chance bin: strongly favor using it to avoid opening a new bin.
    if fitting_bins_count == 1 && bin_residual != bin_capacity {
        score -= 35.0;
    }

    // Discourage opening new bins early in the stream when open bins exist.
    let is_new_bin = bin_residual == bin_capacity;
    if is_new_bin {
        let progress = step_index as f64 / (total_items.max(1) as f64);
        score += 20.0 + 30.0 * (1.0 - progress);
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Tight-fit reward: strongly favor bins where the item nearly fills the residual.
    let fit_ratio = item_size as f64 / bin_residual.max(1) as f64;
    score -= 2.5 * fit_ratio * fit_ratio;

    // Perfect-fill bonus.
    if post_residual == 0 {
        score -= 40.0;
    } else if post_residual < 10 {
        score -= 15.0;
    }

    // Penalize leaving dead space that no future item (min size 1, typical >=10) can use.
    if post_residual > 0 && post_residual < 10 {
        score -= 20.0; // tiny dead space is fine (already rewarded)
    }
    if post_residual >= 10 && post_residual < item_size {
        // residual smaller than current item: only useful if next item fits it
        if next_item_size > 0 && next_item_size <= post_residual {
            score -= 10.0;
        } else {
            score += 12.0;
        }
    }

    // Lookahead coupling: reward bins whose leftover can host the next item.
    if next_item_size > 0 && post_residual >= next_item_size {
        let chain_tightness = next_item_size as f64 / post_residual as f64;
        score -= 8.0 * chain_tightness;
    } else if next_item_size > 0 && post_residual > 0 {
        score += 4.0;
    }

    // Last-chance dynamics: if this is the only fitting bin, avoid opening a new bin
    // unless the fit is terrible.
    if fitting_bins_count == 1 && bin_residual != bin_capacity {
        score -= 18.0 + 0.3 * (post_residual as f64);
    }

    // New-bin candidate logic: opening a bin wastes mean residual across open bins.
    if bin_residual == bin_capacity {
        let progress = step_index as f64 / (total_items.max(1) as f64);
        let wasted = mean_residual * open_bins_count as f64;
        // Prefer new bin only when open bins are nearly full on average and many bins fit.
        score += 25.0 + 0.5 * wasted - 10.0 * progress;
        if fitting_bins_count <= 1 {
            score += 30.0; // discourage abandoning the sole fitting bin
        }
        if next_item_size > 0 && next_item_size >= item_size {
            score += 6.0; // big item follows: fresh bin keeps flexibility
        }
    }

    // Mild penalty for spreading across many open bins when this bin is loose.
    let openness = open_bins_count as f64 / (1.0 + mean_residual.max(1.0));
    score += 0.05 * openness * (post_residual as f64);

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let progress = step_index as f64 / total_items.max(1) as f64;
    let cap = bin_capacity as f64;
    let pr = post_residual as f64;
    let norm_pr = pr / cap;

    // Base: waste after placement, mildly discounted as stream progresses
    let mut score = norm_pr * (1.0 + 0.5 * progress);

    // Smooth non-linear penalty for small unusable residuals (dead space)
    let dead = (1.0 - norm_pr).powi(3) * norm_pr;
    score += 12.0 * dead * (1.0 - progress);

    // Polynomial coupling: residual vs stream progress
    score += 4.0 * norm_pr * norm_pr * (1.0 + 2.0 * progress * (1.0 - progress));

    // Lookahead: reward bins whose post-residual fits the next item
    if next_item_size > 0 && next_item_size as f64 <= pr {
        score -= 3.0 * (next_item_size as f64 / cap);
    } else if next_item_size > 0 {
        score += 1.5 * (1.0 - progress);
    }

    // Last-chance bin bonus
    if fitting_bins_count == 1 && bin_residual != bin_capacity {
        score -= 2.0;
    }

    // New-bin candidate: prefer it only when open bins fit poorly
    if bin_residual == bin_capacity {
        score = pr as f64 - 6.0 + 2.0 * mean_residual / cap;
    }

    // Encourage consolidation when many bins are open
    score += 0.1 * open_bins_count as f64 * norm_pr * progress;

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Base: prefer tight fits via quadratic waste penalty
    let fit_ratio = item_size as f64 / bin_residual.max(1) as f64;
    score -= 60.0 * fit_ratio * fit_ratio;

    // Harmonic classes: classify post_residual into capacity fractions
    let frac = post_residual as f64 / bin_capacity as f64;
    let class = (frac * 10.0).floor(); // decile of remaining space
    // Penalize classes that are "dead zones": tiny leftovers (< 10% capacity)
    if class == 0.0 {
        score += 25.0;
    } else if class == 1.0 {
        score += 12.0;
    } else if class >= 5.0 && class <= 7.0 {
        // Mid-range residuals are flexible: reward
        score -= 8.0;
    }

    // Modulo arithmetic on post_residual: multiples of common item sizes (10, 20, 25, 50)
    let pr = post_residual;
    if pr % 10 == 0 && pr > 0 {
        score -= 6.0; // residue divisible by smallest item class: likely reusable
    }
    if pr % 25 == 0 && pr > 0 {
        score -= 4.0;
    }
    if pr % 50 == 0 && pr > 0 {
        score -= 5.0;
    }
    // Odd, prime-ish residues are awkward: penalize
    if pr > 0 && pr % 10 != 0 && pr < 15 {
        score += 10.0;
    }

    // Lookahead coupling: if next item fits exactly in post_residual, strong reward
    if next_item_size > 0 {
        if next_item_size == pr {
            score -= 40.0;
        } else if next_item_size < pr {
            let gap = (pr - next_item_size) as f64;
            score -= 15.0 * (1.0 - gap / bin_capacity as f64);
        } else {
            score += 6.0; // next item won't fit here
        }
    }

    // Last chance bin: strong reward to avoid opening a new bin
    if fitting_bins_count == 1 {
        score -= 30.0;
    } else if fitting_bins_count > 1 {
        score += 3.0 * (fitting_bins_count as f64 - 1.0);
    }

    // New-bin candidate logic: only attractive if item is large or stream near end
    if bin_residual == bin_capacity {
        let progress = step_index as f64 / total_items.max(1) as f64;
        let item_frac = item_size as f64 / bin_capacity as f64;
        // Opening a new bin is good for big items, bad for small ones
        score -= 20.0 * item_frac - 10.0 * progress;
        if item_frac < 0.35 {
            score += 35.0; // discourage wasting a fresh bin on tiny items
        }
    }

    // Mean residual context: if this bin is far below mean residual, it's an outlier
    let dev = mean_residual - post_residual as f64;
    score += 0.05 * dev;

    // Stream progression: later in stream, consolidate more aggressively
    let t = step_index as f64 / total_items.max(1) as f64;
    score -= 5.0 * t * (1.0 - fit_ratio);

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Strict dead-space avoidance: residuals in (0,10) are unusable for future
    // items (min size 1..100 stream, but small gaps rarely help) — heavy penalty
    // for creating tiny slivers; slight reward for exact fits (post_residual == 0).
    if post_residual == 0 {
        score -= 50.0; // perfect fit is ideal
    } else if post_residual < 10 {
        score += 40.0; // unusable dead space
    } else if post_residual < 20 {
        score += 12.0; // marginal gap
    }

    // Reward tight fits: smaller post_residual relative to item size is better.
    score -= (item_size as f64) * (100.0 - post_residual as f64) / 100.0 * 0.3;

    // Last-chance pressure: if this is the only bin that fits, strongly favor it
    // to avoid opening a new bin.
    if fitting_bins_count == 1 && bin_residual != bin_capacity {
        score -= 30.0;
    }

    // Open-bin count pressure: penalize new-bin opening when many bins are open,
    // but allow it when existing fits are poor (handled via base score).
    if bin_residual == bin_capacity {
        // brand-new bin candidate: neutral residual, add fixed startup cost
        // scaled by how many bins are already open.
        score += 25.0 + 3.0 * open_bins_count as f64;
        // If next item is large, a fresh bin may be valuable.
        if next_item_size > 0 && next_item_size > post_residual {
            score -= 10.0;
        }
    }

    // Lookahead: if next item fits exactly in the post residual, reward this placement.
    if next_item_size > 0 && post_residual >= next_item_size && post_residual - next_item_size < 10 {
        score -= 20.0;
    }

    // Slight preference for using bins with below-mean residual (consolidate fullness).
    score += (bin_residual as f64 - mean_residual) * 0.05;

    // Early in stream: be a bit more willing to open bins (diversity helps later).
    let progress = step_index as f64 / total_items.max(1) as f64;
    if bin_residual == bin_capacity {
        score -= 10.0 * (1.0 - progress);
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Aggressive 2-step lookahead: reward exact match between post_residual
    // and next_item_size (perfect two-item packing).
    let post = post_residual as f64;
    let nxt = next_item_size as f64;

    if next_item_size > 0 {
        let diff = (post - nxt).abs();
        // Perfect match: strong reward.
        if diff == 0.0 {
            score -= 40.0;
        } else if next_item_size <= post_residual {
            // Next item fits in leftover: partial reward scaled by closeness.
            score -= 25.0 * (1.0 - diff / bin_capacity as f64);
        } else {
            // Next item does NOT fit leftover: penalize leaving awkward space.
            score += 10.0 * (diff / bin_capacity as f64);
        }
    }

    // Penalize dead space that is too small for typical items (unusable gap).
    if post_residual > 0 && post_residual < 10 {
        score += 30.0;
    }

    // Prefer tight fits relative to mean residual across open bins.
    if post < mean_residual {
        score -= 5.0;
    } else {
        score += 3.0 * (post - mean_residual) / bin_capacity as f64;
    }

    // Last-chance bin: strongly discourage opening a new bin when this is
    // the only fitting bin (unless fit is terrible).
    if fitting_bins_count == 1 && bin_residual != bin_capacity {
        score -= 20.0;
    }

    // New-bin candidate: penalize opening a new bin early in the stream,
    // relax late when many bins are open and mean residual is high.
    if bin_residual == bin_capacity {
        let progress = step_index as f64 / total_items.max(1) as f64;
        let pressure = (mean_residual / bin_capacity as f64) * (open_bins_count as f64).sqrt();
        score += 15.0 + 25.0 * (1.0 - progress) - 10.0 * pressure.min(1.5);
        // Opening a new bin is fine if next item is large and won't fit anywhere well.
        if next_item_size > 60 {
            score -= 12.0;
        }
    }

    // Mild bonus for filling bins more completely (waste-avoidance).
    score -= (item_size as f64 / bin_capacity as f64) * 5.0;

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Reward near-perfect fits: strongly discount small post-residuals.
    if post_residual <= 2 {
        score -= 60.0;
    } else if post_residual <= 10 {
        score -= 40.0 - (post_residual as f64) * 2.0;
    }

    // Lookahead: penalize residuals that cannot host the next item (dead space),
    // reward residuals that can still be used.
    if next_item_size > 0 {
        if (post_residual as u64) < (next_item_size as u64) {
            score += (next_item_size as f64 - post_residual as f64) * 1.5;
        } else {
            score -= 4.0;
            // Bonus if residual matches next item almost exactly.
            let gap = post_residual as f64 - next_item_size as f64;
            if gap <= 5.0 {
                score -= 8.0 - gap;
            }
        }
    }

    // Last-chance bin: strongly favor using the only bin that fits.
    if fitting_bins_count == 1 && bin_residual < bin_capacity {
        score -= 25.0;
    }

    // Crowding: when many bins are open, prefer filling existing ones
    // rather than opening more; when few are open, opening a bin is cheaper.
    let crowding = open_bins_count as f64;
    if bin_residual == bin_capacity {
        // New-bin candidate: penalize more when many bins already open.
        score += 6.0 + crowding * 1.2;
        // Late in the stream, opening new bins is more wasteful.
        let progress = step_index as f64 / (total_items.max(1) as f64);
        score += progress * 15.0;
    } else {
        // Fitting an open bin: reward scaled by how crowded the stream is.
        score -= 2.0 + crowding * 0.15;
    }

    // Global mean residual coupling: if this bin's post-residual deviates
    // upward from the mean residual, it's likely to become dead space.
    let pr = post_residual as f64;
    if pr > mean_residual {
        score += (pr - mean_residual) * 0.8;
    } else {
        score -= (mean_residual - pr) * 0.3;
    }

    // Mild time-horizon term: early on, keep bins flexible (moderate residuals);
    // late, greedily minimize residual.
    let progress = step_index as f64 / (total_items.max(1) as f64);
    score += (1.0 - progress) * pr * 0.05;

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    let cap = bin_capacity as f64;
    let pr = post_residual as f64;
    let progress = if total_items > 0 { step_index as f64 / total_items as f64 } else { 0.0 };

    // Normalized post-residual (0..1), penalize large leftover space
    let pr_norm = pr / cap;
    score += 30.0 * pr_norm * pr_norm;

    // Smooth non-linear coupling: residual waste matters more later in the stream
    let progress_term = progress * progress * (3.0 - 2.0 * progress); // smoothstep
    score += 40.0 * progress_term * pr_norm * pr_norm;

    // Reward tight fits (small post residual) more strongly as stream progresses
    let tightness = 1.0 - pr_norm;
    score -= 25.0 * progress_term * tightness * tightness;

    // Penalize bins whose residual deviates strongly from the mean residual
    // (keeps bin population homogeneous, easier future packing)
    let dev = (pr - mean_residual) / cap;
    score += 15.0 * dev * dev;

    // Last-chance bonus: if this is the only fitting bin, strongly favor using it
    if fitting_bins_count == 1 {
        score -= 60.0 * (1.0 + progress_term);
    }

    // Lookahead: reward leaving a residual that can still host the next item
    if next_item_size > 0 && pr >= next_item_size as f64 {
        let slack = (pr - next_item_size as f64) / cap;
        score -= 12.0 * (1.0 - slack) * (1.0 - slack);
    } else if next_item_size > 0 {
        // penalize leaving a residual too small for the next item (dead space)
        score += 10.0 * progress_term;
    }

    // Mild penalty for opening a new bin when many bins are already open
    if bin_residual == bin_capacity {
        score += 20.0 + 10.0 * (open_bins_count as f64).sqrt();
        // but if no existing bin fits well, allow new bin
        if fitting_bins_count == 0 {
            score -= 100.0;
        }
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Harmonic class of post_residual: modulo buckets on capacity fractions
    let pr = post_residual as i64;
    let cap = bin_capacity as i64;
    let class = pr % 10;

    // Dead-space penalty: residuals in awkward classes (1..9 mod 10) waste space
    if pr > 0 && class != 0 {
        score += 3.0 + 0.4 * (10 - class) as f64;
    }
    // Perfect closure classes (0 mod 10, and 0) are excellent
    if pr == 0 {
        score -= 25.0;
    } else if class == 0 {
        score -= 8.0;
    }

    // Coupling with next item: if next item fits exactly into post_residual, big reward
    if next_item_size > 0 {
        let nxt = next_item_size as i64;
        if nxt == pr {
            score -= 30.0;
        } else if nxt <= pr {
            let nxt_class = nxt % 10;
            // next item creates another awkward class -> mild penalty
            if (pr - nxt) % 10 != 0 && (pr - nxt) > 0 {
                score += 2.0;
            } else {
                score -= 5.0;
            }
            if nxt_class == 0 {
                score -= 3.0;
            }
        } else {
            // next item won't fit here: penalize bins whose residual is close-but-too-small
            if pr > 0 && pr >= nxt / 2 {
                score += 4.0;
            }
        }
    }

    // Last-chance bin: strongly favor using it to avoid opening a new bin
    if fitting_bins_count == 1 && bin_residual < bin_capacity {
        score -= 15.0;
    }

    // New-bin candidate handling: neutral-ish score, penalized when good fits exist
    if bin_residual == bin_capacity {
        score = (bin_capacity as f64) * 0.75 + 10.0;
        if fitting_bins_count == 0 {
            score -= 60.0; // must open new bin
        }
        // open new bin early when mean residual is high (existing bins are fragmented)
        if mean_residual > 40.0 && fitting_bins_count > 0 {
            score += 15.0;
        }
    }

    // Mild tightness reward: prefer bins where item fills a large fraction of residual
    let fill_frac = item_size as f64 / bin_residual.max(1) as f64;
    score -= 10.0 * fill_frac * fill_frac;

    // Progress scaling: be greedier about closure late in the stream
    let progress = step_index as f64 / total_items.max(1) as f64;
    score -= 6.0 * progress * (1.0 - fill_frac);

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Strong penalty for small unusable gaps (dead space < 10).
    if post_residual > 0 && post_residual < 10 {
        score += 40.0 + (10 - post_residual) as f64 * 3.0;
    }

    // Reward near-perfect fits.
    if post_residual == 0 {
        score -= 60.0;
    } else if post_residual <= 5 {
        score -= 15.0;
    }

    // Last-chance bin: strong reward to avoid opening a new bin.
    if fitting_bins_count == 1 && bin_residual != bin_capacity {
        score -= 25.0;
    }

    // Pressure against opening new bins when many bins are open.
    let progress = step_index as f64 / total_items.max(1) as f64;
    if bin_residual == bin_capacity {
        // New-bin candidate: penalize, more so late in the stream.
        score += 20.0 + open_bins_count as f64 * 1.5 + progress * 15.0;
        // But if no open bin fits well, allow opening: handled by others' dead-space penalties.
        if fitting_bins_count == 0 {
            score -= 35.0;
        }
    } else {
        // Mild penalty for bins whose residual deviates far below mean (fragmented bins).
        if (bin_residual as f64) < mean_residual - 15.0 {
            score += 5.0;
        }
        // Reward bins whose leftover can still host the next item.
        if next_item_size > 0 && post_residual >= next_item_size {
            score -= 8.0;
        } else if next_item_size > 0 && post_residual > 0 {
            score += 6.0;
        }
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Strong base: prefer tight fits (low post_residual), weighted.
    score *= 1.0 + 0.01 * (post_residual as f64 / bin_capacity as f64);

    // Aggressive 2-step lookahead: reward exact/near exact chaining.
    if next_item_size > 0 {
        if post_residual == next_item_size {
            score -= 60.0; // perfect chain
        } else if post_residual > next_item_size {
            let leftover = post_residual - next_item_size;
            score -= 40.0 * (1.0 - leftover as f64 / bin_capacity as f64);
        } else {
            // next item cannot fit here; penalize proportionally to the gap
            score += 0.5 * (next_item_size - post_residual) as f64;
        }
    } else {
        // Last item: any placement is fine; slight preference for tight fit.
        score -= 10.0;
    }

    // Relative to mean residual: bins with much more room than average
    // are "wasted" on small items; prefer filling below-average-residual bins.
    score += 0.3 * (mean_residual - bin_residual as f64);

    // Last-chance bin: if this is the only bin that fits, strongly favor using it
    // to avoid opening a new bin.
    if fitting_bins_count == 1 {
        score -= 25.0;
    }

    // New-bin candidate: only attractive when the item is large relative to
    // capacity or open bins are all poor fits. Penalize opening new bins
    // moderately, less so early in the stream.
    if bin_residual == bin_capacity {
        let progress = step_index as f64 / total_items.max(1) as f64;
        let fill_ratio = item_size as f64 / bin_capacity as f64;
        let open_pressure = open_bins_count as f64;
        score = 25.0 + 50.0 * (1.0 - fill_ratio) + 5.0 * open_pressure.min(10.0)
                - 20.0 * progress;
    }

    // Small tie-breaker toward fuller bins.
    score -= 0.05 * (bin_capacity - bin_residual) as f64;

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Core: reward tight fits (low post_residual relative to capacity).
    let cap = bin_capacity as f64;
    let tightness = 1.0 - (post_residual as f64) / cap; // 0..1, higher = tighter
    score -= 55.0 * tightness * tightness;

    // Perfect fit gets a big bonus.
    if post_residual == 0 {
        score -= 120.0;
    } else if post_residual <= 10 {
        score -= 35.0;
    }

    // Last-chance bin: strongly prefer using it to avoid opening a new bin.
    if fitting_bins_count == 1 && bin_residual != bin_capacity {
        score -= 70.0;
    } else if fitting_bins_count > 1 {
        // With many options, mild penalty for very loose fits to keep flexibility.
        score += 8.0 * (post_residual as f64) / cap;
    }

    // Lookahead: if the next item fits in the post residual, reward this placement.
    if next_item_size > 0 && next_item_size <= post_residual {
        score -= 25.0;
        // Extra reward if next item nearly fills the remainder too.
        if post_residual - next_item_size <= 10 {
            score -= 20.0;
        }
    } else if next_item_size > 0 && next_item_size > post_residual {
        // Penalize creating a dead space smaller than the typical next item.
        score += 12.0 * (post_residual as f64) / cap;
    }

    // Penalize placing into bins with residual far from the mean (fragmentation).
    let dev = (bin_residual as f64 - mean_residual).abs();
    score += 0.15 * dev;

    // Global state: many open bins -> encourage closing them out (tight fits),
    // few open bins -> new bins are cheap, be pickier.
    let open_ratio = open_bins_count as f64 / (total_items.max(1) as f64).sqrt();
    score += 6.0 * open_ratio * (post_residual as f64 / cap);

    // Time horizon: late in the stream, favor consolidating into existing bins.
    let progress = step_index as f64 / (total_items.max(1) as f64);
    score += 20.0 * progress * (post_residual as f64 / cap);

    // New-bin candidate: only attractive when this bin would be a bad host
    // (large post_residual waste) or when it's the only option.
    if bin_residual == bin_capacity {
        score += 45.0;
        if fitting_bins_count == 0 {
            score -= 100.0;
        }
        // Late stream: opening new bins is expensive, discourage more.
        score += 30.0 * progress;
        // If some existing bin achieves a near-perfect fit, discourage new bin.
        if post_residual >= bin_capacity - item_size && item_size <= 20 {
            score += 10.0;
        }
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let progress = (step_index as f64 / total_items.max(1) as f64).clamp(0.0, 1.0);
    let pr = post_residual as f64;
    let cap = bin_capacity as f64;
    let norm_pr = pr / cap;
    let norm_item = item_size as f64 / cap;

    // Base: post residual, mildly discounted early (prefer filling bins tightly later)
    let mut score = pr * (0.9 + 0.2 * progress);

    // Smooth polynomial coupling: large post-residuals are worse as stream progresses
    score += 40.0 * norm_pr * norm_pr * (0.5 + progress);

    // Reward tight fits (small normalized post residual) with smooth falloff
    score -= 25.0 * (1.0 - norm_pr) * (1.0 - norm_pr) * norm_item;

    // Lookahead: penalize if next item cannot use the post residual (smooth)
    if next_item_size > 0 {
        let nx = next_item_size as f64 / cap;
        let usable = (nx - norm_pr).max(0.0);
        score -= 15.0 * usable * (1.0 - norm_pr);
        score += 10.0 * norm_pr * (1.0 - usable / nx.max(1e-9)) * progress;
    }

    // Last-chance bin bonus: strongly favor the only fitting bin
    if fitting_bins_count == 1 {
        score -= 30.0 * (1.0 + norm_item);
    }

    // New-bin candidate: penalize opening a bin unless item is large or fits poorly elsewhere
    let is_new_bin = bin_residual == bin_capacity;
    if is_new_bin {
        score += 20.0 + 15.0 * (1.0 - norm_item) * (1.0 - progress);
        score -= 10.0 * norm_item * progress;
    }

    // Mean residual interaction: if this bin's residual deviates favorably from mean
    let dev = (pr - mean_residual) / cap;
    score += 8.0 * dev * (1.0 - progress);

    // Slight penalty for many open bins (encourage closing bins out)
    score += 0.5 * open_bins_count as f64 * norm_pr;

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Harmonic class of post_residual: quantize dead space into capacity fractions.
    let cap = bin_capacity as f64;
    let pr = post_residual as f64;
    let frac = pr / cap; // 0..1

    // Integer division thresholds on post_residual: reward small, "usable" leftovers.
    let pr_q = post_residual / 10; // decile class
    match pr_q {
        0 => score -= 25.0,          // post_residual < 10: near-perfect fit
        1 => score -= 12.0,          // 10..20
        2 | 3 => score -= 4.0,       // 20..40
        4 | 5 => score += 2.0,       // 40..60: mediocre leftover
        6 | 7 => score += 8.0,       // 60..80: large dead space
        _ => score += 15.0,          // 80..100: almost empty bin used wastefully
    }

    // Modular arithmetic: leftover that matches common small item classes (<=10 multiples)
    // is more likely to be filled by future items -> reward.
    let harmonics: [u32; 6] = [10, 20, 25, 30, 40, 50];
    for &h in harmonics.iter() {
        if post_residual >= h && post_residual % h == 0 {
            score -= 6.0 + (h as f64) * 0.08;
        }
    }
    // Reward leftovers that can exactly host a plausible next item class.
    if next_item_size > 0 && post_residual >= next_item_size {
        let slack = post_residual - next_item_size;
        if slack < 10 {
            score -= 14.0; // next item slots in almost perfectly
        } else if slack < 25 {
            score -= 6.0;
        }
    } else if next_item_size > 0 {
        // next item cannot fit here: this leftover is likely dead -> penalize mildly
        score += 5.0;
    }

    // Coupling with mean residual: prefer bins tighter than the average open bin.
    let diff = mean_residual - pr;
    if diff > 0.0 {
        score -= diff * 0.5; // tighter than average -> favored
    } else {
        score += (-diff) * 0.3;
    }

    // Last-chance bin: if this is the only fitting bin, strongly favor using it.
    if fitting_bins_count == 1 && bin_residual != bin_capacity {
        score -= 30.0;
    }

    // New-bin candidate handling: opening a fresh bin is only attractive early in the
    // stream or when the item would leave ugly dead space in every open bin.
    let is_new_bin = bin_residual == bin_capacity;
    if is_new_bin {
        let progress = step_index as f64 / total_items.max(1) as f64;
        let waste_penalty = (post_residual as f64) * 0.9; // fresh bin: post_residual = cap - item
        let stream_left = 1.0 - progress;
        // Early stream: opening bins is cheap-ish; late stream: strongly discourage.
        score = 40.0 + waste_penalty * (0.5 + stream_left) + 60.0 * progress * progress;
        if open_bins_count == 0 {
            score -= 100.0; // must open the first bin
        }
        if fitting_bins_count == 0 {
            score -= 80.0; // nothing else fits: new bin required
        }
    }

    // Mild pressure to consolidate when many bins are open.
    score += (open_bins_count as f64) * 0.15;

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Strong strict dead-space avoidance: gaps that likely cannot be reused
    // (smaller than a plausible future item) are heavily penalized.
    if post_residual > 0 {
        let unusable = (post_residual < 10) || (next_item_size > 0 && post_residual < next_item_size);
        if unusable {
            score += 60.0 + 0.8 * post_residual as f64;
        } else {
            // Reward leaving a gap that the lookahead item can exactly use.
            if next_item_size > 0 && post_residual == next_item_size {
                score -= 25.0;
            }
            // Mild reward for very tight fits overall.
            let tightness = 1.0 - (post_residual as f64 / bin_capacity as f64);
            score -= 10.0 * tightness * tightness;
        }
    } else {
        // Perfect fit: heavily rewarded.
        score -= 40.0;
    }

    // Open-bin pressure: discourage spreading across many bins unless the fit is good.
    let progress = if total_items > 0 { step_index as f64 / total_items as f64 } else { 0.0 };
    score += 0.15 * open_bins_count as f64 * (1.0 - tightness_factor(post_residual, bin_capacity));

    // New-bin candidate handling: empty bin gets an intrinsic opening cost,
    // waived when no open bin fits or the existing fit is poor.
    if bin_residual == bin_capacity {
        let base_cost = 55.0 + 0.1 * open_bins_count as f64;
        if fitting_bins_count == 0 {
            score -= base_cost; // must open a bin
        } else if post_residual >= 40 {
            // Plenty of room wasted; opening fresh bin may be better.
            score -= base_cost * 0.9;
        } else {
            score += base_cost * 0.3; // prefer reusing a well-fitting open bin
        }
    }

    // Last-chance bonus: if this is the only bin that fits, avoid forcing a new bin.
    if fitting_bins_count == 1 && bin_residual != bin_capacity {
        score -= 12.0;
    }

    // Slight preference toward bins below mean residual (keeps residuals balanced).
    score += 0.05 * (mean_residual - bin_residual as f64);

    score
}

#[inline]
fn tightness_factor(post_residual: u32, bin_capacity: u32) -> f64 {
    1.0 - (post_residual as f64 / bin_capacity as f64)
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Perfect fit: strongly reward.
    if post_residual == 0 {
        score -= 1000.0;
    }

    // 2-step lookahead: if the next item exactly fills the post-residual,
    // this is a chained perfect fit — reward heavily.
    if next_item_size > 0 && post_residual > 0 {
        if post_residual == next_item_size {
            score -= 400.0;
        } else if next_item_size <= post_residual {
            // Next item fits, but leaves more waste: mild reward scaled by tightness.
            let tightness = 1.0 - (post_residual - next_item_size) as f64 / bin_capacity as f64;
            score -= 150.0 * tightness;
        } else {
            // Post-residual becomes dead space for the next item: penalize
            // proportionally to how small/unusable it is.
            let dead = post_residual as f64;
            if dead < 10.0 {
                score += 60.0 * (10.0 - dead) / 10.0;
            }
            // Penalize if residual is below the minimum plausible item size.
            if post_residual < 1 {
                score += 50.0;
            }
        }
    }

    // Compare against mean residual across open bins: bins with residual far
    // above mean are "wasteful" targets unless the fit is tight.
    let tight_fit = (post_residual as f64) / bin_residual.max(1) as f64;
    if (bin_residual as f64) > mean_residual {
        score += 0.5 * ((bin_residual as f64) - mean_residual) * (1.0 - tight_fit);
    } else {
        score -= 0.5 * (mean_residual - bin_residual as f64) * tight_fit;
    }

    // Last chance bin: if this is the only bin that fits, strongly prefer
    // using it over opening a new bin (unless the fit is terrible).
    if fitting_bins_count == 1 {
        score -= 250.0;
        if post_residual > 30 {
            score += 100.0; // don't waste a nearly-full bin's uniqueness on a loose fit
        }
    }

    // New empty bin candidate: only attractive when no open bin fits well.
    let is_new_bin = bin_residual == bin_capacity;
    if is_new_bin {
        // Base penalty for opening a new bin.
        score += 20.0;
        // Scale with number of open bins (prefer consolidating early).
        score += 3.0 * open_bins_count as f64;
        // If the best alternative would leave large waste, opening fresh is fine.
        // Encoded via lookahead: if next item is large, a fresh bin is useful later.
        if next_item_size >= 50 {
            score -= 30.0;
        }
        // Late in the stream, avoid opening bins for tiny leftovers.
        let progress = step_index as f64 / total_items.max(1) as f64;
        if post_residual as f64 > 0.6 * bin_capacity as f64 && progress > 0.8 {
            score += 40.0;
        }
    }

    // Small absolute waste bonus: reward leaving residuals that match common
    // small item sizes (10, 20) so future small items can slot in.
    if post_residual == 10 || post_residual == 20 {
        score -= 80.0;
    }

    // Mild preference for filling larger bins first when residuals equal.
    score += 0.01 * bin_residual as f64 * (1.0 - tight_fit);

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Reward tight fits (small post_residual relative to item size).
    let fit_ratio = item_size as f64 / bin_residual.max(1) as f64;
    score -= 12.0 * fit_ratio;

    // Penalize large dead space nonlinearly.
    let dead = post_residual as f64;
    score += 0.08 * dead * dead / bin_capacity as f64;

    // Lookahead: if next item fits into post_residual, reward heavily.
    if next_item_size > 0 && next_item_size <= post_residual {
        score -= 18.0;
        // Extra reward if next item is large (hard to place elsewhere).
        if next_item_size > post_residual / 2 {
            score -= 6.0;
        }
    } else if next_item_size > 0 && next_item_size > post_residual {
        // Next item won't chain here: mild penalty proportional to gap.
        score += 3.0 * (next_item_size - post_residual) as f64 / bin_capacity as f64;
    }

    // Last-chance bin: strong reward to avoid opening a new bin.
    if fitting_bins_count == 1 {
        score -= 15.0;
    }

    // New-bin candidate handling: opening a bin is only attractive when
    // current item barely fits nowhere well or few bins fit the item.
    if bin_residual == bin_capacity {
        // Penalize opening new bins early in the stream.
        let progress = step_index as f64 / (total_items.max(1) as f64);
        score += 30.0 - 15.0 * progress;
        // If item is large relative to capacity, new bin is more acceptable.
        score -= 10.0 * (item_size as f64 / bin_capacity as f64);
        // If many bins can fit the item, discourage new bin strongly.
        if fitting_bins_count > 1 {
            score += 20.0 * (fitting_bins_count as f64).ln();
        }
        // If mean residual is high, existing bins have room: discourage new bin.
        score += 0.15 * mean_residual;
    }

    // Slight preference for filling bins with lower residual among peers.
    score += 0.05 * (bin_residual as f64 - mean_residual).abs().signum()
        * (bin_residual as f64 - mean_residual);

    // Time horizon: as stream progresses, consolidate into fewer bins.
    let progress = step_index as f64 / (total_items.max(1) as f64);
    score -= 5.0 * progress * (post_residual as f64 / bin_capacity as f64);

    // Encourage using existing bins when many are open.
    score += 0.5 * (open_bins_count as f64).ln().max(0.0) * (post_residual as f64 / bin_capacity as f64);

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let progress = if total_items > 1 { step_index as f64 / total_items as f64 } else { 0.0 };
    let cap = bin_capacity as f64;
    let pr = post_residual as f64;

    // Base: prefer minimal post-residual (tight fit).
    let mut score = pr;

    // Normalized post-residual fraction.
    let pr_frac = pr / cap;

    // Non-linear polynomial coupling of post_residual with stream progress:
    // early on, large residuals are tolerable; late in the stream they are heavily penalized.
    let progress_weight = 0.5 + 2.5 * progress * progress;
    score += progress_weight * pr_frac * pr_frac * cap * 0.2;

    // Smooth reward for near-perfect fits (low residual) scaled by progress.
    let tightness = 1.0 - pr_frac;
    score -= progress_weight * tightness * tightness * 8.0;

    // Penalize dead space that cannot fit the next item (smooth interaction).
    if next_item_size > 0 {
        let nxt = next_item_size as f64;
        if pr < nxt {
            let gap = (nxt - pr) / cap;
            score += 6.0 * gap * (1.0 + progress);
        } else {
            // Reward residual that exactly accommodates the next item smoothly.
            let fit_quality = 1.0 - ((pr - nxt) / cap);
            score -= 4.0 * fit_quality * fit_quality * (0.5 + progress);
        }
    }

    // Last-chance bonus: if this is the only fitting bin, strongly favor using it.
    if fitting_bins_count == 1 {
        score -= 10.0 * (0.5 + progress);
    } else if fitting_bins_count > 1 {
        // Slight penalty for spreading across many bins when alternatives exist.
        score += 0.5 * (fitting_bins_count as f64).ln().max(0.0);
    }

    // New-bin candidate handling: empty bin has residual == capacity.
    let is_new_bin = bin_residual == bin_capacity;
    if is_new_bin {
        // Opening a new bin is penalized mildly; more so late in the stream
        // and when many bins are already open.
        score = cap * (0.6 + 0.4 * progress) + 0.3 * open_bins_count as f64;
        // But if residuals across open bins are large (poor fits everywhere),
        // opening fresh is less bad.
        score -= (mean_residual / cap).min(1.0) * 20.0;
    }

    // Mild global pressure to keep mean residual low (consolidation).
    score += 0.05 * mean_residual * progress;

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Harmonic class of post_residual: residue classes mod 10.
    let pr = post_residual as u32;
    let cls = pr % 10;
    // Dead-space classes: residues 1..9 are awkward; multiples of 10 are usable.
    let class_penalty: f64 = match cls {
        0 => -6.0,                       // perfectly aligned residual
        1 | 2 => 8.0,                    // nearly useless slivers
        3 | 4 | 6 | 7 => 3.0,            // semi-usable
        5 => -1.0,                       // half-of-ten, moderate
        _ => 5.0,                        // 8, 9
    };
    score += class_penalty;

    // Integer-division tier of post_residual (how many size-10 items fit).
    let tier = pr / 10;
    score -= 2.0 * tier as f64; // reward bins that remain useful

    // Perfect fits are gold.
    if pr == 0 {
        score -= 50.0;
    }

    // Lookahead coupling: if next item fits into post_residual, big reward.
    if next_item_size > 0 && next_item_size <= pr {
        score -= 12.0 + 0.1 * next_item_size as f64;
    } else if next_item_size > 0 && next_item_size <= bin_capacity && next_item_size > pr {
        // next item won't fit here: slight penalty proportional to wasted potential
        score += 2.0;
    }

    // Last-chance bin: strongly prefer using it before opening a new bin.
    if fitting_bins_count == 1 && bin_residual < bin_capacity {
        score -= 20.0;
    }

    // New-bin candidate: keep it attractive only when existing bins are fragmented
    // or the fit here is poor.
    if bin_residual == bin_capacity {
        // Base cost of opening a new bin, modulated by stream progress and fragmentation.
        let progress = step_index as f64 / (total_items.max(1) as f64);
        let frag = (mean_residual / bin_capacity as f64).clamp(0.0, 1.0);
        score = 45.0 + 25.0 * (1.0 - progress) - 20.0 * frag;
        // If the item is large relative to capacity, opening fresh is fine.
        if item_size > bin_capacity / 2 {
            score -= 10.0;
        }
        // Last-chance override: don't open new bin if only one bin fits.
        if fitting_bins_count == 1 {
            score += 30.0;
        }
    }

    // Mild preference to fill already-open bins as stream matures.
    let progress = step_index as f64 / (total_items.max(1) as f64);
    score -= 3.0 * progress * (bin_residual as f64 / bin_capacity as f64);

    // Penalize bins far from the mean residual when fit is loose (fragmentation control).
    let dev = (bin_residual as f64 - mean_residual).abs();
    score += 0.05 * dev;

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Perfect fit: strong reward (bin is closed, zero waste).
    if post_residual == 0 {
        score -= 20.0;
    }

    // Strict dead-space avoidance: residuals in (0,10) are "unusable gaps"
    // since minimum item size is 10. Penalize heavily so such placements
    // lose to almost any alternative, including opening a new bin.
    if post_residual > 0 && post_residual < 10 {
        score += 35.0;
    }

    // Lookahead: if the next item cannot fit into the resulting residual,
    // this placement strands space — penalize proportionally.
    if post_residual > 0 && next_item_size > post_residual {
        score += next_item_size as f64 * 0.25;
    }

    // Last-chance bin: if this is the only bin that fits the item,
    // using it avoids opening a new bin — reward.
    if fitting_bins_count == 1 && bin_residual != bin_capacity {
        score -= 12.0;
    }

    // Mild pressure toward consolidating into fewer open bins.
    score += open_bins_count as f64 * 0.05;

    // Slight bias against opening a brand-new bin when a reasonable
    // reuse exists (new bin has bin_residual == bin_capacity).
    if bin_residual == bin_capacity {
        score += 6.0;
    }

    // Mild preference for placing into bins whose residual is already
    // small relative to the fleet mean (tighten nearly-full bins first).
    score += (mean_residual - post_residual as f64).abs() * 0.01;

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Perfect-fit reward: zero post-residual is ideal.
    if post_residual == 0 {
        score -= 1000.0;
    }

    // 2-step lookahead: reward when the next item fits exactly into post_residual.
    if next_item_size > 0 && post_residual >= next_item_size {
        let slack = post_residual - next_item_size;
        if slack == 0 {
            score -= 500.0; // chain of two perfect fits
        } else {
            score -= 200.0 - slack as f64; // next item fits, penalize leftover slack
        }
    } else if next_item_size > 0 {
        // Next item won't fit here: penalize proportionally to the wasted opportunity.
        score += 50.0 + (next_item_size - post_residual) as f64 * 0.5;
    }

    // Penalize small unusable residuals (dead space below the minimum item size).
    if post_residual > 0 && post_residual < 10 {
        score += 300.0;
    }

    // Compare against mean residual: bins tighter than average are better targets.
    score -= (mean_residual - post_residual as f64) * 0.5;

    // Last-chance bin: strongly favor using the only bin that can fit the item.
    if fitting_bins_count == 1 && bin_residual != bin_capacity {
        score -= 400.0;
    }

    // New-bin candidate: neutral-ish baseline, penalize slightly so we prefer
    // reusing open bins unless the fit is truly poor.
    if bin_residual == bin_capacity {
        score += 20.0;
    }

    // Late in the stream, be slightly more conservative about opening new bins.
    let progress = step_index as f64 / total_items.max(1) as f64;
    if bin_residual == bin_capacity {
        score += progress * 30.0;
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Exact / near-exact fit: strong reward.
    if post_residual == 0 {
        score -= 500.0;
    } else {
        // Non-linear penalty on leftover: small leftovers are cheap, big ones expensive.
        let pr = post_residual as f64;
        score += (pr * pr) / (bin_capacity as f64 * 0.5);
    }

    // Lookahead: if the next item fits exactly into the post-residual, reward heavily.
    if next_item_size > 0 {
        if next_item_size == post_residual {
            score -= 350.0;
        } else if next_item_size <= post_residual {
            // Next item fits but leaves more waste: mild proportional reward.
            let chained_waste = (post_residual - next_item_size) as f64;
            score -= 120.0 - chained_waste * 1.5;
        } else {
            // Next item cannot use this bin's remainder: penalize dead space.
            score += 40.0 + (next_item_size - post_residual) as f64 * 0.3;
        }
    }

    // Last-chance bin: strongly favor using the only bin that fits.
    if fitting_bins_count == 1 && bin_residual != bin_capacity {
        score -= 200.0;
    }

    // New-bin candidate handling: only attractive when existing fits are poor.
    if bin_residual == bin_capacity {
        let pressure = (open_bins_count as f64).ln().max(1.0);
        // Base cost of opening a new bin, discounted when many bins are open
        // (consolidation is less valuable late in the stream).
        score = 260.0 - pressure * 25.0;
        if post_residual > 0 {
            score += post_residual as f64 * 0.8; // new bin always wastes (100 - item)
        }
        if next_item_size > 0 && next_item_size <= post_residual {
            score -= 100.0; // fresh bin can still chain the next item
        }
    }

    // Global state coupling: prefer filling bins whose residual is below the mean
    // (drive low-residual bins to zero), avoid dumping into high-residual bins.
    let res_f = bin_residual as f64;
    if res_f < mean_residual {
        score -= (mean_residual - res_f) * 0.6;
    } else {
        score += (res_f - mean_residual) * 0.4;
    }

    // Time horizon: early in the stream, be conservative (keep bins flexible);
    // late in the stream, pack aggressively.
    let t = if total_items > 0 { step_index as f64 / total_items as f64 } else { 0.0 };
    score -= t * 60.0 * (1.0 - post_residual as f64 / bin_capacity as f64);
    score += (1.0 - t) * post_residual as f64 * 0.3;

    // Slight penalty for spreading across too many open bins.
    score += open_bins_count as f64 * 0.05;

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let progress = step_index as f64 / total_items.max(1) as f64;
    let pr = post_residual as f64;
    let cap = bin_capacity as f64;
    let norm_pr = pr / cap;
    let fit_norm = item_size as f64 / cap;
    let next_norm = next_item_size as f64 / cap;

    let mut score = pr;

    // Non-linear polynomial coupling of post_residual with stream progress
    let poly = norm_pr * norm_pr * (1.0 - norm_pr);
    score -= 60.0 * poly * (0.5 + progress);

    // Reward tight fits, stronger late in the stream
    score -= (fit_norm * fit_norm) * 25.0 * (0.3 + 0.7 * progress);

    // Penalize dead space relative to next item: residual just below next item is bad
    if next_item_size > 0 {
        let gap = norm_pr - next_norm;
        score += 15.0 * gap.abs() * (1.0 - progress);
    }

    // Last-chance bin bonus
    if fitting_bins_count == 1 {
        score -= 30.0;
    }

    // Mild penalty for many open bins with high mean residual (fragmentation)
    score += 0.05 * open_bins_count as f64 * (mean_residual / cap);

    // New-bin candidate: prefer it only when residuals across bins are large
    if bin_residual == bin_capacity {
        score += 8.0 * (mean_residual / cap) * (1.0 - progress);
        score -= 5.0 * progress;
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Harmonic class of post_residual: bins whose leftover falls into "useful"
    // residue classes (multiples of common item sizes) are favored.
    let pr = post_residual;
    let useful = if pr == 0 {
        -30.0 // perfect fit, best possible
    } else if pr % 10 == 0 {
        -8.0
    } else if pr % 5 == 0 {
        -3.0
    } else if pr >= 10 && pr <= 20 {
        2.0
    } else {
        0.0
    };
    score += useful;

    // Penalize dead space that cannot fit even the smallest item
    if pr < 10 && pr > 0 {
        score += 25.0;
    }

    // Last-chance bin: strongly favor using it to avoid opening a new bin
    if fitting_bins_count == 1 && bin_residual != bin_capacity {
        score -= 40.0;
    }

    // Lookahead coupling: if next item fits in post_residual, reward this bin
    if next_item_size > 0 && post_residual >= next_item_size {
        score -= 12.0 + (post_residual - next_item_size) as f64 * 0.2;
    } else if next_item_size > 0 && post_residual > 0 {
        // next item won't fit here: penalize wasting space next item could use
        score += 6.0;
    }

    // New-bin candidate handling: only prefer fresh bin when existing fits are bad
    if bin_residual == bin_capacity {
        // base cost of opening a bin
        score += 15.0;
        // but if the item is huge relative to capacity, a fresh bin is fine
        score -= (item_size as f64 / bin_capacity as f64) * 20.0;
        // late in stream with many open bins, prefer consolidation
        let progress = step_index as f64 / total_items.max(1) as f64;
        score += progress * 10.0 + open_bins_count as f64 * 0.5;
    }

    // Tight-fit bonus: item fills most of the bin
    let fill = item_size as f64 / bin_residual.max(1) as f64;
    if fill > 0.8 && bin_residual != bin_capacity {
        score -= 10.0 * fill;
    }

    // Prefer bins below mean residual (they're the "fuller" ones)
    score += ((post_residual as f64 - mean_residual) * 0.3).max(-5.0).min(5.0);

    // Integer-division threshold: leftover in [1..9] is dead, [10..29] marginal
    let class = pr / 30; // 0 = tiny, 1 = medium, 2+ = roomy
    score += match class {
        0 => 10.0,
        1 => 0.0,
        _ => -4.0,
    };

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Strict dead-space avoidance: tiny unusable gaps are heavily penalized
    if post_residual > 0 && post_residual < 10 {
        score += 60.0;
    } else if post_residual >= 10 && post_residual < 20 {
        score += 15.0;
    }

    // Reward near-perfect fits
    if post_residual == 0 {
        score -= 40.0;
    }

    // Exact match with lookahead item: strongly favor reserving this residual
    if next_item_size > 0 && post_residual == next_item_size {
        score -= 25.0;
    }

    // Last chance bin: avoid opening a new bin
    if fitting_bins_count == 1 && bin_residual >= item_size {
        score -= 30.0;
    }

    // Open-bin pressure: discourage opening new bins when few bins are open
    if bin_residual == bin_capacity {
        score += 20.0 + 3.0 * open_bins_count as f64;
    } else {
        score -= 2.0 * open_bins_count as f64;
    }

    // Prefer bins whose residual is below average (denser bins first)
    score += (bin_residual as f64 - mean_residual) * 0.3;

    // Early in stream: be frugal with new bins
    let progress = if total_items > 0 { step_index as f64 / total_items as f64 } else { 0.0 };
    if bin_residual == bin_capacity {
        score += 10.0 * (1.0 - progress);
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Perfect fit: strongly reward.
    if post_residual == 0 {
        score -= 1000.0;
    }

    // Tight fit reward: item fills most of the bin.
    let fill_ratio = item_size as f64 / bin_residual as f64;
    score -= 30.0 * fill_ratio * fill_ratio;

    // 2-step lookahead: if the next item exactly fills the post-residual,
    // this bin is a perfect chain — reward heavily.
    if next_item_size > 0 && post_residual == next_item_size {
        score -= 900.0;
    }
    // If next item fits into post_residual, leaving even less waste after two steps.
    if next_item_size > 0 && next_item_size <= post_residual {
        let two_step_waste = (post_residual - next_item_size) as f64;
        score -= 40.0 * (1.0 - two_step_waste / bin_capacity as f64);
        score += 0.15 * two_step_waste; // mild penalty for leftover after step 2
    } else if next_item_size > 0 {
        // Next item won't fit here; penalize small unusable leftovers.
        score += 0.3 * post_residual as f64;
    }

    // Relative to mean residual: prefer bins that are tighter than average.
    score -= 2.0 * (mean_residual - post_residual as f64);

    // Last-chance bin: if this is the only bin that fits, avoid opening a new bin.
    if fitting_bins_count == 1 && bin_residual != bin_capacity {
        score -= 120.0;
    }

    // New-bin candidate handling: opening a new bin is only attractive when the
    // item is large and no open bin fits well.
    if bin_residual == bin_capacity {
        let progress = step_index as f64 / total_items.max(1) as f64;
        let open_pressure = open_bins_count as f64;
        // Base cost of a new bin, reduced when item is big (large item wastes less).
        let base = 260.0 - 1.2 * item_size as f64;
        score = base + 3.0 * open_pressure * (1.0 - progress) + 0.5 * post_residual as f64;
        // If next item is small, a fresh bin is fine for it too.
        if next_item_size > 0 && next_item_size <= bin_capacity - item_size {
            score -= 25.0;
        }
    }

    score
}
